BEGIN;
SELECT set_config('app.test_d_admin', :'admin_auth_id', true);
DO $$
DECLARE
  ids jsonb := pg_temp.delade_ids();
  a uuid := ids ->> 'a';
  m uuid := ids ->> 'm';
  hall uuid := ids ->> 'hall';
  roller1 uuid := ids ->> 'roller1';
  local_hall uuid := ids ->> 'local_hall';
  other_room uuid;
  declined_room uuid;
  m_local uuid;
  loan uuid;
  wrong text[] := '{}';
  st text;
BEGIN
  -- h. While a loan of the hall is live, A's room for it binds; once both
  -- have ended, it binds nothing.
  PERFORM pg_temp.delade_as(current_setting('app.test_d_admin'), NULL);
  INSERT INTO "Rooms" ("schoolId", name, "updatedAt") VALUES (a, 'Delade A annan', now()) RETURNING id INTO other_room;
  INSERT INTO "Rooms" ("schoolId", name, "updatedAt") VALUES (a, 'Delade A avböjd', now()) RETURNING id INTO declined_room;
  PERFORM pg_temp.delade_as('00000000-0000-4000-8000-000000000105', NULL);
  INSERT INTO "Rooms" ("schoolId", name, "updatedAt") VALUES (m, 'Delade M lånar h', now()) RETURNING id INTO m_local;
  IF EXISTS (SELECT 1 FROM app.lendable_rooms() WHERE room_id = local_hall) THEN
    wrong := wrong || '278h M is offered A''s live room for the hall'::text;
  END IF;
  -- M asks for A's room, and M declines nothing: A declines it.
  loan := app.room_loan_request(declined_room, m_local, NULL, NULL, 1, '08:00', '09:00', '2030-08-19', '2031-06-13', NULL);
  PERFORM pg_temp.delade_as(current_setting('app.test_d_admin'), NULL);
  PERFORM app.room_loan_decide(loan, false);
  st := pg_temp.delade_state(format('SELECT app.room_loan_request(%L, %L, NULL, NULL, 1, ''08:00'', ''09:00'', ''2030-08-19'', ''2031-06-13'', NULL)', roller1, local_hall));
  IF st <> 'RL409' THEN wrong := wrong || format('278h A''s live room for the hall stands for Roller 1: %s', st); END IF;
  st := pg_temp.delade_state(format('SELECT app.room_loan_request(%L, %L, NULL, NULL, 1, ''08:00'', ''09:00'', ''2030-08-19'', ''2031-06-13'', NULL)', hall, other_room));
  IF st <> 'RL409' THEN wrong := wrong || format('278h A asks for the hall by another room while a loan is live: %s', st); END IF;
  -- A room once asked for and declined is A's room for a room it borrows.
  st := pg_temp.delade_state(format('SELECT app.room_loan_request(%L, %L, NULL, NULL, 1, ''08:00'', ''09:00'', ''2030-08-19'', ''2031-06-13'', NULL)', roller1, declined_room));
  IF st <> 'ok' THEN wrong := wrong || format('278h A holds Roller 1 by a room once asked for and declined: %s', st); END IF;
  -- Both live loans of the hall end.
  FOR loan IN SELECT id FROM "RoomLoans" WHERE "roomId" = hall AND status IN ('PENDING', 'APPROVED') LOOP
    PERFORM app.room_loan_withdraw(loan);
  END LOOP;
  PERFORM pg_temp.delade_as('00000000-0000-4000-8000-000000000105', NULL);
  IF NOT EXISTS (SELECT 1 FROM app.lendable_rooms() WHERE room_id = local_hall) THEN
    wrong := wrong || '278h M is not offered A''s room for the hall once its loans have ended'::text;
  END IF;
  st := pg_temp.delade_state(format('SELECT app.room_loan_request(%L, NULL, NULL, NULL, 3, ''08:00'', ''09:00'', ''2030-08-19'', ''2031-06-13'', NULL)', local_hall));
  IF st <> 'ok' THEN wrong := wrong || format('278h M asks for A''s room for the hall once its loans have ended: %s', st); END IF;
  PERFORM pg_temp.delade_as(current_setting('app.test_d_admin'), NULL);
  st := pg_temp.delade_state(format('SELECT app.room_loan_request(%L, %L, NULL, NULL, 4, ''08:00'', ''09:00'', ''2030-08-19'', ''2031-06-13'', NULL)', hall, other_room));
  IF st <> 'ok' THEN wrong := wrong || format('278h A asks for the hall by another room once the loans have ended: %s', st); END IF;
  st := pg_temp.delade_state(format('SELECT app.room_loan_request(%L, %L, NULL, NULL, 2, ''08:00'', ''09:00'', ''2030-08-19'', ''2031-06-13'', NULL)', roller1, local_hall));
  IF st <> 'RL409' THEN wrong := wrong || format('278h Roller 1 by a second room while one is live: %s', st); END IF;

  -- i. A's local room goes, and its loans with it.
  DELETE FROM "Rooms" WHERE id = local_hall;
  IF EXISTS (SELECT 1 FROM "RoomLoans" WHERE "localRoomId" = local_hall) THEN
    wrong := wrong || '278i the loans of a deleted local room stay'::text;
  END IF;

  PERFORM pg_temp.delade_as(NULL, NULL);
  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'delade 278h: %', array_to_string(wrong, '; ');
  END IF;
END $$;
ROLLBACK;

-- 278j. A request takes the lock of the room it asks for and of the room
-- it names, so a race over either queues (the transaction holds both after
-- it). A request naming a room while another request of the same room waits
-- without one: approving the waiting one holds by the named room, and makes
-- no second room (20261217090100).
BEGIN;
SELECT set_config('app.test_d_admin', :'admin_auth_id', true);
DO $$
DECLARE
  ids jsonb := pg_temp.delade_ids();
  a uuid := ids ->> 'a';
  m uuid := ids ->> 'm';
  roller1 uuid := ids ->> 'roller1';
  fresh_room uuid;
  named uuid;
  named2 uuid;
  waiting uuid;
  second uuid;
  rooms_before bigint;
  n bigint;
  wrong text[] := '{}';
  st text;
BEGIN
  PERFORM pg_temp.delade_as('00000000-0000-4000-8000-000000000105', NULL);
  INSERT INTO "Rooms" ("schoolId", name, "updatedAt") VALUES (m, 'Delade M lås', now()) RETURNING id INTO fresh_room;
  PERFORM pg_temp.delade_as(current_setting('app.test_d_admin'), NULL);
  INSERT INTO "Rooms" ("schoolId", name, "updatedAt") VALUES (a, 'Delade A namngiven', now()) RETURNING id INTO named;
  INSERT INTO "Rooms" ("schoolId", name, "updatedAt") VALUES (a, 'Delade A namngiven 2', now()) RETURNING id INTO named2;
  IF EXISTS (SELECT 1 FROM pg_locks l WHERE l.locktype = 'advisory' AND l.pid = pg_backend_pid()) THEN
    RAISE EXCEPTION 'delade 278j: the transaction holds an advisory lock before the request';
  END IF;
  -- The first request of the transaction, naming a room: both locks, whichever id is lower.
  PERFORM app.room_loan_request(fresh_room, named, NULL, NULL, 1, '08:00', '09:00', '2030-08-19', '2031-06-13', NULL);
  SELECT count(*) INTO n FROM pg_locks l
   WHERE l.locktype = 'advisory' AND l.pid = pg_backend_pid() AND l.granted AND l.objsubid = 1
     AND ((l.classid::bigint << 32) | l.objid::bigint) IN (hashtextextended('RoomLoans:' || named::text, 0),
                                                             hashtextextended('RoomLoans:' || fresh_room::text, 0));
  IF n <> 2 THEN wrong := wrong || format('278j a request naming its room holds %s of the two rooms'' locks', n); END IF;

  -- A request without a room waits; another names one; the first's approval holds by it.
  waiting := app.room_loan_request(roller1, NULL, NULL, NULL, 1, '08:00', '09:00', '2030-08-19', '2031-06-13', NULL);
  second := app.room_loan_request(roller1, named2, NULL, NULL, 2, '08:00', '09:00', '2030-08-19', '2031-06-13', NULL);
  IF NOT EXISTS (SELECT 1 FROM "RoomLoans" WHERE id = second AND "localRoomId" = named2)
     OR NOT EXISTS (SELECT 1 FROM "RoomLoans" WHERE id = waiting AND "localRoomId" IS NULL) THEN
    wrong := wrong || '278j the requests do not stand as asked'::text;
  END IF;
  SELECT count(*) INTO rooms_before FROM "Rooms" WHERE "schoolId" = a;
  PERFORM pg_temp.delade_as('00000000-0000-4000-8000-000000000107', NULL);
  st := pg_temp.delade_state(format('SELECT app.room_loan_decide(%L, true)', waiting));
  PERFORM pg_temp.delade_as(current_setting('app.test_d_admin'), NULL);
  IF st <> 'ok' OR NOT EXISTS (SELECT 1 FROM "RoomLoans" WHERE id = waiting AND status = 'APPROVED' AND "localRoomId" = named2)
     OR (SELECT count(*) FROM "Rooms" WHERE "schoolId" = a) <> rooms_before THEN
    wrong := wrong || format('278j approving the request waiting without a room (%s) does not hold by the named room, or makes another', st);
  END IF;

  PERFORM pg_temp.delade_as(NULL, NULL);
  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'delade 278j: %', array_to_string(wrong, '; ');
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 279: en skola som lämnar huvudmannen faller ur allt vid nästa sats,
-- utom att ägaren läser och avslutar ett godkänt lån av sin egen sal, och
-- PostgREST:s roll når ingenting (20261217090000).
--
--   a. the roller school's rektor leaves H (app.school_leaves_huvudman):
--      A's administrator no longer reads M among the other schools, nor T
--      or Y as shared with M, nor T's lessons at M, nor the A–M travel, nor
--      the loans of M's hall, nor M's rooms to ask for; asking for M's room
--      is RL404, withdrawing the approved loan of M's hall is RL404, M's
--      planner deciding A's pending loan is RL404, and neither planner
--      writes the travel between them. M, the owner, still reads the
--      approved loan of its hall (not the pending one, nor the travel).
--      Nothing is deleted: the owner's check 278i counts the rows after a
--      departure;
--   b. A, the borrower, leaves H instead: A reads neither loan and
--      withdraws neither (RL404); M reads the approved one and not the
--      pending one, and deciding the pending one is RL404; C asks for the
--      hall on Tuesdays 10:00–11:00, which M cannot approve (23P01) until M
--      ends the approved loan to A, which it may; then it can, and the
--      ended loan is out of M's sight;
--   c. PostgREST's role (authenticated) may call none of the nine functions
--      and read none of the three tables, whoever it is and whichever
--      school it names.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('app.test_d_admin', :'admin_auth_id', true);
DO $$
DECLARE
  ids jsonb := pg_temp.delade_ids();
  a uuid := ids ->> 'a';
  m uuid := ids ->> 'm';
  pending uuid;
  approved uuid;
  wrong text[] := '{}';
  st text;
BEGIN
  PERFORM pg_temp.delade_as('00000000-0000-4000-8000-000000000105', NULL);
  SELECT id INTO pending FROM "RoomLoans" WHERE status = 'PENDING' LIMIT 1;
  SELECT id INTO approved FROM "RoomLoans" WHERE status = 'APPROVED' LIMIT 1;
  IF pending IS NULL OR approved IS NULL THEN RAISE EXCEPTION 'delade 279: the pending or the approved loan is missing'; END IF;
  PERFORM pg_temp.delade_as('00000000-0000-4000-8000-000000000106', NULL);
  PERFORM app.school_leaves_huvudman();

  PERFORM pg_temp.delade_as(current_setting('app.test_d_admin'), NULL);
  IF EXISTS (SELECT 1 FROM app.sibling_schools() WHERE school_id = m) THEN wrong := wrong || '279a M is still a school of H''s'::text; END IF;
  IF EXISTS (SELECT 1 FROM app.shared_teachers() WHERE school_id = m) THEN wrong := wrong || '279a a teacher is still shared with M'::text; END IF;
  IF EXISTS (SELECT 1 FROM app.shared_teacher_busy('2000-01-01', '2100-01-01') WHERE school_id = m) THEN
    wrong := wrong || '279a A reads lessons at M'::text;
  END IF;
  IF EXISTS (SELECT 1 FROM "SchoolTravelTimes") THEN wrong := wrong || '279a A reads the travel to M'::text; END IF;
  IF EXISTS (SELECT 1 FROM "RoomLoans") THEN wrong := wrong || '279a A reads the loans of M''s hall'::text; END IF;
  IF EXISTS (SELECT 1 FROM app.lendable_rooms() WHERE school_id = m) THEN wrong := wrong || '279a A is offered M''s rooms'::text; END IF;
  st := pg_temp.delade_state(format('SELECT app.room_loan_request(%L, NULL, NULL, NULL, 1, ''08:00'', ''09:00'', ''2030-08-19'', ''2031-06-13'', NULL)',
                               ids ->> 'roller1'));
  IF st <> 'RL404' THEN wrong := wrong || format('279a A asks for M''s room: %s', st); END IF;
  st := pg_temp.delade_state(format('SELECT app.room_loan_withdraw(%L)', approved));
  IF st <> 'RL404' THEN wrong := wrong || format('279a A withdraws the approved loan of M''s hall after M left: %s', st); END IF;
  PERFORM pg_temp.delade_as('00000000-0000-4000-8000-000000000105', NULL);
  IF (SELECT array_agg(id) FROM "RoomLoans") IS DISTINCT FROM ARRAY[approved] OR EXISTS (SELECT 1 FROM "SchoolTravelTimes") THEN
    wrong := wrong || '279a M, having left, reads other than its approved loan, or reads the travel'::text;
  END IF;
  st := pg_temp.delade_state(format('SELECT app.room_loan_decide(%L, true)', pending));
  IF st <> 'RL404' THEN wrong := wrong || format('279a M decides A''s loan after leaving: %s', st); END IF;
  -- Nor does either planner write the travel between them.
  PERFORM pg_temp.delade_as(current_setting('app.test_d_admin'), NULL);
  st := pg_temp.delade_rows(format('UPDATE "SchoolTravelTimes" SET minutes = 30, "setBySchoolId" = %L WHERE %L IN ("schoolAId", "schoolBId")', a, m));
  IF st <> 'rows 0' THEN wrong := wrong || format('279a A changes the travel to M after M left: %s', st); END IF;
  st := pg_temp.delade_rows(format('DELETE FROM "SchoolTravelTimes" WHERE %L IN ("schoolAId", "schoolBId")', m));
  IF st <> 'rows 0' THEN wrong := wrong || format('279a A deletes the travel to M after M left: %s', st); END IF;
  st := pg_temp.delade_rows(format('INSERT INTO "SchoolTravelTimes" ("schoolAId", "schoolBId", minutes, "setBySchoolId") VALUES (%L, %L, 5, %L) ON CONFLICT DO NOTHING',
                                   least(a, m), greatest(a, m), a));
  IF st <> '42501' THEN wrong := wrong || format('279a A adds a travel to M after M left: %s', st); END IF;

  PERFORM pg_temp.delade_as(NULL, NULL);
  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'delade 279a: %', array_to_string(wrong, '; ');
  END IF;
END $$;
ROLLBACK;

BEGIN;
SELECT set_config('app.test_d_admin', :'admin_auth_id', true);
DO $$
DECLARE
  ids jsonb := pg_temp.delade_ids();
  hall uuid := ids ->> 'hall';
  pending uuid;
  approved uuid;
  c_loan uuid;
  wrong text[] := '{}';
  st text;
BEGIN
  PERFORM pg_temp.delade_as('00000000-0000-4000-8000-000000000105', NULL);
  SELECT id INTO pending FROM "RoomLoans" WHERE status = 'PENDING' LIMIT 1;
  SELECT id INTO approved FROM "RoomLoans" WHERE status = 'APPROVED' LIMIT 1;
  IF pending IS NULL OR approved IS NULL THEN RAISE EXCEPTION 'delade 279b: the pending or the approved loan is missing'; END IF;
  -- A, the borrower, leaves H (A's full administrator decides).
  PERFORM pg_temp.delade_as(current_setting('app.test_d_admin'), NULL);
  PERFORM app.school_leaves_huvudman();
  IF EXISTS (SELECT 1 FROM "RoomLoans") THEN wrong := wrong || '279b A reads the loans of M''s hall after leaving'::text; END IF;
  st := pg_temp.delade_state(format('SELECT app.room_loan_withdraw(%L)', approved));
  IF st <> 'RL404' THEN wrong := wrong || format('279b A withdraws the approved loan after leaving: %s', st); END IF;
  -- M, the owner, reads the approved loan and decides nothing of A's.
  PERFORM pg_temp.delade_as('00000000-0000-4000-8000-000000000105', NULL);
  IF (SELECT array_agg(id) FROM "RoomLoans") IS DISTINCT FROM ARRAY[approved] THEN
    wrong := wrong || '279b M does not read exactly its approved loan to A, who left'::text;
  END IF;
  st := pg_temp.delade_state(format('SELECT app.room_loan_decide(%L, true)', pending));
  IF st <> 'RL404' THEN wrong := wrong || format('279b M decides the pending loan of A, who left: %s', st); END IF;
  -- C asks for the hall on Tuesdays; the loan to A holds it until M ends it.
  PERFORM pg_temp.delade_as('fe000000-0000-4000-8000-000000000269', NULL);
  c_loan := app.room_loan_request(hall, NULL, NULL, NULL, 2, '10:00', '11:00', '2030-08-19', '2031-06-13', NULL);
  PERFORM pg_temp.delade_as('00000000-0000-4000-8000-000000000105', NULL);
  st := pg_temp.delade_state(format('SELECT app.room_loan_decide(%L, true)', c_loan));
  IF st <> '23P01' THEN wrong := wrong || format('279b M approves C over the loan to A: %s', st); END IF;
  st := pg_temp.delade_state(format('SELECT app.room_loan_revoke(%L)', approved));
  IF st <> 'ok' THEN wrong := wrong || format('279b M ends its approved loan to A, who left: %s', st); END IF;
  st := pg_temp.delade_state(format('SELECT app.room_loan_decide(%L, true)', c_loan));
  IF st <> 'ok' THEN wrong := wrong || format('279b M approves C once the loan to A has ended: %s', st); END IF;
  IF (SELECT array_agg(id) FROM "RoomLoans") IS DISTINCT FROM ARRAY[c_loan] THEN
    wrong := wrong || '279b M reads other than C''s loan once the loan to A has ended'::text;
  END IF;

  PERFORM pg_temp.delade_as(NULL, NULL);
  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'delade 279b: %', array_to_string(wrong, '; ');
  END IF;
END $$;
ROLLBACK;

BEGIN;
SELECT set_config('app.test_d_admin', :'admin_auth_id', true);
DO $$
BEGIN
  PERFORM set_config('app.test_d_ids', pg_temp.delade_ids()::text, true);
END $$;
DO $$
DECLARE
  ids jsonb := current_setting('app.test_d_ids')::jsonb;
  wrong text[] := '{}';
  st text;
  fn text;
  rec record;
BEGIN
  SET LOCAL ROLE authenticated;
  FOR rec IN SELECT * FROM (VALUES
      (current_setting('app.test_d_admin'), ''),
      ('00000000-0000-4000-8000-000000000105', json_build_object('x-school-id', ids ->> 'm')::text),
      ('fe000000-0000-4000-8000-000000000260', json_build_object('x-school-id', ids ->> 'a')::text)) v(sub, headers) LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', rec.sub)::text, true);
    PERFORM set_config('request.headers', rec.headers, true);
    FOREACH fn IN ARRAY ARRAY[
        'SELECT app.same_huvudman_school_ids()', 'SELECT * FROM app.sibling_schools()', 'SELECT * FROM app.shared_teachers()',
        'SELECT * FROM app.shared_teacher_busy(''2000-01-01'', ''2100-01-01'')', 'SELECT * FROM app.lendable_rooms()',
        format('SELECT app.room_loan_request(%L, NULL, NULL, NULL, 1, ''08:00'', ''09:00'', ''2030-08-19'', ''2031-06-13'', NULL)', ids ->> 'roller1'),
        format('SELECT app.room_loan_decide(%L, true)', gen_random_uuid()), format('SELECT app.room_loan_withdraw(%L)', gen_random_uuid()),
        format('SELECT app.room_loan_revoke(%L)', gen_random_uuid()),
        'SELECT * FROM "RoomLoans"', 'SELECT * FROM "SchoolTravelTimes"', 'SELECT * FROM "SharedTeacherMarks"'] LOOP
      st := pg_temp.delade_state(fn);
      IF st <> '42501' THEN
        wrong := wrong || format('%s as %s: %s', fn, rec.sub, st);
      END IF;
    END LOOP;
  END LOOP;
  IF current_user <> 'authenticated' THEN
    RAISE EXCEPTION 'delade 279c: the block did not run as PostgREST''s role';
  END IF;
  SET LOCAL ROLE app_authenticated;
  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'delade 279c: PostgREST''s role reaches the sharing: %', array_to_string(wrong, '; ');
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 279d: publiceringens eget val för krockar med huvudmannens andra
-- skolor (PublicationSettings."gateOtherSchool", 20261217090100), och det som
-- generatorn och publiceringen läser genom de smala läsningarna.
--
--   a. the column is a PublishGateMode, NOT NULL, WARN by default, and every
--      school's row reads WARN: no school is refused anything it published
--      before;
--   b. the scheduler (the roller school's schemaläggare, who generates and
--      publishes) reads what other-school-holds.ts and other-school-finding.ts
--      ask: the other schools, the shared teachers' lessons there in the
--      year's dates, and the loans between the schools; and so does school
--      A's administrator for the roller year. The expedition reads them too
--      (every profile reads), and writes no loan.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('app.test_d_admin', :'admin_auth_id', true);
DO $$
DECLARE
  ids jsonb := pg_temp.delade_ids();
  col record;
  wrong text[] := '{}';
  n bigint;
  sub text;
BEGIN
  SELECT a.atttypid::regtype::text AS type, a.attnotnull AS notnull, pg_get_expr(d.adbin, d.adrelid) AS def INTO col
    FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
   WHERE a.attrelid = '"PublicationSettings"'::regclass AND a.attname = 'gateOtherSchool';
  IF col IS NULL OR col.type <> '"PublishGateMode"' OR NOT col.notnull OR col.def NOT LIKE '''WARN''%' THEN
    wrong := wrong || format('279d gateOtherSchool is %s', row_to_json(col));
  END IF;

  FOREACH sub IN ARRAY ARRAY['00000000-0000-4000-8000-000000000107', '00000000-0000-4000-8000-000000000108'] LOOP
    PERFORM pg_temp.delade_as(sub, NULL);
    IF (SELECT count(*) FROM app.sibling_schools()) <> 2
       OR (SELECT count(*) FROM app.shared_teacher_busy('2026-08-01', '2027-07-31') WHERE teacher_id::text = ids ->> 't_m') <> 1
       OR (SELECT count(*) FROM "RoomLoans") <> 2 THEN
      wrong := wrong || format('279d %s does not read what the generator and the publish read', sub);
    END IF;
    SELECT count(*) INTO n FROM "PublicationSettings" WHERE "gateOtherSchool" <> 'WARN';
    IF n <> 0 THEN
      wrong := wrong || format('279d %s reads %s rows with gateOtherSchool set before any school chose', sub, n);
    END IF;
  END LOOP;
  PERFORM pg_temp.delade_as('00000000-0000-4000-8000-000000000108', NULL);
  IF pg_temp.delade_state(format('SELECT app.room_loan_decide(%L, true)', gen_random_uuid())) <> 'RL403' THEN
    wrong := wrong || '279d the expedition decides a loan'::text;
  END IF;

  PERFORM pg_temp.delade_as(current_setting('app.test_d_admin'), NULL);
  IF (SELECT count(*) FROM app.shared_teacher_busy('2030-08-15', '2031-06-15') WHERE teacher_id::text = ids ->> 't_a') <> 3
     OR (SELECT count(*) FROM "RoomLoans" WHERE "borrowerSchoolId"::text = ids ->> 'a' AND status = 'APPROVED') <> 1 THEN
    wrong := wrong || '279d school A''s administrator does not read the roller year''s holds'::text;
  END IF;

  PERFORM pg_temp.delade_as(NULL, NULL);
  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'delade 279d: %', array_to_string(wrong, '; ');
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 285: Elevlistan i uppföljningen, katalogen (20261215090000). En
-- SS12000-kalenderhändelse säger med studentExceptions participates false
-- vilka av gruppens elever en ersättande grupp tar av den, så dess
-- meta.modified ska flyttas när den listan kan ändras. Hjälparen
-- app.ss12000_bump_replaced är SECURITY DEFINER med fäst search_path och
-- körbar av ingen API-roll; triggerfunktionerna på StudentGroupMembers,
-- StudentGroups och Users frågar den, och deras triggrar är desamma.
-- Händelserna och aktiviteterna flyttas vid commit: väntetabellen är
-- unlogged (ingen publikation kan fälla flushen), och det som skjuter upp
-- (app.ss12000_bump_activities, tjänstlänkarna, Users) flyttar inget vid
-- satsen.
-- ---------------------------------------------------------------------------

BEGIN;
DO $$
DECLARE
  fn constant text := 'app.ss12000_bump_replaced(uuid, uuid[], uuid[], uuid[], uuid[])';
  r text;
  bad text;
BEGIN
  IF NOT (SELECT prosecdef FROM pg_proc WHERE oid = fn::regprocedure) THEN RAISE EXCEPTION 'elevlistan 285: % is not SECURITY DEFINER', fn; END IF;
  IF (SELECT proconfig FROM pg_proc WHERE oid = fn::regprocedure) IS DISTINCT FROM ARRAY['search_path=public, pg_temp'] THEN
    RAISE EXCEPTION 'elevlistan 285: % does not pin its search_path', fn;
  END IF;
  FOREACH r IN ARRAY ARRAY['anon', 'authenticated', 'service_role', 'app_authenticated'] LOOP
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) AND has_function_privilege(r, fn, 'EXECUTE') THEN
      RAISE EXCEPTION 'elevlistan 285: % may call %', r, fn;
    END IF;
  END LOOP;
  IF (SELECT proacl::text FROM pg_proc WHERE oid = fn::regprocedure) ~ '[{,]=X/' THEN
    RAISE EXCEPTION 'elevlistan 285: PUBLIC may call %', fn;
  END IF;
  SELECT string_agg(p.proname, ', ' ORDER BY p.proname) INTO bad
    FROM pg_proc p JOIN pg_namespace ns ON ns.oid = p.pronamespace AND ns.nspname = 'app'
   WHERE p.proname IN ('ss12000_v_group_members', 'ss12000_v_groups', 'ss12000_v_users')
     AND p.prosrc NOT LIKE '%app.ss12000_bump_replaced(%';
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'elevlistan 285: % does not ask app.ss12000_bump_replaced', bad; END IF;
  -- The events move at commit: the table the statements record them in, in
  -- schema app, row security on and no API role's to read or write; and its
  -- constraint trigger, deferred, calling the flush.
  IF (SELECT relrowsecurity FROM pg_class WHERE oid = 'app."Ss12000ReplacedPending"'::regclass) IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'elevlistan 285: app."Ss12000ReplacedPending" has row security off';
  END IF;
  -- Unlogged: in no publication, so a publication of deletes for all tables
  -- or for schema app cannot fail the flush's DELETE (review R3-M3).
  IF (SELECT relpersistence FROM pg_class WHERE oid = 'app."Ss12000ReplacedPending"'::regclass) IS DISTINCT FROM 'u' THEN
    RAISE EXCEPTION 'elevlistan 285: app."Ss12000ReplacedPending" is logged, and a publication of deletes would fail every flush';
  END IF;
  FOREACH r IN ARRAY ARRAY['anon', 'authenticated', 'service_role', 'app_authenticated'] LOOP
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r)
       AND has_table_privilege(r, 'app."Ss12000ReplacedPending"', 'SELECT, INSERT, UPDATE, DELETE, TRUNCATE') THEN
      RAISE EXCEPTION 'elevlistan 285: % reaches app."Ss12000ReplacedPending"', r;
    END IF;
  END LOOP;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger t JOIN pg_proc p ON p.oid = t.tgfoid
                  WHERE t.tgrelid = 'app."Ss12000ReplacedPending"'::regclass AND t.tgname = 'Ss12000ReplacedPending_flush_at_commit'
                    AND t.tgconstraint <> 0 AND t.tgdeferrable AND t.tginitdeferred AND p.proname = 'ss12000_flush_replaced') THEN
    RAISE EXCEPTION 'elevlistan 285: the flush is not a deferred constraint trigger on the table';
  END IF;
  FOREACH r IN ARRAY ARRAY['app.ss12000_defer_lessons(uuid, uuid[])', 'app.ss12000_defer_activities(uuid, uuid[])',
                           'app.ss12000_activity_ids(uuid, uuid[], uuid[], uuid[], boolean)', 'app.ss12000_flush_replaced()'] LOOP
    IF NOT (SELECT prosecdef FROM pg_proc WHERE oid = r::regprocedure)
       OR (SELECT proconfig FROM pg_proc WHERE oid = r::regprocedure) IS DISTINCT FROM ARRAY['search_path=public, pg_temp']
       OR has_function_privilege('app_authenticated', r, 'EXECUTE') OR has_function_privilege('anon', r, 'EXECUTE') THEN
      RAISE EXCEPTION 'elevlistan 285: % is not a revoked SECURITY DEFINER with a pinned search_path', r;
    END IF;
  END LOOP;
  -- What two connections would need to see (the adapter probe's el- checks
  -- do), pinned in the bodies too: the flush catches the lock timeout and
  -- nothing else, and only within its patience; an attempt gives up after
  -- 50 ms, long before a deadlock check (deadlock_timeout); it locks in
  -- (resource, entityId) order before it writes; the patience is 10 s of
  -- wall-clock time unless a test shortens it; and it moves, never records
  -- again. Every bump upserts in entityId order, and the statement records,
  -- never moves.
  IF (SELECT prosrc FROM pg_proc WHERE oid = 'app.ss12000_flush_replaced()'::regprocedure) NOT LIKE '%EXCEPTION WHEN lock_not_available THEN%IF last_try THEN%RAISE;%'
     OR (SELECT prosrc FROM pg_proc WHERE oid = 'app.ss12000_flush_replaced()'::regprocedure) ILIKE '%WHEN OTHERS%'
     OR (SELECT prosrc FROM pg_proc WHERE oid = 'app.ss12000_flush_replaced()'::regprocedure) NOT LIKE '%IF NOT last_try THEN%PERFORM set_config(''lock_timeout'', ''50ms'', true);%'
     OR (SELECT prosrc FROM pg_proc WHERE oid = 'app.ss12000_flush_replaced()'::regprocedure)
          NOT LIKE '%(v."resource" = ''CalendarEvent'' AND v."entityId" = ANY (r.lessons))%(v."resource" = ''Activity'' AND v."entityId" = ANY (r.activities))%ORDER BY v."resource", v."entityId"%FOR UPDATE;%'
     OR (SELECT prosrc FROM pg_proc WHERE oid = 'app.ss12000_flush_replaced()'::regprocedure) NOT LIKE '%current_setting(''app.ss12000_replaced_patience'', true), '''')::numeric, 10);%'
     OR (SELECT prosrc FROM pg_proc WHERE oid = 'app.ss12000_flush_replaced()'::regprocedure) NOT LIKE '%deadline := clock_timestamp() + patience * interval ''1 second'';%last_try := clock_timestamp() >= deadline;%'
     OR (SELECT prosrc FROM pg_proc WHERE oid = 'app.ss12000_flush_replaced()'::regprocedure) ~ '(ss12000_bump_activities|ss12000_defer_)' THEN
    RAISE EXCEPTION 'elevlistan 285: the flush''s body is not the all-or-none one';
  END IF;
  -- What the sync's apply writes beside memberships moves its events and
  -- activities at commit too (R3-M1): app.ss12000_bump_activities records
  -- them, and so do the duty links and Users.
  IF (SELECT prosrc FROM pg_proc WHERE oid = 'app.ss12000_bump_activities(uuid, uuid[], uuid[], uuid[], boolean)'::regprocedure)
       NOT LIKE '%app.ss12000_defer_activities(p_school, app.ss12000_activity_ids(p_school, p_groups, p_subjects, p_teachers, p_all));%'
     OR (SELECT prosrc FROM pg_proc WHERE oid = 'app.ss12000_bump_activities(uuid, uuid[], uuid[], uuid[], boolean)'::regprocedure) LIKE '%ss12000_bump(%' THEN
    RAISE EXCEPTION 'elevlistan 285: app.ss12000_bump_activities moves activities at the statement';
  END IF;
  SELECT string_agg(p.proname, ', ' ORDER BY p.proname) INTO bad
    FROM pg_proc p JOIN pg_namespace ns ON ns.oid = p.pronamespace AND ns.nspname = 'app'
   WHERE p.proname IN ('ss12000_duty_links_moved', 'ss12000_v_users') AND p.prosrc LIKE '%ss12000_bump_lessons(%';
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'elevlistan 285: % moves events at the statement', bad; END IF;
  IF (SELECT prosrc FROM pg_proc WHERE oid = 'app.ss12000_bump(uuid, text, uuid[])'::regprocedure) NOT LIKE '%ORDER BY d.id%' THEN
    RAISE EXCEPTION 'elevlistan 285: app.ss12000_bump does not upsert in entityId order';
  END IF;
  IF (SELECT prosrc FROM pg_proc WHERE oid = 'app.ss12000_bump_replaced(uuid, uuid[], uuid[], uuid[], uuid[])'::regprocedure) LIKE '%ss12000_bump_lessons%' THEN
    RAISE EXCEPTION 'elevlistan 285: app.ss12000_bump_replaced moves events at the statement';
  END IF;
  -- The triggers themselves are 20261014130000's: one per event and table, each calling its function.
  SELECT string_agg(c.relname || '.' || t.tgname || ' -> ' || p.proname, ', ' ORDER BY c.relname, t.tgname) INTO bad
    FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid JOIN pg_proc p ON p.oid = t.tgfoid
   WHERE c.relname IN ('StudentGroupMembers', 'StudentGroups', 'Users') AND t.tgname LIKE '%\_ss12000\_versions\_%';
  IF bad IS DISTINCT FROM
       'StudentGroupMembers.StudentGroupMembers_ss12000_versions_del -> ss12000_v_group_members, '
       'StudentGroupMembers.StudentGroupMembers_ss12000_versions_ins -> ss12000_v_group_members, '
       'StudentGroupMembers.StudentGroupMembers_ss12000_versions_upd -> ss12000_v_group_members, '
       'StudentGroups.StudentGroups_ss12000_versions_del -> ss12000_v_groups, '
       'StudentGroups.StudentGroups_ss12000_versions_ins -> ss12000_v_groups, '
       'StudentGroups.StudentGroups_ss12000_versions_upd -> ss12000_v_groups, '
       'Users.Users_ss12000_versions_del -> ss12000_v_users, '
       'Users.Users_ss12000_versions_ins -> ss12000_v_users, '
       'Users.Users_ss12000_versions_upd -> ss12000_v_users' THEN
    RAISE EXCEPTION 'elevlistan 285: the version triggers are %', bad;
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 286: Elevlistan i uppföljningen, beteendet (20261215090000), i
-- avsnitt 271:s skola (rls-ersattande-school). Administratören skriver genom
-- API:ts roll, och tjänsteprincipalen läser vilka kalenderhändelser som fick
-- en ny version i samma transaktion (xid). Lektionerna heter EG-n som i
-- fixturerna.
--
--   286a  Elev 7A (P2) går med i EG SvA7, som ersätter svenska: varje
--         svensklektion i år som når hen genom en annan grupp flyttas (EG-1
--         7A, EG-5 som namnger P1, EG-6 7B med 7A, EG-7 halvan, EG-12 7B med
--         halvan, EG-14 7A med EnS7, EG-15 7B med fjolårets SvA6); ingen
--         matematik, engelska, SvA-lektion, fördjupning, fjolårets EG-0
--         eller den andra skolans EG-9.
--   286b  samma elev i en undervisningsgrupp som inte ersätter något
--         (EG Sv7 fördjupning): ingen händelse flyttas, gruppen gör det.
--   286c  P1 (SvA7) lämnar halvan EG7A:1: halvans svenska (EG-7) och 7B:s
--         med halvan (EG-12), som listade hen, flyttas; halvans matematik
--         (EG-8) inte.
--   286d  EG SvA7 slutar ersätta: 7A:s svenska (EG-1), där P1 kommer tillbaka,
--         flyttas; engelskan (EG-10), där EnS7 fortfarande tar P1, och
--         SvA-lektionen (EG-3) inte.
--   286e  P1 flyttar från 7A till 7B: 7A:s svenska (EG-1) och engelska (EG-10),
--         som listade hen, och 7B:s med fjolårets SvA6 (EG-15), som nu gör
--         det, flyttas; matematiken, SvA och fördjupningen inte.
--   286f  P1:s ss12000Id länkas om (A5.3): varje händelse som listar hen som
--         inte deltagande flyttas (EG-1, EG-6, EG-7, EG-10, EG-12, EG-14);
--         matematiken och SvA inte.
--   286g  EG EnS7 tas bort: engelskan (EG-10) flyttas, matematiken inte.
--   286h  en skola utan ersättande grupp (den primära): en elev som byter
--         klass och går med i en undervisningsgrupp flyttar ingen händelse,
--         som före migreringen.
--   286i  EG SvA6 flyttas från i fjol till i år (granskningens H1): varje
--         svensklektion vars undantag läsåret ändrar flyttas, i år och fjolårets
--         EG-0; matematiken, engelskan, SvA och fördjupningen inte.
--   286j  EG7B blir en undervisningsgrupp (kind): dess egna svensklektioner,
--         där P3 nu behålls (keptBy), flyttas. P3 är 7B:s hemelev, så fallet
--         kräver också att hemklassens elever räknas som gruppens.
--   286k  EG EnS7 slutar ersätta engelska: engelskan (EG-10) flyttas, fast
--         ingen annan grupp av P1 ersätter engelska (paret ges uttryckligen).
--   286l  fjolårets EG SvA6 tas bort: fjolårets svenska (EG-0) flyttas,
--         ingen av årets.
--   286m  P1 avaktiveras: varje händelse som listade hen flyttas.
--   286n  P6, som slutat, återaktiveras: 7A:s svenska som nu listar hen flyttas.
--   286o  P3 tas bort (administratörens Ta bort): 7B:s svenska där P3 inte
--         deltog flyttas, fast medlemskapen redan är borta när Users trigger
--         körs; 7A:s egna lektioner inte.
--   286p  EG6A, fjolårets klass utan elever, flyttas till i år (granskningens
--         R2-L1): dess egen svenska EG-0 flyttas, eftersom fjolårets SvA6 inte
--         längre tar P2 (som når lektionen genom Sv6n) från en lektion i år;
--         ingen av årets lektioner.
--   286q  händelserna flyttas vid commit: efter en medlemsskrivning har ingen
--         händelse transaktionens xid förrän den uppskjutna flushen körts.
--   286r  flushen lämnar transaktionens lock_timeout som den var.
--   286s  EG-läraren avaktiveras (som synkens tillämpning gör i medlemskapens
--         transaktion, granskningens R3-M1): ingen händelse eller aktivitet
--         har transaktionens xid före commit, och efter flushen har hens
--         lektioner i år det, både händelserna och aktiviteterna.
--   286t  EG7A byter namn: app.ss12000_bump_activities skjuter upp, så
--         gruppens aktiviteter (EG-1, EG-6 med 7A) flyttas vid commit och
--         inte vid satsen.
--   286u  EG-läraren får en tjänstlänk (som synkens tillämpning skriver i
--         medlemskapens transaktion, granskningens R4-L1): ingen händelse
--         eller aktivitet har transaktionens xid före commit, och efter
--         flushen har hens lektioner i år det, både händelserna och
--         aktiviteterna.
--   286v  EG7A får ett ss12000Id: gruppens aktiviteter (EG-1, EG-6) flyttas
--         vid commit, som vid ett nytt namn (R4-L1).
--   286w  skolan får en skolenhet: varje aktivitet i år flyttas vid commit
--         och ingen vid satsen; fjolårets EG-0 är ingen aktivitet (R4-L1).
-- ---------------------------------------------------------------------------

-- 286a
BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001500')::text, true);
DO $$
DECLARE
  school uuid := app.current_school_id();
BEGIN
  IF app.current_user_role() IS DISTINCT FROM 'SCHOOL_ADMIN' OR (SELECT slug FROM "Schools" WHERE id = school) IS DISTINCT FROM 'rls-ersattande-school' THEN
    RAISE EXCEPTION 'elevlistan 286a: expected the replacing school''s administrator';
  END IF;
  PERFORM set_config('app.test_rls286_school', school::text, true);
    INSERT INTO "StudentGroupMembers" ("schoolId", "studentGroupId", "studentId")
    VALUES (school, (SELECT id FROM "StudentGroups" WHERE "schoolId" = school AND name = 'EG SvA7'), (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000001503'));
END $$;
-- The events move at commit (app.ss12000_flush_replaced); force it here.
SET CONSTRAINTS ALL IMMEDIATE;
SELECT set_config('request.jwt.claims', '', true);
SELECT set_config('app.service_school_id', current_setting('app.test_rls286_school'), true);
DO $$
DECLARE
  moved text[] := ARRAY(
    SELECT c.note FROM "Ss12000EntityVersions" v JOIN "CalendarLessons" c ON c.id = v."entityId"
     WHERE v.resource = 'CalendarEvent' AND v.xid = pg_current_xact_id() ORDER BY 1);
BEGIN
  IF NOT moved @> ARRAY['EG-1', 'EG-5', 'EG-6', 'EG-7', 'EG-12', 'EG-14', 'EG-15'] THEN
    RAISE EXCEPTION 'elevlistan 286a: moved % but not every one of %', moved, ARRAY['EG-1', 'EG-5', 'EG-6', 'EG-7', 'EG-12', 'EG-14', 'EG-15'];
  END IF;
  IF moved && ARRAY['EG-0', 'EG-2', 'EG-3', 'EG-8', 'EG-9', 'EG-10', 'EG-13'] THEN
    RAISE EXCEPTION 'elevlistan 286a: moved %, among them one of %', moved, ARRAY['EG-0', 'EG-2', 'EG-3', 'EG-8', 'EG-9', 'EG-10', 'EG-13'];
  END IF;
END $$;
ROLLBACK;

-- 286b
BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001500')::text, true);
DO $$
DECLARE
  school uuid := app.current_school_id();
BEGIN
  IF app.current_user_role() IS DISTINCT FROM 'SCHOOL_ADMIN' OR (SELECT slug FROM "Schools" WHERE id = school) IS DISTINCT FROM 'rls-ersattande-school' THEN
