-- ---------------------------------------------------------------------------
-- Section 287: en lärares gräns för undervisning i följd sitter på tjänsten,
-- och skolans brytare för den på Skolreglerna (20261218090000). The columns,
-- their CHECKs and their defaults, and what the work rule no longer holds.
--
-- Sammanhängande undervisning: "at most X minutes of teaching in a row, then
-- Y minutes free", set per teacher. It may be an arbetsanpassning, so it is
-- HR data and sits on the POST beside deltid in days
-- (TeacherEmployments."maxTeachingDaysPerWeek", section 161), where only
-- those who decide write it and the post's arms keep PostgREST's role from
-- every post but the teacher's own (section 288 holds who reads and writes
-- it, role by role). In the matrix school, whose one teacher (111) has a post
-- the fixtures wrote as the owner before the columns existed, and whose
-- Skolregler row they wrote without naming the switch:
--
--   * "maxConsecutiveTeachingMinutes" and "consecutiveBreakMinutes" are
--     nullable integers with no default on TeacherEmployments, and
--     "generatorKeepsConsecutiveTeaching" is boolean NOT NULL DEFAULT false on
--     LunchSettings, each with its comment (the post's two say HR data), and
--     each role holds on a new column exactly what it holds on a column of the
--     same table that was there before: the rows' arms are the whole of who
--     reads and writes them, no GRANT moved;
--   * the row written before the columns reads null and null, and the Skolregler
--     row reads false: off for every school until it says so;
--   * each column refuses a value outside its range by its own named CHECK on
--     the post (prisma-errors.ts turns the name into a 400) and takes both ends
--     of it: the limit 30..480 and the break 5..120, both multiples of five, so
--     a figure inside the range and off the engine's grid is refused too;
--   * the pair: one set without the other is refused by the pair CHECK's name,
--     from either side, on an UPDATE and on an INSERT, and both set or both
--     null pass;
--   * the columns stand beside the days and the percentages, not on them:
--     setting or clearing the stretch moves none of them, and clearing the
--     days moves not the stretch;
--   * the full administrator, who decides, sets, changes and clears both by
--     UPDATE and by the upsert the gateway writes, on the teacher's post and on
--     a post of their own; a post naming neither carries null and null, and a
--     write that leaves the two columns out of its SET leaves them as they are;
--   * THE WORK RULE HOLDS NEITHER: TeacherWorkRules has no such column and no
--     such CHECK, and its trigger function is the one 20261123090000 made, with
--     the cap's and the wish's sentence and no word of the stretch (section 160
--     holds what it does);
--   * the switch is NOT NULL and takes true and false, a fresh Skolregler row
--     naming nothing reads false.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);

-- 'sqlstate|message|detail|constraint' of a statement's refusal, or 'none'.
CREATE FUNCTION pg_temp.rls287_refusal(statement text) RETURNS text LANGUAGE plpgsql AS $$
DECLARE st text; msg text; det text; con text;
BEGIN
  EXECUTE statement;
  RETURN 'none';
EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS st = RETURNED_SQLSTATE, msg = MESSAGE_TEXT, det = PG_EXCEPTION_DETAIL, con = CONSTRAINT_NAME;
  RETURN st || '|' || msg || '|' || coalesce(det, '') || '|' || coalesce(con, '');
END $$;

DO $$
DECLARE
  school uuid := app.current_school_id();
  decider uuid := app.current_user_id();
  teacher uuid := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000111');
  post uuid;
  year uuid;
  col record;
  got text;
  what text;
  c record;
  r record;
  rule record;
  fn record;
BEGIN
  IF app.current_user_role() IS DISTINCT FROM 'SCHOOL_ADMIN' OR NOT app.current_user_decides()
     OR NOT app.current_user_may('PLANERING', true)
     OR (SELECT slug FROM "Schools" WHERE id = school) IS DISTINCT FROM 'rls-roller-school' THEN
    RAISE EXCEPTION 'stretch columns: expected the matrix school''s full administrator, who decides and writes PLANERING';
  END IF;
  SELECT id, "academicYearId" INTO post, year FROM "TeacherEmployments" WHERE "userId" = teacher;
  IF teacher IS NULL OR post IS NULL THEN
    RAISE EXCEPTION 'stretch columns: the matrix school''s teacher or their post is missing; fixtures did not run';
  END IF;

  -- The catalogue: type, nullability, default and comment of the three.
  FOR col IN SELECT * FROM (VALUES
      ('TeacherEmployments', 'maxConsecutiveTeachingMinutes', 'integer', false, NULL, 'Most minutes of teaching in a row%HR data%'),
      ('TeacherEmployments', 'consecutiveBreakMinutes', 'integer', false, NULL, 'The free time between two of the teacher%HR data%'),
      ('LunchSettings', 'generatorKeepsConsecutiveTeaching', 'boolean', true, 'false', 'Sammanhängande undervisning:%')
    ) AS t(tbl, name, type_name, not_null, default_value, comment_like)
  LOOP
    SELECT a.attnotnull AS not_null, format_type(a.atttypid, a.atttypmod) AS type_name,
           pg_get_expr(d.adbin, d.adrelid) AS default_value, col_description(a.attrelid, a.attnum) AS comment
      INTO rule
      FROM pg_attribute a
      LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
     WHERE a.attrelid = format('%I', col.tbl)::regclass AND a.attname = col.name AND NOT a.attisdropped;
    IF rule IS NULL OR rule.not_null IS DISTINCT FROM col.not_null OR rule.type_name <> col.type_name
       OR rule.default_value IS DISTINCT FROM col.default_value
       OR rule.comment IS NULL OR rule.comment NOT LIKE col.comment_like THEN
      RAISE EXCEPTION 'stretch columns: %.% is not % % default % with its comment: %',
        col.tbl, col.name, col.type_name, CASE WHEN col.not_null THEN 'NOT NULL' ELSE 'nullable' END,
        coalesce(col.default_value, 'none'), row_to_json(rule);
    END IF;
  END LOOP;

  -- Row-level arms only: every role holds on a new column exactly what it holds
  -- on a column of the same table that was there before, the API's role all
  -- three it writes with, and anon and service_role what they hold on the row.
  IF NOT has_column_privilege('app_authenticated', '"TeacherEmployments"', 'maxConsecutiveTeachingMinutes', 'SELECT')
     OR NOT has_column_privilege('app_authenticated', '"TeacherEmployments"', 'maxConsecutiveTeachingMinutes', 'UPDATE')
     OR NOT has_column_privilege('app_authenticated', '"TeacherEmployments"', 'consecutiveBreakMinutes', 'INSERT')
     OR NOT has_column_privilege('app_authenticated', '"LunchSettings"', 'generatorKeepsConsecutiveTeaching', 'UPDATE') THEN
    RAISE EXCEPTION 'stretch columns: app_authenticated cannot read and write the columns as it does the rows';
  END IF;
  FOR r IN
    SELECT ro.rolname, p.privilege, k.tbl, k.new_col, k.old_col
      FROM pg_roles ro
      CROSS JOIN unnest(ARRAY['SELECT', 'INSERT', 'UPDATE', 'REFERENCES']) AS p(privilege)
      CROSS JOIN (VALUES
        ('"TeacherEmployments"', 'maxConsecutiveTeachingMinutes', 'maxTeachingDaysPerWeek'),
        ('"TeacherEmployments"', 'consecutiveBreakMinutes', 'maxTeachingDaysPerWeek'),
        ('"LunchSettings"', 'generatorKeepsConsecutiveTeaching', 'lunchMinutes')
      ) AS k(tbl, new_col, old_col)
     WHERE ro.rolname IN ('app_authenticated', 'authenticated', 'anon', 'service_role')
  LOOP
    IF has_column_privilege(r.rolname, r.tbl, r.new_col, r.privilege)
       IS DISTINCT FROM has_column_privilege(r.rolname, r.tbl, r.old_col, r.privilege) THEN
      RAISE EXCEPTION 'stretch columns: % holds % on %.% as it does not on %', r.rolname, r.privilege, r.tbl, r.new_col, r.old_col;
    END IF;
  END LOOP;

  -- The three CHECKs exist, are validated, and are on the post.
  FOREACH what IN ARRAY ARRAY[
    'TeacherEmployments_maxConsecutiveTeachingMinutes_check',
    'TeacherEmployments_consecutiveBreakMinutes_check',
    'TeacherEmployments_consecutive_is_a_pair_check'
  ] LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_constraint
                    WHERE conrelid = '"TeacherEmployments"'::regclass AND conname = what AND contype = 'c' AND convalidated) THEN
      RAISE EXCEPTION 'stretch columns: the validated CHECK % is missing', what;
    END IF;
  END LOOP;

  -- THE WORK RULE HOLDS NEITHER. No column, no CHECK; and its trigger function
  -- is 20261123090000's: the cap's and the wish's sentence, a comparison of the
  -- two and not a word of the stretch, owned by the table's owner, SECURITY
  -- DEFINER with its search_path pinned, executable by nobody but the owner,
  -- and still fired by the trigger.
  IF EXISTS (SELECT 1 FROM pg_attribute a
              WHERE a.attrelid = '"TeacherWorkRules"'::regclass AND a.attnum > 0 AND NOT a.attisdropped
                AND a.attname IN ('maxConsecutiveTeachingMinutes', 'consecutiveBreakMinutes')) THEN
    RAISE EXCEPTION 'stretch columns: the work rule still holds a column of the stretch';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = '"TeacherWorkRules"'::regclass AND conname ILIKE '%consecutive%') THEN
    RAISE EXCEPTION 'stretch columns: the work rule still holds a CHECK of the stretch';
  END IF;
  SELECT p.prosrc, p.prosecdef, p.proconfig, p.proacl, p.proowner, tbl.relowner
    INTO fn
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace AND n.nspname = 'app'
    CROSS JOIN pg_class tbl
   WHERE p.proname = 'teacher_work_rules_day_is_planned' AND tbl.oid = '"TeacherWorkRules"'::regclass;
  IF fn IS NULL
     OR fn.prosrc ILIKE '%consecutive%' OR fn.prosrc ILIKE '%stretch%'
     OR position('RAISE EXCEPTION ''WORK_RULE_DAY_IS_PLANNED: dagstaket och den önskade lediga dagen sätts av en administratör som planerar''' IN fn.prosrc) = 0
     OR position('IF (cap_after IS DISTINCT FROM cap_before OR wish_after IS DISTINCT FROM wish_before)' IN fn.prosrc) = 0 THEN
    RAISE EXCEPTION 'stretch columns: the work rule''s trigger function is not 20261123090000''s: %', fn.prosrc;
  END IF;
  IF NOT fn.prosecdef OR fn.proowner <> fn.relowner
     OR NOT ('search_path=public, pg_temp' = ANY (coalesce(fn.proconfig, '{}')))
     OR fn.proacl IS NULL OR EXISTS (SELECT 1 FROM aclexplode(fn.proacl) a WHERE a.grantee <> fn.proowner) THEN
    RAISE EXCEPTION 'stretch columns: the work rule''s trigger function is not the owner''s SECURITY DEFINER, executable by the owner alone: %', row_to_json(fn);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger t
                  WHERE t.tgrelid = '"TeacherWorkRules"'::regclass AND t.tgname = 'TeacherWorkRules_day_is_planned' AND t.tgenabled = 'O') THEN
    RAISE EXCEPTION 'stretch columns: the work rule''s trigger is not enabled';
  END IF;

  -- Written by the fixtures as the owner before the columns: null and null on
  -- the post, beside its percentages, and the Skolregler row false.
  SELECT * INTO rule FROM "TeacherEmployments" WHERE id = post;
  IF rule."maxConsecutiveTeachingMinutes" IS NOT NULL OR rule."consecutiveBreakMinutes" IS NOT NULL
     OR rule."employmentPercent" IS DISTINCT FROM 80 OR rule."reductionPercent" IS DISTINCT FROM 10 THEN
    RAISE EXCEPTION 'stretch columns: the post written before the columns does not read null and null beside its percentages: %', row_to_json(rule);
  END IF;
  IF (SELECT "generatorKeepsConsecutiveTeaching" FROM "LunchSettings" WHERE "schoolId" = school) IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'stretch columns: the Skolregler row written before the switch does not read off';
  END IF;

  -- Each range's refusal, by the CHECK's own name: the half that is wrong
  -- beside a half that is right, so the pair CHECK has nothing to say.
  FOR c IN SELECT * FROM (VALUES
      ('"maxConsecutiveTeachingMinutes" = 25, "consecutiveBreakMinutes" = 10', 'TeacherEmployments_maxConsecutiveTeachingMinutes_check'),
      ('"maxConsecutiveTeachingMinutes" = 485, "consecutiveBreakMinutes" = 10', 'TeacherEmployments_maxConsecutiveTeachingMinutes_check'),
      -- Inside the range, off the five-minute grid the engine plans on.
      ('"maxConsecutiveTeachingMinutes" = 302, "consecutiveBreakMinutes" = 10', 'TeacherEmployments_maxConsecutiveTeachingMinutes_check'),
      ('"maxConsecutiveTeachingMinutes" = 0, "consecutiveBreakMinutes" = 10', 'TeacherEmployments_maxConsecutiveTeachingMinutes_check'),
      ('"maxConsecutiveTeachingMinutes" = -60, "consecutiveBreakMinutes" = 10', 'TeacherEmployments_maxConsecutiveTeachingMinutes_check'),
      ('"maxConsecutiveTeachingMinutes" = 60, "consecutiveBreakMinutes" = 3', 'TeacherEmployments_consecutiveBreakMinutes_check'),
      ('"maxConsecutiveTeachingMinutes" = 60, "consecutiveBreakMinutes" = 125', 'TeacherEmployments_consecutiveBreakMinutes_check'),
      ('"maxConsecutiveTeachingMinutes" = 60, "consecutiveBreakMinutes" = 12', 'TeacherEmployments_consecutiveBreakMinutes_check'),
      ('"maxConsecutiveTeachingMinutes" = 60, "consecutiveBreakMinutes" = 0', 'TeacherEmployments_consecutiveBreakMinutes_check'),
      -- One half without the other, from either side.
      ('"maxConsecutiveTeachingMinutes" = 60', 'TeacherEmployments_consecutive_is_a_pair_check'),
      ('"consecutiveBreakMinutes" = 10', 'TeacherEmployments_consecutive_is_a_pair_check')
    ) AS t(assignment, constraint_name)
  LOOP
    got := pg_temp.rls287_refusal(format('UPDATE "TeacherEmployments" SET %s WHERE id = %L', c.assignment, post));
    IF split_part(got, '|', 1) <> '23514' OR split_part(got, '|', 4) IS DISTINCT FROM c.constraint_name THEN
      RAISE EXCEPTION 'stretch columns: % was answered "%", not by %', c.assignment, got, c.constraint_name;
    END IF;
  END LOOP;
  -- A post that holds both cannot be made to hold one alone.
  UPDATE "TeacherEmployments" SET "maxConsecutiveTeachingMinutes" = 60, "consecutiveBreakMinutes" = 10 WHERE id = post;
  FOREACH what IN ARRAY ARRAY['"maxConsecutiveTeachingMinutes" = NULL', '"consecutiveBreakMinutes" = NULL'] LOOP
    got := pg_temp.rls287_refusal(format('UPDATE "TeacherEmployments" SET %s WHERE id = %L', what, post));
    IF split_part(got, '|', 1) <> '23514'
       OR split_part(got, '|', 4) IS DISTINCT FROM 'TeacherEmployments_consecutive_is_a_pair_check' THEN
      RAISE EXCEPTION 'stretch columns: clearing one half was answered "%", not by the pair CHECK', got;
    END IF;
  END LOOP;
  -- The same refusals on an INSERT, here the full administrator's own post.
  FOR c IN SELECT * FROM (VALUES
      ('25, 10', 'TeacherEmployments_maxConsecutiveTeachingMinutes_check'),
      ('60, 125', 'TeacherEmployments_consecutiveBreakMinutes_check'),
      ('60, NULL', 'TeacherEmployments_consecutive_is_a_pair_check'),
      ('NULL, 10', 'TeacherEmployments_consecutive_is_a_pair_check')
    ) AS t(figures, constraint_name)
  LOOP
    got := pg_temp.rls287_refusal(format(
      'INSERT INTO "TeacherEmployments" ("schoolId", "userId", "academicYearId", "employmentPercent", "maxConsecutiveTeachingMinutes", "consecutiveBreakMinutes", "updatedAt")
       VALUES (%L, %L, %L, 100, %s, now())', school, decider, year, c.figures));
    IF split_part(got, '|', 1) <> '23514' OR split_part(got, '|', 4) IS DISTINCT FROM c.constraint_name THEN
      RAISE EXCEPTION 'stretch columns: an INSERT of % was answered "%", not by %', c.figures, got, c.constraint_name;
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM "TeacherEmployments" WHERE "userId" = decider) THEN
    RAISE EXCEPTION 'stretch columns: a refused INSERT left a post behind';
  END IF;

  -- The ends and the middle go through, and are read back.
  -- Odd multiples of five too (35, 475, 15), so a step of ten is not the step.
  FOR c IN SELECT * FROM (VALUES (30, 5), (480, 120), (30, 120), (480, 5), (35, 10), (475, 115), (60, 10), (150, 15)) AS t(x, y) LOOP
    UPDATE "TeacherEmployments" SET "maxConsecutiveTeachingMinutes" = c.x, "consecutiveBreakMinutes" = c.y WHERE id = post;
    IF NOT EXISTS (SELECT 1 FROM "TeacherEmployments" WHERE id = post
                      AND "maxConsecutiveTeachingMinutes" = c.x AND "consecutiveBreakMinutes" = c.y) THEN
      RAISE EXCEPTION 'stretch columns: % and % were not stored', c.x, c.y;
    END IF;
  END LOOP;

  -- Beside the days and the percentages, not on them.
  UPDATE "TeacherEmployments" SET "maxTeachingDaysPerWeek" = 4 WHERE id = post;
  IF NOT EXISTS (SELECT 1 FROM "TeacherEmployments" WHERE id = post
                    AND "maxConsecutiveTeachingMinutes" = 150 AND "consecutiveBreakMinutes" = 15
                    AND "maxTeachingDaysPerWeek" = 4 AND "employmentPercent" = 80 AND "reductionPercent" = 10) THEN
    RAISE EXCEPTION 'stretch columns: writing the days moved the stretch or a percentage: %',
      (SELECT row_to_json(e) FROM "TeacherEmployments" e WHERE id = post);
  END IF;
  UPDATE "TeacherEmployments" SET "maxTeachingDaysPerWeek" = NULL WHERE id = post;
  IF NOT EXISTS (SELECT 1 FROM "TeacherEmployments" WHERE id = post
                    AND "maxConsecutiveTeachingMinutes" = 150 AND "consecutiveBreakMinutes" = 15) THEN
    RAISE EXCEPTION 'stretch columns: clearing the days moved the stretch';
  END IF;
  UPDATE "TeacherEmployments" SET "maxTeachingDaysPerWeek" = 4 WHERE id = post;
  UPDATE "TeacherEmployments" SET "maxConsecutiveTeachingMinutes" = NULL, "consecutiveBreakMinutes" = NULL WHERE id = post;
  IF NOT FOUND THEN RAISE EXCEPTION 'stretch columns: the full administrator could not clear both'; END IF;
  IF NOT EXISTS (SELECT 1 FROM "TeacherEmployments" WHERE id = post
                    AND "maxConsecutiveTeachingMinutes" IS NULL AND "consecutiveBreakMinutes" IS NULL
                    AND "maxTeachingDaysPerWeek" = 4 AND "employmentPercent" = 80 AND "reductionPercent" = 10) THEN
    RAISE EXCEPTION 'stretch columns: clearing the stretch moved the days or a percentage: %',
      (SELECT row_to_json(e) FROM "TeacherEmployments" e WHERE id = post);
  END IF;
  UPDATE "TeacherEmployments" SET "maxTeachingDaysPerWeek" = NULL WHERE id = post;

  -- The gateway's own write: INSERT … ON CONFLICT (school, user, year) DO UPDATE,
  -- here setting both on the teacher's post, moving them, leaving them out of
  -- its SET (what a PUT that leaves them out does) and clearing both.
  FOR c IN SELECT * FROM (VALUES (240, 15), (90, 10)) AS t(x, y) LOOP
    INSERT INTO "TeacherEmployments"
      ("schoolId", "userId", "academicYearId", "employmentPercent", "maxConsecutiveTeachingMinutes", "consecutiveBreakMinutes", "updatedAt")
    VALUES (school, teacher, year, 80, c.x, c.y, now())
    ON CONFLICT ("schoolId", "userId", "academicYearId") DO UPDATE SET
      "maxConsecutiveTeachingMinutes" = EXCLUDED."maxConsecutiveTeachingMinutes",
      "consecutiveBreakMinutes" = EXCLUDED."consecutiveBreakMinutes", "updatedAt" = EXCLUDED."updatedAt";
    IF NOT EXISTS (SELECT 1 FROM "TeacherEmployments" WHERE id = post
                      AND "maxConsecutiveTeachingMinutes" = c.x AND "consecutiveBreakMinutes" = c.y AND "reductionPercent" = 10) THEN
      RAISE EXCEPTION 'stretch columns: the upsert did not leave a limit of % and a break of %', c.x, c.y;
    END IF;
  END LOOP;
  INSERT INTO "TeacherEmployments" ("schoolId", "userId", "academicYearId", "employmentPercent", "updatedAt")
  VALUES (school, teacher, year, 70, now())
  ON CONFLICT ("schoolId", "userId", "academicYearId") DO UPDATE SET
    "employmentPercent" = EXCLUDED."employmentPercent", "updatedAt" = EXCLUDED."updatedAt";
  IF NOT EXISTS (SELECT 1 FROM "TeacherEmployments" WHERE id = post AND "employmentPercent" = 70
                    AND "maxConsecutiveTeachingMinutes" = 90 AND "consecutiveBreakMinutes" = 10) THEN
    RAISE EXCEPTION 'stretch columns: an upsert that leaves the two out of its SET did not leave them as they were';
  END IF;
  INSERT INTO "TeacherEmployments"
    ("schoolId", "userId", "academicYearId", "employmentPercent", "maxConsecutiveTeachingMinutes", "consecutiveBreakMinutes", "updatedAt")
  VALUES (school, teacher, year, 80, NULL, NULL, now())
  ON CONFLICT ("schoolId", "userId", "academicYearId") DO UPDATE SET
    "maxConsecutiveTeachingMinutes" = EXCLUDED."maxConsecutiveTeachingMinutes",
    "consecutiveBreakMinutes" = EXCLUDED."consecutiveBreakMinutes", "updatedAt" = EXCLUDED."updatedAt";
  IF NOT EXISTS (SELECT 1 FROM "TeacherEmployments" WHERE id = post
                    AND "maxConsecutiveTeachingMinutes" IS NULL AND "consecutiveBreakMinutes" IS NULL) THEN
    RAISE EXCEPTION 'stretch columns: the upsert did not clear both';
  END IF;

  -- An administrator who also has a post: one naming neither carries null and
  -- null, and one naming both carries them.
  INSERT INTO "TeacherEmployments" ("schoolId", "userId", "academicYearId", "employmentPercent", "updatedAt")
  VALUES (school, decider, year, 100, now());
  IF NOT EXISTS (SELECT 1 FROM "TeacherEmployments" WHERE "userId" = decider
                    AND "maxConsecutiveTeachingMinutes" IS NULL AND "consecutiveBreakMinutes" IS NULL) THEN
    RAISE EXCEPTION 'stretch columns: a post naming neither does not carry null and null';
  END IF;
  UPDATE "TeacherEmployments" SET "maxConsecutiveTeachingMinutes" = 120, "consecutiveBreakMinutes" = 20 WHERE "userId" = decider;
  IF NOT FOUND THEN RAISE EXCEPTION 'stretch columns: the full administrator could not set their own limit'; END IF;
  DELETE FROM "TeacherEmployments" WHERE "userId" = decider;
  IF NOT FOUND THEN RAISE EXCEPTION 'stretch columns: the full administrator could not remove their own post holding a limit'; END IF;

  -- The switch: NOT NULL, takes both values, and a fresh Skolregler row that
  -- names nothing reads off.
  got := pg_temp.rls287_refusal(format('UPDATE "LunchSettings" SET "generatorKeepsConsecutiveTeaching" = NULL WHERE "schoolId" = %L', school));
  IF split_part(got, '|', 1) <> '23502' THEN
    RAISE EXCEPTION 'stretch columns: clearing the switch was answered "%", not by NOT NULL', got;
  END IF;
  UPDATE "LunchSettings" SET "generatorKeepsConsecutiveTeaching" = true WHERE "schoolId" = school;
  IF NOT FOUND OR (SELECT "generatorKeepsConsecutiveTeaching" FROM "LunchSettings" WHERE "schoolId" = school) IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'stretch columns: the full administrator could not turn the switch on';
  END IF;
  DELETE FROM "LunchSettings" WHERE "schoolId" = school;
  IF NOT FOUND THEN RAISE EXCEPTION 'stretch columns: the full administrator could not remove the Skolregler row'; END IF;
  INSERT INTO "LunchSettings" ("schoolId", "lunchStartTime", "lunchEndTime", "lunchMinutes", "updatedAt")
  VALUES (school, '11:00', '13:00', 30, now());
  IF (SELECT "generatorKeepsConsecutiveTeaching" FROM "LunchSettings" WHERE "schoolId" = school) IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'stretch columns: a fresh Skolregler row naming nothing does not read off';
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 288: en lärares gräns för undervisning i följd är en HR-uppgift på
-- tjänsten: den läses av läraren själv och av ingen annan direkt, den skrivs
-- av den som beslutar och av ingen annan (20261218090000). Section 161's
-- reading of deltid in days, for the two columns, and then every role.
--
-- The limit ("maxConsecutiveTeachingMinutes") and the break
-- ("consecutiveBreakMinutes") may be an arbetsanpassning after sick leave, so
-- they sit on the post (TeacherEmployments) and not on the work rule, whose
-- rows every colleague reads. The post's arms are the whole of the protection
-- (no trigger asks anything), and section 288 holds each of them, role by role,
-- through the two roles a request can arrive as: app_authenticated, which is
-- how the gateway reads and writes, and authenticated, which is how PostgREST
-- would. In the matrix school, with a post for its teacher (111) holding 180
-- minutes and a break of 30, one for a colleague teacher (planted by the
-- expedition, who owns the roster) holding 240 and 15, and one for the full
-- administrator, holding none:
--
--   * THE ARMS, from the catalogue: the post and its history have exactly the
--     arms they had. Every one an administrator's is TO app_authenticated
--     alone, the teacher's own SELECT arm of each is the only arm anybody
--     else's role can use, and the insert, update and delete arms ask
--     app.current_user_decides() (the update's USING admits every
--     administrator, because a row lock needs it, and its WITH CHECK is what
--     refuses);
--   * THE COLLEAGUE (another TEACHER), as each role: reads no row of
--     another's post and no version of it, and writes none — an UPDATE
--     reaches no row, an INSERT or an upsert is refused by row security, a
--     DELETE reaches no row;
--   * THE TEACHER THEMSELF, as each role: reads their own limit on the post
--     and in its history, and writes nothing of it, the same four ways;
--   * AN ADMINISTRATOR WITHOUT HR-LÄS (the schemaläggare, the expedition and
--     the läsare) and ONE WITH IT (each of the three with HR-läs, the rektor
--     and the full administrator): DIRECTLY, as authenticated, they read NO
--     post and no version of any, whoever's, their own post included, because
--     the arms that show them a row are TO app_authenticated alone; and no
--     write of theirs, the deciders' included, changes anything. Through
--     app_authenticated every one of them is shown the row: the SQL layer
--     cannot hide a column, so the gateway is what leaves the HR columns out of
--     its answer for a reader without HR-läs (hideHr, hr-visibility.ts) and
--     the mask is the gateway's to keep, not this section's;
--   * WHO WRITES, through app_authenticated: only those who decide. The rektor
--     and the full administrator set, change and clear both by UPDATE and by
--     the upsert, and delete a post that holds them; the schemaläggare, the
--     expedition and the läsare, with or without HR-läs, are refused by the
--     update's WITH CHECK, the insert's and the upsert's (42501, row-level
--     security), and a DELETE reaches no row. HR-läs reads; it does not decide;
--   * THE HISTORY: a write of the limit alone makes exactly one version,
--     carrying it before (null) and after, as 161 holds for the days; the
--     administrators' arm on the history shows the version through the API's
--     role and none directly, the teacher's own arm shows them their own;
--   * the pupil and the guardian read no post and no version, as each role;
--   * the service principal's arm on the post is the API role's: it reads the
--     school's posts through app_authenticated (a provider that names its
--     columns) and none through authenticated, and writes none either way; the
--     sync reads none;
--   * nobody writes the history: a version inserted, rewritten or deleted is
--     refused for every role, the deciders included, by the table's privilege
--     (or, were a role given the privilege, by the trigger that keeps the
--     history append-only); nobody but the owner truncates, references or
--     maintains either table, and anon holds nothing on them.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000108')::text, true);

-- 'rows=N' of a statement that ran, else 'sqlstate|message|constraint'.
CREATE FUNCTION pg_temp.rls288_try(statement text) RETURNS text LANGUAGE plpgsql AS $$
DECLARE n bigint; st text; msg text; con text;
BEGIN
  EXECUTE statement;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN 'rows=' || n;
EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS st = RETURNED_SQLSTATE, msg = MESSAGE_TEXT, con = CONSTRAINT_NAME;
  RETURN st || '|' || msg || '|' || coalesce(con, '');
END $$;

-- Row security's refusal of a write: insufficient_privilege and its own words.
CREATE FUNCTION pg_temp.rls288_is_rls(got text) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$
  SELECT split_part(got, '|', 1) = '42501' AND got LIKE '%row-level security%'
$$;

-- THE ARMS, from the catalogue. Exactly these policies, for exactly these
-- roles and commands: an arm added, widened to authenticated or dropped fails
-- here by name, before any role is asked.
DO $$
DECLARE
  arm record;
  expected text;
  actual text;
BEGIN
  expected := $e$
    TeacherEmployments|teacher_employments_admin_delete|DELETE|{app_authenticated}
    TeacherEmployments|teacher_employments_admin_insert|INSERT|{app_authenticated}
    TeacherEmployments|teacher_employments_admin_select|SELECT|{app_authenticated}
    TeacherEmployments|teacher_employments_admin_update|UPDATE|{app_authenticated}
    TeacherEmployments|teacher_employments_service_select|SELECT|{app_authenticated}
    TeacherEmployments|teacher_employments_teacher_own_select|SELECT|{authenticated}
    TeacherEmploymentLogs|teacher_employment_logs_admin_select|SELECT|{app_authenticated}
    TeacherEmploymentLogs|teacher_employment_logs_teacher_own_select|SELECT|{authenticated}
  $e$;
  SELECT string_agg(l, E'\n' ORDER BY l COLLATE "C") INTO actual
    FROM (SELECT format('%s|%s|%s|%s', tablename, policyname, cmd, roles) AS l
            FROM pg_policies WHERE tablename IN ('TeacherEmployments', 'TeacherEmploymentLogs')) x;
  SELECT string_agg(l, E'\n' ORDER BY l COLLATE "C") INTO expected
    FROM (SELECT btrim(l) AS l FROM regexp_split_to_table(expected, E'\n') AS l WHERE btrim(l) <> '') x;
  IF actual IS DISTINCT FROM expected THEN
    RAISE EXCEPTION E'stretch post: the arms of the post and its history are not the ones this section holds:\n%', actual;
  END IF;
  -- Only the teacher's own SELECT arms are open to a role other than the API's.
  FOR arm IN SELECT * FROM pg_policies WHERE tablename IN ('TeacherEmployments', 'TeacherEmploymentLogs') LOOP
    IF arm.permissive <> 'PERMISSIVE' THEN
      RAISE EXCEPTION 'stretch post: % is not permissive', arm.policyname;
    END IF;
    IF arm.roles::text[] && ARRAY['public', 'anon', 'authenticated'] AND NOT (arm.cmd = 'SELECT' AND arm.policyname LIKE '%teacher_own_select') THEN
      RAISE EXCEPTION 'stretch post: % is open to a role other than the API''s', arm.policyname;
    END IF;
  END LOOP;
  -- Who may write: the decisions, in the insert's check, the update's check and the delete's using.
  IF (SELECT with_check FROM pg_policies WHERE policyname = 'teacher_employments_admin_insert') NOT LIKE '%current_user_decides%'
     OR (SELECT with_check FROM pg_policies WHERE policyname = 'teacher_employments_admin_update') NOT LIKE '%current_user_decides%'
     OR (SELECT qual FROM pg_policies WHERE policyname = 'teacher_employments_admin_delete') NOT LIKE '%current_user_decides%' THEN
    RAISE EXCEPTION 'stretch post: a write arm of the post does not ask who decides';
  END IF;
  -- Nobody writes the history; only the owner truncates, references or triggers; anon holds nothing.
  FOR arm IN
    SELECT ro.rolname, t.tbl, p.privilege
      FROM pg_roles ro
      CROSS JOIN (VALUES ('public."TeacherEmployments"'), ('public."TeacherEmploymentLogs"')) AS t(tbl)
      CROSS JOIN unnest(ARRAY['INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER', 'SELECT']) AS p(privilege)
     WHERE ro.rolname IN ('app_authenticated', 'authenticated', 'anon', 'service_role')
  LOOP
    IF has_table_privilege(arm.rolname, arm.tbl, arm.privilege) IS DISTINCT FROM (
         CASE
           WHEN arm.rolname = 'anon' THEN false
           WHEN arm.privilege = 'SELECT' THEN true
           WHEN arm.tbl = 'public."TeacherEmployments"' AND arm.privilege IN ('INSERT', 'UPDATE', 'DELETE')
                AND arm.rolname IN ('app_authenticated', 'authenticated') THEN true
           ELSE false
         END) THEN
      RAISE EXCEPTION 'stretch post: the table privilege % of % on % is not what the owner gave it', arm.privilege, arm.rolname, arm.tbl;
    END IF;
    IF arm.privilege <> 'SELECT' AND current_setting('server_version_num')::int >= 170000
       AND has_table_privilege(arm.rolname, arm.tbl, 'MAINTAIN') THEN
      RAISE EXCEPTION 'stretch post: % holds MAINTAIN on %', arm.rolname, arm.tbl;
    END IF;
  END LOOP;
  IF has_any_column_privilege('anon', 'public."TeacherEmployments"', 'SELECT')
     OR has_any_column_privilege('anon', 'public."TeacherEmploymentLogs"', 'SELECT') THEN
    RAISE EXCEPTION 'stretch post: anon reads a column of the post or its history';
  END IF;
END $$;

-- The expedition (PERSONAL) takes on a colleague, a teacher with no post yet.
DO $$
DECLARE
  school uuid := app.current_school_id();
BEGIN
  IF app.current_user_may('PLANERING', true) OR NOT app.current_user_may('PERSONAL', true)
     OR (SELECT slug FROM "Schools" WHERE id = school) IS DISTINCT FROM 'rls-roller-school' THEN
    RAISE EXCEPTION 'stretch post: expected the matrix school''s expedition (PERSONAL, not PLANERING)';
  END IF;
  INSERT INTO "Users" ("schoolId", email, "firstName", "lastName", role, "authId", "isActive", "updatedAt")
  VALUES (school, 'rls288-kollega@example.invalid', 'RLS288', 'Kollega', 'TEACHER',
          '00000000-0000-4000-8000-000000000288', true, now());
END $$;

-- The full administrator, who decides, gives the teacher's post a limit of 180
-- minutes and a break of 30, the colleague a post holding 240 and 15, and
-- their own post holds none. The teacher's version carries the limit alone.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
DO $$
DECLARE
  school uuid := app.current_school_id();
  admin uuid := app.current_user_id();
  teacher uuid := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000111');
  colleague uuid := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000288');
  post111 uuid;
  postc uuid;
  posta uuid;
  year uuid;
  versions bigint;
  logged record;
BEGIN
  IF NOT app.current_user_decides() OR app.current_user_role() IS DISTINCT FROM 'SCHOOL_ADMIN'
     OR (SELECT slug FROM "Schools" WHERE id = school) IS DISTINCT FROM 'rls-roller-school' THEN
    RAISE EXCEPTION 'stretch post: expected the matrix school''s full administrator, who decides';
  END IF;
  SELECT id, "academicYearId" INTO post111, year FROM "TeacherEmployments" WHERE "userId" = teacher;
  IF post111 IS NULL OR colleague IS NULL THEN
    RAISE EXCEPTION 'stretch post: the teacher''s post or the colleague is missing; fixtures did not run';
  END IF;

  SELECT count(*) INTO versions FROM "TeacherEmploymentLogs" WHERE "entityId" = post111;
  UPDATE "TeacherEmployments" SET "maxConsecutiveTeachingMinutes" = 180, "consecutiveBreakMinutes" = 30 WHERE id = post111;
  IF NOT FOUND THEN RAISE EXCEPTION 'stretch post: the full administrator could not set the teacher''s limit'; END IF;
  IF (SELECT count(*) FROM "TeacherEmploymentLogs" WHERE "entityId" = post111) <> versions + 1 THEN
    RAISE EXCEPTION 'stretch post: a write of the limit alone made % versions, not one',
      (SELECT count(*) FROM "TeacherEmploymentLogs" WHERE "entityId" = post111) - versions;
  END IF;
  SELECT action, before, after INTO logged FROM "TeacherEmploymentLogs"
   WHERE "entityId" = post111 ORDER BY version DESC LIMIT 1;
  IF logged.action IS DISTINCT FROM 'UPDATE'
     OR (logged.after ->> 'maxConsecutiveTeachingMinutes')::int IS DISTINCT FROM 180
     OR (logged.after ->> 'consecutiveBreakMinutes')::int IS DISTINCT FROM 30
     OR logged.before -> 'maxConsecutiveTeachingMinutes' IS DISTINCT FROM 'null'::jsonb
     OR logged.before -> 'consecutiveBreakMinutes' IS DISTINCT FROM 'null'::jsonb THEN
    RAISE EXCEPTION 'stretch post: the version holds % → %', logged.before, logged.after;
  END IF;

  INSERT INTO "TeacherEmployments"
    ("schoolId", "userId", "academicYearId", "employmentPercent", "maxConsecutiveTeachingMinutes", "consecutiveBreakMinutes", "updatedAt")
  VALUES (school, colleague, year, 100, 240, 15, now()) RETURNING id INTO postc;
  INSERT INTO "TeacherEmployments" ("schoolId", "userId", "academicYearId", "employmentPercent", "updatedAt")
  VALUES (school, admin, year, 100, now()) RETURNING id INTO posta;
  IF (SELECT action FROM "TeacherEmploymentLogs" WHERE "entityId" = postc ORDER BY version DESC LIMIT 1) IS DISTINCT FROM 'CREATE'
     OR ((SELECT after FROM "TeacherEmploymentLogs" WHERE "entityId" = postc ORDER BY version DESC LIMIT 1) ->> 'maxConsecutiveTeachingMinutes')::int
        IS DISTINCT FROM 240 THEN
    RAISE EXCEPTION 'stretch post: the colleague''s post was not logged holding its limit';
  END IF;
  PERFORM set_config('app.test_rls288', json_build_object(
    'school', school, 'year', year, 'teacher', teacher, 'colleague', colleague, 'admin', admin,
    'post111', post111, 'postc', postc, 'posta', posta,
    'planner', (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000107'))::text, true);
END $$;

-- EVERY ROLE READS. The post and its history, as each role the request can
-- arrive as. An administrator is shown the three posts through the API's role
-- (the gateway masks what a reader without HR-läs is not to see) and, through
-- PostgREST's role, none and no version; a teacher is shown their own post and
-- its versions through both and nobody else's; a pupil and a guardian nothing.
DO $$
DECLARE
  t jsonb := current_setting('app.test_rls288')::jsonb;
  post111 uuid := (t ->> 'post111')::uuid;
  postc uuid := (t ->> 'postc')::uuid;
  posta uuid := (t ->> 'posta')::uuid;
  actor record;
  via text;
  me uuid;
  n bigint;
  logs bigint;
  own_limit text;
  hr boolean;
BEGIN
  FOR actor IN SELECT * FROM (VALUES
      ('00000000-0000-4000-8000-000000000105', 'the full administrator', 'ADMIN', true, true),
      ('00000000-0000-4000-8000-000000000106', 'the rektor', 'ADMIN', true, true),
      ('00000000-0000-4000-8000-000000000107', 'the schemaläggare', 'ADMIN', false, false),
      ('00000000-0000-4000-8000-000000000109', 'the schemaläggare with HR-läs', 'ADMIN', false, true),
      ('00000000-0000-4000-8000-000000000108', 'the expedition', 'ADMIN', false, false),
      ('00000000-0000-4000-8000-000000000110', 'the expedition with HR-läs', 'ADMIN', false, true),
      ('00000000-0000-4000-8000-000000000115', 'the läsare', 'ADMIN', false, false),
      ('00000000-0000-4000-8000-000000000116', 'the läsare with HR-läs', 'ADMIN', false, true),
      ('00000000-0000-4000-8000-000000000111', 'the teacher', 'TEACHER', false, false),
      ('00000000-0000-4000-8000-000000000288', 'the colleague', 'TEACHER', false, false),
      ('00000000-0000-4000-8000-000000000112', 'the pupil', 'NONE', false, false),
      ('00000000-0000-4000-8000-000000000113', 'the guardian', 'NONE', false, false)
    ) AS x(auth_id, label, kind, decides, reads_hr)
  LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', actor.auth_id)::text, true);
    me := app.current_user_id();
    IF me IS NULL THEN RAISE EXCEPTION 'stretch post: % has no user in the matrix school', actor.label; END IF;
    IF actor.kind = 'ADMIN' THEN
      -- The fixtures' flags, as this section assumes them: who decides, and who
      -- reads HR (the deciders, and any administrator flagged with HR-läs).
      hr := app.current_user_decides() OR coalesce((SELECT "hrRead" FROM "Users" WHERE id = me), false);
      IF app.current_user_role() IS DISTINCT FROM 'SCHOOL_ADMIN' OR app.current_user_decides() IS DISTINCT FROM actor.decides
         OR hr IS DISTINCT FROM actor.reads_hr THEN
        RAISE EXCEPTION 'stretch post: % is not an administrator who decides = %, reads HR = % (%)',
          actor.label, actor.decides, actor.reads_hr, hr;
      END IF;
    ELSIF actor.kind = 'TEACHER' AND app.current_user_role() IS DISTINCT FROM 'TEACHER' THEN
      RAISE EXCEPTION 'stretch post: % is not a teacher', actor.label;
    END IF;

    FOREACH via IN ARRAY ARRAY['authenticated', 'app_authenticated'] LOOP
      EXECUTE format('SET LOCAL ROLE %I', via);
      IF current_user <> via THEN RAISE EXCEPTION 'stretch post: running as %, not %', current_user, via; END IF;
      SELECT count(*) INTO n FROM "TeacherEmployments";
      SELECT count(*) INTO logs FROM "TeacherEmploymentLogs";
      IF actor.kind = 'NONE' OR (actor.kind = 'ADMIN' AND via = 'authenticated') THEN
        -- PostgREST's role: no post and no version of anybody, an administrator's
        -- own included, because the arms that show an administrator a row are TO
        -- app_authenticated alone. A pupil and a guardian have no arm at all.
        IF n <> 0 OR logs <> 0 THEN
          RAISE EXCEPTION 'stretch post: as % % reads % posts and % versions', via, actor.label, n, logs;
        END IF;
      ELSIF actor.kind = 'ADMIN' THEN
        -- The API's role: the three posts, each with its limit as the owner
        -- left it. The SQL layer shows the row whole; hideHr is the gateway's.
        IF (SELECT "maxConsecutiveTeachingMinutes" || '/' || "consecutiveBreakMinutes" FROM "TeacherEmployments" WHERE id = post111) IS DISTINCT FROM '180/30'
           OR (SELECT "maxConsecutiveTeachingMinutes" || '/' || "consecutiveBreakMinutes" FROM "TeacherEmployments" WHERE id = postc) IS DISTINCT FROM '240/15'
           OR (SELECT "maxConsecutiveTeachingMinutes" IS NULL AND "consecutiveBreakMinutes" IS NULL FROM "TeacherEmployments" WHERE id = posta) IS DISTINCT FROM true THEN
          RAISE EXCEPTION 'stretch post: as % % does not read the three posts'' limits: %', via, actor.label,
            (SELECT string_agg(coalesce("maxConsecutiveTeachingMinutes"::text, '-') || '/' || coalesce("consecutiveBreakMinutes"::text, '-'), ' ' ORDER BY id)
               FROM "TeacherEmployments" WHERE id IN (post111, postc, posta));
        END IF;
        IF (SELECT count(*) FROM "TeacherEmploymentLogs"
             WHERE "entityId" = post111 AND (after ->> 'maxConsecutiveTeachingMinutes')::int = 180 AND action = 'UPDATE') <> 1
           OR (SELECT count(*) FROM "TeacherEmploymentLogs"
                WHERE "entityId" = postc AND (after ->> 'maxConsecutiveTeachingMinutes')::int = 240 AND action = 'CREATE') <> 1 THEN
          RAISE EXCEPTION 'stretch post: as % % does not read the versions that hold the limits', via, actor.label;
        END IF;
      ELSE
        -- A teacher: their own post and its versions, through both roles, and
        -- not one row or version of anybody else's.
        own_limit := CASE WHEN me = (t ->> 'teacher')::uuid THEN '180/30' ELSE '240/15' END;
        IF n <> 1 OR (SELECT "userId" FROM "TeacherEmployments") IS DISTINCT FROM me
           OR (SELECT "maxConsecutiveTeachingMinutes" || '/' || "consecutiveBreakMinutes" FROM "TeacherEmployments") IS DISTINCT FROM own_limit THEN
          RAISE EXCEPTION 'stretch post: as % % reads % posts, not their own with %', via, actor.label, n, own_limit;
        END IF;
        IF EXISTS (SELECT 1 FROM "TeacherEmploymentLogs" WHERE "userId" <> me) THEN
          RAISE EXCEPTION 'stretch post: as % % reads a version of somebody else''s post', via, actor.label;
        END IF;
        -- ... among them the version that holds the limit.
        IF (SELECT count(*) FROM "TeacherEmploymentLogs"
             WHERE "userId" = me AND (after ->> 'maxConsecutiveTeachingMinutes')::int = split_part(own_limit, '/', 1)::int) <> 1 THEN
          RAISE EXCEPTION 'stretch post: as % % does not read the one version of their own post that holds their limit', via, actor.label;
        END IF;
      END IF;
    END LOOP;
    SET LOCAL ROLE app_authenticated;
  END LOOP;
END $$;

-- EVERY ROLE WRITES. Five statements at the teacher's post, each as every role
-- through each of the two roles a request can arrive as:
--   set both     UPDATE … SET limit, break
--   clear both   UPDATE … SET NULL, NULL
--   an upsert    INSERT … ON CONFLICT DO UPDATE, the statement the gateway writes
--   a fresh post INSERT of a post for somebody who has none (the schemaläggare)
--   delete       DELETE of the post
-- Those who decide write through the API's role (the next block). Everyone else
-- — every administrator through PostgREST's role, a deciding one included, and
-- the administrators who do not decide through the API's, and every teacher,
-- pupil and guardian through either — changes nothing. What they are answered
-- depends on where the refusal sits:
--   * no arm admits the row to a write (authenticated has no write arm at all,
--     and a teacher is no administrator): an UPDATE or a DELETE reaches no row;
--   * an INSERT is checked before it is looked at as an update, so a fresh post
--     and an upsert are refused by row security (42501) in both roles;
--   * an administrator who does not decide, through the API's role, reaches the
--     row (the update arm's USING admits every administrator, which a row lock
--     needs) and is refused by its WITH CHECK, which asks who decides (42501);
--     their DELETE finds the delete arm's USING false and reaches no row.
DO $$
DECLARE
  t jsonb := current_setting('app.test_rls288')::jsonb;
  school uuid := (t ->> 'school')::uuid;
  year uuid := (t ->> 'year')::uuid;
  post111 uuid := (t ->> 'post111')::uuid;
  teacher uuid := (t ->> 'teacher')::uuid;
  planner uuid := (t ->> 'planner')::uuid;
  actor record;
  via text;
  got text;
  c record;
  expect_rls boolean;
BEGIN
  FOR actor IN SELECT * FROM (VALUES
      ('00000000-0000-4000-8000-000000000105', 'the full administrator', 'ADMIN', true),
      ('00000000-0000-4000-8000-000000000106', 'the rektor', 'ADMIN', true),
      ('00000000-0000-4000-8000-000000000107', 'the schemaläggare', 'ADMIN', false),
      ('00000000-0000-4000-8000-000000000109', 'the schemaläggare with HR-läs', 'ADMIN', false),
      ('00000000-0000-4000-8000-000000000108', 'the expedition', 'ADMIN', false),
      ('00000000-0000-4000-8000-000000000110', 'the expedition with HR-läs', 'ADMIN', false),
      ('00000000-0000-4000-8000-000000000115', 'the läsare', 'ADMIN', false),
      ('00000000-0000-4000-8000-000000000116', 'the läsare with HR-läs', 'ADMIN', false),
      ('00000000-0000-4000-8000-000000000111', 'the teacher', 'TEACHER', false),
      ('00000000-0000-4000-8000-000000000288', 'the colleague', 'TEACHER', false),
      ('00000000-0000-4000-8000-000000000112', 'the pupil', 'NONE', false),
      ('00000000-0000-4000-8000-000000000113', 'the guardian', 'NONE', false)
    ) AS x(auth_id, label, kind, decides)
  LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', actor.auth_id)::text, true);
    FOREACH via IN ARRAY ARRAY['authenticated', 'app_authenticated'] LOOP
      -- The deciders write posts through the API's role: the next block. The
      -- history is refused them as everybody, in this loop.
      EXECUTE format('SET LOCAL ROLE %I', via);
      IF current_user <> via THEN RAISE EXCEPTION 'stretch post: running as %, not %', current_user, via; END IF;
      -- Row security's answer to the two UPDATEs and the DELETE.
      expect_rls := via = 'app_authenticated' AND actor.kind = 'ADMIN';
      FOR c IN SELECT * FROM (VALUES
          ('setting both', true,
           format('UPDATE "TeacherEmployments" SET "maxConsecutiveTeachingMinutes" = 300, "consecutiveBreakMinutes" = 20 WHERE id = %L', post111)),
          ('clearing both', true,
           format('UPDATE "TeacherEmployments" SET "maxConsecutiveTeachingMinutes" = NULL, "consecutiveBreakMinutes" = NULL WHERE id = %L', post111)),
          ('an upsert setting both', false,
           format('INSERT INTO "TeacherEmployments" ("schoolId", "userId", "academicYearId", "employmentPercent", "maxConsecutiveTeachingMinutes", "consecutiveBreakMinutes", "updatedAt")
                   VALUES (%L, %L, %L, 80, 300, 20, now())
                   ON CONFLICT ("schoolId", "userId", "academicYearId") DO UPDATE SET
                     "maxConsecutiveTeachingMinutes" = EXCLUDED."maxConsecutiveTeachingMinutes",
                     "consecutiveBreakMinutes" = EXCLUDED."consecutiveBreakMinutes", "updatedAt" = EXCLUDED."updatedAt"', school, teacher, year)),
          ('a fresh post carrying both', false,
           format('INSERT INTO "TeacherEmployments" ("schoolId", "userId", "academicYearId", "employmentPercent", "maxConsecutiveTeachingMinutes", "consecutiveBreakMinutes", "updatedAt")
                   VALUES (%L, %L, %L, 100, 60, 10, now())', school, planner, year)),
          ('deleting the post', false, format('DELETE FROM "TeacherEmployments" WHERE id = %L', post111)),
          -- The history is nobody's to rewrite: no role holds a write privilege
          -- on it, so the answer is the privilege's and not a row's.
          ('forging a version', false,
           format('INSERT INTO "TeacherEmploymentLogs" ("schoolId", "userId", "academicYearId", version, entity, "entityId", action, after)
                   VALUES (%L, %L, %L, 99, ''EMPLOYMENT'', %L, ''UPDATE'', ''{"maxConsecutiveTeachingMinutes": 300}'')', school, teacher, year, post111)),
          ('rewriting a version', false, 'UPDATE "TeacherEmploymentLogs" SET "after" = NULL'),
          ('deleting a version', false, 'DELETE FROM "TeacherEmploymentLogs"')
        ) AS s(what, updates, statement)
      LOOP
        CONTINUE WHEN actor.decides AND via = 'app_authenticated' AND c.what NOT IN ('forging a version', 'rewriting a version', 'deleting a version');
        got := pg_temp.rls288_try(c.statement);
        IF c.what IN ('forging a version', 'rewriting a version', 'deleting a version') THEN
          IF split_part(got, '|', 1) <> '42501' OR got NOT LIKE '%permission denied for table TeacherEmploymentLogs%' THEN
            RAISE EXCEPTION 'stretch post: % by % as % was answered "%", not by the table''s privilege', c.what, actor.label, via, got;
          END IF;
        ELSIF c.what IN ('an upsert setting both', 'a fresh post carrying both') THEN
          IF NOT pg_temp.rls288_is_rls(got) THEN
            RAISE EXCEPTION 'stretch post: % by % as % was answered "%", not by row security', c.what, actor.label, via, got;
          END IF;
        ELSIF c.updates AND expect_rls THEN
          IF NOT pg_temp.rls288_is_rls(got) THEN
            RAISE EXCEPTION 'stretch post: % by % as % was answered "%", not by the update arm''s check', c.what, actor.label, via, got;
          END IF;
        ELSIF got IS DISTINCT FROM 'rows=0' THEN
          RAISE EXCEPTION 'stretch post: % by % as % was answered "%", not by reaching no row', c.what, actor.label, via, got;
        END IF;
      END LOOP;
    END LOOP;
    SET LOCAL ROLE app_authenticated;
  END LOOP;
END $$;

-- WHO WRITES: those who decide, as the API's role. The rektor and the full
-- administrator set, change and clear both by UPDATE and by the upsert, each
-- leaving the version the history shows, and put the post back as it was.
DO $$
DECLARE
  t jsonb := current_setting('app.test_rls288')::jsonb;
  school uuid := (t ->> 'school')::uuid;
  year uuid := (t ->> 'year')::uuid;
  post111 uuid := (t ->> 'post111')::uuid;
  teacher uuid := (t ->> 'teacher')::uuid;
  who text;
  versions bigint;
  got text;
BEGIN
  FOREACH who IN ARRAY ARRAY['00000000-0000-4000-8000-000000000105', '00000000-0000-4000-8000-000000000106'] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', who)::text, true);
    SET LOCAL ROLE app_authenticated;
    IF NOT app.current_user_decides() THEN RAISE EXCEPTION 'stretch post: % does not decide', who; END IF;
    SELECT count(*) INTO versions FROM "TeacherEmploymentLogs" WHERE "entityId" = post111;

    got := pg_temp.rls288_try(format(
      'UPDATE "TeacherEmployments" SET "maxConsecutiveTeachingMinutes" = 300, "consecutiveBreakMinutes" = 20 WHERE id = %L', post111));
    IF got <> 'rows=1' OR NOT EXISTS (SELECT 1 FROM "TeacherEmployments" WHERE id = post111
                                         AND "maxConsecutiveTeachingMinutes" = 300 AND "consecutiveBreakMinutes" = 20) THEN
      RAISE EXCEPTION 'stretch post: % could not move the limit: %', who, got;
    END IF;
    got := pg_temp.rls288_try(format(
      'UPDATE "TeacherEmployments" SET "maxConsecutiveTeachingMinutes" = NULL, "consecutiveBreakMinutes" = NULL WHERE id = %L', post111));
    IF got <> 'rows=1' OR NOT EXISTS (SELECT 1 FROM "TeacherEmployments" WHERE id = post111
                                         AND "maxConsecutiveTeachingMinutes" IS NULL AND "consecutiveBreakMinutes" IS NULL) THEN
      RAISE EXCEPTION 'stretch post: % could not clear the limit: %', who, got;
    END IF;
    got := pg_temp.rls288_try(format(
      'INSERT INTO "TeacherEmployments" ("schoolId", "userId", "academicYearId", "employmentPercent", "maxConsecutiveTeachingMinutes", "consecutiveBreakMinutes", "updatedAt")
       VALUES (%L, %L, %L, 80, 150, 10, now())
       ON CONFLICT ("schoolId", "userId", "academicYearId") DO UPDATE SET
         "maxConsecutiveTeachingMinutes" = EXCLUDED."maxConsecutiveTeachingMinutes",
         "consecutiveBreakMinutes" = EXCLUDED."consecutiveBreakMinutes", "updatedAt" = EXCLUDED."updatedAt"', school, teacher, year));
    IF got <> 'rows=1' OR NOT EXISTS (SELECT 1 FROM "TeacherEmployments" WHERE id = post111
                                         AND "maxConsecutiveTeachingMinutes" = 150 AND "consecutiveBreakMinutes" = 10) THEN
      RAISE EXCEPTION 'stretch post: the upsert of % did not leave 150 and 10: %', who, got;
    END IF;
    -- Three writes, three versions: each carries the limit as it stood.
    IF (SELECT count(*) FROM "TeacherEmploymentLogs" WHERE "entityId" = post111) <> versions + 3
       OR (SELECT (after ->> 'maxConsecutiveTeachingMinutes')::int FROM "TeacherEmploymentLogs"
            WHERE "entityId" = post111 ORDER BY version DESC LIMIT 1) IS DISTINCT FROM 150
       OR (SELECT after -> 'maxConsecutiveTeachingMinutes' FROM "TeacherEmploymentLogs"
            WHERE "entityId" = post111 ORDER BY version DESC OFFSET 1 LIMIT 1) IS DISTINCT FROM 'null'::jsonb THEN
      RAISE EXCEPTION 'stretch post: the three writes of % did not leave three versions carrying the limit as it stood', who;
    END IF;
    UPDATE "TeacherEmployments" SET "maxConsecutiveTeachingMinutes" = 180, "consecutiveBreakMinutes" = 30 WHERE id = post111;
  END LOOP;
END $$;

-- Nothing the refused wrote is there: the three posts and the schemaläggare's
-- missing one are as they were planted.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
DO $$
DECLARE
  t jsonb := current_setting('app.test_rls288')::jsonb;
BEGIN
  IF (SELECT "maxConsecutiveTeachingMinutes" || '/' || "consecutiveBreakMinutes" FROM "TeacherEmployments" WHERE id = (t ->> 'post111')::uuid) IS DISTINCT FROM '180/30'
     OR (SELECT "maxConsecutiveTeachingMinutes" || '/' || "consecutiveBreakMinutes" FROM "TeacherEmployments" WHERE id = (t ->> 'postc')::uuid) IS DISTINCT FROM '240/15'
     OR (SELECT "maxConsecutiveTeachingMinutes" IS NOT NULL OR "consecutiveBreakMinutes" IS NOT NULL FROM "TeacherEmployments" WHERE id = (t ->> 'posta')::uuid) THEN
    RAISE EXCEPTION 'stretch post: a write that was refused moved a limit after all';
  END IF;
  IF EXISTS (SELECT 1 FROM "TeacherEmployments" WHERE "userId" = (t ->> 'planner')::uuid) THEN
    RAISE EXCEPTION 'stretch post: a refused fresh post is there after all';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM "TeacherEmployments" WHERE id = (t ->> 'post111')::uuid) THEN
    RAISE EXCEPTION 'stretch post: a refused DELETE took the teacher''s post';
  END IF;
END $$;

-- The deciders delete a post that holds a limit, and the history keeps the
-- version that says what it held, for the colleague's own arm to show them;
-- what the deletion left is read by the colleague both ways and by no
-- administrator directly. The rektor deletes the colleague's and the full
-- administrator's own posts; PostgREST's role, as the rektor, deletes none.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000106')::text, true);
DO $$
DECLARE
  t jsonb := current_setting('app.test_rls288')::jsonb;
  got text;
BEGIN
  SET LOCAL ROLE authenticated;
  got := pg_temp.rls288_try(format('DELETE FROM "TeacherEmployments" WHERE id = %L', t ->> 'postc'));
  IF got <> 'rows=0' THEN RAISE EXCEPTION 'stretch post: the rektor deleted a post as authenticated: %', got; END IF;
  SET LOCAL ROLE app_authenticated;
  got := pg_temp.rls288_try(format('DELETE FROM "TeacherEmployments" WHERE id = %L', t ->> 'postc'));
  IF got <> 'rows=1' THEN RAISE EXCEPTION 'stretch post: the rektor could not delete a post holding a limit: %', got; END IF;
  got := pg_temp.rls288_try(format('DELETE FROM "TeacherEmployments" WHERE id = %L', t ->> 'posta'));
  IF got <> 'rows=1' THEN RAISE EXCEPTION 'stretch post: the rektor could not delete a post holding none: %', got; END IF;
  IF (SELECT (before ->> 'maxConsecutiveTeachingMinutes')::int FROM "TeacherEmploymentLogs"
       WHERE "entityId" = (t ->> 'postc')::uuid AND action = 'DELETE') IS DISTINCT FROM 240 THEN
    RAISE EXCEPTION 'stretch post: the deletion of a post holding a limit did not log the limit it held';
  END IF;
END $$;
DO $$
DECLARE
  t jsonb := current_setting('app.test_rls288')::jsonb;
  who text;
  via text;
BEGIN
  -- The colleague, whose post is gone, reads their own versions through both
  -- roles, the deletion among them; the teacher reads none of them.
  FOREACH who IN ARRAY ARRAY['00000000-0000-4000-8000-000000000288', '00000000-0000-4000-8000-000000000111'] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', who)::text, true);
    FOREACH via IN ARRAY ARRAY['authenticated', 'app_authenticated'] LOOP
      EXECUTE format('SET LOCAL ROLE %I', via);
      IF EXISTS (SELECT 1 FROM "TeacherEmployments" WHERE id = (t ->> 'postc')::uuid) THEN
        RAISE EXCEPTION 'stretch post: as % somebody reads the colleague''s deleted post', via;
      END IF;
      IF (SELECT count(*) FROM "TeacherEmploymentLogs" WHERE "entityId" = (t ->> 'postc')::uuid AND action = 'DELETE')
         IS DISTINCT FROM (CASE WHEN who LIKE '%288' THEN 1 ELSE 0 END) THEN
        RAISE EXCEPTION 'stretch post: as % %''s read of the colleague''s deletion is wrong', via, who;
      END IF;
    END LOOP;
    SET LOCAL ROLE app_authenticated;
  END LOOP;
END $$;

-- The service principal and the sync. The service principal's arm on the post
-- is the API role's, so it reads the school's posts through app_authenticated
-- (the provider that uses it names the columns it needs) and none through
-- authenticated; it reads no version of one, and writes nothing either way.
-- The sync has no arm on the post: it reads none.
DO $$
DECLARE
  t jsonb := current_setting('app.test_rls288')::jsonb;
  school uuid := (t ->> 'school')::uuid;
  via text;
  setting text;
  n bigint;
  others bigint;
  got text;
BEGIN
  PERFORM set_config('request.jwt.claims', '', true);
  FOREACH setting IN ARRAY ARRAY['app.service_school_id', 'app.sync_school_id'] LOOP
    PERFORM set_config(setting, school::text, true);
    FOREACH via IN ARRAY ARRAY['authenticated', 'app_authenticated'] LOOP
      EXECUTE format('SET LOCAL ROLE %I', via);
      SELECT count(*), count(*) FILTER (WHERE "schoolId" <> school) INTO n, others FROM "TeacherEmployments";
      IF others <> 0 THEN RAISE EXCEPTION 'stretch post: % as % reads another school''s post', setting, via; END IF;
      IF n > 0 AND NOT (setting = 'app.service_school_id' AND via = 'app_authenticated') THEN
        RAISE EXCEPTION 'stretch post: % as % reads % posts', setting, via, n;
      END IF;
      IF n = 0 AND setting = 'app.service_school_id' AND via = 'app_authenticated' THEN
        RAISE EXCEPTION 'stretch post: the service principal reads no post as app_authenticated';
      END IF;
      IF EXISTS (SELECT 1 FROM "TeacherEmploymentLogs") THEN
        RAISE EXCEPTION 'stretch post: % as % reads a version of a post', setting, via;
      END IF;
      got := pg_temp.rls288_try('UPDATE "TeacherEmployments" SET "maxConsecutiveTeachingMinutes" = 300, "consecutiveBreakMinutes" = 20');
      IF got <> 'rows=0' THEN RAISE EXCEPTION 'stretch post: % as % wrote a limit: %', setting, via, got; END IF;
      got := pg_temp.rls288_try('DELETE FROM "TeacherEmployments"');
      IF got <> 'rows=0' THEN RAISE EXCEPTION 'stretch post: % as % deleted a post: %', setting, via, got; END IF;
      got := pg_temp.rls288_try(format(
        'INSERT INTO "TeacherEmployments" ("schoolId", "userId", "academicYearId", "employmentPercent", "updatedAt") VALUES (%L, %L, %L, 100, now())',
        school, t ->> 'planner', t ->> 'year'));
      IF NOT pg_temp.rls288_is_rls(got) THEN RAISE EXCEPTION 'stretch post: % as % wrote a post: %', setting, via, got; END IF;
    END LOOP;
    SET LOCAL ROLE app_authenticated;
    PERFORM set_config(setting, '', true);
  END LOOP;
END $$;

-- THE CAP AND THE WISH STILL SIT ON THE WORK RULE, and their trigger
-- (app.teacher_work_rules_day_is_planned, 20261123090000) asks `may this person
-- WRITE planering`. An administrator who only READS planering and also teaches
-- (the expedition, 108, and the läsare, 115) reads every area, has a work rule
-- of their own and is a SCHOOL_ADMIN, so the row's arm admits them on their own
-- row. Asked as a read, the question answers yes for both and the trigger lets
-- everything through, to be refused only afterwards by the area's write check on
-- the new row (42501); asked as a write it answers with its own sentence
-- (AR403), which is what proves it was asked. The review of the first build
-- (mutant T6) found no row that holds this; it is held here, by the cap and by
-- the wish. The limit on teaching in a row is the post's and is held above.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000107')::text, true);
CREATE FUNCTION pg_temp.rls288_refusal(statement text) RETURNS text LANGUAGE plpgsql AS $$
DECLARE st text; msg text; det text;
BEGIN
  EXECUTE statement;
  RETURN 'none';
EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS st = RETURNED_SQLSTATE, msg = MESSAGE_TEXT, det = PG_EXCEPTION_DETAIL;
  RETURN st || '|' || msg || '|' || coalesce(det, '') || '|';
END $$;
DO $$
DECLARE
  who text;
  school uuid := (SELECT "schoolId" FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000107' LIMIT 1);
BEGIN
  FOREACH who IN ARRAY ARRAY['00000000-0000-4000-8000-000000000108', '00000000-0000-4000-8000-000000000115'] LOOP
    INSERT INTO "TeacherWorkRules" ("schoolId", "userId", "maxTeachingMinutesPerDay", "preferredFreeDayOfWeek", "updatedAt")
    VALUES (school, (SELECT id FROM "Users" WHERE "authId" = who::uuid AND "schoolId" = school), 300, 5, now());
  END LOOP;
END $$;
DO $$
DECLARE
  who text;
  me uuid;
  school uuid := (SELECT "schoolId" FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000107' LIMIT 1);
  planned constant text := 'AR403|WORK_RULE_DAY_IS_PLANNED: dagstaket och den önskade lediga dagen sätts av en administratör som planerar|area=PLANERING|';
  got text;
  c record;
BEGIN
  FOREACH who IN ARRAY ARRAY['00000000-0000-4000-8000-000000000108', '00000000-0000-4000-8000-000000000115'] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', who)::text, true);
    me := app.current_user_id();
    IF app.current_user_may('PLANERING', true) OR NOT app.current_user_may('PLANERING', false) THEN
      RAISE EXCEPTION 'cap trigger: % should read PLANERING and not write it', who;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM "TeacherWorkRules" WHERE "userId" = me AND "maxTeachingMinutesPerDay" = 300 AND "preferredFreeDayOfWeek" = 5) THEN
      RAISE EXCEPTION 'cap trigger: % does not read the row planted for them', who;
    END IF;
    FOR c IN SELECT * FROM (VALUES
        ('raising the cap', 'UPDATE "TeacherWorkRules" SET "maxTeachingMinutesPerDay" = 400 WHERE "userId" = %1$L'),
        ('moving the wish', 'UPDATE "TeacherWorkRules" SET "preferredFreeDayOfWeek" = 3 WHERE "userId" = %1$L'),
        ('clearing both', 'UPDATE "TeacherWorkRules" SET "maxTeachingMinutesPerDay" = NULL, "preferredFreeDayOfWeek" = NULL WHERE "userId" = %1$L')
      ) AS x(what, statement)
    LOOP
      got := pg_temp.rls288_refusal(format(c.statement, me));
      IF got IS DISTINCT FROM planned THEN
        RAISE EXCEPTION 'cap trigger: % by % on their own row was answered "%", not by the planner''s sentence', c.what, who, got;
      END IF;
    END LOOP;
    -- The upsert's INSERT is checked against the area's write before the
    -- conflict is looked at: refused by row security, never an update.
    got := pg_temp.rls288_refusal(format(
      'INSERT INTO "TeacherWorkRules" ("schoolId", "userId", "maxTeachingMinutesPerDay", "updatedAt") VALUES (%L, %L, 400, now())
       ON CONFLICT ("userId") DO UPDATE SET "maxTeachingMinutesPerDay" = EXCLUDED."maxTeachingMinutesPerDay", "updatedAt" = EXCLUDED."updatedAt"',
      school, me));
    IF split_part(got, '|', 1) <> '42501' OR got NOT LIKE '%row-level security%' THEN
      RAISE EXCEPTION 'cap trigger: an upsert by % on their own row was answered "%", not by row security', who, got;
    END IF;
    DELETE FROM "TeacherWorkRules" WHERE "userId" = me;
    IF FOUND THEN RAISE EXCEPTION 'cap trigger: % deleted their own row holding the cap and the wish', who; END IF;
  END LOOP;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000107')::text, true);
  IF (SELECT count(*) FROM "TeacherWorkRules" r JOIN "Users" u ON u.id = r."userId"
       WHERE u."authId" IN ('00000000-0000-4000-8000-000000000108', '00000000-0000-4000-8000-000000000115')
         AND u."schoolId" = school AND r."maxTeachingMinutesPerDay" = 300 AND r."preferredFreeDayOfWeek" = 5) <> 2 THEN
    RAISE EXCEPTION 'cap trigger: an administrator who only reads planering moved their own cap or wish after all';
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 289: brytaren för sammanhängande undervisning är Skolreglernas och
-- skrivs av den som planerar (LunchSettings."generatorKeepsConsecutiveTeaching",
-- 20261218090000), och migreringen är additiv bredvid API:t som redan körs.
-- Section 283's reading of the pupils' håltimmar switch, line for line, and
-- then the old API's own statements.
--
-- In the matrix school, whose Skolregler row the fixtures wrote as the owner
-- without naming the column:
--   * the schemaläggare (PLANERING) turns it on and off again, by UPDATE and
--     by the upsert the gateway writes; the full administrator and the rektor
--     hold PLANERING and turn it too;
--   * the expedition (PERSONAL, not PLANERING) and the läsare are refused by
--     the arm's WITH CHECK (insufficient_privilege, as section 181's
--     expedition is) and both still read it; the teacher reads it, and an
--     UPDATE reaches no row of it; each of these as the API's role and as
--     PostgREST's;
--   * a pupil and a guardian read no row at all, and anon holds no privilege
--     on the column, the row or the post's two new columns;
--   * no GRANT moved: the API's role holds SELECT, INSERT, UPDATE and DELETE
--     on both tables as before, nobody holds TRUNCATE, REFERENCES or TRIGGER,
--     and on Postgres 17 nobody holds MAINTAIN (20261016120000).
--
-- Beside the API that serves while the migration goes in (docs/DEPLOYMENT.md):
-- the statements it sends name only the columns it knew. They were read off
-- origin/main when the migration was written (src/staffing/
-- teacher-employments.service.ts employmentData, src/import/import.service.ts,
-- src/year-rollover/rollover-apply.ts, src/resources/lunch-settings.service.ts) and are
-- run here as the full administrator, who decides, against a post that holds a
-- limit. Each leaves the new columns as they were, on a row that holds them and
-- on a row written fresh:
--   * its PUT of a post — the upsert naming the percentages, the contract, the
--     target, the signature and the note, and the days when the body carries
--     them — leaves the limit, and a post it writes fresh carries null and
--     null, which the pair CHECK admits;
--   * the import's UPDATE of a post names its own columns and leaves the limit;
--   * its rollover, one createMany of the next year's posts without the two
--     columns, writes null and null: the old API carries no limit into a new
--     year, which is why nothing but the API after this ever sets one;
--   * its DELETE of a post takes the row with the limit it held;
--   * its upsert of the Skolregler, naming the old columns and not the switch,
--     leaves the switch as it was, on or off, and a fresh row it writes reads
--     off.
-- The work rule is not one of them: nothing of this feature sits on it.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000107')::text, true);
DO $$
DECLARE
  school uuid := app.current_school_id();
  r text;
  tbl text;
  priv text;
BEGIN
  IF (SELECT slug FROM "Schools" WHERE id = school) IS DISTINCT FROM 'rls-roller-school'
     OR NOT app.current_user_may('PLANERING', true) THEN
    RAISE EXCEPTION 'stretch switch: expected the matrix school''s schemaläggare';
  END IF;

  -- No GRANT moved. The API's role writes both tables as it did; nobody
  -- holds what no API role was given (section 36 holds the rest of the
  -- tables to the same); MAINTAIN is counted where the version has it.
  FOREACH tbl IN ARRAY ARRAY['"TeacherEmployments"', '"LunchSettings"'] LOOP
    FOREACH priv IN ARRAY ARRAY['SELECT', 'INSERT', 'UPDATE', 'DELETE'] LOOP
      IF NOT has_table_privilege('app_authenticated', tbl, priv) THEN
        RAISE EXCEPTION 'stretch switch: app_authenticated lost % on %', priv, tbl;
      END IF;
    END LOOP;
    FOREACH r IN ARRAY ARRAY['app_authenticated', 'authenticated', 'anon', 'service_role'] LOOP
      IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN CONTINUE; END IF;
      FOREACH priv IN ARRAY ARRAY['TRUNCATE', 'REFERENCES', 'TRIGGER'] LOOP
        IF has_table_privilege(r, tbl, priv) THEN
          RAISE EXCEPTION 'stretch switch: % holds % on %', r, priv, tbl;
        END IF;
      END LOOP;
      IF current_setting('server_version_num')::int >= 170000 THEN
        IF has_table_privilege(r, tbl, 'MAINTAIN') THEN
          RAISE EXCEPTION 'stretch switch: % holds MAINTAIN on %', r, tbl;
        END IF;
      END IF;
    END LOOP;
  END LOOP;
  -- anon reads and writes neither table nor any of the three new columns.
  FOREACH priv IN ARRAY ARRAY['SELECT', 'INSERT', 'UPDATE'] LOOP
    IF has_column_privilege('anon', '"LunchSettings"', 'generatorKeepsConsecutiveTeaching', priv)
       OR has_column_privilege('anon', '"TeacherEmployments"', 'maxConsecutiveTeachingMinutes', priv)
       OR has_column_privilege('anon', '"TeacherEmployments"', 'consecutiveBreakMinutes', priv)
       OR has_table_privilege('anon', '"LunchSettings"', priv)
       OR has_table_privilege('anon', '"TeacherEmployments"', priv) THEN
      RAISE EXCEPTION 'stretch switch: anon holds % on the Skolregler or the post', priv;
    END IF;
  END LOOP;
  IF has_any_column_privilege('anon', '"LunchSettings"', 'SELECT')
     OR has_any_column_privilege('anon', '"TeacherEmployments"', 'SELECT') THEN
    RAISE EXCEPTION 'stretch switch: anon reads a column of the Skolregler or the post';
  END IF;

  IF (SELECT "generatorKeepsConsecutiveTeaching" FROM "LunchSettings" WHERE "schoolId" = school) IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'stretch switch: the row written before the column does not read off';
  END IF;
  UPDATE "LunchSettings" SET "generatorKeepsConsecutiveTeaching" = true WHERE "schoolId" = school;
  IF NOT FOUND THEN RAISE EXCEPTION 'stretch switch: the schemaläggare could not turn it on'; END IF;
  -- The gateway's own write: INSERT … ON CONFLICT ("schoolId") DO UPDATE.
  INSERT INTO "LunchSettings" ("schoolId", "lunchStartTime", "lunchEndTime", "lunchMinutes", "updatedAt", "generatorKeepsConsecutiveTeaching")
  VALUES (school, '11:00', '13:00', 30, now(), false)
  ON CONFLICT ("schoolId") DO UPDATE SET "generatorKeepsConsecutiveTeaching" = EXCLUDED."generatorKeepsConsecutiveTeaching";
  IF (SELECT "generatorKeepsConsecutiveTeaching" FROM "LunchSettings" WHERE "schoolId" = school) THEN
    RAISE EXCEPTION 'stretch switch: the schemaläggare''s upsert did not turn it off';
  END IF;
  UPDATE "LunchSettings" SET "generatorKeepsConsecutiveTeaching" = true WHERE "schoolId" = school;
  -- The switches are separate columns: this one moved neither of the others.
  IF (SELECT "generatorKeepsPupilGapsDown" OR "generatorKeepsTravelTime" FROM "LunchSettings" WHERE "schoolId" = school) THEN
    RAISE EXCEPTION 'stretch switch: turning it on turned another switch on';
  END IF;
END $$;
SELECT set_config('app.test_rls289_school', app.current_school_id()::text, true);

-- The full administrator and the rektor hold PLANERING: each turns it once.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
DO $$
BEGIN
  UPDATE "LunchSettings" SET "generatorKeepsConsecutiveTeaching" = false WHERE "schoolId" = app.current_school_id();
  IF NOT FOUND THEN RAISE EXCEPTION 'stretch switch: the full administrator could not turn it off'; END IF;
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000106')::text, true);
DO $$
BEGIN
  UPDATE "LunchSettings" SET "generatorKeepsConsecutiveTeaching" = true WHERE "schoolId" = app.current_school_id();
  IF NOT FOUND THEN RAISE EXCEPTION 'stretch switch: the rektor could not turn it on'; END IF;
END $$;

-- The expedition and the läsare read it on and are refused a change by the
-- arm's WITH CHECK; the teacher reads it on and an UPDATE reaches no row.
-- Each as the API's role and as PostgREST's.
DO $$
DECLARE
  who text;
  via text;
  n bigint;
  msg text;
  school uuid := current_setting('app.test_rls289_school')::uuid;
BEGIN
  FOREACH who IN ARRAY ARRAY[
    '00000000-0000-4000-8000-000000000108',
    '00000000-0000-4000-8000-000000000115',
    '00000000-0000-4000-8000-000000000111'
  ] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', who)::text, true);
    FOREACH via IN ARRAY ARRAY['authenticated', 'app_authenticated'] LOOP
      EXECUTE format('SET LOCAL ROLE %I', via);
      IF current_user <> via THEN RAISE EXCEPTION 'stretch switch: running as %, not %', current_user, via; END IF;
      IF (SELECT "generatorKeepsConsecutiveTeaching" FROM "LunchSettings" WHERE "schoolId" = school) IS DISTINCT FROM true THEN
        RAISE EXCEPTION 'stretch switch: % does not read the switch the rektor turned on, as %', who, via;
      END IF;
      BEGIN
        UPDATE "LunchSettings" SET "generatorKeepsConsecutiveTeaching" = false WHERE "schoolId" = school;
        GET DIAGNOSTICS n = ROW_COUNT;
        IF n <> 0 THEN RAISE EXCEPTION 'stretch switch: % turned it off without PLANERING, as %', who, via; END IF;
        IF app.current_user_role() = 'SCHOOL_ADMIN' THEN
          RAISE EXCEPTION 'stretch switch: % (an administrator without PLANERING) was not refused, as %', who, via;
        END IF;
      EXCEPTION WHEN insufficient_privilege THEN
        GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
        IF msg NOT LIKE '%row-level security%' THEN
          RAISE EXCEPTION 'stretch switch: % was refused by "%", not by row security, as %', who, msg, via;
        END IF;
        IF app.current_user_role() <> 'SCHOOL_ADMIN' THEN
          RAISE EXCEPTION 'stretch switch: % (%) was refused where no row is theirs, as %', who, app.current_user_role(), via;
        END IF;
      END;
    END LOOP;
    SET LOCAL ROLE app_authenticated;
  END LOOP;
END $$;

-- A pupil and a guardian read no row of the Skolregler at all.
DO $$
DECLARE
  who text;
BEGIN
  FOREACH who IN ARRAY ARRAY['00000000-0000-4000-8000-000000000112', '00000000-0000-4000-8000-000000000113'] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', who)::text, true);
    IF EXISTS (SELECT 1 FROM "LunchSettings") THEN
      RAISE EXCEPTION 'stretch switch: % reads the Skolregler', who;
    END IF;
  END LOOP;
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000107')::text, true);
DO $$
BEGIN
  IF (SELECT "generatorKeepsConsecutiveTeaching" FROM "LunchSettings" WHERE "schoolId" = app.current_school_id()) IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'stretch switch: a profile without PLANERING moved it after all';
  END IF;
END $$;

-- Beside the API from before: its statements name the old columns only. The
-- full administrator, who decides, gives the teacher's post a limit through
-- the new columns' own statements and the Skolregler hold the switch on; then
-- the old API's go.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
DO $$
DECLARE
  school uuid := current_setting('app.test_rls289_school')::uuid;
  teacher uuid := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000111');
  decider uuid := app.current_user_id();
  post uuid;
  year uuid;
  carried record;
BEGIN
  SELECT id, "academicYearId" INTO post, year FROM "TeacherEmployments" WHERE "userId" = teacher;
  IF post IS NULL THEN RAISE EXCEPTION 'stretch switch: no post of the teacher to plan'; END IF;
  UPDATE "TeacherEmployments" SET "maxConsecutiveTeachingMinutes" = 240, "consecutiveBreakMinutes" = 15 WHERE id = post;
  IF NOT FOUND THEN RAISE EXCEPTION 'stretch switch: the full administrator could not give the post a limit'; END IF;

  -- Its PUT of a post (employmentData): the upsert naming the percentages, the
  -- contract, the target, the signature and the note — and not the limit.
  INSERT INTO "TeacherEmployments"
    ("schoolId", "userId", "academicYearId", "employmentPercent", "reductionPercent", "contractKind",
     "teachingTargetMinutesPerWeek", "signature", "note", "updatedAt")
  VALUES (school, teacher, year, 70, 0, 'FERIE', 900, 'RL', 'old api', now())
  ON CONFLICT ("schoolId", "userId", "academicYearId") DO UPDATE SET
    "employmentPercent" = EXCLUDED."employmentPercent", "reductionPercent" = EXCLUDED."reductionPercent",
    "contractKind" = EXCLUDED."contractKind", "teachingTargetMinutesPerWeek" = EXCLUDED."teachingTargetMinutesPerWeek",
    "signature" = EXCLUDED."signature", "note" = EXCLUDED."note", "updatedAt" = EXCLUDED."updatedAt";
  IF NOT EXISTS (SELECT 1 FROM "TeacherEmployments" WHERE id = post AND "employmentPercent" = 70 AND "teachingTargetMinutesPerWeek" = 900
                    AND "maxConsecutiveTeachingMinutes" = 240 AND "consecutiveBreakMinutes" = 15) THEN
    RAISE EXCEPTION 'stretch switch: the old API''s PUT of a post did not leave the limit as it was: %',
      (SELECT row_to_json(e) FROM "TeacherEmployments" e WHERE id = post);
  END IF;
  -- … and with the days, which a body of that API carries when the form sets them.
  INSERT INTO "TeacherEmployments"
    ("schoolId", "userId", "academicYearId", "employmentPercent", "reductionPercent", "contractKind",
     "teachingTargetMinutesPerWeek", "signature", "note", "maxTeachingDaysPerWeek", "updatedAt")
  VALUES (school, teacher, year, 80, 10, 'FERIE', NULL, 'RL', NULL, 4, now())
  ON CONFLICT ("schoolId", "userId", "academicYearId") DO UPDATE SET
    "employmentPercent" = EXCLUDED."employmentPercent", "reductionPercent" = EXCLUDED."reductionPercent",
    "contractKind" = EXCLUDED."contractKind", "teachingTargetMinutesPerWeek" = EXCLUDED."teachingTargetMinutesPerWeek",
    "signature" = EXCLUDED."signature", "note" = EXCLUDED."note",
    "maxTeachingDaysPerWeek" = EXCLUDED."maxTeachingDaysPerWeek", "updatedAt" = EXCLUDED."updatedAt";
  IF NOT EXISTS (SELECT 1 FROM "TeacherEmployments" WHERE id = post AND "maxTeachingDaysPerWeek" = 4
                    AND "maxConsecutiveTeachingMinutes" = 240 AND "consecutiveBreakMinutes" = 15) THEN
    RAISE EXCEPTION 'stretch switch: the old API''s PUT of a post with its days did not leave the limit as it was';
  END IF;
  -- The import's UPDATE of a post.
  UPDATE "TeacherEmployments" SET "employmentPercent" = 60, "reductionPercent" = 0, "signature" = 'RL', "updatedAt" = now()
   WHERE "schoolId" = school AND "userId" = teacher AND "academicYearId" = year;
  IF NOT EXISTS (SELECT 1 FROM "TeacherEmployments" WHERE id = post AND "employmentPercent" = 60
                    AND "maxConsecutiveTeachingMinutes" = 240 AND "consecutiveBreakMinutes" = 15) THEN
    RAISE EXCEPTION 'stretch switch: the old API''s import of a post moved the limit';
  END IF;
  -- A post it writes fresh, and the rollover's createMany, carry null and null.
  INSERT INTO "TeacherEmployments"
    ("schoolId", "userId", "academicYearId", "employmentPercent", "reductionPercent", "contractKind",
     "teachingTargetMinutesPerWeek", "signature", "note", "updatedAt")
  VALUES (school, decider, year, 100, 0, 'FERIE', NULL, NULL, NULL, now());
  SELECT "maxConsecutiveTeachingMinutes" AS m, "consecutiveBreakMinutes" AS b INTO carried
    FROM "TeacherEmployments" WHERE "userId" = decider AND "academicYearId" = year;
  IF carried.m IS NOT NULL OR carried.b IS NOT NULL THEN
    RAISE EXCEPTION 'stretch switch: a post the old API writes fresh does not carry null and null';
  END IF;
  -- Its DELETE takes the row with the limit it held; the history says so.
  UPDATE "TeacherEmployments" SET "maxConsecutiveTeachingMinutes" = 120, "consecutiveBreakMinutes" = 10 WHERE "userId" = decider;
  DELETE FROM "TeacherEmployments" WHERE "schoolId" = school AND "userId" = decider AND "academicYearId" = year;
  IF NOT FOUND OR EXISTS (SELECT 1 FROM "TeacherEmployments" WHERE "userId" = decider) THEN
    RAISE EXCEPTION 'stretch switch: the old API''s DELETE of a post holding a limit did not take it';
  END IF;

  -- Its upsert of the Skolregler: the old columns, not the switch. On leaves on.
  INSERT INTO "LunchSettings"
    ("schoolId", "lunchEnabled", "lunchStartTime", "lunchEndTime", "lunchMinutes", "diningSeats", "maxLessonsPerDayPerGroup", "updatedAt")
  VALUES (school, true, '11:00', '13:00', 40, 80, 6, now())
  ON CONFLICT ("schoolId") DO UPDATE SET "lunchEnabled" = EXCLUDED."lunchEnabled", "lunchStartTime" = EXCLUDED."lunchStartTime",
    "lunchEndTime" = EXCLUDED."lunchEndTime", "lunchMinutes" = EXCLUDED."lunchMinutes", "diningSeats" = EXCLUDED."diningSeats",
    "maxLessonsPerDayPerGroup" = EXCLUDED."maxLessonsPerDayPerGroup", "updatedAt" = EXCLUDED."updatedAt";
  IF NOT EXISTS (SELECT 1 FROM "LunchSettings" WHERE "schoolId" = school AND "lunchMinutes" = 40 AND "diningSeats" = 80
                    AND "generatorKeepsConsecutiveTeaching") THEN
    RAISE EXCEPTION 'stretch switch: the old API''s upsert of the Skolregler did not leave the switch on: %',
      (SELECT row_to_json(l) FROM "LunchSettings" l WHERE "schoolId" = school);
  END IF;
  -- Off leaves off; and a UPDATE of the old columns leaves either.
  UPDATE "LunchSettings" SET "generatorKeepsConsecutiveTeaching" = false WHERE "schoolId" = school;
  INSERT INTO "LunchSettings" ("schoolId", "lunchEnabled", "lunchStartTime", "lunchEndTime", "lunchMinutes", "updatedAt")
  VALUES (school, false, '11:00', '13:00', 35, now())
  ON CONFLICT ("schoolId") DO UPDATE SET "lunchEnabled" = EXCLUDED."lunchEnabled", "lunchStartTime" = EXCLUDED."lunchStartTime",
    "lunchEndTime" = EXCLUDED."lunchEndTime", "lunchMinutes" = EXCLUDED."lunchMinutes", "updatedAt" = EXCLUDED."updatedAt";
  UPDATE "LunchSettings" SET "lunchMinutes" = 30, "updatedAt" = now() WHERE "schoolId" = school;
  IF NOT EXISTS (SELECT 1 FROM "LunchSettings" WHERE "schoolId" = school AND "lunchMinutes" = 30 AND NOT "generatorKeepsConsecutiveTeaching") THEN
    RAISE EXCEPTION 'stretch switch: the old API''s statements did not leave the switch off';
  END IF;
  -- A fresh row it writes reads off.
  DELETE FROM "LunchSettings" WHERE "schoolId" = school;
  INSERT INTO "LunchSettings" ("schoolId", "lunchEnabled", "lunchStartTime", "lunchEndTime", "lunchMinutes", "updatedAt")
  VALUES (school, false, '11:00', '13:00', 30, now());
  IF (SELECT "generatorKeepsConsecutiveTeaching" FROM "LunchSettings" WHERE "schoolId" = school) IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'stretch switch: a Skolregler row the old API writes fresh does not read off';
  END IF;
END $$;
ROLLBACK;


-- ---------------------------------------------------------------------------
-- Section 290: en lokal timplan gäller ett årskurspann, och en beslutad plan
-- får det en gång (LocalTimplans."gradeFrom", "gradeTo", "gradeSpanSetAt",
-- "gradeSpanSetByUserId", 20261219090000).
--
-- The check (P1) counts only the årskurser a plan is for. The columns are the
-- plan's own, so the arms of section 16 cover them; what this section holds is
-- what the migration added:
--   * the CHECKs: both or neither, 0..11, from <= to, and a stamp only on a
--     decided plan that has a span, both stamps or none;
--   * a DRAFT takes, changes and clears a span freely, and carries no stamp: a
--     writer with a JWT subject who names one on an INSERT, on an UPDATE of a
--     draft or on the transition that decides it finds it cleared;
--   * a DECIDED plan with no span takes one ONCE, from NULL, with nothing else
--     different in the same UPDATE, and the trigger writes who (the caller, not
--     the user the writer names) and when (now(), not the date the writer
--     names). A second change, the same values again, a clearing, half a pair,
--     the stamps alone, and the span beside a different name, weeks, status,
--     decision note or copy pointer are TP409, as every change to a decided
--     plan is. A plan decided WITH a span changes in no way;
--   * the minutes stay put: a decided plan's entries refuse INSERT, UPDATE and
--     DELETE after the span is set, as before;
--   * the same through PostgREST's role (authenticated) as through the API's;
--   * the statements the API that serves before the migration sends name
--     none of the four columns, and do what they did: a plan born with no span,
--     a draft renamed, a decided plan refused;
--   * the setter's key is the decider's: (id, schoolId), ON DELETE and ON UPDATE
--     RESTRICT, so the record keeps the name.
-- The owner's side (no JWT subject: the stamps must be stated) is in
-- rls-owner-checks.sql.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', :'admin_auth_id')::text, true);
DO $$
DECLARE
  school  uuid := app.current_school_id();
  me      uuid := app.current_user_id();
  pupil   uuid;
  b1      uuid;
  s1      uuid;
  fresh   uuid;
  draft   uuid;
  spanned uuid;
  plain   uuid;
  pointed uuid;
  other   uuid;
  via     text;
  n       bigint;
  rec     record;
  c       text;
BEGIN
  IF app.current_user_role() <> 'SCHOOL_ADMIN' THEN
    RAISE EXCEPTION 'span: expected to be acting as an admin, am %', app.current_user_role();
  END IF;
  SELECT id INTO b1 FROM "NationalTimplanVersions" WHERE code = 'SFS2023:945/B1';
  SELECT id INTO pupil FROM "Users" WHERE "schoolId" = school AND role = 'STUDENT' LIMIT 1;
  IF pupil IS NULL THEN
    RAISE EXCEPTION 'span: the fixture school has no pupil to name as a setter';
  END IF;

  -- Every plan that exists is NULL: nothing was backfilled.
  SELECT count(*) INTO n FROM "LocalTimplans"
   WHERE "gradeFrom" IS NOT NULL OR "gradeTo" IS NOT NULL
      OR "gradeSpanSetAt" IS NOT NULL OR "gradeSpanSetByUserId" IS NOT NULL;
  IF n <> 0 THEN
    RAISE EXCEPTION 'span: % existing plan(s) already carry a span or a stamp', n;
  END IF;

  INSERT INTO "Subjects" ("schoolId", name, code, "nationalCode", "updatedAt")
  VALUES (school, 'RLS-span-matematik', 'RLSSPAN1', 'MA', now());
  SELECT id INTO s1 FROM "Subjects" WHERE "schoolId" = school AND code = 'RLSSPAN1';

  -- The CHECKs, on a draft.
  FOREACH c IN ARRAY ARRAY['4,NULL', 'NULL,9', '9,4', '-1,4', '4,12', '12,12'] LOOP
    BEGIN
      EXECUTE format(
        $q$INSERT INTO "LocalTimplans" ("schoolId", name, "schoolForm", "nationalTimplanVersionId", "gradeFrom", "gradeTo", "updatedAt")
           VALUES (%L, 'RLS-span check %s', 'GRUNDSKOLA', %L, %s, now())$q$,
        school, c, b1, c);
      RAISE EXCEPTION 'span: a plan with the span (%) was stored', c;
    EXCEPTION WHEN check_violation THEN NULL;
    END;
  END LOOP;
  FOREACH c IN ARRAY ARRAY['0,11', '7,7', '0,0'] LOOP
    EXECUTE format(
      $q$INSERT INTO "LocalTimplans" ("schoolId", name, "schoolForm", "nationalTimplanVersionId", "gradeFrom", "gradeTo", "updatedAt")
         VALUES (%L, 'RLS-span ok %s', 'GRUNDSKOLA', %L, %s, now())$q$,
      school, c, b1, c);
  END LOOP;

  -- A draft takes, changes and clears a span, and carries no stamp, whatever
  -- the writer says: on an INSERT, on an UPDATE, and at the decision.
  INSERT INTO "LocalTimplans"
    ("schoolId", name, "schoolForm", "nationalTimplanVersionId", "gradeFrom", "gradeTo",
     "gradeSpanSetAt", "gradeSpanSetByUserId", "updatedAt")
  VALUES (school, 'RLS-span utkast', 'GRUNDSKOLA', b1, 4, 9, '2019-01-01', pupil, now())
  RETURNING id INTO draft;
  SELECT "gradeSpanSetAt" AS set_at, "gradeSpanSetByUserId" AS set_by INTO rec FROM "LocalTimplans" WHERE id = draft;
  IF rec.set_at IS NOT NULL OR rec.set_by IS NOT NULL THEN
    RAISE EXCEPTION 'span: a draft was born with a span stamp (%, %)', rec.set_at, rec.set_by;
  END IF;
  UPDATE "LocalTimplans" SET "gradeFrom" = 0, "gradeTo" = 5, "updatedAt" = now() WHERE id = draft;
  UPDATE "LocalTimplans" SET "gradeFrom" = 4, "gradeTo" = 9, "gradeSpanSetAt" = now(), "gradeSpanSetByUserId" = me, "updatedAt" = now() WHERE id = draft;
  SELECT "gradeSpanSetAt" AS set_at, "gradeSpanSetByUserId" AS set_by, "gradeFrom" AS f, "gradeTo" AS t INTO rec FROM "LocalTimplans" WHERE id = draft;
  IF rec.set_at IS NOT NULL OR rec.set_by IS NOT NULL OR rec.f <> 4 OR rec.t <> 9 THEN
    RAISE EXCEPTION 'span: an UPDATE of a draft left a stamp or lost the span (%)', rec;
  END IF;
  UPDATE "LocalTimplans" SET "gradeFrom" = NULL, "gradeTo" = NULL, "updatedAt" = now() WHERE id = draft;
  UPDATE "LocalTimplans" SET "gradeFrom" = 4, "gradeTo" = 9, "updatedAt" = now() WHERE id = draft;
  INSERT INTO "LocalTimplanEntries" ("schoolId", "localTimplanId", "subjectId", "gradeLevel", "minutesPerWeek")
  VALUES (school, draft, s1, 4, 180), (school, draft, s1, 5, 180);
  -- The decision of a plan that already has a span: the writer's forged
  -- stamps are cleared, the span stays, and the decision is the caller's.
  UPDATE "LocalTimplans"
     SET status = 'DECIDED', "decidedAt" = now(), "decidedByUserId" = me, "decisionNote" = 'RLS-span beslut',
         "gradeSpanSetAt" = '2019-01-01', "gradeSpanSetByUserId" = pupil, "updatedAt" = now()
   WHERE id = draft;
  spanned := draft;
  SELECT "gradeSpanSetAt" AS set_at, "gradeSpanSetByUserId" AS set_by, "gradeFrom" AS f, "gradeTo" AS t, status AS st
    INTO rec FROM "LocalTimplans" WHERE id = spanned;
  IF rec.set_at IS NOT NULL OR rec.set_by IS NOT NULL OR rec.f <> 4 OR rec.t <> 9 OR rec.st <> 'DECIDED' THEN
    RAISE EXCEPTION 'span: deciding a plan with a span left a forged stamp or moved the span (%)', rec;
  END IF;

  -- A plan decided WITH a span changes in no way: another span, the same span
  -- again, none.
  FOREACH c IN ARRAY ARRAY['"gradeFrom" = 1, "gradeTo" = 9', '"gradeFrom" = 4, "gradeTo" = 9', '"gradeFrom" = NULL, "gradeTo" = NULL',
                           '"gradeTo" = 8', '"gradeSpanSetAt" = now()'] LOOP
    BEGIN
      EXECUTE format('UPDATE "LocalTimplans" SET %s, "updatedAt" = now() WHERE id = %L', c, spanned);
      RAISE EXCEPTION 'span: a plan decided with a span was changed by SET %', c;
    EXCEPTION WHEN SQLSTATE 'TP409' THEN NULL;
    END;
  END LOOP;

  -- A decided plan with no span: entries first (the minutes), then the decision.
  INSERT INTO "LocalTimplans" ("schoolId", name, "schoolForm", "nationalTimplanVersionId", "updatedAt")
  VALUES (school, 'RLS-span beslutad utan', 'GRUNDSKOLA', b1, now())
  RETURNING id INTO plain;
  INSERT INTO "LocalTimplanEntries" ("schoolId", "localTimplanId", "subjectId", "gradeLevel", "minutesPerWeek")
  VALUES (school, plain, s1, 4, 180), (school, plain, s1, 5, 180), (school, plain, s1, 2, 90);
  UPDATE "LocalTimplans"
     SET status = 'DECIDED', "decidedAt" = now(), "decidedByUserId" = me, "decisionNote" = 'RLS-span beslut utan', "updatedAt" = now()
   WHERE id = plain;
  INSERT INTO "LocalTimplans" ("schoolId", name, "schoolForm", "nationalTimplanVersionId", "updatedAt")
  VALUES (school, 'RLS-span peka', 'GRUNDSKOLA', b1, now())
  RETURNING id INTO other;

  -- The refusals first: none of them may leave a trace on the row.
  FOREACH c IN ARRAY ARRAY[
    '"gradeFrom" = 4',                                                     -- half a pair
    '"gradeTo" = 9',
    '"gradeFrom" = 4, "gradeTo" = 9, name = ''omdöpt''',                   -- the span beside anything else
    '"gradeFrom" = 4, "gradeTo" = 9, "planningWeeks" = 30.0',
    '"gradeFrom" = 4, "gradeTo" = 9, "decisionNote" = ''annat beslut''',
    '"gradeFrom" = 4, "gradeTo" = 9, "decidedAt" = ''2019-01-01''',
    '"gradeFrom" = 4, "gradeTo" = 9, status = ''DRAFT'', "decidedAt" = NULL, "decidedByUserId" = NULL, "decisionNote" = NULL',
    format('"gradeFrom" = 4, "gradeTo" = 9, "copiedFromId" = %L', other),
    '"gradeSpanSetAt" = now(), "gradeSpanSetByUserId" = app.current_user_id()', -- the stamps alone
    '"gradeFrom" = NULL, "gradeTo" = NULL'                                  -- no span to clear
  ] LOOP
    BEGIN
      EXECUTE format('UPDATE "LocalTimplans" SET %s, "updatedAt" = now() WHERE id = %L', c, plain);
      RAISE EXCEPTION 'span: a decided plan was changed by SET %', c;
    EXCEPTION WHEN SQLSTATE 'TP409' THEN NULL;
    END;
  END LOOP;
  SELECT count(*) INTO n FROM "LocalTimplans"
   WHERE id = plain AND "gradeFrom" IS NULL AND "gradeTo" IS NULL AND name = 'RLS-span beslutad utan'
     AND "gradeSpanSetAt" IS NULL AND "gradeSpanSetByUserId" IS NULL AND "copiedFromId" IS NULL;
  IF n <> 1 THEN
    RAISE EXCEPTION 'span: a refused statement left a trace on the decided plan';
  END IF;

  -- The one change: both columns, from none, nothing else, and the writer's
  -- own idea of who and when is overwritten (a pupil, in 2019).
  -- (updatedAt is moved with clock_timestamp(), as the gateway's Prisma moves
  -- it with the clock: now() is this transaction's start and would equal the
  -- INSERT's, so the exception for it could be removed unseen.)
  UPDATE "LocalTimplans"
     SET "gradeFrom" = 4, "gradeTo" = 9, "gradeSpanSetAt" = '2019-01-01', "gradeSpanSetByUserId" = pupil,
         "updatedAt" = clock_timestamp()
   WHERE id = plain;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN
    RAISE EXCEPTION 'span: an admin could not give a decided plan its span once (% row(s))', n;
  END IF;
  SELECT "gradeSpanSetAt" AS set_at, "gradeSpanSetByUserId" AS set_by, "gradeFrom" AS f, "gradeTo" AS t, status AS st, name AS nm,
         "decidedByUserId" AS dec
    INTO rec FROM "LocalTimplans" WHERE id = plain;
  IF rec.f <> 4 OR rec.t <> 9 OR rec.st <> 'DECIDED' OR rec.nm <> 'RLS-span beslutad utan' OR rec.dec <> me THEN
    RAISE EXCEPTION 'span: setting the span once changed more than the span (%)', rec;
  END IF;
  IF rec.set_at IS DISTINCT FROM now() OR rec.set_by IS DISTINCT FROM me THEN
    RAISE EXCEPTION 'span: the span was stamped % by % instead of now() by the caller', rec.set_at, rec.set_by;
  END IF;

  -- And only once: every statement that was refused is refused again, now for
  -- a plan that holds a span, together with a second set of the same values,
  -- another span and a clearing.
  FOREACH c IN ARRAY ARRAY[
    '"gradeFrom" = 4, "gradeTo" = 9',
    '"gradeFrom" = 1, "gradeTo" = 9',
    '"gradeFrom" = NULL, "gradeTo" = NULL',
    '"gradeSpanSetAt" = NULL, "gradeSpanSetByUserId" = NULL',
    '"gradeSpanSetByUserId" = app.current_user_id()',
    'name = ''omdöpt'''
  ] LOOP
    BEGIN
      EXECUTE format('UPDATE "LocalTimplans" SET %s, "updatedAt" = now() WHERE id = %L', c, plain);
      RAISE EXCEPTION 'span: a decided plan with a span set after the decision was changed by SET %', c;
    EXCEPTION WHEN SQLSTATE 'TP409' THEN NULL;
    END;
  END LOOP;

  -- The minutes stay put, span or not: the entries trigger is untouched.
  BEGIN
    UPDATE "LocalTimplanEntries" SET "minutesPerWeek" = 200 WHERE "localTimplanId" = plain AND "gradeLevel" = 4;
    RAISE EXCEPTION 'span: a minute was changed under a decided plan that took its span';
  EXCEPTION WHEN SQLSTATE 'TP409' THEN NULL;
  END;
  BEGIN
    INSERT INTO "LocalTimplanEntries" ("schoolId", "localTimplanId", "subjectId", "gradeLevel", "minutesPerWeek")
    VALUES (school, plain, s1, 6, 60);
    RAISE EXCEPTION 'span: a minute was added under a decided plan that took its span';
  EXCEPTION WHEN SQLSTATE 'TP409' THEN NULL;
  END;
  BEGIN
    DELETE FROM "LocalTimplanEntries" WHERE "localTimplanId" = plain AND "gradeLevel" = 2;
    RAISE EXCEPTION 'span: a minute outside the span was deleted under a decided plan';
  EXCEPTION WHEN SQLSTATE 'TP409' THEN NULL;
  END;
  SELECT count(*) INTO n FROM "LocalTimplanEntries"
   WHERE "localTimplanId" = plain AND "minutesPerWeek" IN (180, 90);
  IF n <> 3 THEN
    RAISE EXCEPTION 'span: the decided plan holds % of its 3 entries unchanged', n;
  END IF;

  -- The same through PostgREST's role as through the API's: a plan is made,
  -- decided and given its span once, and refused a second time.
  FOREACH via IN ARRAY ARRAY['app_authenticated', 'authenticated'] LOOP
    EXECUTE format('SET LOCAL ROLE %I', via);
    IF current_user <> via THEN
      RAISE EXCEPTION 'span: expected to be % and am %', via, current_user;
    END IF;
    INSERT INTO "LocalTimplans" ("schoolId", name, "schoolForm", "nationalTimplanVersionId", "updatedAt")
    VALUES (school, 'RLS-span via ' || via, 'GRUNDSKOLA', b1, now())
    RETURNING id INTO fresh;
    UPDATE "LocalTimplans"
       SET status = 'DECIDED', "decidedAt" = now(), "decidedByUserId" = me, "decisionNote" = 'via ' || via, "updatedAt" = now()
     WHERE id = fresh;
    UPDATE "LocalTimplans" SET "gradeFrom" = 6, "gradeTo" = 9, "updatedAt" = clock_timestamp() WHERE id = fresh;
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n <> 1 THEN
      RAISE EXCEPTION 'span: % could not give a decided plan its span once (% row(s))', via, n;
    END IF;
    SELECT "gradeSpanSetAt" AS set_at, "gradeSpanSetByUserId" AS set_by INTO rec FROM "LocalTimplans" WHERE id = fresh;
    IF rec.set_at IS DISTINCT FROM now() OR rec.set_by IS DISTINCT FROM me THEN
      RAISE EXCEPTION 'span: % left the stamp as (%, %)', via, rec.set_at, rec.set_by;
    END IF;
    BEGIN
      UPDATE "LocalTimplans" SET "gradeFrom" = 7, "gradeTo" = 9, "updatedAt" = now() WHERE id = fresh;
      RAISE EXCEPTION 'span: % changed a span that was set after the decision', via;
    EXCEPTION WHEN SQLSTATE 'TP409' THEN NULL;
    END;
  END LOOP;
  SET LOCAL ROLE app_authenticated;

  -- A decided plan's column is no wider than it was: the statements of the API
  -- that serves before the migration name none of the four columns.
  INSERT INTO "LocalTimplans" ("schoolId", name, "schoolForm", "nationalTimplanVersionId", "planningWeeks", "updatedAt")
  VALUES (school, 'RLS-span gamla API:t', 'GRUNDSKOLA', b1, 36.0, now())
  RETURNING id INTO fresh;
  UPDATE "LocalTimplans" SET name = 'RLS-span gamla API:t omdöpt', "planningWeeks" = 35.6, "updatedAt" = now() WHERE id = fresh;
  SELECT count(*) INTO n FROM "LocalTimplans"
   WHERE id = fresh AND "gradeFrom" IS NULL AND "gradeTo" IS NULL
     AND "gradeSpanSetAt" IS NULL AND "gradeSpanSetByUserId" IS NULL;
  IF n <> 1 THEN
    RAISE EXCEPTION 'span: a plan written by the old API''s statements carries a span or a stamp';
  END IF;
  UPDATE "LocalTimplans"
     SET status = 'DECIDED', "decidedAt" = now(), "decidedByUserId" = me, "decisionNote" = 'gamla API:t', "updatedAt" = now()
   WHERE id = fresh;
  BEGIN
    UPDATE "LocalTimplans" SET name = 'gamla API:t igen', "updatedAt" = now() WHERE id = fresh;
    RAISE EXCEPTION 'span: the old API''s rename of a decided plan was admitted';
  EXCEPTION WHEN SQLSTATE 'TP409' THEN NULL;
  END;

  -- The setter's key is the decider's: the composite key to Users, RESTRICT both ways.
  FOREACH c IN ARRAY ARRAY['LocalTimplans_decidedByUserId_schoolId_fkey', 'LocalTimplans_gradeSpanSetByUserId_schoolId_fkey'] LOOP
    SELECT confdeltype AS d, confupdtype AS u, confrelid::regclass::text AS ref,
           (SELECT array_agg(attname::text ORDER BY k.ord) FROM unnest(conkey) WITH ORDINALITY k(attnum, ord)
              JOIN pg_attribute a ON a.attrelid = conrelid AND a.attnum = k.attnum) AS cols
      INTO rec
      FROM pg_constraint WHERE conrelid = 'public."LocalTimplans"'::regclass AND conname = c;
    IF rec IS NULL OR rec.d <> 'r' OR rec.u <> 'r' OR rec.ref <> '"Users"' OR rec.cols[2] <> 'schoolId' THEN
      RAISE EXCEPTION 'span: % is not a RESTRICT/RESTRICT key on Users(id, schoolId) (%)', c, rec;
    END IF;
  END LOOP;
  BEGIN
    DELETE FROM "Users" WHERE id = me;
    RAISE EXCEPTION 'span: the person who decided and set a span was deleted';
  EXCEPTION WHEN foreign_key_violation THEN NULL;
  END;

  -- Tenant: only this school's plans are visible, spans and stamps included.
  SELECT count(*) INTO n FROM "LocalTimplans" WHERE "schoolId" <> school;
  IF n <> 0 THEN
    RAISE EXCEPTION 'span: % local timplan(s) from another school visible', n;
  END IF;
END $$;
ROLLBACK;


-- ---------------------------------------------------------------------------
-- Section 315: vikarieförfrågningarna står i katalogen som migreringen skrev
-- dem (CoverRequests, CoverRequestLessons, CoverRequestRecipients,
-- CoverConfirmations, 20270102091000).
--
-- Fyra tabeller, 15 armar, ingen DELETE för någon roll, ingenting för
-- PostgREST:s roller, och sex funktioner som bara API:ts roll får anropa.
-- Migrationens egen vakt (COVER_REQUEST_REACH) körs när migreringen
-- läggs på; här står samma sak mot den databas sviten kör mot, och med
-- tabellernas rättigheter, triggrarna och det partiella unika indexet som
-- håller en öppen förfrågan per lektion.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', :'admin_auth_id')::text, true);
DO $$
DECLARE
  t text;
  r text;
  f text;
  n integer;
  tables text[] := ARRAY['CoverRequests', 'CoverRequestLessons', 'CoverRequestRecipients', 'CoverConfirmations'];
  functions text[] := ARRAY['app.cover_request_sender(uuid)', 'app.cover_confirm(uuid)',
                            'app.cover_my_passes(timestamptz, timestamptz)', 'app.cover_requests_settle()',
                            'app.cover_request_is_open(uuid)'];
  src text;
BEGIN
  FOREACH t IN ARRAY tables LOOP
    IF NOT (SELECT relrowsecurity FROM pg_class WHERE oid = format('public.%I', t)::regclass) THEN
      RAISE EXCEPTION 'cover requests: % has no row-level security', t;
    END IF;
    IF NOT (has_table_privilege('app_authenticated', format('public.%I', t), 'SELECT')
            AND has_table_privilege('app_authenticated', format('public.%I', t), 'INSERT')) THEN
      RAISE EXCEPTION 'cover requests: the API role lacks a grant on %', t;
    END IF;
    -- A line is turned off by its request's trigger and a confirmation is
    -- written once: no arm updates either, so no UPDATE is granted.
    IF has_table_privilege('app_authenticated', format('public.%I', t), 'UPDATE') IS DISTINCT FROM (t IN ('CoverRequests', 'CoverRequestRecipients')) THEN
      RAISE EXCEPTION 'cover requests: the API role''s UPDATE on % is not what the arms say', t;
    END IF;
    IF has_table_privilege('app_authenticated', format('public.%I', t), 'DELETE, TRUNCATE, REFERENCES, TRIGGER') THEN
      RAISE EXCEPTION 'cover requests: the API role may delete from, truncate, reference or trigger %', t;
    END IF;
    FOREACH r IN ARRAY ARRAY['authenticated', 'anon'] LOOP
      IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r)
         AND has_table_privilege(r, format('public.%I', t), 'SELECT, INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER') THEN
        RAISE EXCEPTION 'cover requests: % holds a privilege on %', r, t;
      END IF;
    END LOOP;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role')
       AND has_table_privilege('service_role', format('public.%I', t), 'INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER') THEN
      RAISE EXCEPTION 'cover requests: service_role writes %', t;
    END IF;
  END LOOP;

  SELECT count(*) INTO n FROM pg_policies WHERE schemaname = 'public' AND tablename = ANY (tables);
  IF n <> 15 THEN RAISE EXCEPTION 'cover requests: the four tables have % arms, not 15', n; END IF;
  SELECT count(*) INTO n FROM pg_policies
   WHERE schemaname = 'public' AND tablename = ANY (tables) AND (roles <> '{app_authenticated}'::name[] OR cmd = 'DELETE' OR cmd = 'ALL');
  IF n <> 0 THEN RAISE EXCEPTION 'cover requests: % arm(s) reach beyond the API role or delete', n; END IF;

  FOREACH f IN ARRAY functions LOOP
    IF NOT has_function_privilege('app_authenticated', f, 'EXECUTE') THEN
      RAISE EXCEPTION 'cover requests: the API role may not execute %', f;
    END IF;
    FOREACH r IN ARRAY ARRAY['anon', 'authenticated', 'service_role'] LOOP
      IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) AND has_function_privilege(r, f, 'EXECUTE') THEN
        RAISE EXCEPTION 'cover requests: % may execute %', r, f;
      END IF;
    END LOOP;
    -- PUBLIC (grantee 0) holds nothing either.
    IF EXISTS (SELECT 1 FROM pg_proc p, aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
                WHERE p.oid = f::regprocedure AND a.grantee = 0) THEN
      RAISE EXCEPTION 'cover requests: PUBLIC may execute %', f;
    END IF;
    IF NOT (SELECT p.prosecdef AND p.proconfig::text LIKE '%search_path=%' FROM pg_proc p WHERE p.oid = f::regprocedure) THEN
      RAISE EXCEPTION 'cover requests: % is not a SECURITY DEFINER with a fixed search_path', f;
    END IF;
  END LOOP;

  -- One open request per pair is a partial unique index on the lines' open flag.
  IF NOT EXISTS (SELECT 1 FROM pg_indexes WHERE tablename = 'CoverRequestLessons'
                  AND indexname = 'CoverRequestLessons_one_open_per_pair'
                  AND indexdef LIKE '%UNIQUE%' AND indexdef LIKE '%WHERE open%') THEN
    RAISE EXCEPTION 'cover requests: the partial unique index of open pairs is gone';
  END IF;
  -- The triggers that make a request end once and keep the rest in step.
  FOREACH f IN ARRAY ARRAY['CoverRequests_a_one_way', 'CoverRequests_b_close_lines', 'CoverRequestRecipients_a_narrow',
                           'TeacherAbsenceCovers_c_closes_requests', 'TeacherAbsenceCovers_d_drops_confirmations',
                           'TeacherAbsenceCovers_e_drops_confirmations_on_delete'] LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = f AND NOT tgisinternal AND tgenabled = 'O') THEN
      RAISE EXCEPTION 'cover requests: the trigger % is missing or disabled', f;
    END IF;
  END LOOP;
  -- Gallring knows the kind, and a school that has decided nothing keeps it.
  IF NOT EXISTS (SELECT 1 FROM unnest(enum_range(NULL::"RetentionDataType")) k WHERE k::text = 'COVER_REQUESTS') THEN
    RAISE EXCEPTION 'cover requests: COVER_REQUESTS is not a retention kind';
  END IF;
  -- app.gallring_due and app.gallring_purge are replaced whole by every release
  -- that adds a kind (20261026091000, 20261231090100, 20270102091000), so the
  -- one that comes last must carry every branch before it: the findings of
  -- Frånvarobevakning under ATTENDANCE and the requests under COVER_REQUESTS.
  -- A release that restates them from an older body silently stops purging
  -- the other's rows. The branches' behaviour is 309o and section 319; this
  -- is that neither is missing from the bodies in force.
  SELECT p.prosrc INTO src FROM pg_proc p WHERE p.oid = 'app.gallring_due(uuid, "RetentionDataType", date, date)'::regprocedure;
  IF src NOT LIKE '%"AbsenceWatchFindings"%' THEN
    RAISE EXCEPTION 'gallring: app.gallring_due has lost the branch for the absence watch''s findings (Frånvarobevakning, 20261231090100)';
  END IF;
  IF src NOT LIKE '%"CoverRequests"%' OR src NOT LIKE '%"CoverConfirmations"%' THEN
    RAISE EXCEPTION 'gallring: app.gallring_due has lost the branch for the cover requests (Vikariefrågan, 20270102091000)';
  END IF;
  SELECT p.prosrc INTO src FROM pg_proc p WHERE p.oid = 'app.gallring_purge(uuid, "RetentionDataType", integer)'::regprocedure;
  IF src NOT LIKE '%DELETE FROM "AbsenceWatchFindings"%' THEN
    RAISE EXCEPTION 'gallring: app.gallring_purge has lost the branch for the absence watch''s findings (Frånvarobevakning, 20261231090100)';
  END IF;
  IF src NOT LIKE '%WHEN ''COVER_REQUESTS'' THEN%' OR src NOT LIKE '%DELETE FROM "CoverRequests"%' THEN
    RAISE EXCEPTION 'gallring: app.gallring_purge has lost the branch for the cover requests (Vikariefrågan, 20270102091000)';
  END IF;
END $$;
ROLLBACK;


-- ---------------------------------------------------------------------------
-- Section 316: vem som ser en förfrågan, och vad en tillfrågad får göra.
--
-- The administrator (Drift) sends a request for two lessons to two colleagues
-- and reads all of it. A colleague asked reads their own question, its
-- lessons and their own answer row, and nothing of the other colleague's;
-- a colleague not asked, a pupil, a guardian and the other school's
-- administrator read none. A colleague writes exactly one thing: their own
-- "nej", while the question is open, once. Everything else a teacher tries
-- (a request, a line, a recipient, somebody else's row, a yes, a changed
-- row) is refused or touches nothing. app.cover_request_sender answers the
-- sender to a colleague who was asked, while the question stands, and
-- refuses by SQLSTATE otherwise: CR404, CR411, CR410, CR409 and CR422.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', :'admin_auth_id')::text, true);
CREATE FUNCTION pg_temp.refuses(stmt text, expected text, what text) RETURNS void LANGUAGE plpgsql AS $f$
DECLARE got text := 'none';
BEGIN
  BEGIN
    EXECUTE stmt;
  EXCEPTION WHEN OTHERS THEN
    got := SQLSTATE;
  END;
  IF got IS DISTINCT FROM expected THEN
    RAISE EXCEPTION 'cover requests: % should be refused with %, was %', what, expected, got USING ERRCODE = 'P0001';
  END IF;
END
$f$;
DO $$
DECLARE
  school uuid := app.current_school_id();
  me uuid := app.current_user_id();
  t1 uuid; t2 uuid; t3 uuid; t4 uuid; pupil uuid; guardian uuid;
  l1 uuid; l2 uuid; a uuid; req uuid; req2 uuid; n bigint;
BEGIN
  SELECT id INTO t1 FROM "Users" WHERE "schoolId" = school AND role = 'TEACHER' AND "isActive" ORDER BY "authId" LIMIT 1;
  SELECT id INTO t2 FROM "Users" WHERE "schoolId" = school AND role = 'TEACHER' AND "isActive" AND id NOT IN (t1) ORDER BY "authId" LIMIT 1;
  SELECT id INTO t3 FROM "Users" WHERE "schoolId" = school AND role = 'TEACHER' AND "isActive" AND id NOT IN (t1, t2) ORDER BY "authId" LIMIT 1;
  SELECT id INTO t4 FROM "Users" WHERE "schoolId" = school AND role = 'TEACHER' AND "isActive" AND id NOT IN (t1, t2, t3) ORDER BY "authId" LIMIT 1;
  SELECT id INTO pupil FROM "Users" WHERE "schoolId" = school AND role = 'STUDENT' AND "isActive" ORDER BY "authId" LIMIT 1;
  SELECT id INTO guardian FROM "Users" WHERE "schoolId" = school AND role = 'GUARDIAN' AND "isActive" ORDER BY "authId" LIMIT 1;
  IF t4 IS NULL OR pupil IS NULL OR guardian IS NULL THEN
    RAISE EXCEPTION 'cover requests: the primary school lacks four teachers, a pupil or a guardian';
  END IF;

  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", "updatedAt")
  SELECT school, (SELECT id FROM "Subjects" WHERE "schoolId" = school ORDER BY id LIMIT 1),
         (SELECT id FROM "StudentGroups" WHERE "schoolId" = school ORDER BY id LIMIT 1),
         DATE '2096-03-01' + k, timestamptz '2096-03-01 08:00 UTC' + k * interval '1 day', timestamptz '2096-03-01 09:00 UTC' + k * interval '1 day', now()
    FROM generate_series(0, 1) AS k;
  SELECT id INTO l1 FROM "CalendarLessons" WHERE "schoolId" = school AND date = DATE '2096-03-01';
  SELECT id INTO l2 FROM "CalendarLessons" WHERE "schoolId" = school AND date = DATE '2096-03-02';
  INSERT INTO "TeacherAbsences" ("schoolId", "userId", "startsAt", "endsAt")
  VALUES (school, t1, timestamptz '2096-02-28 00:00 UTC', timestamptz '2096-03-05 00:00 UTC') RETURNING id INTO a;

  -- The administrator sends a request for two lessons to two colleagues.
  INSERT INTO "CoverRequests" ("schoolId", "requestedByUserId", "expiresAt") VALUES (school, me, now() + interval '1 hour') RETURNING id INTO req;
  INSERT INTO "CoverRequestLessons" ("schoolId", "requestId", "absenceId", "calendarLessonId") VALUES (school, req, a, l1), (school, req, a, l2);
  INSERT INTO "CoverRequestRecipients" ("schoolId", "requestId", "userId") VALUES (school, req, t2), (school, req, t3);
  SELECT count(*) INTO n FROM "CoverRequests" WHERE id = req AND status = 'OPEN' AND "closedAt" IS NULL;
  IF n <> 1 THEN RAISE EXCEPTION 'cover requests: the request is not OPEN'; END IF;
  SELECT count(*) INTO n FROM "CoverRequestLessons" WHERE "requestId" = req AND open;
  IF n <> 2 THEN RAISE EXCEPTION 'cover requests: the lessons are not open'; END IF;

  -- What even the administrator is refused: a request born ended, a recipient
  -- born answered, a delete, a move of the time, a yes from nobody asked.
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CoverRequests" ("schoolId", "requestedByUserId", "expiresAt", status, "closedAt") VALUES (%L, %L, now() + interval '1 hour', 'EXPIRED', now())$q$, school, me),
                          'CR400', 'a request born ended');
  -- In somebody else's name it is stored in the writer's: the sender is the one a yes places a vikarie as.
  INSERT INTO "CoverRequests" ("schoolId", "requestedByUserId", "expiresAt") VALUES (school, t2, now() + interval '1 hour') RETURNING id INTO req2;
  IF (SELECT "requestedByUserId" FROM "CoverRequests" WHERE id = req2) <> me THEN
    RAISE EXCEPTION 'cover requests: a request sent in somebody else''s name kept that name';
  END IF;
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CoverRequestRecipients" ("schoolId", "requestId", "userId", answer, "answeredAt") VALUES (%L, %L, %L, 'ACCEPTED', now())$q$, school, req, t4),
                          'CR403', 'a recipient born with a yes');
  PERFORM pg_temp.refuses(format($q$DELETE FROM "CoverRequests" WHERE id = %L$q$, req), '42501', 'a delete of a request');
  PERFORM pg_temp.refuses(format($q$UPDATE "CoverRequests" SET "expiresAt" = "expiresAt" + interval '1 hour' WHERE id = %L$q$, req),
                          'CR400', 'a request moving its time');
  PERFORM pg_temp.refuses(format($q$UPDATE "CoverRequests" SET status = 'ACCEPTED', "acceptedByUserId" = %L WHERE id = %L$q$, t4, req),
                          'CR404', 'a yes from somebody not asked');
  PERFORM pg_temp.refuses(format($q$UPDATE "CoverRequests" SET status = 'ACCEPTED' WHERE id = %L$q$, req),
                          'CR404', 'a yes from nobody');

  -- The administrator reads everything, including both answer rows.
  SELECT count(*) INTO n FROM "CoverRequestRecipients" WHERE "requestId" = req;
  IF n <> 2 THEN RAISE EXCEPTION 'cover requests: the administrator reads % recipient row(s), not 2', n; END IF;

  PERFORM set_config('app.test_rls316_req', req::text, true);
  PERFORM set_config('app.test_rls316_t2', t2::text, true);
  PERFORM set_config('app.test_rls316_t3', t3::text, true);
  PERFORM set_config('app.test_rls316_t4', t4::text, true);
  PERFORM set_config('app.test_rls316_t1', t1::text, true);
  PERFORM set_config('app.test_rls316_l1', l1::text, true);
  PERFORM set_config('app.test_rls316_a', a::text, true);
  PERFORM set_config('app.test_rls316_me_auth', (SELECT "authId"::text FROM "Users" WHERE id = me), true);
  PERFORM set_config('app.test_rls316_t2_auth', (SELECT "authId"::text FROM "Users" WHERE id = t2), true);
  PERFORM set_config('app.test_rls316_t3_auth', (SELECT "authId"::text FROM "Users" WHERE id = t3), true);
  PERFORM set_config('app.test_rls316_t4_auth', (SELECT "authId"::text FROM "Users" WHERE id = t4), true);
  PERFORM set_config('app.test_rls316_pupil_auth', (SELECT "authId"::text FROM "Users" WHERE id = pupil), true);
  PERFORM set_config('app.test_rls316_guardian_auth', (SELECT "authId"::text FROM "Users" WHERE id = guardian), true);
END $$;

-- 316b: the colleague asked (t3) reads their question and nothing of t2's.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('app.test_rls316_t3_auth'))::text, true);
DO $$
DECLARE
  req uuid := current_setting('app.test_rls316_req')::uuid;
  t2 uuid := current_setting('app.test_rls316_t2')::uuid;
  t3 uuid := current_setting('app.test_rls316_t3')::uuid;
  n bigint; sender record;
BEGIN
  IF app.current_user_role() <> 'TEACHER' OR app.current_user_id() <> t3 THEN
    RAISE EXCEPTION 'cover requests: expected to be acting as the third teacher';
  END IF;
  SELECT count(*) INTO n FROM "CoverRequests" WHERE id = req;
  IF n <> 1 THEN RAISE EXCEPTION 'cover requests: a colleague asked reads % request(s), not their own', n; END IF;
  SELECT count(*) INTO n FROM "CoverRequestLessons" WHERE "requestId" = req;
  IF n <> 2 THEN RAISE EXCEPTION 'cover requests: a colleague asked reads % line(s), not 2', n; END IF;
  SELECT count(*) INTO n FROM "CoverRequestRecipients" WHERE "requestId" = req;
  IF n <> 1 THEN RAISE EXCEPTION 'cover requests: a colleague asked reads % answer row(s), not their own', n; END IF;
  SELECT count(*) INTO n FROM "CoverRequestRecipients" WHERE "userId" = t2;
  IF n <> 0 THEN RAISE EXCEPTION 'cover requests: a colleague reads another colleague''s answer'; END IF;
  SELECT count(*) INTO n FROM "CoverConfirmations";
  IF n <> 0 THEN RAISE EXCEPTION 'cover requests: a colleague with no pass reads % confirmation(s)', n; END IF;

  -- What a colleague is refused.
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CoverRequests" ("schoolId", "requestedByUserId", "expiresAt") VALUES (%L, %L, now() + interval '1 hour')$q$, app.current_school_id(), t3),
                          '42501', 'a colleague sending a request');
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CoverRequestRecipients" ("schoolId", "requestId", "userId") VALUES (%L, %L, %L)$q$, app.current_school_id(), req, t3),
                          '42501', 'a colleague adding a recipient');
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CoverConfirmations" ("schoolId", "absenceId", "calendarLessonId", "userId") VALUES (%L, %L, %L, %L)$q$,
                                 app.current_school_id(), current_setting('app.test_rls316_a')::uuid, current_setting('app.test_rls316_l1')::uuid, t3),
                          '42501', 'a colleague writing a confirmation');
  UPDATE "CoverRequests" SET status = 'ACCEPTED', "acceptedByUserId" = t3 WHERE id = req;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'cover requests: a colleague changed a request (% row)', n; END IF;
  PERFORM pg_temp.refuses(format($q$UPDATE "CoverRequestLessons" SET open = false WHERE "requestId" = %L$q$, req), '42501', 'a colleague changing a line');
  -- A yes written straight to their own row: the guard (a BEFORE trigger, which
  -- speaks first) and the arm's WITH CHECK both refuse it.
  PERFORM pg_temp.refuses(format($q$UPDATE "CoverRequestRecipients" SET answer = 'ACCEPTED' WHERE "requestId" = %L AND "userId" = %L$q$, req, t3),
                          'CR403', 'a yes written by the colleague');
  UPDATE "CoverRequestRecipients" SET answer = 'DECLINED' WHERE "requestId" = req AND "userId" = t2;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'cover requests: a colleague declined for another'; END IF;

  -- The sender, to a colleague asked: the administrator who sent it.
  SELECT * INTO sender FROM app.cover_request_sender(req);
  IF sender."authId"::text <> current_setting('app.test_rls316_me_auth') OR sender."userId" IS NULL THEN
    RAISE EXCEPTION 'cover requests: the sender is not the administrator who asked (%)', sender;
  END IF;

  -- Their own no, once, with the clock the database's.
  UPDATE "CoverRequestRecipients" SET answer = 'DECLINED', "answeredAt" = timestamptz '2001-01-01' WHERE "requestId" = req AND "userId" = t3;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'cover requests: a colleague could not decline their own (% row)', n; END IF;
  SELECT count(*) INTO n FROM "CoverRequestRecipients"
   WHERE "requestId" = req AND "userId" = t3 AND answer = 'DECLINED' AND "answeredAt" > now() - interval '1 minute';
  IF n <> 1 THEN RAISE EXCEPTION 'cover requests: the no was not stamped with the database''s clock'; END IF;
  -- The no keeps the time it was given: the same answer written again moves nothing.
  UPDATE "CoverRequestRecipients" SET answer = 'DECLINED', "answeredAt" = timestamptz '2001-01-01' WHERE "requestId" = req AND "userId" = t3;
  SELECT count(*) INTO n FROM "CoverRequestRecipients"
   WHERE "requestId" = req AND "userId" = t3 AND "answeredAt" > now() - interval '1 minute';
  IF n <> 1 THEN RAISE EXCEPTION 'cover requests: a colleague who declined moved the time of the no'; END IF;
  -- Having answered, they are told so and are no longer anybody's yes.
  PERFORM pg_temp.refuses(format($q$SELECT * FROM app.cover_request_sender(%L)$q$, req), 'CR411', 'the sender, to a colleague who answered');
  PERFORM pg_temp.refuses(format($q$UPDATE "CoverRequestRecipients" SET answer = 'PENDING', "answeredAt" = NULL WHERE "requestId" = %L AND "userId" = %L$q$, req, t3),
                          'CR411', 'a no taken back');
END $$;

-- 316c: not asked, a pupil, a guardian and the other school: nothing, and not the sender.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('app.test_rls316_t4_auth'))::text, true);
DO $$
DECLARE n bigint;
BEGIN
  SELECT (SELECT count(*) FROM "CoverRequests") + (SELECT count(*) FROM "CoverRequestLessons")
       + (SELECT count(*) FROM "CoverRequestRecipients") INTO n;
  IF n <> 0 THEN RAISE EXCEPTION 'cover requests: a colleague not asked reads % row(s)', n; END IF;
  PERFORM pg_temp.refuses(format($q$SELECT * FROM app.cover_request_sender(%L)$q$, current_setting('app.test_rls316_req')), 'CR404', 'the sender, to a colleague not asked');
  PERFORM pg_temp.refuses(format($q$SELECT app.cover_confirm(%L)$q$, current_setting('app.test_rls316_l1')), 'CR404', 'a confirmation of a lesson that is not theirs');
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('app.test_rls316_pupil_auth'))::text, true);
DO $$
DECLARE n bigint;
BEGIN
  SELECT (SELECT count(*) FROM "CoverRequests") + (SELECT count(*) FROM "CoverRequestLessons")
       + (SELECT count(*) FROM "CoverRequestRecipients") + (SELECT count(*) FROM "CoverConfirmations") INTO n;
  IF n <> 0 THEN RAISE EXCEPTION 'cover requests: a pupil reads % row(s)', n; END IF;
  PERFORM pg_temp.refuses(format($q$SELECT * FROM app.cover_request_sender(%L)$q$, current_setting('app.test_rls316_req')), 'CR404', 'the sender, to a pupil');
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('app.test_rls316_guardian_auth'))::text, true);
DO $$
DECLARE n bigint;
BEGIN
  SELECT (SELECT count(*) FROM "CoverRequests") + (SELECT count(*) FROM "CoverRequestLessons")
       + (SELECT count(*) FROM "CoverRequestRecipients") + (SELECT count(*) FROM "CoverConfirmations") INTO n;
  IF n <> 0 THEN RAISE EXCEPTION 'cover requests: a guardian reads % row(s)', n; END IF;
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000006')::text, true);
DO $$
DECLARE n bigint;
BEGIN
  SELECT (SELECT count(*) FROM "CoverRequests") + (SELECT count(*) FROM "CoverRequestLessons")
       + (SELECT count(*) FROM "CoverRequestRecipients") + (SELECT count(*) FROM "CoverConfirmations") INTO n;
  IF n <> 0 THEN RAISE EXCEPTION 'cover requests: another school''s administrator reads % row(s)', n; END IF;
  PERFORM pg_temp.refuses(format($q$SELECT * FROM app.cover_request_sender(%L)$q$, current_setting('app.test_rls316_req')), 'CR404', 'the sender, to another school');
END $$;

-- 316d: the question's endings, as the colleague who is still asked (t2) meets them.
SELECT set_config('request.jwt.claims', json_build_object('sub', :'admin_auth_id')::text, true);
DO $$
DECLARE
  req uuid := current_setting('app.test_rls316_req')::uuid;
  school uuid := app.current_school_id();
  n bigint;
BEGIN
  -- A sender removed from the request can place nobody (CR422), and the
  -- request keeps its history; the one the key's SET NULL leaves is this.
  UPDATE "CoverRequests" SET "requestedByUserId" = NULL WHERE id = req;
  PERFORM set_config('app.test_rls316_after_sender_null', 'x', true);
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('app.test_rls316_t2_auth'))::text, true);
DO $$
BEGIN
  PERFORM pg_temp.refuses(format($q$SELECT * FROM app.cover_request_sender(%L)$q$, current_setting('app.test_rls316_req')), 'CR422', 'the sender of a request whose sender is gone');
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', :'admin_auth_id')::text, true);
DO $$
DECLARE
  req uuid := current_setting('app.test_rls316_req')::uuid;
  t2 uuid := current_setting('app.test_rls316_t2')::uuid;
BEGIN
  -- Withdrawn: the colleague asked is told it is gone, and cannot decline into it.
  UPDATE "CoverRequests" SET status = 'WITHDRAWN' WHERE id = req;
  IF (SELECT count(*) FROM "CoverRequestLessons" WHERE "requestId" = req AND open) <> 0 THEN
    RAISE EXCEPTION 'cover requests: a withdrawn request still holds its lessons open';
  END IF;
  IF (SELECT "closedAt" FROM "CoverRequests" WHERE id = req) IS NULL THEN
    RAISE EXCEPTION 'cover requests: a withdrawn request has no end';
  END IF;
  PERFORM set_config('app.test_rls316_withdrawn', t2::text, true);
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('app.test_rls316_t2_auth'))::text, true);
DO $$
DECLARE req uuid := current_setting('app.test_rls316_req')::uuid;
BEGIN
  PERFORM pg_temp.refuses(format($q$SELECT * FROM app.cover_request_sender(%L)$q$, req), 'CR410', 'the sender of a withdrawn request');
  PERFORM pg_temp.refuses(format($q$UPDATE "CoverRequestRecipients" SET answer = 'DECLINED' WHERE "requestId" = %L AND "userId" = %L$q$, req, app.current_user_id()),
                          'CR412', 'a no to a question that has ended');
END $$;
ROLLBACK;


-- ---------------------------------------------------------------------------
-- Section 317: en förfrågan slutar en gång, och det första jaet är det enda.
--
-- What the database says by itself of the first yes (the race over real
-- connections is the adapter probe's, probe-cover-requests.ts): ACCEPTED
-- needs somebody asked who has not answered (CR404) and a request that has
-- not expired by the database's clock (CR410); the end is stamped by the
-- database (closedAt, acceptedAt), closes the lessons for a new request,
-- and is final (CR412); two open requests never ask for one lesson (23505);
-- a decision on the lesson ends the request that asks for it (CLOSED); a
-- colleague answers once (CR411); a yes writes the answer row itself.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', :'admin_auth_id')::text, true);
CREATE FUNCTION pg_temp.refuses(stmt text, expected text, what text) RETURNS void LANGUAGE plpgsql AS $f$
DECLARE got text := 'none';
BEGIN
  BEGIN
    EXECUTE stmt;
  EXCEPTION WHEN OTHERS THEN
    got := SQLSTATE;
  END;
  IF got IS DISTINCT FROM expected THEN
    RAISE EXCEPTION 'cover requests: % should be refused with %, was %', what, expected, got USING ERRCODE = 'P0001';
  END IF;
END
$f$;
DO $$
DECLARE
  school uuid := app.current_school_id();
  me uuid := app.current_user_id();
  t1 uuid; t2 uuid; t3 uuid;
  l uuid; l3 uuid; a uuid; r1 uuid; r2 uuid; r3 uuid; rx uuid;
  me_auth text; t2_auth text; t3_auth text;
  rec "CoverRequests";
  n bigint;
BEGIN
  SELECT id INTO t1 FROM "Users" WHERE "schoolId" = school AND role = 'TEACHER' AND "isActive" ORDER BY "authId" LIMIT 1;
  SELECT id INTO t2 FROM "Users" WHERE "schoolId" = school AND role = 'TEACHER' AND "isActive" AND id <> t1 ORDER BY "authId" LIMIT 1;
  SELECT id INTO t3 FROM "Users" WHERE "schoolId" = school AND role = 'TEACHER' AND "isActive" AND id NOT IN (t1, t2) ORDER BY "authId" LIMIT 1;
  -- The logins, read while this is still the administrator: a teacher reads no one else's.
  SELECT "authId"::text INTO me_auth FROM "Users" WHERE id = me;
  SELECT "authId"::text INTO t2_auth FROM "Users" WHERE id = t2;
  SELECT "authId"::text INTO t3_auth FROM "Users" WHERE id = t3;
  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", "updatedAt")
  VALUES (school, (SELECT id FROM "Subjects" WHERE "schoolId" = school ORDER BY id LIMIT 1),
          (SELECT id FROM "StudentGroups" WHERE "schoolId" = school ORDER BY id LIMIT 1),
          DATE '2097-03-01', timestamptz '2097-03-01 08:00 UTC', timestamptz '2097-03-01 09:00 UTC', now())
  RETURNING id INTO l;
  INSERT INTO "CalendarLessonTeachers" ("schoolId", "calendarLessonId", "teacherId", role) VALUES (school, l, t1, 'LEAD');
  INSERT INTO "TeacherAbsences" ("schoolId", "userId", "startsAt", "endsAt")
  VALUES (school, t1, timestamptz '2097-02-28 00:00 UTC', timestamptz '2097-03-05 00:00 UTC') RETURNING id INTO a;

  -- Two requests never ask for one lesson at once.
  INSERT INTO "CoverRequests" ("schoolId", "requestedByUserId", "expiresAt") VALUES (school, me, now() + interval '1 hour') RETURNING id INTO r1;
  INSERT INTO "CoverRequestLessons" ("schoolId", "requestId", "absenceId", "calendarLessonId") VALUES (school, r1, a, l);
  INSERT INTO "CoverRequestRecipients" ("schoolId", "requestId", "userId") VALUES (school, r1, t2), (school, r1, t3);
  INSERT INTO "CoverRequests" ("schoolId", "requestedByUserId", "expiresAt") VALUES (school, me, now() + interval '1 hour') RETURNING id INTO r2;
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CoverRequestLessons" ("schoolId", "requestId", "absenceId", "calendarLessonId") VALUES (%L, %L, %L, %L)$q$, school, r2, a, l),
                          '23505', 'a second open request for one lesson');

  -- The first yes: the stamps are the database's, whatever the writer says.
  UPDATE "CoverRequests" SET status = 'ACCEPTED', "acceptedByUserId" = t2, "acceptedAt" = timestamptz '2001-01-01', "closedAt" = timestamptz '2001-01-01' WHERE id = r1;
  SELECT * INTO rec FROM "CoverRequests" WHERE id = r1;
  IF rec.status <> 'ACCEPTED' OR rec."acceptedByUserId" <> t2 OR rec."acceptedAt" < now() - interval '1 minute'
     OR rec."closedAt" <> rec."acceptedAt" THEN
    RAISE EXCEPTION 'cover requests: the first yes is not stamped by the database (%)', rec;
  END IF;
  IF (SELECT count(*) FROM "CoverRequestLessons" WHERE "requestId" = r1 AND open) <> 0 THEN
    RAISE EXCEPTION 'cover requests: an accepted request still holds its lesson open';
  END IF;
  UPDATE "CoverRequestRecipients" SET answer = 'ACCEPTED' WHERE "requestId" = r1 AND "userId" = t2;
  IF (SELECT "answeredAt" FROM "CoverRequestRecipients" WHERE "requestId" = r1 AND "userId" = t2) IS NULL THEN
    RAISE EXCEPTION 'cover requests: a yes is not stamped on the answer row';
  END IF;

  -- The one who said yes asking again is told it is theirs (a lost answer, a second tap).
  PERFORM set_config('request.jwt.claims', json_build_object('sub', t2_auth)::text, true);
  PERFORM pg_temp.refuses(format($q$SELECT * FROM app.cover_request_sender(%L)$q$, r1), 'CR413', 'the sender, to the colleague who said yes');
  PERFORM set_config('request.jwt.claims', json_build_object('sub', t3_auth)::text, true);
  PERFORM pg_temp.refuses(format($q$SELECT * FROM app.cover_request_sender(%L)$q$, r1), 'CR409', 'the sender, to a colleague who came second');
  PERFORM set_config('request.jwt.claims', json_build_object('sub', me_auth)::text, true);

  -- Lines and recipients are added to an open request only: a line put into an
  -- ended one would be born open and hold its lesson against every new request.
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CoverRequestLessons" ("schoolId", "requestId", "absenceId", "calendarLessonId") VALUES (%L, %L, %L, %L)$q$, school, r1, a, l),
                          '42501', 'a line added to a request that has ended');
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CoverRequestRecipients" ("schoolId", "requestId", "userId") VALUES (%L, %L, %L)$q$, school, r1, t1),
                          '42501', 'a colleague added to a request that has ended');

  -- The end is final, whoever asks.
  PERFORM pg_temp.refuses(format($q$UPDATE "CoverRequests" SET status = 'ACCEPTED', "acceptedByUserId" = %L WHERE id = %L$q$, t3, r1), 'CR412', 'a second yes');
  PERFORM pg_temp.refuses(format($q$UPDATE "CoverRequests" SET status = 'WITHDRAWN' WHERE id = %L$q$, r1), 'CR412', 'a withdrawal after the yes');
  PERFORM pg_temp.refuses(format($q$UPDATE "CoverRequests" SET status = 'OPEN', "closedAt" = NULL, "acceptedAt" = NULL WHERE id = %L$q$, r1), 'CR412', 'a request reopened');
  PERFORM pg_temp.refuses(format($q$UPDATE "CoverRequestRecipients" SET answer = 'DECLINED' WHERE "requestId" = %L AND "userId" = %L$q$, r1, t2),
                          'CR411', 'a yes taken back as a no');

  -- The lesson is free for a new request once the old has ended (r2 is its own).
  INSERT INTO "CoverRequestLessons" ("schoolId", "requestId", "absenceId", "calendarLessonId") VALUES (school, r2, a, l);
  INSERT INTO "CoverRequestRecipients" ("schoolId", "requestId", "userId") VALUES (school, r2, t3);

  -- A yes after the time is out: the database's clock decides, not the writer's.
  -- On a lesson of its own and on firm ground (the absent teacher is on it, the absence is active),
  -- so that what ends it is its time and nothing else.
  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", "updatedAt")
  VALUES (school, (SELECT id FROM "Subjects" WHERE "schoolId" = school ORDER BY id LIMIT 1),
          (SELECT id FROM "StudentGroups" WHERE "schoolId" = school ORDER BY id LIMIT 1),
          DATE '2097-03-02', timestamptz '2097-03-02 08:00 UTC', timestamptz '2097-03-02 09:00 UTC', now())
  RETURNING id INTO l3;
  INSERT INTO "CalendarLessonTeachers" ("schoolId", "calendarLessonId", "teacherId", role) VALUES (school, l3, t1, 'LEAD');
  INSERT INTO "CoverRequests" ("schoolId", "requestedByUserId", "expiresAt") VALUES (school, me, now() + interval '1 second') RETURNING id INTO r3;
  INSERT INTO "CoverRequestLessons" ("schoolId", "requestId", "absenceId", "calendarLessonId") VALUES (school, r3, a, l3);
  INSERT INTO "CoverRequestRecipients" ("schoolId", "requestId", "userId") VALUES (school, r3, t3);
  PERFORM pg_sleep(1.3);
  PERFORM pg_temp.refuses(format($q$UPDATE "CoverRequests" SET status = 'ACCEPTED', "acceptedByUserId" = %L WHERE id = %L$q$, t3, r3), 'CR410', 'a yes after the time is out');
  -- The job's door has no login: a person who calls it is refused, the job is not.
  PERFORM pg_temp.refuses($q$SELECT * FROM app.cover_requests_settle()$q$, 'CR403', 'the settling run by a person');
  PERFORM set_config('request.jwt.claims', '', true);
  SELECT count(*) INTO n FROM app.cover_requests_settle() s
   WHERE s."requestId" = r3 AND s."outcome" = 'EXPIRED' AND s."senderId" = me AND s."senderAuthId"::text = me_auth;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', me_auth)::text, true);
  IF n <> 1 THEN
    RAISE EXCEPTION 'cover requests: the pass did not answer the request that ran out, with the administrator who sent it';
  END IF;
  IF (SELECT status FROM "CoverRequests" WHERE id = r3) <> 'EXPIRED' THEN
    RAISE EXCEPTION 'cover requests: the pass did not end the request that ran out';
  END IF;
  IF (SELECT status FROM "CoverRequests" WHERE id = r2) <> 'OPEN' THEN
    RAISE EXCEPTION 'cover requests: the pass ended a request that has time left and firm ground';
  END IF;

  -- A decision on the lesson, made another way, ends the request that asks for it.
  INSERT INTO "TeacherAbsenceCovers" ("schoolId", "absenceId", "calendarLessonId", "absentTeacherId", decision, "removedTeachers", "decidedByUserId")
  VALUES (school, a, l, t1, 'CO_TEACHER', jsonb_build_array(jsonb_build_object('teacherId', t1, 'role', 'LEAD')), me);
  SELECT * INTO rec FROM "CoverRequests" WHERE id = r2;
  IF rec.status <> 'CLOSED' OR rec."closedAt" IS NULL OR rec."acceptedAt" IS NOT NULL THEN
    RAISE EXCEPTION 'cover requests: a decision on the lesson did not close its request (%)', rec;
  END IF;
  IF (SELECT count(*) FROM "CoverRequestLessons" WHERE "requestId" = r2 AND open) <> 0 THEN
    RAISE EXCEPTION 'cover requests: a closed request still holds its lesson open';
  END IF;
  -- And a decision on a lesson nobody asked about moves nothing.
  UPDATE "TeacherAbsenceCovers" SET "decidedAt" = now() WHERE "absenceId" = a AND "calendarLessonId" = l;

  -- A decision's own change closes a request; a key's SET NULL of who decided it
  -- (a person removed) is no decision on the lesson. r5 asks for the pair the
  -- decision above is on.
  INSERT INTO "CoverRequests" ("schoolId", "requestedByUserId", "expiresAt") VALUES (school, me, now() + interval '1 hour') RETURNING id INTO rx;
  INSERT INTO "CoverRequestLessons" ("schoolId", "requestId", "absenceId", "calendarLessonId") VALUES (school, rx, a, l);
  UPDATE "TeacherAbsenceCovers" SET "decidedByUserId" = NULL WHERE "absenceId" = a AND "calendarLessonId" = l;
  IF (SELECT status FROM "CoverRequests" WHERE id = rx) <> 'OPEN' THEN
    RAISE EXCEPTION 'cover requests: clearing who decided a lesson ended the question about it';
  END IF;
  UPDATE "TeacherAbsenceCovers" SET decision = 'SUPERVISED_STUDY', "substituteId" = NULL WHERE "absenceId" = a AND "calendarLessonId" = l;
  IF (SELECT status FROM "CoverRequests" WHERE id = rx) <> 'CLOSED' THEN
    RAISE EXCEPTION 'cover requests: a changed decision did not end the question about its lesson';
  END IF;

  -- A person removed clears their own column and nothing else: the request
  -- they sent stays, and cannot be answered.
  DELETE FROM "Users" WHERE id = t2;
  SELECT * INTO rec FROM "CoverRequests" WHERE id = r1;
  IF rec."acceptedByUserId" IS NOT NULL OR rec.status <> 'ACCEPTED' OR rec."acceptedAt" IS NULL THEN
    RAISE EXCEPTION 'cover requests: removing the one who said yes changed more than their column (%)', rec;
  END IF;
  IF (SELECT count(*) FROM "CoverRequestRecipients" WHERE "requestId" = r1 AND "userId" = t2) <> 0 THEN
    RAISE EXCEPTION 'cover requests: a removed person still has an answer row';
  END IF;
END $$;

-- 317b: the job's pass ends a request whose grounds are gone (CLOSED, outcome
-- NOT_NEEDED) and leaves one on firm ground alone; grounds gone come before
-- time out; a request whose sender is gone is ended all the same.
CREATE FUNCTION pg_temp.settled(req uuid, back text) RETURNS text LANGUAGE plpgsql AS $f$
DECLARE o text;
BEGIN
  PERFORM set_config('request.jwt.claims', '', true);
  SELECT s."outcome" INTO o FROM app.cover_requests_settle() s WHERE s."requestId" = req;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', back)::text, true);
  RETURN coalesce(o, 'none');
END
$f$;
DO $$
DECLARE
  school uuid := app.current_school_id();
  me uuid := app.current_user_id();
  me_auth text;
  t1 uuid; t2 uuid;
  l uuid; a uuid; r uuid; r2 uuid;
  k integer := 0;
  kind text;
  day date;
  got text;
  subj uuid := (SELECT id FROM "Subjects" WHERE "schoolId" = school ORDER BY id LIMIT 1);
  grp uuid := (SELECT id FROM "StudentGroups" WHERE "schoolId" = school ORDER BY id LIMIT 1);
BEGIN
  SELECT "authId"::text INTO me_auth FROM "Users" WHERE id = me;
  SELECT id INTO t1 FROM "Users" WHERE "schoolId" = school AND role = 'TEACHER' AND "isActive" ORDER BY "authId" LIMIT 1;
  SELECT id INTO t2 FROM "Users" WHERE "schoolId" = school AND role = 'TEACHER' AND "isActive" AND id <> t1 ORDER BY "authId" LIMIT 1;

  FOREACH kind IN ARRAY ARRAY['cancelled', 'withdrawn', 'shortened', 'teacher_left', 'lesson_removed'] LOOP
    k := k + 1;
    day := DATE '2098-01-01' + k;
    INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", "updatedAt")
    VALUES (school, subj, grp, day, (day::timestamp AT TIME ZONE 'UTC') + interval '8 hours', (day::timestamp AT TIME ZONE 'UTC') + interval '9 hours', now())
    RETURNING id INTO l;
    INSERT INTO "CalendarLessonTeachers" ("schoolId", "calendarLessonId", "teacherId", role) VALUES (school, l, t1, 'LEAD');
    INSERT INTO "TeacherAbsences" ("schoolId", "userId", "startsAt", "endsAt")
    VALUES (school, t1, day::timestamp AT TIME ZONE 'UTC', (day::timestamp AT TIME ZONE 'UTC') + interval '1 day') RETURNING id INTO a;
    INSERT INTO "CoverRequests" ("schoolId", "requestedByUserId", "expiresAt") VALUES (school, me, now() + interval '1 hour') RETURNING id INTO r;
    INSERT INTO "CoverRequestLessons" ("schoolId", "requestId", "absenceId", "calendarLessonId") VALUES (school, r, a, l);
    INSERT INTO "CoverRequestRecipients" ("schoolId", "requestId", "userId") VALUES (school, r, t2);

    IF pg_temp.settled(r, me_auth) <> 'none' OR (SELECT status FROM "CoverRequests" WHERE id = r) <> 'OPEN' THEN
      RAISE EXCEPTION 'cover requests (%): the pass ended a request on firm ground', kind;
    END IF;

    IF kind = 'cancelled' THEN
      UPDATE "CalendarLessons" SET status = 'CANCELLED', "cancelCause" = 'EVENT' WHERE id = l;
    ELSIF kind = 'withdrawn' THEN
      UPDATE "TeacherAbsences" SET status = 'WITHDRAWN', "withdrawnAt" = now() WHERE id = a;
    ELSIF kind = 'shortened' THEN
      UPDATE "TeacherAbsences" SET "endsAt" = (day::timestamp AT TIME ZONE 'UTC') + interval '6 hours' WHERE id = a;
    ELSIF kind = 'teacher_left' THEN
      DELETE FROM "CalendarLessonTeachers" WHERE "calendarLessonId" = l AND "teacherId" = t1;
    ELSE
      -- The line goes with its lesson (the key's CASCADE): a request with no line left.
      DELETE FROM "CalendarLessons" WHERE id = l;
    END IF;

    got := pg_temp.settled(r, me_auth);
    IF got <> 'NOT_NEEDED' THEN
      RAISE EXCEPTION 'cover requests (%): the pass answered % for a request whose grounds are gone, not NOT_NEEDED', kind, got;
    END IF;
    IF (SELECT status FROM "CoverRequests" WHERE id = r) <> 'CLOSED' OR (SELECT "closedAt" FROM "CoverRequests" WHERE id = r) IS NULL
       OR (SELECT count(*) FROM "CoverRequestLessons" WHERE "requestId" = r AND open) <> 0 THEN
      RAISE EXCEPTION 'cover requests (%): the pass did not close the request and free its lessons', kind;
    END IF;
    -- Ended once: the next pass finds nothing to do.
    IF pg_temp.settled(r, me_auth) <> 'none' THEN
      RAISE EXCEPTION 'cover requests (%): the pass settled a request twice', kind;
    END IF;
  END LOOP;

  -- The absent teacher's row is gone because a decision of the board put a
  -- vikarie on the lesson; the vikarie is away themself, so the pair is open
  -- again on the board and a question about it stands. The pass leaves it be
  -- (the decision is what tells where the absent teacher went).
  day := DATE '2098-01-20';
  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", "updatedAt")
  VALUES (school, subj, grp, day, (day::timestamp AT TIME ZONE 'UTC') + interval '8 hours', (day::timestamp AT TIME ZONE 'UTC') + interval '9 hours', now())
  RETURNING id INTO l;
  INSERT INTO "TeacherAbsences" ("schoolId", "userId", "startsAt", "endsAt")
  VALUES (school, t1, day::timestamp AT TIME ZONE 'UTC', (day::timestamp AT TIME ZONE 'UTC') + interval '1 day') RETURNING id INTO a;
  INSERT INTO "TeacherAbsenceCovers" ("schoolId", "absenceId", "calendarLessonId", "absentTeacherId", decision, "removedTeachers", "substituteId", "decidedByUserId")
  VALUES (school, a, l, t1, 'SUBSTITUTE', jsonb_build_array(jsonb_build_object('teacherId', t1, 'role', 'LEAD')), t2, me);
  -- The decision is made first: it would close a request that already stood.
  INSERT INTO "CoverRequests" ("schoolId", "requestedByUserId", "expiresAt") VALUES (school, me, now() + interval '1 hour') RETURNING id INTO r;
  INSERT INTO "CoverRequestLessons" ("schoolId", "requestId", "absenceId", "calendarLessonId") VALUES (school, r, a, l);
  INSERT INTO "CoverRequestRecipients" ("schoolId", "requestId", "userId") VALUES (school, r, t2);
  IF pg_temp.settled(r, me_auth) <> 'none' OR (SELECT status FROM "CoverRequests" WHERE id = r) <> 'OPEN' THEN
    RAISE EXCEPTION 'cover requests: the pass closed a question about a pair the board still needs covered (the vikarie is away themself)';
  END IF;
  -- With the decision gone and the absent teacher still off the lesson, nothing says where they went.
  DELETE FROM "TeacherAbsenceCovers" WHERE "absenceId" = a AND "calendarLessonId" = l;
  IF pg_temp.settled(r, me_auth) <> 'NOT_NEEDED' THEN
    RAISE EXCEPTION 'cover requests: the pass kept a question about a lesson the absent teacher has left with no decision to say why';
  END IF;

  -- Grounds gone come before time out: a question that ran out in the same
  -- hour as the absence was taken back is said to have been taken back.
  day := DATE '2098-02-01';
  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", "updatedAt")
  VALUES (school, subj, grp, day, (day::timestamp AT TIME ZONE 'UTC') + interval '8 hours', (day::timestamp AT TIME ZONE 'UTC') + interval '9 hours', now())
  RETURNING id INTO l;
  INSERT INTO "CalendarLessonTeachers" ("schoolId", "calendarLessonId", "teacherId", role) VALUES (school, l, t1, 'LEAD');
  INSERT INTO "TeacherAbsences" ("schoolId", "userId", "startsAt", "endsAt")
  VALUES (school, t1, day::timestamp AT TIME ZONE 'UTC', (day::timestamp AT TIME ZONE 'UTC') + interval '1 day') RETURNING id INTO a;
  INSERT INTO "CoverRequests" ("schoolId", "requestedByUserId", "expiresAt") VALUES (school, me, now() + interval '1 second') RETURNING id INTO r2;
  INSERT INTO "CoverRequestLessons" ("schoolId", "requestId", "absenceId", "calendarLessonId") VALUES (school, r2, a, l);
  INSERT INTO "CoverRequestRecipients" ("schoolId", "requestId", "userId") VALUES (school, r2, t2);
  UPDATE "CalendarLessons" SET status = 'CANCELLED', "cancelCause" = 'EVENT' WHERE id = l;
  PERFORM pg_sleep(1.3);
  got := pg_temp.settled(r2, me_auth);
  IF got <> 'NOT_NEEDED' OR (SELECT status FROM "CoverRequests" WHERE id = r2) <> 'CLOSED' THEN
    RAISE EXCEPTION 'cover requests: a question both out of time and without grounds ended as % / %, not NOT_NEEDED / CLOSED',
      got, (SELECT status FROM "CoverRequests" WHERE id = r2);
  END IF;

  -- A sender who is gone (the key's SET NULL) leaves the request ended all the
  -- same, with nobody to tell it to: the row's sender columns are NULL.
  day := DATE '2098-03-01';
  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", "updatedAt")
  VALUES (school, subj, grp, day, (day::timestamp AT TIME ZONE 'UTC') + interval '8 hours', (day::timestamp AT TIME ZONE 'UTC') + interval '9 hours', now())
  RETURNING id INTO l;
  INSERT INTO "CalendarLessonTeachers" ("schoolId", "calendarLessonId", "teacherId", role) VALUES (school, l, t1, 'LEAD');
  INSERT INTO "TeacherAbsences" ("schoolId", "userId", "startsAt", "endsAt")
  VALUES (school, t1, day::timestamp AT TIME ZONE 'UTC', (day::timestamp AT TIME ZONE 'UTC') + interval '1 day') RETURNING id INTO a;
  INSERT INTO "CoverRequests" ("schoolId", "requestedByUserId", "expiresAt") VALUES (school, me, now() + interval '1 second') RETURNING id INTO r;
  INSERT INTO "CoverRequestLessons" ("schoolId", "requestId", "absenceId", "calendarLessonId") VALUES (school, r, a, l);
  INSERT INTO "CoverRequestRecipients" ("schoolId", "requestId", "userId") VALUES (school, r, t2);
  UPDATE "CoverRequests" SET "requestedByUserId" = NULL WHERE id = r;
  PERFORM pg_sleep(1.3);
  PERFORM set_config('request.jwt.claims', '', true);
  SELECT count(*) INTO k FROM app.cover_requests_settle() s
   WHERE s."requestId" = r AND s."outcome" = 'EXPIRED' AND s."senderId" IS NULL AND s."senderAuthId" IS NULL AND s."senderProfile" IS NULL;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', me_auth)::text, true);
  IF k <> 1 OR (SELECT status FROM "CoverRequests" WHERE id = r) <> 'EXPIRED' THEN
    RAISE EXCEPTION 'cover requests: a request whose sender is gone was not ended with no sender to tell';
  END IF;
END $$;
ROLLBACK;


-- ---------------------------------------------------------------------------
-- Section 318: vikarien bekräftar sitt pass med ett tryck.
--
-- app.cover_confirm writes the caller's own confirmation of a pass a cover
-- decision gave them and nobody else's; it is idempotent, refuses a lesson
-- that is not theirs (CR404), one that is over, and one held by somebody
-- else. A decision handed to another vikarie takes the old confirmation
-- with it, and an undone decision takes it too. The colleague reads their
-- own confirmations and nobody's else; app.cover_my_passes answers their
-- passes and whether they are confirmed, to them alone.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', :'admin_auth_id')::text, true);
CREATE FUNCTION pg_temp.refuses(stmt text, expected text, what text) RETURNS void LANGUAGE plpgsql AS $f$
DECLARE got text := 'none';
BEGIN
  BEGIN
    EXECUTE stmt;
  EXCEPTION WHEN OTHERS THEN
    got := SQLSTATE;
  END;
  IF got IS DISTINCT FROM expected THEN
    RAISE EXCEPTION 'cover confirmations: % should be refused with %, was %', what, expected, got USING ERRCODE = 'P0001';
  END IF;
END
$f$;
DO $$
DECLARE
  school uuid := app.current_school_id();
  me uuid := app.current_user_id();
  t1 uuid; t2 uuid; t3 uuid;
  l uuid; lpast uuid; a uuid; apast uuid;
BEGIN
  SELECT id INTO t1 FROM "Users" WHERE "schoolId" = school AND role = 'TEACHER' AND "isActive" ORDER BY "authId" LIMIT 1;
  SELECT id INTO t2 FROM "Users" WHERE "schoolId" = school AND role = 'TEACHER' AND "isActive" AND id <> t1 ORDER BY "authId" LIMIT 1;
  SELECT id INTO t3 FROM "Users" WHERE "schoolId" = school AND role = 'TEACHER' AND "isActive" AND id NOT IN (t1, t2) ORDER BY "authId" LIMIT 1;
  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", "updatedAt")
  SELECT school, (SELECT id FROM "Subjects" WHERE "schoolId" = school ORDER BY id LIMIT 1),
         (SELECT id FROM "StudentGroups" WHERE "schoolId" = school ORDER BY id LIMIT 1),
         d, d + time '08:00', d + time '09:00', now()
    FROM (VALUES (DATE '2098-03-01'), (DATE '2020-03-02')) AS v(d);
  SELECT id INTO l FROM "CalendarLessons" WHERE "schoolId" = school AND date = DATE '2098-03-01';
  SELECT id INTO lpast FROM "CalendarLessons" WHERE "schoolId" = school AND date = DATE '2020-03-02';
  INSERT INTO "TeacherAbsences" ("schoolId", "userId", "startsAt", "endsAt")
  VALUES (school, t1, timestamptz '2098-02-28 00:00 UTC', timestamptz '2098-03-05 00:00 UTC') RETURNING id INTO a;
  INSERT INTO "TeacherAbsences" ("schoolId", "userId", "startsAt", "endsAt", status, "withdrawnAt")
  VALUES (school, t1, timestamptz '2020-03-01 00:00 UTC', timestamptz '2020-03-05 00:00 UTC', 'WITHDRAWN', now()) RETURNING id INTO apast;
  INSERT INTO "CalendarLessonTeachers" ("calendarLessonId", "teacherId", "schoolId", role) VALUES (l, t2, school, 'SUBSTITUTE'), (lpast, t2, school, 'SUBSTITUTE');
  INSERT INTO "TeacherAbsenceCovers" ("schoolId", "absenceId", "calendarLessonId", "absentTeacherId", decision, "removedTeachers", "substituteId", "decidedByUserId")
  VALUES (school, a, l, t1, 'SUBSTITUTE', jsonb_build_array(jsonb_build_object('teacherId', t1, 'role', 'LEAD')), t2, me),
         (school, apast, lpast, t1, 'SUBSTITUTE', jsonb_build_array(jsonb_build_object('teacherId', t1, 'role', 'LEAD')), t2, me);
  PERFORM set_config('app.test_rls318_l', l::text, true);
  PERFORM set_config('app.test_rls318_lpast', lpast::text, true);
  PERFORM set_config('app.test_rls318_a', a::text, true);
  PERFORM set_config('app.test_rls318_t2', t2::text, true);
  PERFORM set_config('app.test_rls318_t3', t3::text, true);
  PERFORM set_config('app.test_rls318_t2_auth', (SELECT "authId"::text FROM "Users" WHERE id = t2), true);
  PERFORM set_config('app.test_rls318_t3_auth', (SELECT "authId"::text FROM "Users" WHERE id = t3), true);
  IF (SELECT count(*) FROM "CoverConfirmations" WHERE "calendarLessonId" = l) <> 0 THEN
    RAISE EXCEPTION 'cover confirmations: a decision is born confirmed';
  END IF;
END $$;

-- 318b: the vikarie (t2).
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('app.test_rls318_t2_auth'))::text, true);
DO $$
DECLARE
  l uuid := current_setting('app.test_rls318_l')::uuid;
  n integer; passes record; first_at timestamptz;
BEGIN
  -- Before the tap: the pass is theirs, and unconfirmed.
  SELECT count(*) INTO n FROM app.cover_my_passes(now(), now() + interval '200 years');
  IF n <> 1 THEN RAISE EXCEPTION 'cover confirmations: the vikarie has % pass(es), not the one ahead', n; END IF;
  SELECT * INTO passes FROM app.cover_my_passes(now(), now() + interval '200 years');
  IF passes."calendarLessonId" <> l OR passes."confirmedAt" IS NOT NULL THEN
    RAISE EXCEPTION 'cover confirmations: the pass is not theirs and unconfirmed (%)', passes;
  END IF;
  n := app.cover_confirm(l);
  IF n <> 1 THEN RAISE EXCEPTION 'cover confirmations: the tap confirmed % pass(es)', n; END IF;
  SELECT "confirmedAt" INTO first_at FROM "CoverConfirmations" WHERE "calendarLessonId" = l;
  IF first_at IS NULL THEN RAISE EXCEPTION 'cover confirmations: the colleague cannot read their own confirmation'; END IF;
  -- Again: still one, and the first tap stands.
  n := app.cover_confirm(l);
  IF n <> 1 OR (SELECT count(*) FROM "CoverConfirmations" WHERE "calendarLessonId" = l) <> 1
     OR (SELECT "confirmedAt" FROM "CoverConfirmations" WHERE "calendarLessonId" = l) <> first_at THEN
    RAISE EXCEPTION 'cover confirmations: a second tap changed something';
  END IF;
  SELECT * INTO passes FROM app.cover_my_passes(now(), now() + interval '200 years');
  IF passes."confirmedAt" IS DISTINCT FROM first_at THEN
    RAISE EXCEPTION 'cover confirmations: the pass does not say when it was confirmed (%)', passes;
  END IF;
  -- A pass already held is not confirmed after the fact.
  PERFORM pg_temp.refuses(format($q$SELECT app.cover_confirm(%L)$q$, current_setting('app.test_rls318_lpast')), 'CR404', 'a tap on a lesson that is over');
  PERFORM pg_temp.refuses(format($q$SELECT app.cover_confirm(%L)$q$, gen_random_uuid()), 'CR404', 'a tap on a lesson that does not exist');
  -- Nothing written by hand.
  PERFORM pg_temp.refuses(format($q$UPDATE "CoverConfirmations" SET "confirmedAt" = now() WHERE "calendarLessonId" = %L$q$, l), '42501', 'an UPDATE of a confirmation');
END $$;

-- 318c: a colleague who is not the vikarie reads and confirms nothing of theirs.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('app.test_rls318_t3_auth'))::text, true);
DO $$
BEGIN
  IF (SELECT count(*) FROM "CoverConfirmations") <> 0 THEN
    RAISE EXCEPTION 'cover confirmations: another colleague reads a confirmation';
  END IF;
  IF (SELECT count(*) FROM app.cover_my_passes(now() - interval '100 years', now() + interval '200 years')) <> 0 THEN
    RAISE EXCEPTION 'cover confirmations: another colleague is shown a pass that is not theirs';
  END IF;
  PERFORM pg_temp.refuses(format($q$SELECT app.cover_confirm(%L)$q$, current_setting('app.test_rls318_l')), 'CR404', 'a tap on somebody else''s pass');
END $$;

-- 318d: the decision handed on, and undone.
SELECT set_config('request.jwt.claims', json_build_object('sub', :'admin_auth_id')::text, true);
DO $$
DECLARE
  l uuid := current_setting('app.test_rls318_l')::uuid;
  a uuid := current_setting('app.test_rls318_a')::uuid;
  t3 uuid := current_setting('app.test_rls318_t3')::uuid;
BEGIN
  IF (SELECT count(*) FROM "CoverConfirmations" WHERE "calendarLessonId" = l) <> 1 THEN
    RAISE EXCEPTION 'cover confirmations: the administrator does not read the confirmation';
  END IF;
  UPDATE "TeacherAbsenceCovers" SET "substituteId" = t3 WHERE "absenceId" = a AND "calendarLessonId" = l;
  IF (SELECT count(*) FROM "CoverConfirmations" WHERE "calendarLessonId" = l) <> 0 THEN
    RAISE EXCEPTION 'cover confirmations: a decision handed to another kept the old vikarie''s confirmation';
  END IF;
  UPDATE "TeacherAbsenceCovers" SET "substituteId" = current_setting('app.test_rls318_t2')::uuid WHERE "absenceId" = a AND "calendarLessonId" = l;
  INSERT INTO "CoverConfirmations" ("schoolId", "absenceId", "calendarLessonId", "userId")
  VALUES (app.current_school_id(), a, l, current_setting('app.test_rls318_t2')::uuid);
  DELETE FROM "TeacherAbsenceCovers" WHERE "absenceId" = a AND "calendarLessonId" = l;
  IF (SELECT count(*) FROM "CoverConfirmations" WHERE "calendarLessonId" = l) <> 0 THEN
    RAISE EXCEPTION 'cover confirmations: an undone decision kept its confirmation';
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Sections 305-308: Frånvarobevakning (20261231090100).
--
-- Gränser per skola och mottagargrupp, ett nattligt jobb som räknar vilka
-- elever som passerat dem, och en vecko- eller månadssammanställning. The
-- school is rls-franvarobevakning-school (fixtures: …d10000000001 and on), a
-- full administrator, rektor, expedition, schemaläggare and läsare, two
-- mentors, a teacher without a class, a deactivated one who once mentored 7A,
-- four pupils and a deactivated fifth, three guardians, and a second school
-- of its own. Lessons and marks are planted by each section, on fixed past
-- days (the Monday 2026-09-14 is where the weeks start) inside its own
-- transaction, so nothing ages and nothing stays.
--
--   305  the tables: defaults, the checks on a limit, the switch's date, what
--        turning it off or removing a limit closes
--   306  the count: window edges, exact thresholds, LATE, UNKNOWN, CANCELLED,
--        a replacement lesson, giltig and ogiltig apart, days in a row across
--        a weekend and an empty day, the summer-time Mondays, the lifecycle
--   307  who reads: the arms, role by role, and who writes
--   308  the digest: the recipients per group, the counts, once per period
--   (on the owner's side, in rls-owner-checks.sql: 305o the findings' own constraints,
--   306o the mentor rule held to the leave decision's, 308o which periods are due,
--   309o gallring over the findings)
-- ---------------------------------------------------------------------------

-- The helpers the sections share. Temporary, so they die with the session.
CREATE FUNCTION pg_temp.fb_as(p_auth text) RETURNS void LANGUAGE sql AS $$
  SELECT set_config('request.jwt.claims', json_build_object('sub', p_auth)::text, true)
$$;

-- One pupil's day: a lesson of p_mins minutes for each status, planted the way
-- the register does (a lesson and the pupil's mark on it). The lessons start at
-- 08:00 local time and follow each other ten minutes apart.
CREATE FUNCTION pg_temp.fb_plant(p_subject uuid, p_group uuid, p_student uuid, p_day date, p_statuses text[],
                                 p_lesson "LessonStatus" DEFAULT 'SCHEDULED', p_mins integer DEFAULT 60)
RETURNS void LANGUAGE plpgsql AS $$
DECLARE
  i integer;
  l uuid;
  s uuid := app.current_school_id();
  first_start timestamptz := (p_day + time '08:00') AT TIME ZONE 'Europe/Stockholm';
BEGIN
  FOR i IN 1..cardinality(p_statuses) LOOP
    INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", status, "updatedAt")
    VALUES (s, p_subject, p_group, p_day,
            first_start + (i - 1) * (p_mins + 10) * interval '1 minute',
            first_start + (i - 1) * (p_mins + 10) * interval '1 minute' + p_mins * interval '1 minute',
            p_lesson, now())
    RETURNING id INTO l;
    INSERT INTO "AttendanceRecords" ("schoolId", "calendarLessonId", "studentId", status, "updatedAt")
    VALUES (s, l, p_student, p_statuses[i]::"AttendanceStatus", now());
  END LOOP;
END $$;

-- n lessons a day on each of the weekdays from p_from to p_to, all with p_status.
CREATE FUNCTION pg_temp.fb_weekdays(p_subject uuid, p_group uuid, p_student uuid, p_from date, p_to date, p_status text, p_n integer DEFAULT 1)
RETURNS void LANGUAGE plpgsql AS $$
DECLARE
  d date;
BEGIN
  FOR d IN SELECT g::date FROM generate_series(p_from, p_to, interval '1 day') g WHERE extract(isodow FROM g) < 6 LOOP
    PERFORM pg_temp.fb_plant(p_subject, p_group, p_student, d, array_fill(p_status, ARRAY[p_n]));
  END LOOP;
END $$;

-- The school's findings as one readable text: pupil, group, kind, basis, the
-- days and the figures. Read as the administrator.
CREATE FUNCTION pg_temp.fb_findings() RETURNS text LANGUAGE sql AS $$
  SELECT coalesce(string_agg(
           substr(u.email, 4, 2) || ' ' || f."recipientGroup" || ' ' || f.kind || ' ' || f.basis
             || ' ' || f."firstCrossedOn" || ' ' || f."lastSeenOn" || ' ' || coalesce(f."clearedOn"::text, '-')
             || ' ' || coalesce(f."absentMinutes"::text || '/' || f."recordedMinutes"::text, f."streakDays"::text || 'd'),
           E'\n' ORDER BY u.email, f."recipientGroup"::text, f.kind::text, f.basis::text, f."firstCrossedOn"), '')
    FROM "AbsenceWatchFindings" f JOIN "Users" u ON u.id = f."studentId"
$$;

-- A statement a CHECK or a unique index must refuse, by the constraint's name.
CREATE FUNCTION pg_temp.fb_refuses(p_sql text, p_constraint text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  EXECUTE p_sql;
  RAISE EXCEPTION 'frånvarobevakning: accepted: %', p_sql;
EXCEPTION WHEN check_violation OR unique_violation THEN
  IF position(p_constraint IN SQLERRM) = 0 THEN
    RAISE EXCEPTION 'frånvarobevakning: % was refused, but not by %: %', p_sql, p_constraint, SQLERRM;
  END IF;
END $$;

-- A statement the caller is refused: a missing privilege, a policy's check, or an
-- UPDATE or DELETE that no policy lets reach a row.
CREATE FUNCTION pg_temp.fb_denied(p_sql text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE
  n bigint;
BEGIN
  EXECUTE p_sql;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF p_sql ~* '^(UPDATE|DELETE)' AND n = 0 THEN RETURN; END IF;
  RAISE EXCEPTION 'frånvarobevakning: not denied (% rows): %', n, p_sql;
EXCEPTION WHEN insufficient_privilege THEN NULL;
END $$;

CREATE FUNCTION pg_temp.fb_expect(p_label text, p_got text, p_want text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  IF p_got IS DISTINCT FROM p_want THEN
    RAISE EXCEPTION E'frånvarobevakning %: got\n%\nwanted\n%', p_label, p_got, p_want;
  END IF;
END $$;

-- What a group's digest tells each of its recipients, as 'xx open/crossed' (the two
-- figures of their notice), asked the only way the API's role may: it holds no EXECUTE on
-- app.absence_watch_digest_plan, which the digest runs as the owner. So the digest is
-- written and taken back: the block that raises ends with its writes undone, the ledger,
-- the read log and the notices among them. A period's digest must therefore not be written
-- for real before it is asked for. p_pupils adds the pupils each recipient's read log row
-- names, which only holds for a reader with nothing in the log from the last quarter-hour.
CREATE FUNCTION pg_temp.fb_would_hear(p_school uuid, p_group "AbsenceWatchGroup", p_start date, p_end date, p_on date,
                                      p_pupils boolean DEFAULT false)
RETURNS text LANGUAGE plpgsql AS $$
DECLARE
  heard text;
  r record;
BEGIN
  BEGIN
    -- The read log is asked in the loop's own statements: what the digest wrote
    -- is not in the snapshot of the statement that called it.
    FOR r IN SELECT d.user_id, d.email, d.meta FROM app.absence_watch_digest(p_school, p_group, p_start, p_end, p_on) d ORDER BY d.email LOOP
      heard := concat_ws(', ', heard,
                         substr(r.email, 4, 2) || ' ' || (r.meta ->> 'open') || '/' || (r.meta ->> 'crossed')
                         || CASE WHEN p_pupils
                                 THEN ' ' || coalesce((SELECT sum(a."readSize") FROM "PersonalDataAccess" a
                                                        WHERE a."actorId" = r.user_id AND a.kind = 'ATTENDANCE' AND a.channel = 'OTHER'), 0)
                                 ELSE '' END);
    END LOOP;
    RAISE EXCEPTION 'frånvarobevakning: taken back' USING ERRCODE = 'FB000', DETAIL = coalesce(heard, '');
  EXCEPTION WHEN SQLSTATE 'FB000' THEN
    GET STACKED DIAGNOSTICS heard = PG_EXCEPTION_DETAIL;
  END;
  RETURN heard;
END $$;

-- ---------------------------------------------------------------------------
-- Section 305: the tables and what their triggers do.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT pg_temp.fb_as('00000000-0000-4000-8000-d10000000001');
DO $$
DECLARE
  school uuid := app.current_school_id();
  s record;
  today date := (now() AT TIME ZONE 'Europe/Stockholm')::date;
  lim uuid;
  p1 uuid;
  subj uuid;
  ka uuid;
BEGIN
  IF app.current_user_role() IS DISTINCT FROM 'SCHOOL_ADMIN' THEN RAISE EXCEPTION 'frånvarobevakning 305: expected the full administrator'; END IF;

  -- No row: off, as for every school before this migration.
  IF EXISTS (SELECT 1 FROM "AbsenceWatchSettings") THEN RAISE EXCEPTION 'frånvarobevakning 305: the school starts with a switch'; END IF;
  INSERT INTO "AbsenceWatchSettings" ("schoolId") VALUES (school);
  SELECT * INTO s FROM "AbsenceWatchSettings";
  IF s.enabled OR s."enabledOn" IS NOT NULL OR s."mentorCadence" <> 'WEEKLY' OR s."rektorCadence" <> 'WEEKLY'
     OR s."kansliCadence" <> 'WEEKLY' OR s."guardianCadence" <> 'MONTHLY' THEN
    RAISE EXCEPTION 'frånvarobevakning 305: the defaults are off, no date, weekly for staff and monthly for guardians: %', s;
  END IF;
  -- Turning it on dates the switch with the school's own day; a writer's date is the trigger's.
  UPDATE "AbsenceWatchSettings" SET enabled = true, "enabledOn" = '2020-01-01';
  SELECT * INTO s FROM "AbsenceWatchSettings";
  IF NOT s.enabled OR s."enabledOn" IS DISTINCT FROM today THEN
    RAISE EXCEPTION 'frånvarobevakning 305: turning it on set enabledOn to %, not %', s."enabledOn", today;
  END IF;
  UPDATE "AbsenceWatchSettings" SET "mentorCadence" = 'MONTHLY', "enabledOn" = '2020-01-01';
  IF (SELECT "enabledOn" FROM "AbsenceWatchSettings") IS DISTINCT FROM today THEN
    RAISE EXCEPTION 'frånvarobevakning 305: another change moved the date the switch went on';
  END IF;
  BEGIN
    UPDATE "AbsenceWatchSettings" SET enabled = true, "enabledOn" = NULL;
    IF (SELECT "enabledOn" FROM "AbsenceWatchSettings") IS NULL THEN RAISE EXCEPTION 'frånvarobevakning 305: an enabled switch without a date'; END IF;
  END;
  -- One row per school (the key), and the school's own.
  BEGIN
    INSERT INTO "AbsenceWatchSettings" ("schoolId") VALUES (school);
    RAISE EXCEPTION 'frånvarobevakning 305: a second switch for the school was accepted';
  EXCEPTION WHEN unique_violation THEN NULL;
  END;
  BEGIN
    INSERT INTO "AbsenceWatchSettings" ("schoolId") VALUES (gen_random_uuid());
    RAISE EXCEPTION 'frånvarobevakning 305: a switch for another school was accepted';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  -- Off and on again: the date is today's, and an off switch keeps the old date.
  UPDATE "AbsenceWatchSettings" SET enabled = false;
  IF (SELECT "enabledOn" FROM "AbsenceWatchSettings") IS DISTINCT FROM today THEN RAISE EXCEPTION 'frånvarobevakning 305: turning it off cleared the date'; END IF;

  -- A limit: both kinds, both ends of every range, and the figures each kind lacks.
  INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, percent, "windowDays") VALUES
    (school, 'MENTOR', 'SHARE', 'INVALID', 1, 7), (school, 'MENTOR', 'SHARE', 'VALID', 100, 60);
  INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, "consecutiveDays") VALUES
    (school, 'MENTOR', 'CONSECUTIVE', 'INVALID', 2), (school, 'MENTOR', 'CONSECUTIVE', 'ALL', 30);
  IF (SELECT count(*) FROM "AbsenceWatchLimits") <> 4 THEN RAISE EXCEPTION 'frånvarobevakning 305: the limits at both ends were not all accepted'; END IF;
  DELETE FROM "AbsenceWatchLimits";
  PERFORM pg_temp.fb_refuses('INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, percent, "windowDays") VALUES (app.current_school_id(), ''MENTOR'', ''SHARE'', ''ALL'', 0, 14)', 'a_kind_has_its_figures');
  PERFORM pg_temp.fb_refuses('INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, percent, "windowDays") VALUES (app.current_school_id(), ''MENTOR'', ''SHARE'', ''ALL'', 101, 14)', 'a_kind_has_its_figures');
  PERFORM pg_temp.fb_refuses('INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, percent, "windowDays") VALUES (app.current_school_id(), ''MENTOR'', ''SHARE'', ''ALL'', 10, 6)', 'a_kind_has_its_figures');
  PERFORM pg_temp.fb_refuses('INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, percent, "windowDays") VALUES (app.current_school_id(), ''MENTOR'', ''SHARE'', ''ALL'', 10, 61)', 'a_kind_has_its_figures');
  PERFORM pg_temp.fb_refuses('INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, percent) VALUES (app.current_school_id(), ''MENTOR'', ''SHARE'', ''ALL'', 10)', 'a_kind_has_its_figures');
  PERFORM pg_temp.fb_refuses('INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, "windowDays") VALUES (app.current_school_id(), ''MENTOR'', ''SHARE'', ''ALL'', 14)', 'a_kind_has_its_figures');
  PERFORM pg_temp.fb_refuses('INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, percent, "windowDays", "consecutiveDays") VALUES (app.current_school_id(), ''MENTOR'', ''SHARE'', ''ALL'', 10, 14, 3)', 'a_kind_has_its_figures');
  PERFORM pg_temp.fb_refuses('INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, "consecutiveDays") VALUES (app.current_school_id(), ''MENTOR'', ''CONSECUTIVE'', ''ALL'', 1)', 'a_kind_has_its_figures');
  PERFORM pg_temp.fb_refuses('INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, "consecutiveDays") VALUES (app.current_school_id(), ''MENTOR'', ''CONSECUTIVE'', ''ALL'', 31)', 'a_kind_has_its_figures');
  PERFORM pg_temp.fb_refuses('INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis) VALUES (app.current_school_id(), ''MENTOR'', ''CONSECUTIVE'', ''ALL'')', 'a_kind_has_its_figures');
  PERFORM pg_temp.fb_refuses('INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, "consecutiveDays", percent) VALUES (app.current_school_id(), ''MENTOR'', ''CONSECUTIVE'', ''ALL'', 3, 10)', 'a_kind_has_its_figures');

  -- One limit per group, kind and basis; the same figures for another group are another limit.
  INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, percent, "windowDays")
  VALUES (school, 'MENTOR', 'SHARE', 'INVALID', 10, 14) RETURNING id INTO lim;
  PERFORM pg_temp.fb_refuses('INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, percent, "windowDays") VALUES (app.current_school_id(), ''MENTOR'', ''SHARE'', ''INVALID'', 20, 30)', 'one_per_group_kind_basis');
  INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, percent, "windowDays") VALUES
    (school, 'REKTOR', 'SHARE', 'INVALID', 10, 14), (school, 'MENTOR', 'SHARE', 'VALID', 10, 14);
  -- A limit keeps its group, kind and basis; its figures change.
  UPDATE "AbsenceWatchLimits" SET percent = 15, "windowDays" = 28 WHERE id = lim;
  BEGIN
    UPDATE "AbsenceWatchLimits" SET "recipientGroup" = 'KANSLI' WHERE id = lim;
    RAISE EXCEPTION 'frånvarobevakning 305: a limit changed group';
  EXCEPTION WHEN SQLSTATE 'AW409' THEN NULL;
  END;
  BEGIN
    UPDATE "AbsenceWatchLimits" SET basis = 'ALL' WHERE id = lim;
    RAISE EXCEPTION 'frånvarobevakning 305: a limit changed basis';
  EXCEPTION WHEN SQLSTATE 'AW409' THEN NULL;
  END;
  BEGIN
    UPDATE "AbsenceWatchLimits" SET kind = 'CONSECUTIVE', percent = NULL, "windowDays" = NULL, "consecutiveDays" = 3 WHERE id = lim;
    RAISE EXCEPTION 'frånvarobevakning 305: a limit changed kind';
  EXCEPTION WHEN SQLSTATE 'AW409' THEN NULL;
  END;
  DELETE FROM "AbsenceWatchLimits" WHERE "recipientGroup" IN ('REKTOR') OR basis = 'VALID';
END $$;

-- Removing a limit closes its open findings at once, and so does turning the
-- bevakning off; the findings are then still there, closed.
DO $$
DECLARE
  school uuid := app.current_school_id();
  subj uuid;
  ka uuid := (SELECT id FROM "StudentGroups" WHERE name = 'FB7A');
  p1 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p1@example.invalid');
  lim uuid := (SELECT id FROM "AbsenceWatchLimits" WHERE "recipientGroup" = 'MENTOR');
  lim2 uuid;
BEGIN
  INSERT INTO "Subjects" ("schoolId", name, code, "updatedAt") VALUES (school, 'Bevakning 305', 'FB305', now()) RETURNING id INTO subj;
  PERFORM pg_temp.fb_weekdays(subj, ka, p1, '2026-09-14', '2026-09-18', 'ABSENT');
  UPDATE "AbsenceWatchSettings" SET enabled = true;
  IF (SELECT opened FROM app.absence_watch_evaluate(school, '2026-09-20')) <> 1 THEN
    RAISE EXCEPTION 'frånvarobevakning 305: the planted absence was not found';
  END IF;
  IF (SELECT count(*) FROM "AbsenceWatchFindings" WHERE "clearedOn" IS NULL) <> 1 THEN RAISE EXCEPTION 'frånvarobevakning 305: no open finding'; END IF;
  DELETE FROM "AbsenceWatchLimits" WHERE id = lim;
  IF (SELECT count(*) FROM "AbsenceWatchFindings" WHERE "clearedOn" IS NULL) <> 0
     OR (SELECT count(*) FROM "AbsenceWatchFindings" WHERE "clearedOn" IS NOT NULL) <> 1 THEN
    RAISE EXCEPTION 'frånvarobevakning 305: removing the limit did not close its finding at once';
  END IF;
  -- The finding says what the pupil passed, though the limit is gone.
  IF (SELECT percent FROM "AbsenceWatchFindings") <> 15 THEN RAISE EXCEPTION 'frånvarobevakning 305: the finding lost the limit it carries'; END IF;

  INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, percent, "windowDays")
  VALUES (school, 'KANSLI', 'SHARE', 'INVALID', 10, 14) RETURNING id INTO lim2;
  PERFORM app.absence_watch_evaluate(school, '2026-09-20');
  IF (SELECT count(*) FROM "AbsenceWatchFindings" WHERE "clearedOn" IS NULL) <> 1 THEN RAISE EXCEPTION 'frånvarobevakning 305: the new limit found nobody'; END IF;
  UPDATE "AbsenceWatchSettings" SET enabled = false;
  IF (SELECT count(*) FROM "AbsenceWatchFindings" WHERE "clearedOn" IS NULL) <> 0 THEN
    RAISE EXCEPTION 'frånvarobevakning 305: turning the bevakning off left a finding open in a view nothing feeds';
  END IF;
  -- An off school is not counted: nothing opens, whatever is planted.
  IF (SELECT opened + kept + closed + pupils FROM app.absence_watch_evaluate(school, '2026-09-20')) <> 0 THEN
    RAISE EXCEPTION 'frånvarobevakning 305: a school with the bevakning off was counted';
  END IF;
END $$;
ROLLBACK;


-- ---------------------------------------------------------------------------
-- Section 319: vikarieförfrågningar gallras som skolan bestämt, och bara
-- skolans (COVER_REQUESTS, 20270102090000 and 20270102091000).
--
-- The läslogg school keeps them 12 months (decided two days ago in the
-- fixtures). The night's purge takes the request that ended 13 months ago
-- with its lessons and its recipients, and the confirmation of the same age,
-- and the request that is still OPEN though its time ran out 13 months ago
-- (the job that ends it was off: nobody can answer it any more); it leaves
-- the request that ended 11 months ago and the one OPEN with years left. The
-- run counts the rows and "gallrat före" then answers COVER_REQUESTS. (Another
-- school's rows are out of the purge's reach by its school predicate; section
-- 83's gallring school holds none of its own to show it, so this section does
-- not claim to.)
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000121')::text, true);
DO $$
BEGIN
  PERFORM set_config('app.test_rls319_school', app.current_school_id()::text, true);
  IF (SELECT count(*) FROM "CoverRequests" WHERE id = 'c0000000-0000-4000-8000-0000000d4001') <> 1 THEN
    RAISE EXCEPTION 'cover gallring: the request that ended 13 months ago is not planted';
  END IF;
END $$;
SELECT set_config('request.jwt.claims', '', true);
DO $$
DECLARE
  run uuid := app.gallring_begin(current_setting('app.test_rls319_school')::uuid, clock_timestamp());
  n integer;
BEGIN
  n := app.gallring_purge(run, 'COVER_REQUESTS', 5000);
  IF n <> 3 THEN
    RAISE EXCEPTION 'cover gallring: the purge took % row(s), not the ended request, its confirmation and the open one that ran out', n;
  END IF;
  n := app.gallring_purge(run, 'COVER_REQUESTS', 5000);
  IF n <> 0 THEN RAISE EXCEPTION 'cover gallring: a second batch took % more', n; END IF;
  PERFORM app.gallring_finish(run, '{}', clock_timestamp());
  PERFORM set_config('app.test_rls319_run', run::text, true);
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000121')::text, true);
DO $$
DECLARE
  run "GallringRuns";
BEGIN
  IF (SELECT count(*) FROM "CoverRequests" WHERE id = 'c0000000-0000-4000-8000-0000000d4001') <> 0 THEN
    RAISE EXCEPTION 'cover gallring: the request older than the period is left';
  END IF;
  IF (SELECT count(*) FROM "CoverRequests" WHERE id = 'c0000000-0000-4000-8000-0000000d4004') <> 0 THEN
    RAISE EXCEPTION 'cover gallring: an open request whose time ran out before the period is kept for ever';
  END IF;
  IF (SELECT count(*) FROM "CoverRequestLessons" WHERE "requestId" IN ('c0000000-0000-4000-8000-0000000d4001', 'c0000000-0000-4000-8000-0000000d4004'))
     + (SELECT count(*) FROM "CoverRequestRecipients" WHERE "requestId" IN ('c0000000-0000-4000-8000-0000000d4001', 'c0000000-0000-4000-8000-0000000d4004')) <> 0 THEN
    RAISE EXCEPTION 'cover gallring: a purged request left its lessons or its recipients';
  END IF;
  IF (SELECT count(*) FROM "CoverRequests" WHERE id IN ('c0000000-0000-4000-8000-0000000d4002', 'c0000000-0000-4000-8000-0000000d4003')) <> 2 THEN
    RAISE EXCEPTION 'cover gallring: the purge took a request inside the period or an open one that can still be answered';
  END IF;
  IF (SELECT count(*) FROM "CoverConfirmations" WHERE "confirmedAt" < now() - interval '12 months') <> 0 THEN
    RAISE EXCEPTION 'cover gallring: a confirmation older than the period is left';
  END IF;
  SELECT * INTO run FROM "GallringRuns" WHERE id = current_setting('app.test_rls319_run')::uuid;
  IF (run.counts ->> 'COVER_REQUESTS')::int IS DISTINCT FROM 3 OR (run.complete ->> 'COVER_REQUESTS')::boolean IS NOT TRUE
     OR (run.periods ->> 'COVER_REQUESTS')::int IS DISTINCT FROM 12 THEN
    RAISE EXCEPTION 'cover gallring: the run says %, %, %', run.periods, run.counts, run.complete;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM app.retention_purged_before() WHERE data_type = 'COVER_REQUESTS') THEN
    RAISE EXCEPTION 'cover gallring: "gallrat före" does not answer COVER_REQUESTS';
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 306: the count.
--
-- Weeks start on Monday 2026-09-14. A pupil's lessons are 60 minutes; one
-- lesson is 60 of the figures below. The window of 14 days ending on
-- Sunday 2026-09-27 is Monday 2026-09-14 to the 27th, both ends in.
-- ---------------------------------------------------------------------------

-- 306a: the window's edges and the threshold, to the minute. The count is as of
-- Thursday 2026-09-24, so the window of 14 days is Friday the 11th to the 24th,
-- both ends in, and the day outside it is the Thursday before, a school day too.
BEGIN;
SELECT pg_temp.fb_as('00000000-0000-4000-8000-d10000000001');
DO $$
DECLARE
  school uuid := app.current_school_id();
  subj uuid;
  ka uuid := (SELECT id FROM "StudentGroups" WHERE name = 'FB7A');
  kb uuid := (SELECT id FROM "StudentGroups" WHERE name = 'FB7B');
  p1 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p1@example.invalid');
  p2 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p2@example.invalid');
  p3 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p3@example.invalid');
  p4 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p4@example.invalid');
  r record;
BEGIN
  INSERT INTO "Subjects" ("schoolId", name, code, "updatedAt") VALUES (school, 'Bevakning 306', 'FB306', now()) RETURNING id INTO subj;
  INSERT INTO "AbsenceWatchSettings" ("schoolId", enabled) VALUES (school, true);
  -- A second limit, wider and never reached (nothing here is giltig), so the days before the
  -- 14-day window are read all the same and it is the limit's own window that leaves them out.
  INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, percent, "windowDays") VALUES
    (school, 'MENTOR', 'SHARE', 'INVALID', 10, 14), (school, 'KANSLI', 'SHARE', 'VALID', 100, 60);

  -- P1: ten lessons in the window, one of them the window's first day (the 11th), absent:
  -- 60 of 600 is 10 %, and the limit is reached at 10.
  PERFORM pg_temp.fb_plant(subj, ka, p1, '2026-09-11', ARRAY['ABSENT']);
  PERFORM pg_temp.fb_weekdays(subj, ka, p1, '2026-09-14', '2026-09-24', 'PRESENT');
  -- P2: ten lessons present in the window, and two absences the Thursday before it: the window is
  -- 14 days, and with the 10th in it 120 of 720 would be 16.7 %.
  PERFORM pg_temp.fb_plant(subj, ka, p2, '2026-09-10', ARRAY['ABSENT', 'ABSENT']);
  PERFORM pg_temp.fb_plant(subj, ka, p2, '2026-09-11', ARRAY['PRESENT']);
  PERFORM pg_temp.fb_weekdays(subj, ka, p2, '2026-09-14', '2026-09-24', 'PRESENT');
  -- P3: ten lessons present and the window's last day absent once: 60 of 660 is 9.09 %.
  PERFORM pg_temp.fb_plant(subj, kb, p3, '2026-09-11', ARRAY['PRESENT', 'PRESENT']);
  PERFORM pg_temp.fb_weekdays(subj, kb, p3, '2026-09-14', '2026-09-23', 'PRESENT');
  PERFORM pg_temp.fb_plant(subj, kb, p3, '2026-09-24', ARRAY['ABSENT']);
  -- P4: the same with a second absence on the last day: 120 of 720, 16.67 %.
  PERFORM pg_temp.fb_plant(subj, kb, p4, '2026-09-11', ARRAY['PRESENT', 'PRESENT']);
  PERFORM pg_temp.fb_weekdays(subj, kb, p4, '2026-09-14', '2026-09-23', 'PRESENT');
  PERFORM pg_temp.fb_plant(subj, kb, p4, '2026-09-24', ARRAY['ABSENT', 'ABSENT']);

  SELECT * INTO r FROM app.absence_watch_evaluate(school, '2026-09-24');
  IF r.opened <> 2 OR r.kept <> 0 OR r.closed <> 0 OR r.pupils <> 4 THEN
    RAISE EXCEPTION 'frånvarobevakning 306a: opened %, kept %, closed %, pupils %', r.opened, r.kept, r.closed, r.pupils;
  END IF;
  PERFORM pg_temp.fb_expect('306a', pg_temp.fb_findings(),
    E'p1 MENTOR SHARE INVALID 2026-09-24 2026-09-24 - 60/600\n' ||
    E'p4 MENTOR SHARE INVALID 2026-09-24 2026-09-24 - 120/720');

  -- A day on (the 25th) loses the window's first day: P1's absence is out and the
  -- finding closes on the day it was found gone; P4 loses two present lessons and is
  -- kept at 120 of 600; and P3, whose 60 of 660 became 60 of 540, is over the limit and opens.
  SELECT * INTO r FROM app.absence_watch_evaluate(school, '2026-09-25');
  IF r.opened <> 1 OR r.kept <> 1 OR r.closed <> 1 THEN
    RAISE EXCEPTION 'frånvarobevakning 306a: the 25th: opened %, kept %, closed %', r.opened, r.kept, r.closed;
  END IF;
  PERFORM pg_temp.fb_expect('306a, a day on', pg_temp.fb_findings(),
    E'p1 MENTOR SHARE INVALID 2026-09-24 2026-09-24 2026-09-25 60/600\n' ||
    E'p3 MENTOR SHARE INVALID 2026-09-25 2026-09-25 - 60/540\n' ||
    E'p4 MENTOR SHARE INVALID 2026-09-24 2026-09-25 - 120/600');
END $$;
ROLLBACK;

-- 306b: LATE is 15 minutes, capped at the lesson; UNKNOWN is nothing; a lesson
-- that was cancelled is no absence whatever was marked on it; a replacement
-- lesson, another class's, counts as any lesson.
BEGIN;
SELECT pg_temp.fb_as('00000000-0000-4000-8000-d10000000001');
DO $$
DECLARE
  school uuid := app.current_school_id();
  subj uuid;
  ka uuid := (SELECT id FROM "StudentGroups" WHERE name = 'FB7A');
  kb uuid := (SELECT id FROM "StudentGroups" WHERE name = 'FB7B');
  p1 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p1@example.invalid');
  p2 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p2@example.invalid');
  p3 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p3@example.invalid');
  p4 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p4@example.invalid');
BEGIN
  INSERT INTO "Subjects" ("schoolId", name, code, "updatedAt") VALUES (school, 'Bevakning 306b', 'FB306B', now()) RETURNING id INTO subj;
  INSERT INTO "AbsenceWatchSettings" ("schoolId", enabled) VALUES (school, true);
  INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, percent, "windowDays") VALUES (school, 'MENTOR', 'SHARE', 'INVALID', 10, 14);

  -- P1: four late arrivals of ten lessons, 15 of 60 each: 60 of 600.
  PERFORM pg_temp.fb_plant(subj, ka, p1, '2026-09-15', ARRAY['LATE', 'LATE', 'LATE', 'LATE']);
  PERFORM pg_temp.fb_plant(subj, ka, p1, '2026-09-16', ARRAY['PRESENT', 'PRESENT', 'PRESENT', 'PRESENT', 'PRESENT', 'PRESENT']);
  -- ... and five lessons nobody registered: with them in the denominator it would be 60 of 900.
  PERFORM pg_temp.fb_plant(subj, ka, p1, '2026-09-17', array_fill('UNKNOWN'::text, ARRAY[5]));
  -- P2: one late arrival to a 10-minute lesson is 10 minutes, not 15: 10 of 100 is 10 %.
  PERFORM pg_temp.fb_plant(subj, ka, p2, '2026-09-15', ARRAY['LATE'], 'SCHEDULED', 10);
  PERFORM pg_temp.fb_plant(subj, ka, p2, '2026-09-16', ARRAY['PRESENT', 'PRESENT', 'PRESENT', 'PRESENT', 'PRESENT', 'PRESENT', 'PRESENT', 'PRESENT', 'PRESENT'], 'SCHEDULED', 10);
  -- P3: ten lessons present and ten that were never registered: UNKNOWN is in neither figure. Five absences on a CANCELLED lesson, as well.
  PERFORM pg_temp.fb_plant(subj, kb, p3, '2026-09-15', array_fill('PRESENT'::text, ARRAY[10]));
  PERFORM pg_temp.fb_plant(subj, kb, p3, '2026-09-16', array_fill('UNKNOWN'::text, ARRAY[10]));
  PERFORM pg_temp.fb_plant(subj, kb, p3, '2026-09-17', array_fill('ABSENT'::text, ARRAY[5]), 'CANCELLED');
  -- P4: the absence is in a lesson of another class (a replacement lesson, a friluftsdag's) and a COMPLETED lesson counts too.
  PERFORM pg_temp.fb_plant(subj, ka, p4, '2026-09-15', ARRAY['ABSENT']);
  PERFORM pg_temp.fb_plant(subj, kb, p4, '2026-09-16', ARRAY['PRESENT', 'PRESENT', 'PRESENT', 'PRESENT', 'PRESENT', 'PRESENT', 'PRESENT', 'PRESENT', 'PRESENT'], 'COMPLETED');
  PERFORM app.absence_watch_evaluate(school, '2026-09-20');
  PERFORM pg_temp.fb_expect('306b', pg_temp.fb_findings(),
    E'p1 MENTOR SHARE INVALID 2026-09-20 2026-09-20 - 60/600\n' ||
    E'p2 MENTOR SHARE INVALID 2026-09-20 2026-09-20 - 10/100\n' ||
    E'p4 MENTOR SHARE INVALID 2026-09-20 2026-09-20 - 60/600');
  -- A lesson that was rescheduled is not held either.
  UPDATE "CalendarLessons" SET status = 'RESCHEDULED' WHERE "studentGroupId" = ka
     AND id IN (SELECT "calendarLessonId" FROM "AttendanceRecords" WHERE "studentId" = p4);
  PERFORM app.absence_watch_evaluate(school, '2026-09-20');
  IF EXISTS (SELECT 1 FROM "AbsenceWatchFindings" WHERE "studentId" = p4 AND "clearedOn" IS NULL)
     OR NOT EXISTS (SELECT 1 FROM "AbsenceWatchFindings" WHERE "studentId" = p4 AND "clearedOn" IS NOT NULL) THEN
    RAISE EXCEPTION 'frånvarobevakning 306b: a rescheduled lesson still counted as absence: %', pg_temp.fb_findings();
  END IF;
END $$;
ROLLBACK;

-- 306c: giltig and ogiltig frånvaro each by themselves, and together.
BEGIN;
SELECT pg_temp.fb_as('00000000-0000-4000-8000-d10000000001');
DO $$
DECLARE
  school uuid := app.current_school_id();
  subj uuid;
  ka uuid := (SELECT id FROM "StudentGroups" WHERE name = 'FB7A');
  p1 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p1@example.invalid');
  p2 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p2@example.invalid');
  p3 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p3@example.invalid');
  p4 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p4@example.invalid');
BEGIN
  INSERT INTO "Subjects" ("schoolId", name, code, "updatedAt") VALUES (school, 'Bevakning 306c', 'FB306C', now()) RETURNING id INTO subj;
  INSERT INTO "AbsenceWatchSettings" ("schoolId", enabled) VALUES (school, true);
  INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, percent, "windowDays") VALUES
    (school, 'MENTOR', 'SHARE', 'VALID', 20, 14), (school, 'REKTOR', 'SHARE', 'INVALID', 20, 14), (school, 'KANSLI', 'SHARE', 'ALL', 30, 14);
  -- P1: two of ten excused (20 % giltig). P2: two of ten absent (20 % ogiltig). P3: two and two,
  -- 20 % of each kind and 40 % in all: over the giltig and the ogiltig limits, and over the one for all.
  PERFORM pg_temp.fb_plant(subj, ka, p1, '2026-09-15', ARRAY['EXCUSED', 'EXCUSED', 'PRESENT', 'PRESENT', 'PRESENT']);
  PERFORM pg_temp.fb_plant(subj, ka, p1, '2026-09-16', ARRAY['PRESENT', 'PRESENT', 'PRESENT', 'PRESENT', 'PRESENT']);
  PERFORM pg_temp.fb_plant(subj, ka, p2, '2026-09-15', ARRAY['ABSENT', 'ABSENT', 'PRESENT', 'PRESENT', 'PRESENT']);
  PERFORM pg_temp.fb_plant(subj, ka, p2, '2026-09-16', ARRAY['PRESENT', 'PRESENT', 'PRESENT', 'PRESENT', 'PRESENT']);
  PERFORM pg_temp.fb_plant(subj, ka, p3, '2026-09-15', ARRAY['EXCUSED', 'EXCUSED', 'ABSENT', 'ABSENT', 'PRESENT']);
  PERFORM pg_temp.fb_plant(subj, ka, p3, '2026-09-16', ARRAY['PRESENT', 'PRESENT', 'PRESENT', 'PRESENT', 'PRESENT']);
  -- P4: five late arrivals of ten lessons: 75 minutes of ogiltig absence (12.5 %), none giltig, and under all three limits.
  PERFORM pg_temp.fb_plant(subj, ka, p4, '2026-09-15', ARRAY['LATE', 'LATE', 'LATE', 'LATE', 'LATE']);
  PERFORM pg_temp.fb_plant(subj, ka, p4, '2026-09-16', ARRAY['PRESENT', 'PRESENT', 'PRESENT', 'PRESENT', 'PRESENT']);
  PERFORM app.absence_watch_evaluate(school, '2026-09-20');
  PERFORM pg_temp.fb_expect('306c', pg_temp.fb_findings(),
    E'p1 MENTOR SHARE VALID 2026-09-20 2026-09-20 - 120/600\n' ||
    E'p2 REKTOR SHARE INVALID 2026-09-20 2026-09-20 - 120/600\n' ||
    E'p3 KANSLI SHARE ALL 2026-09-20 2026-09-20 - 240/600\n' ||
    E'p3 MENTOR SHARE VALID 2026-09-20 2026-09-20 - 120/600\n' ||
    E'p3 REKTOR SHARE INVALID 2026-09-20 2026-09-20 - 120/600');
END $$;
ROLLBACK;

-- 306d: days in a row. Friday 2026-09-25 is cancelled for everybody below
-- (a lov or a cancelled day leaves no registered lesson), and the week-end
-- falls between the Friday and the Monday.
BEGIN;
SELECT pg_temp.fb_as('00000000-0000-4000-8000-d10000000001');
DO $$
DECLARE
  school uuid := app.current_school_id();
  subj uuid;
  ka uuid := (SELECT id FROM "StudentGroups" WHERE name = 'FB7A');
  kb uuid := (SELECT id FROM "StudentGroups" WHERE name = 'FB7B');
  p1 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p1@example.invalid');
  p2 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p2@example.invalid');
  p3 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p3@example.invalid');
  p4 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p4@example.invalid');
  p5 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p5@example.invalid');
BEGIN
  INSERT INTO "Subjects" ("schoolId", name, code, "updatedAt") VALUES (school, 'Bevakning 306d', 'FB306D', now()) RETURNING id INTO subj;
  INSERT INTO "AbsenceWatchSettings" ("schoolId", enabled) VALUES (school, true);
  INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, "consecutiveDays") VALUES (school, 'REKTOR', 'CONSECUTIVE', 'ALL', 3);

  -- P1: Wed, Thu, Fri, Mon, all day absent, after a Tuesday present: four days across the week-end.
  PERFORM pg_temp.fb_plant(subj, ka, p1, '2026-09-22', ARRAY['PRESENT', 'PRESENT']);
  PERFORM pg_temp.fb_plant(subj, ka, p1, '2026-09-23', ARRAY['ABSENT', 'EXCUSED']);
  PERFORM pg_temp.fb_plant(subj, ka, p1, '2026-09-24', ARRAY['ABSENT', 'ABSENT']);
  PERFORM pg_temp.fb_plant(subj, ka, p1, '2026-09-25', ARRAY['ABSENT', 'ABSENT']);
  PERFORM pg_temp.fb_plant(subj, ka, p1, '2026-09-28', ARRAY['ABSENT', 'ABSENT']);
  -- P2: Thu and Fri absent, and back on the Monday: no run is going.
  PERFORM pg_temp.fb_plant(subj, ka, p2, '2026-09-23', ARRAY['ABSENT', 'ABSENT']);
  PERFORM pg_temp.fb_plant(subj, ka, p2, '2026-09-24', ARRAY['ABSENT', 'ABSENT']);
  PERFORM pg_temp.fb_plant(subj, ka, p2, '2026-09-25', ARRAY['ABSENT', 'ABSENT']);
  PERFORM pg_temp.fb_plant(subj, ka, p2, '2026-09-28', ARRAY['PRESENT', 'PRESENT']);
  -- P3: Thu, Fri and a Monday of which one lesson of two was attended: not a day of absence.
  PERFORM pg_temp.fb_plant(subj, kb, p3, '2026-09-24', ARRAY['ABSENT', 'ABSENT']);
  PERFORM pg_temp.fb_plant(subj, kb, p3, '2026-09-25', ARRAY['ABSENT', 'ABSENT']);
  PERFORM pg_temp.fb_plant(subj, kb, p3, '2026-09-28', ARRAY['ABSENT', 'PRESENT']);
  -- P4: Wed, Thu and Mon absent, and a Friday whose lessons were cancelled with absences marked on them
  -- and whose other two nobody registered: the Friday is nothing, the run is three.
  PERFORM pg_temp.fb_plant(subj, kb, p4, '2026-09-23', ARRAY['ABSENT', 'ABSENT']);
  PERFORM pg_temp.fb_plant(subj, kb, p4, '2026-09-24', ARRAY['ABSENT', 'ABSENT']);
  PERFORM pg_temp.fb_plant(subj, kb, p4, '2026-09-25', ARRAY['ABSENT', 'ABSENT'], 'CANCELLED');
  PERFORM pg_temp.fb_plant(subj, kb, p4, '2026-09-25', ARRAY['UNKNOWN', 'UNKNOWN']);
  PERFORM pg_temp.fb_plant(subj, kb, p4, '2026-09-28', ARRAY['ABSENT', 'ABSENT']);
  -- P5 is deactivated: four absent days count for nobody.
  PERFORM pg_temp.fb_plant(subj, ka, p5, '2026-09-22', ARRAY['ABSENT']);
  PERFORM pg_temp.fb_plant(subj, ka, p5, '2026-09-23', ARRAY['ABSENT']);
  PERFORM pg_temp.fb_plant(subj, ka, p5, '2026-09-24', ARRAY['ABSENT']);
  PERFORM pg_temp.fb_plant(subj, ka, p5, '2026-09-28', ARRAY['ABSENT']);

  PERFORM app.absence_watch_evaluate(school, '2026-09-28');
  -- The run reaches three on the third day of it, the 25th for P1 and the 28th for P4.
  PERFORM pg_temp.fb_expect('306d', pg_temp.fb_findings(),
    E'p1 REKTOR CONSECUTIVE ALL 2026-09-25 2026-09-28 - 4d\n' ||
    E'p4 REKTOR CONSECUTIVE ALL 2026-09-28 2026-09-28 - 3d');
  -- A run that ended more than seven days ago is not a run going: the 6th of October.
  PERFORM app.absence_watch_evaluate(school, '2026-10-06');
  IF (SELECT count(*) FROM "AbsenceWatchFindings" WHERE "clearedOn" IS NULL) <> 0 THEN
    RAISE EXCEPTION 'frånvarobevakning 306d: a run whose last day is eight days old is still open: %', pg_temp.fb_findings();
  END IF;
  -- Seven days is going (the 5th of October is the 28th plus seven; the 4th would be six).
  PERFORM app.absence_watch_evaluate(school, '2026-10-05');
  IF (SELECT count(*) FROM "AbsenceWatchFindings" WHERE "clearedOn" IS NULL) <> 2 THEN
    RAISE EXCEPTION 'frånvarobevakning 306d: a run whose last day is seven days old was dropped: %', pg_temp.fb_findings();
  END IF;
END $$;
ROLLBACK;

-- 306e: giltig and ogiltig days in a row each by themselves.
BEGIN;
SELECT pg_temp.fb_as('00000000-0000-4000-8000-d10000000001');
DO $$
DECLARE
  school uuid := app.current_school_id();
  subj uuid;
  ka uuid := (SELECT id FROM "StudentGroups" WHERE name = 'FB7A');
  p1 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p1@example.invalid');
  kb uuid := (SELECT id FROM "StudentGroups" WHERE name = 'FB7B');
  p2 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p2@example.invalid');
  p3 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p3@example.invalid');
  p4 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p4@example.invalid');
BEGIN
  INSERT INTO "Subjects" ("schoolId", name, code, "updatedAt") VALUES (school, 'Bevakning 306e', 'FB306E', now()) RETURNING id INTO subj;
  INSERT INTO "AbsenceWatchSettings" ("schoolId", enabled) VALUES (school, true);
  INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, "consecutiveDays") VALUES
    (school, 'MENTOR', 'CONSECUTIVE', 'VALID', 2), (school, 'REKTOR', 'CONSECUTIVE', 'INVALID', 2), (school, 'KANSLI', 'CONSECUTIVE', 'ALL', 3);
  -- P1: a Tuesday present and a giltig Wednesday and Thursday: two days of giltig absence, and two are not three.
  PERFORM pg_temp.fb_plant(subj, ka, p1, '2026-09-22', ARRAY['PRESENT']);
  PERFORM pg_temp.fb_plant(subj, ka, p1, '2026-09-23', ARRAY['EXCUSED', 'EXCUSED']);
  PERFORM pg_temp.fb_plant(subj, ka, p1, '2026-09-24', ARRAY['EXCUSED', 'EXCUSED']);
  -- P2: Tuesday giltig, Wednesday and Thursday ogiltig: two ogiltiga days, and three of absence in all.
  PERFORM pg_temp.fb_plant(subj, ka, p2, '2026-09-22', ARRAY['EXCUSED', 'EXCUSED']);
  PERFORM pg_temp.fb_plant(subj, ka, p2, '2026-09-23', ARRAY['ABSENT', 'ABSENT']);
  PERFORM pg_temp.fb_plant(subj, ka, p2, '2026-09-24', ARRAY['ABSENT', 'ABSENT']);
  -- P3 and P4: a day that is half absence is no day of absence, under either basis by itself. P3 is
  -- ogiltig on the Wednesday and half so on the Thursday, P4 giltig on the Wednesday and half so on the Thursday.
  PERFORM pg_temp.fb_plant(subj, kb, p3, '2026-09-23', ARRAY['ABSENT', 'ABSENT']);
  PERFORM pg_temp.fb_plant(subj, kb, p3, '2026-09-24', ARRAY['ABSENT', 'PRESENT']);
  PERFORM pg_temp.fb_plant(subj, kb, p4, '2026-09-23', ARRAY['EXCUSED', 'EXCUSED']);
  PERFORM pg_temp.fb_plant(subj, kb, p4, '2026-09-24', ARRAY['EXCUSED', 'PRESENT']);
  PERFORM app.absence_watch_evaluate(school, '2026-09-25');
  PERFORM pg_temp.fb_expect('306e', pg_temp.fb_findings(),
    E'p1 MENTOR CONSECUTIVE VALID 2026-09-24 2026-09-25 - 2d\n' ||
    E'p2 KANSLI CONSECUTIVE ALL 2026-09-24 2026-09-25 - 3d\n'  ||
    E'p2 REKTOR CONSECUTIVE INVALID 2026-09-24 2026-09-25 - 2d');
END $$;
ROLLBACK;

-- 306f: the lifecycle. A finding opens once, is kept by the next count and
-- closes on the day the pupil is under; the run of a second absence opens a
-- new one and leaves the closed one as it was. A count of the same day again
-- changes nothing. A day that has not passed, or a school that is not, is refused.
BEGIN;
SELECT pg_temp.fb_as('00000000-0000-4000-8000-d10000000001');
DO $$
DECLARE
  school uuid := app.current_school_id();
  subj uuid;
  ka uuid := (SELECT id FROM "StudentGroups" WHERE name = 'FB7A');
  p1 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p1@example.invalid');
  lim uuid;
  r record;
BEGIN
  INSERT INTO "Subjects" ("schoolId", name, code, "updatedAt") VALUES (school, 'Bevakning 306f', 'FB306F', now()) RETURNING id INTO subj;
  INSERT INTO "AbsenceWatchSettings" ("schoolId", enabled) VALUES (school, true);
  INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, percent, "windowDays")
  VALUES (school, 'MENTOR', 'SHARE', 'INVALID', 10, 14) RETURNING id INTO lim;
  PERFORM pg_temp.fb_plant(subj, ka, p1, '2026-09-15', ARRAY['ABSENT', 'PRESENT', 'PRESENT', 'PRESENT', 'PRESENT']);
  PERFORM pg_temp.fb_weekdays(subj, ka, p1, '2026-09-16', '2026-09-22', 'PRESENT');

  SELECT * INTO r FROM app.absence_watch_evaluate(school, '2026-09-22');
  IF r.opened <> 1 THEN RAISE EXCEPTION 'frånvarobevakning 306f: opened %', r.opened; END IF;
  SELECT * INTO r FROM app.absence_watch_evaluate(school, '2026-09-22');
  IF r.opened <> 0 OR r.kept <> 1 OR r.closed <> 0 THEN RAISE EXCEPTION 'frånvarobevakning 306f: the same day twice: opened %, kept %, closed %', r.opened, r.kept, r.closed; END IF;
  -- The next day it holds: found on the 22nd, seen on the 23rd.
  PERFORM pg_temp.fb_plant(subj, ka, p1, '2026-09-23', ARRAY['ABSENT']);
  PERFORM app.absence_watch_evaluate(school, '2026-09-23');
  PERFORM pg_temp.fb_expect('306f, kept', pg_temp.fb_findings(), E'p1 MENTOR SHARE INVALID 2026-09-22 2026-09-23 - 120/660');
  -- The limit is raised to 20: the finding no longer holds and closes; the limit's figures were updated.
  UPDATE "AbsenceWatchLimits" SET percent = 20 WHERE id = lim;
  SELECT * INTO r FROM app.absence_watch_evaluate(school, '2026-09-23');
  IF r.closed <> 1 THEN RAISE EXCEPTION 'frånvarobevakning 306f: a raised limit left the finding open'; END IF;
  -- Lowered again: a new finding, and the closed one is as it was.
  UPDATE "AbsenceWatchLimits" SET percent = 10 WHERE id = lim;
  PERFORM app.absence_watch_evaluate(school, '2026-09-24');
  PERFORM pg_temp.fb_expect('306f, again', pg_temp.fb_findings(),
    E'p1 MENTOR SHARE INVALID 2026-09-22 2026-09-23 2026-09-23 120/660\n' ||
    E'p1 MENTOR SHARE INVALID 2026-09-24 2026-09-24 - 120/660');
  -- A figure edited while the finding stays is shown as the limit stands now.
  UPDATE "AbsenceWatchLimits" SET percent = 11, "windowDays" = 28 WHERE id = lim;
  PERFORM app.absence_watch_evaluate(school, '2026-09-25');
  IF (SELECT percent || '/' || "windowDays" FROM "AbsenceWatchFindings" WHERE "clearedOn" IS NULL) <> '11/28' THEN
    RAISE EXCEPTION 'frånvarobevakning 306f: an edited limit did not reach its finding';
  END IF;

  -- A day that has not passed is refused: today's lessons are not over.
  BEGIN
    PERFORM app.absence_watch_evaluate(school, (now() AT TIME ZONE 'Europe/Stockholm')::date);
    RAISE EXCEPTION 'frånvarobevakning 306f: today was counted';
  EXCEPTION WHEN SQLSTATE 'AW400' THEN NULL;
  END;
  BEGIN
    PERFORM app.absence_watch_evaluate(school, (now() AT TIME ZONE 'Europe/Stockholm')::date + 1);
    RAISE EXCEPTION 'frånvarobevakning 306f: tomorrow was counted';
  EXCEPTION WHEN SQLSTATE 'AW400' THEN NULL;
  END;
  BEGIN
    PERFORM app.absence_watch_evaluate(gen_random_uuid(), '2026-09-22');
    RAISE EXCEPTION 'frånvarobevakning 306f: a school that does not exist was counted';
  EXCEPTION WHEN SQLSTATE 'AW404' THEN NULL;
  END;
  -- Yesterday is the latest that counts, in the school's own dates.
  PERFORM app.absence_watch_evaluate(school, (now() AT TIME ZONE 'Europe/Stockholm')::date - 1);
END $$;
ROLLBACK;

-- 306g: the Mondays of the summer-time switches. Spring forward is Sunday
-- 2026-03-29 and fall back Sunday 2026-10-25. A 60-minute lesson is 60 minutes
-- on the Monday after, though the offset moved; the lesson's day is the local
-- date; the window's days are local dates.
BEGIN;
SELECT pg_temp.fb_as('00000000-0000-4000-8000-d10000000001');
DO $$
DECLARE
  school uuid := app.current_school_id();
  subj uuid;
  ka uuid := (SELECT id FROM "StudentGroups" WHERE name = 'FB7A');
  p1 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p1@example.invalid');
  p2 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p2@example.invalid');
BEGIN
  INSERT INTO "Subjects" ("schoolId", name, code, "updatedAt") VALUES (school, 'Bevakning 306g', 'FB306G', now()) RETURNING id INTO subj;
  INSERT INTO "AbsenceWatchSettings" ("schoolId", enabled) VALUES (school, true);
  INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, percent, "windowDays") VALUES (school, 'MENTOR', 'SHARE', 'INVALID', 25, 7);
  INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, "consecutiveDays") VALUES (school, 'REKTOR', 'CONSECUTIVE', 'ALL', 2);
  -- Spring: the Friday before and the Monday after. 1 absent of 4: 25 %, reached.
  PERFORM pg_temp.fb_plant(subj, ka, p1, '2026-03-27', ARRAY['PRESENT', 'PRESENT']);
  PERFORM pg_temp.fb_plant(subj, ka, p1, '2026-03-30', ARRAY['ABSENT', 'PRESENT']);
  -- A lesson's minutes are its elapsed time: one from 01:30 to 03:30 on the night the clock
  -- jumps from 02:00 to 03:00 is 60 minutes, not the 120 that the wall clock shows.
  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", "updatedAt")
  VALUES (school, subj, ka, '2026-03-29', ('2026-03-29 01:30'::timestamp AT TIME ZONE 'Europe/Stockholm'),
          ('2026-03-29 03:30'::timestamp AT TIME ZONE 'Europe/Stockholm'), now());
  INSERT INTO "AttendanceRecords" ("schoolId", "calendarLessonId", "studentId", status, "updatedAt")
  SELECT school, id, (SELECT id FROM "Users" WHERE email = 'fb-p3@example.invalid'), 'ABSENT', now() FROM "CalendarLessons" WHERE date = '2026-03-29';
  PERFORM pg_temp.fb_plant(subj, ka, (SELECT id FROM "Users" WHERE email = 'fb-p3@example.invalid'), '2026-03-30', ARRAY['PRESENT']);
  -- Fall: Friday and Monday absent all day across the extra hour.
  PERFORM pg_temp.fb_plant(subj, ka, p2, '2026-10-23', ARRAY['ABSENT', 'ABSENT']);
  PERFORM pg_temp.fb_plant(subj, ka, p2, '2026-10-26', ARRAY['ABSENT', 'ABSENT']);
  PERFORM app.absence_watch_evaluate(school, '2026-03-30');
  PERFORM pg_temp.fb_expect('306g, spring', pg_temp.fb_findings(),
    E'p1 MENTOR SHARE INVALID 2026-03-30 2026-03-30 - 60/240\n' ||
    E'p3 MENTOR SHARE INVALID 2026-03-30 2026-03-30 - 60/120');
  PERFORM app.absence_watch_evaluate(school, '2026-10-26');
  PERFORM pg_temp.fb_expect('306g, fall', pg_temp.fb_findings(),
    E'p1 MENTOR SHARE INVALID 2026-03-30 2026-03-30 2026-10-26 60/240\n' ||
    E'p2 MENTOR SHARE INVALID 2026-10-26 2026-10-26 - 240/240\n' ||
    E'p2 REKTOR CONSECUTIVE ALL 2026-10-26 2026-10-26 - 2d\n' ||
    E'p3 MENTOR SHARE INVALID 2026-03-30 2026-03-30 2026-10-26 60/120');
END $$;
ROLLBACK;

-- 306h: the first day of the window with no wider limit to widen the lookback: the
-- one limit's 14 days are all that is read, and the 11th is in them, the 10th is not.
BEGIN;
SELECT pg_temp.fb_as('00000000-0000-4000-8000-d10000000001');
DO $$
DECLARE
  school uuid := app.current_school_id();
  subj uuid;
  ka uuid := (SELECT id FROM "StudentGroups" WHERE name = 'FB7A');
  p1 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p1@example.invalid');
  p2 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p2@example.invalid');
BEGIN
  INSERT INTO "Subjects" ("schoolId", name, code, "updatedAt") VALUES (school, 'Bevakning 306h', 'FB306H', now()) RETURNING id INTO subj;
  INSERT INTO "AbsenceWatchSettings" ("schoolId", enabled) VALUES (school, true);
  INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, percent, "windowDays") VALUES (school, 'MENTOR', 'SHARE', 'INVALID', 10, 14);
  PERFORM pg_temp.fb_plant(subj, ka, p1, '2026-09-11', ARRAY['ABSENT']);
  PERFORM pg_temp.fb_weekdays(subj, ka, p1, '2026-09-14', '2026-09-24', 'PRESENT');
  PERFORM pg_temp.fb_plant(subj, ka, p2, '2026-09-10', ARRAY['ABSENT', 'ABSENT']);
  PERFORM pg_temp.fb_weekdays(subj, ka, p2, '2026-09-11', '2026-09-24', 'PRESENT');
  PERFORM app.absence_watch_evaluate(school, '2026-09-24');
  PERFORM pg_temp.fb_expect('306h', pg_temp.fb_findings(), E'p1 MENTOR SHARE INVALID 2026-09-24 2026-09-24 - 60/600');
END $$;
ROLLBACK;

-- 306i: a lov is no day and breaks no run. The school's höstlov (the week of
-- 2026-09-28 to 10-02, planted as the calendar has it, with no lesson in it)
-- lies between a pupil's Thursday and Friday and the Monday after it: three
-- school days in a row, and a share counted over the days that had lessons.
BEGIN;
SELECT pg_temp.fb_as('00000000-0000-4000-8000-d10000000001');
DO $$
DECLARE
  school uuid := app.current_school_id();
  subj uuid;
  ka uuid := (SELECT id FROM "StudentGroups" WHERE name = 'FB7A');
  p1 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p1@example.invalid');
  p2 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p2@example.invalid');
BEGIN
  INSERT INTO "Subjects" ("schoolId", name, code, "updatedAt") VALUES (school, 'Bevakning 306i', 'FB306I', now()) RETURNING id INTO subj;
  INSERT INTO "SchoolBreaks" ("schoolId", "academicYearId", name, kind, "startDate", "endDate", "updatedAt")
  SELECT school, y.id, 'Höstlov', 'HOLIDAY', '2026-09-28', '2026-10-02', now() FROM "AcademicYears" y WHERE y."isActive";
  INSERT INTO "AbsenceWatchSettings" ("schoolId", enabled) VALUES (school, true);
  INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, "consecutiveDays") VALUES (school, 'REKTOR', 'CONSECUTIVE', 'ALL', 3);
  INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, percent, "windowDays") VALUES (school, 'MENTOR', 'SHARE', 'INVALID', 50, 14);
  -- P1: absent the Thursday and Friday before the lov and the Monday after it.
  PERFORM pg_temp.fb_plant(subj, ka, p1, '2026-09-24', ARRAY['ABSENT', 'ABSENT']);
  PERFORM pg_temp.fb_plant(subj, ka, p1, '2026-09-25', ARRAY['ABSENT', 'ABSENT']);
  PERFORM pg_temp.fb_plant(subj, ka, p1, '2026-10-05', ARRAY['ABSENT', 'ABSENT']);
  -- P2: present the same days, absent on the Friday before and the Monday after only: two days, and a half.
  PERFORM pg_temp.fb_plant(subj, ka, p2, '2026-09-24', ARRAY['PRESENT', 'PRESENT']);
  PERFORM pg_temp.fb_plant(subj, ka, p2, '2026-09-25', ARRAY['ABSENT', 'ABSENT']);
  PERFORM pg_temp.fb_plant(subj, ka, p2, '2026-10-05', ARRAY['ABSENT', 'ABSENT']);
  PERFORM app.absence_watch_evaluate(school, '2026-10-05');
  -- The 14 days ending the 5th have six lessons of P1's, all absent, and the run is three days that reach over the lov.
  PERFORM pg_temp.fb_expect('306i', pg_temp.fb_findings(),
    E'p1 MENTOR SHARE INVALID 2026-10-05 2026-10-05 - 360/360\n' ||
    E'p1 REKTOR CONSECUTIVE ALL 2026-10-05 2026-10-05 - 3d\n' ||
    E'p2 MENTOR SHARE INVALID 2026-10-05 2026-10-05 - 240/360');
END $$;
ROLLBACK;

-- 306j: absence that is going on. A share over a window of 60 days is a finding only
-- while the pupil's latest registered day is at most seven days old, as a run's is:
-- at the end of a term nobody is still over a limit in July.
BEGIN;
SELECT pg_temp.fb_as('00000000-0000-4000-8000-d10000000001');
DO $$
DECLARE
  school uuid := app.current_school_id();
  subj uuid;
  ka uuid := (SELECT id FROM "StudentGroups" WHERE name = 'FB7A');
  p1 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p1@example.invalid');
  p2 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p2@example.invalid');
  p3 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p3@example.invalid');
BEGIN
  INSERT INTO "Subjects" ("schoolId", name, code, "updatedAt") VALUES (school, 'Bevakning 306j', 'FB306J', now()) RETURNING id INTO subj;
  INSERT INTO "AbsenceWatchSettings" ("schoolId", enabled) VALUES (school, true);
  INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, percent, "windowDays") VALUES (school, 'MENTOR', 'SHARE', 'INVALID', 10, 60);
  -- Counted as of Friday 2026-09-25. P1's last registered day is Friday the 18th, seven days
  -- before; P2's is Thursday the 17th, eight days before; P3's was in the middle of August.
  PERFORM pg_temp.fb_weekdays(subj, ka, p1, '2026-09-14', '2026-09-18', 'ABSENT');
  PERFORM pg_temp.fb_weekdays(subj, ka, p2, '2026-09-14', '2026-09-17', 'ABSENT');
  PERFORM pg_temp.fb_weekdays(subj, ka, p3, '2026-08-17', '2026-08-21', 'ABSENT');
  PERFORM app.absence_watch_evaluate(school, '2026-09-25');
  PERFORM pg_temp.fb_expect('306j', pg_temp.fb_findings(), E'p1 MENTOR SHARE INVALID 2026-09-25 2026-09-25 - 300/300');
  -- And when school starts again a pupil who is absent from the first day is found at once, while
  -- P1, who has not been registered for twelve days, is closed:
  PERFORM pg_temp.fb_weekdays(subj, ka, p2, '2026-09-28', '2026-09-29', 'ABSENT');
  PERFORM app.absence_watch_evaluate(school, '2026-09-30');
  PERFORM pg_temp.fb_expect('306j, back', pg_temp.fb_findings(),
    E'p1 MENTOR SHARE INVALID 2026-09-25 2026-09-25 2026-09-30 300/300\n' ||
    E'p2 MENTOR SHARE INVALID 2026-09-30 2026-09-30 - 360/360');
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 307: who reads and who writes.
--
-- One set of findings, over both schools:
--   P1 (7A): MENTOR, GUARDIAN and REKTOR findings
--   P3 (7B): MENTOR and GUARDIAN findings
--   P4 (7B): a MENTOR finding (16.7 %, under the guardians' 20 %)
--   P2 (7A): none
--   the other school's pupil: a MENTOR and a GUARDIAN finding
-- ---------------------------------------------------------------------------

BEGIN;
SELECT pg_temp.fb_as('00000000-0000-4000-8000-d10000000001');
DO $$
DECLARE
  school uuid := app.current_school_id();
  subj uuid;
  ka uuid := (SELECT id FROM "StudentGroups" WHERE name = 'FB7A');
  kb uuid := (SELECT id FROM "StudentGroups" WHERE name = 'FB7B');
  p1 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p1@example.invalid');
  p2 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p2@example.invalid');
  p3 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p3@example.invalid');
  p4 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p4@example.invalid');
BEGIN
  PERFORM set_config('app.test_fb_school', school::text, true);
  INSERT INTO "Subjects" ("schoolId", name, code, "updatedAt") VALUES (school, 'Bevakning 307', 'FB307', now()) RETURNING id INTO subj;
  INSERT INTO "AbsenceWatchSettings" ("schoolId", enabled) VALUES (school, true);
  INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, percent, "windowDays") VALUES
    (school, 'MENTOR', 'SHARE', 'INVALID', 10, 14), (school, 'GUARDIAN', 'SHARE', 'INVALID', 20, 14);
  INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, "consecutiveDays") VALUES (school, 'REKTOR', 'CONSECUTIVE', 'ALL', 2);
  PERFORM pg_temp.fb_plant(subj, ka, p1, '2026-09-23', ARRAY['ABSENT', 'ABSENT']);
  PERFORM pg_temp.fb_plant(subj, ka, p1, '2026-09-24', ARRAY['ABSENT', 'ABSENT']);
  PERFORM pg_temp.fb_plant(subj, ka, p2, '2026-09-23', ARRAY['PRESENT', 'PRESENT']);
  PERFORM pg_temp.fb_plant(subj, kb, p3, '2026-09-23', ARRAY['ABSENT', 'PRESENT']);
  PERFORM pg_temp.fb_plant(subj, kb, p4, '2026-09-23', ARRAY['ABSENT', 'PRESENT', 'PRESENT', 'PRESENT', 'PRESENT', 'PRESENT']);
  PERFORM app.absence_watch_evaluate(school, '2026-09-25');
  PERFORM pg_temp.fb_expect('307 school', pg_temp.fb_findings(),
    E'p1 GUARDIAN SHARE INVALID 2026-09-25 2026-09-25 - 240/240\n' ||
    E'p1 MENTOR SHARE INVALID 2026-09-25 2026-09-25 - 240/240\n' ||
    E'p1 REKTOR CONSECUTIVE ALL 2026-09-24 2026-09-25 - 2d\n' ||
    E'p3 GUARDIAN SHARE INVALID 2026-09-25 2026-09-25 - 60/120\n' ||
    E'p3 MENTOR SHARE INVALID 2026-09-25 2026-09-25 - 60/120\n' ||
    E'p4 MENTOR SHARE INVALID 2026-09-25 2026-09-25 - 60/360');
END $$;

-- The other school's administrator plants its own.
SELECT pg_temp.fb_as('00000000-0000-4000-8000-d10000000031');
DO $$
DECLARE
  school uuid := app.current_school_id();
  subj uuid;
  k9 uuid := (SELECT id FROM "StudentGroups" WHERE name = 'FB9A');
  po uuid := (SELECT id FROM "Users" WHERE email = 'fb-annan-p@example.invalid');
BEGIN
  IF school = current_setting('app.test_fb_school')::uuid THEN RAISE EXCEPTION 'frånvarobevakning 307: the other administrator is at the first school'; END IF;
  PERFORM set_config('app.test_fb_other', school::text, true);
  INSERT INTO "Subjects" ("schoolId", name, code, "updatedAt") VALUES (school, 'Bevakning 307 annan', 'FB307A', now()) RETURNING id INTO subj;
  INSERT INTO "AbsenceWatchSettings" ("schoolId", enabled) VALUES (school, true);
  INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, percent, "windowDays") VALUES
    (school, 'MENTOR', 'SHARE', 'INVALID', 10, 14), (school, 'GUARDIAN', 'SHARE', 'INVALID', 10, 14);
  PERFORM pg_temp.fb_plant(subj, k9, po, '2026-09-23', ARRAY['ABSENT', 'ABSENT']);
  PERFORM app.absence_watch_evaluate(school, '2026-09-25');
  IF (SELECT count(*) FROM "AbsenceWatchFindings") <> 2 THEN RAISE EXCEPTION 'frånvarobevakning 307: the other school''s findings'; END IF;
END $$;

CREATE FUNCTION pg_temp.fb_sees(p_auth text) RETURNS text LANGUAGE plpgsql AS $$
DECLARE
  seen text;
BEGIN
  PERFORM pg_temp.fb_as(p_auth);
  SELECT coalesce(string_agg(substr(u.email, 4, 2) || ' ' || f."recipientGroup", ', ' ORDER BY u.email, f."recipientGroup"::text), '')
    INTO seen
    FROM "AbsenceWatchFindings" f JOIN "Users" u ON u.id = f."studentId";
  RETURN seen;
END $$;

-- (A join to Users is under row security too: a pupil the reader cannot read
-- would drop out of the text above, so every text is read beside a count.)
CREATE FUNCTION pg_temp.fb_count(p_auth text) RETURNS integer LANGUAGE plpgsql AS $$
DECLARE
  n integer;
BEGIN
  PERFORM pg_temp.fb_as(p_auth);
  SELECT count(*) INTO n FROM "AbsenceWatchFindings";
  RETURN n;
END $$;

DO $$
DECLARE
  who record;
BEGIN
  -- Every administrator reads every finding of the school, and none of the other's.
  FOR who IN SELECT * FROM (VALUES ('full', '0001'), ('rektor', '0002'), ('expedition', '0003'), ('schemaläggare', '0004'), ('läsare', '0005')) v(name, auth) LOOP
    IF pg_temp.fb_count('00000000-0000-4000-8000-d1000000' || who.auth) <> 6 THEN
      RAISE EXCEPTION 'frånvarobevakning 307: the % reads % findings, not the 6 of the school', who.name, pg_temp.fb_count('00000000-0000-4000-8000-d1000000' || who.auth);
    END IF;
  END LOOP;
  PERFORM pg_temp.fb_expect('307 admin', pg_temp.fb_sees('00000000-0000-4000-8000-d10000000001'),
    'p1 GUARDIAN, p1 MENTOR, p1 REKTOR, p3 GUARDIAN, p3 MENTOR, p4 MENTOR');
  IF pg_temp.fb_count('00000000-0000-4000-8000-d10000000031') <> 2 THEN
    RAISE EXCEPTION 'frånvarobevakning 307: the other school''s administrator reads % findings, not its 2', pg_temp.fb_count('00000000-0000-4000-8000-d10000000031');
  END IF;

  -- A mentor reads the MENTOR findings of their own class and nothing else.
  IF pg_temp.fb_count('00000000-0000-4000-8000-d10000000006') <> 1 OR pg_temp.fb_count('00000000-0000-4000-8000-d10000000007') <> 2 THEN
    RAISE EXCEPTION 'frånvarobevakning 307: the mentors read % and % findings, not 1 and 2', pg_temp.fb_count('00000000-0000-4000-8000-d10000000006'), pg_temp.fb_count('00000000-0000-4000-8000-d10000000007');
  END IF;
  PERFORM pg_temp.fb_expect('307 mentor of 7A', pg_temp.fb_sees('00000000-0000-4000-8000-d10000000006'), 'p1 MENTOR');
  PERFORM pg_temp.fb_expect('307 mentor of 7B', pg_temp.fb_sees('00000000-0000-4000-8000-d10000000007'), 'p3 MENTOR, p4 MENTOR');
  IF pg_temp.fb_count('00000000-0000-4000-8000-d10000000008') <> 0 THEN RAISE EXCEPTION 'frånvarobevakning 307: a teacher without a class reads findings'; END IF;
  IF pg_temp.fb_count('00000000-0000-4000-8000-d10000000009') <> 0 THEN RAISE EXCEPTION 'frånvarobevakning 307: a deactivated mentor reads findings'; END IF;
  -- The other school's mentor reads their own class's, not this school's.
  IF pg_temp.fb_count('00000000-0000-4000-8000-d10000000034') <> 1 THEN
    RAISE EXCEPTION 'frånvarobevakning 307: the other school''s mentor reads % findings, not their one', pg_temp.fb_count('00000000-0000-4000-8000-d10000000034');
  END IF;

  -- A guardian reads the GUARDIAN findings of their own child.
  PERFORM pg_temp.fb_expect('307 guardian of P1', pg_temp.fb_sees('00000000-0000-4000-8000-d10000000021'), 'p1 GUARDIAN');
  PERFORM pg_temp.fb_expect('307 guardian of P2 and P3', pg_temp.fb_sees('00000000-0000-4000-8000-d10000000022'), 'p3 GUARDIAN');
  IF pg_temp.fb_count('00000000-0000-4000-8000-d10000000021') <> 1 OR pg_temp.fb_count('00000000-0000-4000-8000-d10000000022') <> 1 THEN
    RAISE EXCEPTION 'frånvarobevakning 307: a guardian reads findings of a child who is not theirs';
  END IF;
  -- P4 has a MENTOR finding only: their guardian reads nothing.
  IF pg_temp.fb_count('00000000-0000-4000-8000-d10000000023') <> 0 THEN RAISE EXCEPTION 'frånvarobevakning 307: a guardian reads a finding that is the mentor''s'; END IF;
  IF pg_temp.fb_count('00000000-0000-4000-8000-d10000000033') <> 1 THEN
    RAISE EXCEPTION 'frånvarobevakning 307: the other school''s guardian reads % findings, not their child''s one', pg_temp.fb_count('00000000-0000-4000-8000-d10000000033');
  END IF;

  -- A pupil reads none, not their own; nor does a login that is nobody, or no login.
  IF pg_temp.fb_count('00000000-0000-4000-8000-d10000000011') <> 0 THEN RAISE EXCEPTION 'frånvarobevakning 307: a pupil reads findings'; END IF;
  IF pg_temp.fb_count('00000000-0000-4000-8000-d10000000099') <> 0 THEN RAISE EXCEPTION 'frånvarobevakning 307: an unknown login reads findings'; END IF;
  PERFORM set_config('request.jwt.claims', '', true);
  IF (SELECT count(*) FROM "AbsenceWatchFindings") <> 0 THEN RAISE EXCEPTION 'frånvarobevakning 307: no principal reads findings'; END IF;
END $$;

-- Nobody writes a finding or the ledger, not even the full administrator. The
-- switch and the limits are Drift's: every profile that writes Drift writes
-- them and the läsare does not; no teacher or guardian reads or writes either.
DO $$
DECLARE
  who record;
  school uuid;
  mine uuid := current_setting('app.test_fb_school')::uuid;
  other uuid := current_setting('app.test_fb_other')::uuid;
  suffix text;
BEGIN
  FOR who IN SELECT * FROM (VALUES ('full', '0001', true), ('rektor', '0002', true), ('expedition', '0003', true),
                                   ('schemaläggare', '0004', true), ('läsare', '0005', false)) v(name, auth, writes) LOOP
    PERFORM pg_temp.fb_as('00000000-0000-4000-8000-d1000000' || who.auth);
    school := app.current_school_id();
    PERFORM pg_temp.fb_denied(format('INSERT INTO "AbsenceWatchFindings" ("schoolId", "studentId", "limitId", "recipientGroup", kind, basis, percent, "windowDays", "firstCrossedOn", "lastSeenOn", "absentMinutes", "recordedMinutes") VALUES (%L, gen_random_uuid(), gen_random_uuid(), ''MENTOR'', ''SHARE'', ''ALL'', 10, 14, current_date, current_date, 1, 10)', school));
    PERFORM pg_temp.fb_denied('UPDATE "AbsenceWatchFindings" SET "clearedOn" = current_date');
    PERFORM pg_temp.fb_denied('DELETE FROM "AbsenceWatchFindings"');
    PERFORM pg_temp.fb_denied(format('INSERT INTO "AbsenceWatchDigests" ("schoolId", "recipientGroup", "periodStart", "periodEnd", recipients, pupils) VALUES (%L, ''MENTOR'', current_date, current_date, 0, 0)', school));
    PERFORM pg_temp.fb_denied('UPDATE "AbsenceWatchDigests" SET recipients = 9');
    PERFORM pg_temp.fb_denied('DELETE FROM "AbsenceWatchDigests"');
    PERFORM pg_temp.fb_denied('DELETE FROM "AbsenceWatchSettings"');
    -- The limit and the switch: the läsare is refused, the others are given.
    BEGIN
      INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, "consecutiveDays") VALUES (school, 'KANSLI', 'CONSECUTIVE', 'VALID', 9);
      IF NOT who.writes THEN RAISE EXCEPTION 'frånvarobevakning 307: the % wrote a limit', who.name; END IF;
      DELETE FROM "AbsenceWatchLimits" WHERE "recipientGroup" = 'KANSLI' AND basis = 'VALID';
    EXCEPTION WHEN insufficient_privilege THEN
      IF who.writes THEN RAISE EXCEPTION 'frånvarobevakning 307: the % was refused a limit', who.name; END IF;
    END;
    BEGIN
      UPDATE "AbsenceWatchSettings" SET "guardianCadence" = 'WEEKLY' WHERE "schoolId" = school;
      IF NOT who.writes THEN RAISE EXCEPTION 'frånvarobevakning 307: the % changed the switch', who.name; END IF;
      UPDATE "AbsenceWatchSettings" SET "guardianCadence" = 'MONTHLY' WHERE "schoolId" = school;
    EXCEPTION WHEN insufficient_privilege THEN
      IF who.writes THEN RAISE EXCEPTION 'frånvarobevakning 307: the % was refused the switch', who.name; END IF;
    END;
    IF (SELECT count(*) FROM "AbsenceWatchLimits") <> 3 THEN RAISE EXCEPTION 'frånvarobevakning 307: the % does not read the three limits', who.name; END IF;
    IF (SELECT count(*) FROM "AbsenceWatchSettings") <> 1 THEN RAISE EXCEPTION 'frånvarobevakning 307: the % does not read the switch', who.name; END IF;
    -- And a limit of the other school's is not theirs to write.
    PERFORM pg_temp.fb_denied(format('INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, "consecutiveDays") VALUES (%L, ''KANSLI'', ''CONSECUTIVE'', ''VALID'', 9)', other));
  END LOOP;
  -- The other school's administrator: its own two limits, and this school's are not theirs.
  PERFORM pg_temp.fb_as('00000000-0000-4000-8000-d10000000031');
  IF (SELECT count(*) FROM "AbsenceWatchLimits") <> 2 OR (SELECT count(*) FROM "AbsenceWatchSettings") <> 1 THEN
    RAISE EXCEPTION 'frånvarobevakning 307: the other school''s administrator reads this school''s limits or switch';
  END IF;
  PERFORM pg_temp.fb_denied(format('INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, "consecutiveDays") VALUES (%L, ''KANSLI'', ''CONSECUTIVE'', ''VALID'', 9)', mine));
  PERFORM pg_temp.fb_denied(format('UPDATE "AbsenceWatchSettings" SET enabled = false WHERE "schoolId" = %L', mine));
  PERFORM pg_temp.fb_denied(format('DELETE FROM "AbsenceWatchLimits" WHERE "schoolId" = %L', mine));
  -- Teachers, guardians and a pupil read neither table, the ledger or the switch, and write none.
  FOREACH suffix IN ARRAY ARRAY['0006', '0008', '0021', '0011'] LOOP
    PERFORM pg_temp.fb_as('00000000-0000-4000-8000-d1000000' || suffix);
    IF (SELECT count(*) FROM "AbsenceWatchLimits") <> 0 OR (SELECT count(*) FROM "AbsenceWatchSettings") <> 0
       OR (SELECT count(*) FROM "AbsenceWatchDigests") <> 0 THEN
      RAISE EXCEPTION 'frånvarobevakning 307: …% reads the school''s limits, switch or ledger', suffix;
    END IF;
    PERFORM pg_temp.fb_denied(format('INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, "consecutiveDays") VALUES (%L, ''KANSLI'', ''CONSECUTIVE'', ''VALID'', 9)', mine));
    PERFORM pg_temp.fb_denied(format('INSERT INTO "AbsenceWatchSettings" ("schoolId") VALUES (%L)', other));
    PERFORM pg_temp.fb_denied(format('UPDATE "AbsenceWatchSettings" SET enabled = false WHERE "schoolId" = %L', mine));
    PERFORM pg_temp.fb_denied('DELETE FROM "AbsenceWatchLimits"');
  END LOOP;
END $$;

-- PostgREST's roles reach none of the four tables and none of the functions:
-- authenticated is tried, and the catalogue is asked for anon, service_role and
-- PUBLIC (the API's role cannot become anon, so a catalogue answer is the proof).
DO $$
DECLARE
  stmt text;
  tbl text;
  fn text;
  r text;
  bad text;
BEGIN
  SET LOCAL ROLE authenticated;
  FOREACH stmt IN ARRAY ARRAY[
    'SELECT count(*) FROM "AbsenceWatchSettings"', 'SELECT count(*) FROM "AbsenceWatchLimits"',
    'SELECT count(*) FROM "AbsenceWatchFindings"', 'SELECT count(*) FROM "AbsenceWatchDigests"',
    'DELETE FROM "AbsenceWatchFindings"', 'DELETE FROM "AbsenceWatchLimits"',
    'SELECT app.absence_watch_evaluate(gen_random_uuid(), current_date - 1)',
    'SELECT * FROM app.absence_watch_schools()',
    'SELECT app.absence_watch_is_mentor_of(gen_random_uuid())',
    'SELECT * FROM app.absence_watch_mentees(gen_random_uuid(), current_date)',
    'SELECT * FROM app.absence_watch_digest_due(gen_random_uuid(), current_date)',
    'SELECT * FROM app.absence_watch_digest_plan(gen_random_uuid(), ''MENTOR'', current_date, current_date, current_date)',
    'SELECT * FROM app.absence_watch_digest(gen_random_uuid(), ''MENTOR'', current_date, current_date, current_date)'
  ] LOOP
    BEGIN
      EXECUTE stmt;
      RAISE EXCEPTION 'frånvarobevakning 307: authenticated was allowed to run %', stmt;
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
  END LOOP;
  SET LOCAL ROLE app_authenticated;
  -- The plan hands out the recipients' addresses and pupils for any school it is given, and
  -- only the digest asks for it: the API's role is refused it.
  PERFORM pg_temp.fb_denied('SELECT * FROM app.absence_watch_digest_plan(gen_random_uuid(), ''MENTOR'', current_date, current_date, current_date)');

  FOREACH tbl IN ARRAY ARRAY['AbsenceWatchSettings', 'AbsenceWatchLimits', 'AbsenceWatchFindings', 'AbsenceWatchDigests'] LOOP
    FOREACH r IN ARRAY ARRAY['anon', 'authenticated'] LOOP
      IF has_table_privilege(r, format('public.%I', tbl), 'SELECT, INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER') THEN
        RAISE EXCEPTION 'frånvarobevakning 307: % holds a privilege on %', r, tbl;
      END IF;
    END LOOP;
    IF has_table_privilege('service_role', format('public.%I', tbl), 'INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER') THEN
      RAISE EXCEPTION 'frånvarobevakning 307: service_role writes %', tbl;
    END IF;
    IF has_table_privilege('app_authenticated', format('public.%I', tbl), 'TRUNCATE, REFERENCES, TRIGGER') THEN
      RAISE EXCEPTION 'frånvarobevakning 307: the API role truncates, references or triggers %', tbl;
    END IF;
  END LOOP;
  -- What the API's role holds: the findings and the ledger are read, the switch is read and written but not deleted, the limits are all four.
  IF NOT has_table_privilege('app_authenticated', 'public."AbsenceWatchFindings"', 'SELECT')
     OR has_table_privilege('app_authenticated', 'public."AbsenceWatchFindings"', 'INSERT, UPDATE, DELETE')
     OR NOT has_table_privilege('app_authenticated', 'public."AbsenceWatchDigests"', 'SELECT')
     OR has_table_privilege('app_authenticated', 'public."AbsenceWatchDigests"', 'INSERT, UPDATE, DELETE')
     OR has_table_privilege('app_authenticated', 'public."AbsenceWatchSettings"', 'DELETE')
     OR NOT has_table_privilege('app_authenticated', 'public."AbsenceWatchSettings"', 'SELECT')
     OR NOT has_table_privilege('app_authenticated', 'public."AbsenceWatchSettings"', 'INSERT')
     OR NOT has_table_privilege('app_authenticated', 'public."AbsenceWatchSettings"', 'UPDATE')
     OR NOT has_table_privilege('app_authenticated', 'public."AbsenceWatchLimits"', 'SELECT')
     OR NOT has_table_privilege('app_authenticated', 'public."AbsenceWatchLimits"', 'INSERT')
     OR NOT has_table_privilege('app_authenticated', 'public."AbsenceWatchLimits"', 'UPDATE')
     OR NOT has_table_privilege('app_authenticated', 'public."AbsenceWatchLimits"', 'DELETE') THEN
    RAISE EXCEPTION 'frånvarobevakning 307: the API role holds other privileges than the migration gives it';
  END IF;

  -- The functions: PUBLIC and PostgREST's roles hold none; the API's role holds
  -- the five it calls and not the mentee list, the plan or the triggers' bodies.
  FOR fn, bad IN
    SELECT p.oid::regprocedure::text,
           concat_ws(',',
             CASE WHEN has_function_privilege('anon', p.oid, 'EXECUTE') THEN 'anon' END,
             CASE WHEN has_function_privilege('authenticated', p.oid, 'EXECUTE') THEN 'authenticated' END,
             CASE WHEN has_function_privilege('service_role', p.oid, 'EXECUTE') THEN 'service_role' END,
             CASE WHEN EXISTS (SELECT 1 FROM aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a WHERE a.grantee = 0) THEN 'PUBLIC' END)
      FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = 'app' AND p.proname LIKE 'absence\_watch\_%'
  LOOP
    IF bad <> '' THEN RAISE EXCEPTION 'frånvarobevakning 307: % may be run by %', fn, bad; END IF;
  END LOOP;
  FOREACH fn IN ARRAY ARRAY['app.absence_watch_is_mentor_of(uuid)', 'app.absence_watch_schools()', 'app.absence_watch_evaluate(uuid, date)',
                            'app.absence_watch_digest_due(uuid, date)', 'app.absence_watch_digest(uuid, "AbsenceWatchGroup", date, date, date)'] LOOP
    IF NOT has_function_privilege('app_authenticated', fn::regprocedure, 'EXECUTE') THEN
      RAISE EXCEPTION 'frånvarobevakning 307: the API role cannot run %', fn;
    END IF;
  END LOOP;
  FOREACH fn IN ARRAY ARRAY['app.absence_watch_mentees(uuid, date)', 'app.absence_watch_digest_plan(uuid, "AbsenceWatchGroup", date, date, date)',
                            'app.absence_watch_settings_stamp()', 'app.absence_watch_settings_stop()',
                            'app.absence_watch_limits_stamp()', 'app.absence_watch_limits_removed()'] LOOP
    IF has_function_privilege('app_authenticated', fn::regprocedure, 'EXECUTE') THEN
      RAISE EXCEPTION 'frånvarobevakning 307: the API role can run %, which is the owner''s', fn;
    END IF;
  END LOOP;

  -- Every policy on the four tables is the API role's alone.
  SELECT string_agg(tablename || '.' || policyname, ', ') INTO bad
    FROM pg_policies WHERE schemaname = 'public' AND tablename LIKE 'AbsenceWatch%' AND roles <> ARRAY['app_authenticated']::name[];
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'frånvarobevakning 307: policies not for app_authenticated alone: %', bad; END IF;
  SELECT string_agg(policyname, ', ' ORDER BY policyname) INTO bad FROM pg_policies WHERE schemaname = 'public' AND tablename = 'AbsenceWatchFindings';
  IF bad <> 'absence_watch_findings_admin_select, absence_watch_findings_guardian_select, absence_watch_findings_mentor_select' THEN
    RAISE EXCEPTION 'frånvarobevakning 307: the findings have the arms %, not the three read arms', bad;
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 308: the digest.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT pg_temp.fb_as('00000000-0000-4000-8000-d10000000001');
DO $$
DECLARE
  school uuid := app.current_school_id();
  subj uuid;
  ka uuid := (SELECT id FROM "StudentGroups" WHERE name = 'FB7A');
  kb uuid := (SELECT id FROM "StudentGroups" WHERE name = 'FB7B');
  p1 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p1@example.invalid');
  p2 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p2@example.invalid');
  p3 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p3@example.invalid');
  p4 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p4@example.invalid');
  p5 uuid := (SELECT id FROM "Users" WHERE email = 'fb-p5@example.invalid');
  r record;
  got text;
  n integer;
  texts text := '';
  -- The mentors are the day's: the digest's own day is today, though the weeks are old.
  today date := (now() AT TIME ZONE 'Europe/Stockholm')::date;
BEGIN
  INSERT INTO "Subjects" ("schoolId", name, code, "updatedAt") VALUES (school, 'Bevakning 308', 'FB308', now()) RETURNING id INTO subj;
  INSERT INTO "AbsenceWatchSettings" ("schoolId", enabled) VALUES (school, true);
  INSERT INTO "AbsenceWatchLimits" ("schoolId", "recipientGroup", kind, basis, percent, "windowDays") VALUES
    (school, 'MENTOR', 'SHARE', 'INVALID', 10, 14), (school, 'GUARDIAN', 'SHARE', 'INVALID', 10, 14),
    (school, 'REKTOR', 'SHARE', 'INVALID', 10, 14), (school, 'KANSLI', 'SHARE', 'INVALID', 10, 14);
  -- Over the week of 2026-09-21 to 27: P1 (7A) absent all week, P3 (7B) absent on
  -- the Tuesday, P2 (7A) present, and P5 (7A), who is deactivated, absent all
  -- week. P4 (7B) was absent on the Friday the 11th: over the limits when the
  -- 20th was counted and back under in the count of the 27th, whose window
  -- starts on the 14th: crossed the week before, not open now.
  PERFORM pg_temp.fb_weekdays(subj, ka, p1, '2026-09-21', '2026-09-25', 'ABSENT', 2);
  PERFORM pg_temp.fb_weekdays(subj, ka, p2, '2026-09-21', '2026-09-25', 'PRESENT', 2);
  PERFORM pg_temp.fb_plant(subj, kb, p3, '2026-09-22', ARRAY['ABSENT', 'ABSENT']);
  PERFORM pg_temp.fb_weekdays(subj, kb, p3, '2026-09-23', '2026-09-25', 'PRESENT', 2);
  PERFORM pg_temp.fb_weekdays(subj, ka, p5, '2026-09-21', '2026-09-25', 'ABSENT', 2);
  PERFORM pg_temp.fb_plant(subj, kb, p4, '2026-09-11', ARRAY['ABSENT', 'ABSENT']);
  PERFORM pg_temp.fb_weekdays(subj, kb, p4, '2026-09-14', '2026-09-18', 'PRESENT', 2);
  PERFORM app.absence_watch_evaluate(school, '2026-09-20');
  IF (SELECT count(*) FROM "AbsenceWatchFindings" WHERE "studentId" = p4 AND "clearedOn" IS NULL) <> 4 THEN
    RAISE EXCEPTION 'frånvarobevakning 308: P4 was not over all four limits on the 20th: %', pg_temp.fb_findings();
  END IF;
  PERFORM app.absence_watch_evaluate(school, '2026-09-27');
  IF (SELECT count(*) FROM "AbsenceWatchFindings" WHERE "studentId" = p4 AND "clearedOn" = '2026-09-27') <> 4
     OR (SELECT count(*) FROM "AbsenceWatchFindings" WHERE "studentId" <> p4 AND "clearedOn" IS NULL) <> 8 THEN
    RAISE EXCEPTION 'frånvarobevakning 308: after the 27th: %', pg_temp.fb_findings();
  END IF;

  -- The digests of Monday the 28th, for the week of the 21st: who hears what. open is the
  -- pupils over a limit now, crossed those whose crossing was in the period; the last figure
  -- of the mentors' lines is the pupils their read log row names. Each is asked for before
  -- its digest is written for real, and taken back (pg_temp.fb_would_hear).
  PERFORM pg_temp.fb_expect('308 mentors', pg_temp.fb_would_hear(school, 'MENTOR', '2026-09-21', '2026-09-27', today, true), 'm1 1/1 1, m2 1/1 1');
  PERFORM pg_temp.fb_expect('308 guardians', pg_temp.fb_would_hear(school, 'GUARDIAN', '2026-09-21', '2026-09-27', today), 'g1 1/1, g2 1/1');
  PERFORM pg_temp.fb_expect('308 rektor', pg_temp.fb_would_hear(school, 'REKTOR', '2026-09-21', '2026-09-27', today), 'fu 2/2, re 2/2');
  PERFORM pg_temp.fb_expect('308 kansli', pg_temp.fb_would_hear(school, 'KANSLI', '2026-09-21', '2026-09-27', today), 'ex 2/2');
  -- The week before: P4 crossed in it and is not open now, and two are open.
  PERFORM pg_temp.fb_expect('308 kansli, the week before', pg_temp.fb_would_hear(school, 'KANSLI', '2026-09-14', '2026-09-20', today), 'ex 2/1');

  -- A pupil who has left is told of to nobody: P3 is deactivated, and the mentor of 7B, P3's
  -- guardian and the administrators hear of the others only. P3 is back for the rest.
  UPDATE "Users" SET "isActive" = false WHERE id = p3;
  PERFORM pg_temp.fb_expect('308 a pupil who left, mentors', pg_temp.fb_would_hear(school, 'MENTOR', '2026-09-21', '2026-09-27', today), 'm1 1/1');
  PERFORM pg_temp.fb_expect('308 a pupil who left, guardians', pg_temp.fb_would_hear(school, 'GUARDIAN', '2026-09-21', '2026-09-27', today), 'g1 1/1');
  PERFORM pg_temp.fb_expect('308 a pupil who left, rektor', pg_temp.fb_would_hear(school, 'REKTOR', '2026-09-21', '2026-09-27', today), 'fu 1/1, re 1/1');
  UPDATE "Users" SET "isActive" = true WHERE id = p3;
  -- Taken back means taken back: no ledger row, no notice and no log row is left by the questions above.
  IF EXISTS (SELECT 1 FROM "AbsenceWatchDigests") OR EXISTS (SELECT 1 FROM "PersonalDataAccess" WHERE kind = 'ATTENDANCE' AND channel = 'OTHER') THEN
    RAISE EXCEPTION 'frånvarobevakning 308: asking who would hear wrote something that stayed';
  END IF;

  -- Written once: the ledger says so, and the second call writes nothing.
  FOR r IN SELECT * FROM app.absence_watch_digest(school, 'MENTOR', '2026-09-21', '2026-09-27', today) LOOP
    n := coalesce(n, 0) + 1;
    texts := texts || ' ' || r.meta::text;
    IF r.email !~ '^fb-m[12]@' THEN RAISE EXCEPTION 'frånvarobevakning 308: a notice for %', r.email; END IF;
  END LOOP;
  IF n IS DISTINCT FROM 2 THEN RAISE EXCEPTION 'frånvarobevakning 308: the mentors'' digest wrote % notices, not 2', n; END IF;
  SELECT count(*) INTO n FROM app.absence_watch_digest(school, 'MENTOR', '2026-09-21', '2026-09-27', today);
  IF n <> 0 THEN RAISE EXCEPTION 'frånvarobevakning 308: the second call wrote % notices', n; END IF;
  -- The read log has a row for each mentor, written with the notices: ATTENDANCE,
  -- the mentor the reader, the pupil of their plan the subject, channel OTHER.
  got := (SELECT string_agg(substr(m.email, 4, 2) || '>' || (SELECT string_agg(substr(s.email, 4, 2), ',' ORDER BY s.email) FROM "Users" s WHERE s.id = ANY (a."subjectIds"))
                            || '/' || a."readSize" || ' ' || a.channel || ' ' || a."actorRole", '; ' ORDER BY m.email, a."at")
            FROM "PersonalDataAccess" a JOIN "Users" m ON m.id = a."actorId" WHERE a.kind = 'ATTENDANCE' AND a.channel = 'OTHER');
  PERFORM pg_temp.fb_expect('308 log', got, 'm1>p1/1 OTHER TEACHER; m2>p3/1 OTHER TEACHER');
  IF (SELECT recipients || '/' || pupils FROM "AbsenceWatchDigests" WHERE "recipientGroup" = 'MENTOR') <> '2/2' THEN
    RAISE EXCEPTION 'frånvarobevakning 308: the ledger counts %', (SELECT recipients || '/' || pupils FROM "AbsenceWatchDigests" WHERE "recipientGroup" = 'MENTOR');
  END IF;
  -- The notice is a count and a period: no pupil, no name, no minutes, no reason.
  IF texts ~* '(Elev|studentId|reason|anledning|minutes|[0-9a-f]{8}-[0-9a-f]{4}-)' THEN
    RAISE EXCEPTION 'frånvarobevakning 308: a notice names more than a count and a period: %', texts;
  END IF;
  IF texts !~ '"open": 1' OR texts !~ '"crossed": 1' OR texts !~ '"group": "MENTOR"' OR texts !~ '"periodEnd": "2026-09-27"' THEN
    RAISE EXCEPTION 'frånvarobevakning 308: the notice is not group, period, open and crossed: %', texts;
  END IF;
  -- Another period of the same group is another digest, and another group's is its own.
  SELECT count(*) INTO n FROM app.absence_watch_digest(school, 'MENTOR', '2026-09-14', '2026-09-20', today);
  IF n <> 2 THEN RAISE EXCEPTION 'frånvarobevakning 308: the week before wrote % notices, not 2 (the two mentors hear of P4 and of the open ones)', n; END IF;
  -- ... and its log rows leave out what the same reader has from the last quarter-hour: M1's
  -- pupil was in the first digest, and M2 is logged for P4 only, though P3 and P4 are 2 of the read.
  got := (SELECT string_agg(substr(m.email, 4, 2) || '>' || (SELECT string_agg(substr(s.email, 4, 2), ',' ORDER BY s.email) FROM "Users" s WHERE s.id = ANY (a."subjectIds"))
                            || '/' || a."readSize", '; ' ORDER BY m.email, a."at")
            FROM "PersonalDataAccess" a JOIN "Users" m ON m.id = a."actorId" WHERE a.kind = 'ATTENDANCE' AND a.channel = 'OTHER');
  PERFORM pg_temp.fb_expect('308 log, the week before', got, 'm1>p1/1; m2>p3/1; m2>p4/2');
  SELECT count(*) INTO n FROM app.absence_watch_digest(school, 'REKTOR', '2026-09-21', '2026-09-27', today);
  IF n <> 2 THEN RAISE EXCEPTION 'frånvarobevakning 308: rektor''s digest wrote % notices, not 2', n; END IF;
  -- The administrators read the pupils, none of them themselves.
  got := (SELECT string_agg(substr(m.email, 4, 2) || '>' || (SELECT string_agg(substr(s.email, 4, 2), ',' ORDER BY s.email) FROM "Users" s WHERE s.id = ANY (a."subjectIds"))
                            || '/' || a."readSize" || ' ' || a."actorRole", '; ' ORDER BY m.email)
            FROM "PersonalDataAccess" a JOIN "Users" m ON m.id = a."actorId" WHERE a.kind = 'ATTENDANCE' AND a.channel = 'OTHER' AND m.role = 'SCHOOL_ADMIN');
  PERFORM pg_temp.fb_expect('308 log, administrators', got, 'fu>p1,p3/2 SCHOOL_ADMIN; re>p1,p3/2 SCHOOL_ADMIN');

  -- With the bevakning off, nothing is written and no ledger row; nobody has anything open.
  UPDATE "AbsenceWatchSettings" SET enabled = false;
  SELECT count(*) INTO n FROM app.absence_watch_digest(school, 'GUARDIAN', '2026-09-21', '2026-09-27', today);
  IF n <> 0 OR EXISTS (SELECT 1 FROM "AbsenceWatchDigests" WHERE "recipientGroup" = 'GUARDIAN') THEN
    RAISE EXCEPTION 'frånvarobevakning 308: a school that is off had a digest written';
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 310: en schemabrytande aktivitet ställer in lektionerna och
-- ersätter dem, katalogen (ScheduleActivities, ScheduleActivityTeachers,
-- ScheduleActivityLessons, 20270101090000).
--
-- The activity owns one avbokning (CancellationBatches) and says what comes
-- in its place: the replacement subject, the responsible teachers per class
-- or group, and the replacement lessons, one per group and day. This section
-- holds what the migration wrote into the catalogue, apart from any row:
--   * row security is on, and each table has exactly four arms, TO the API's
--     role: staff (administrator and teacher) read, and only an
--     administrator writes, the write asking the area DRIFT in WITH CHECK
--     (insert, update) or USING (delete); the update arm's USING never asks
--     the area, so a row lock keeps working for every administrator (the
--     rule of section 106). No arm names a pupil or a guardian;
--   * the grants: the API's role holds SELECT, INSERT, UPDATE and DELETE;
--     PostgREST's authenticated and anon hold nothing, not even a column;
--     service_role holds SELECT only; nobody holds TRUNCATE, REFERENCES or
--     TRIGGER, nobody but the owner holds a PUBLIC grant, and on Postgres 17
--     nobody holds MAINTAIN (20261016120000);
--   * the keys: ten foreign keys in all, each with its ON DELETE and ON
--     UPDATE, the SET NULL ones naming only their own column; every key to a
--     school-owned table is the composite (id, schoolId), so a row cannot
--     point across the school boundary. studentGroupId on the teachers and
--     on the lessons is NOT a key, on purpose (the class is named in the
--     activity's selection, and a replacement lesson goes with its class
--     through CalendarLessons);
--   * the CHECKs, the primary keys and every unique index (one avbokning per
--     activity, one lead per activity and group, one replacement lesson per
--     group and day, one activity per lesson), and the indexes the person
--     keys are looked up by.
-- How the arms behave is section 311's, the school boundary section 312's,
-- the cascades and the constraints at work section 313's.
-- ---------------------------------------------------------------------------

BEGIN;
DO $$
DECLARE
  tables constant regclass[] := ARRAY['public."ScheduleActivities"', 'public."ScheduleActivityTeachers"',
                                       'public."ScheduleActivityLessons"']::regclass[];
  api oid := (SELECT oid FROM pg_roles WHERE rolname = 'app_authenticated');
  bad text;
BEGIN
  IF api IS NULL THEN
    RAISE EXCEPTION 'sa310: the API''s role does not exist, so nothing below says anything';
  END IF;

  -- Row security is on, for all three.
  SELECT string_agg(c.relname, ', ') INTO bad FROM pg_class c WHERE c.oid = ANY (tables) AND NOT c.relrowsecurity;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'sa310: row security is off on %', bad; END IF;

  -- Exactly these arms, with these commands: no more, no fewer.
  SELECT string_agg(polname || ':' || polcmd::text, ',' ORDER BY polname COLLATE "C") INTO bad
    FROM pg_policy WHERE polrelid = ANY (tables);
  IF bad IS DISTINCT FROM
       'schedule_activities_admin_delete:d,schedule_activities_admin_insert:a,schedule_activities_admin_update:w,schedule_activities_staff_select:r,'
       'schedule_activity_lessons_admin_delete:d,schedule_activity_lessons_admin_insert:a,schedule_activity_lessons_admin_update:w,schedule_activity_lessons_staff_select:r,'
       'schedule_activity_teachers_admin_delete:d,schedule_activity_teachers_admin_insert:a,schedule_activity_teachers_admin_update:w,schedule_activity_teachers_staff_select:r' THEN
    RAISE EXCEPTION 'sa310: policies are %', bad;
  END IF;

  -- Every arm is the API's role's alone (a TO public arm would admit a row on
  -- a GUC, as section 36 describes), and none is RESTRICTIVE.
  SELECT string_agg(p.polname, ', ') INTO bad FROM pg_policy p
   WHERE p.polrelid = ANY (tables) AND (p.polroles <> ARRAY[api] OR NOT p.polpermissive);
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'sa310: arms that are not the API role''s permissive ones: %', bad; END IF;

  -- What each arm asks. A read asks the school and the staff roles and never
  -- the area; a write asks the school, SCHOOL_ADMIN and DRIFT as a write.
  SELECT string_agg(format('%s.%s', tablename, policyname), ', ') INTO bad
    FROM pg_policies
   WHERE schemaname = 'public' AND tablename IN ('ScheduleActivities', 'ScheduleActivityTeachers', 'ScheduleActivityLessons')
     AND NOT CASE
       WHEN policyname LIKE '%\_staff\_select' THEN
         qual LIKE '%current_school_id%' AND qual LIKE '%SCHOOL_ADMIN%' AND qual LIKE '%TEACHER%'
         AND qual NOT LIKE '%STUDENT%' AND qual NOT LIKE '%GUARDIAN%' AND qual NOT LIKE '%current_user_may%'
         AND with_check IS NULL
       WHEN policyname LIKE '%\_admin\_insert' THEN
         qual IS NULL AND with_check LIKE '%current_school_id%' AND with_check LIKE '%= ''SCHOOL_ADMIN''%'
         AND with_check ~ 'current_user_may\(''DRIFT''::"AdminArea", true\)'
       WHEN policyname LIKE '%\_admin\_update' THEN
         qual LIKE '%current_school_id%' AND qual LIKE '%= ''SCHOOL_ADMIN''%' AND qual NOT LIKE '%current_user_may%'
         AND with_check LIKE '%current_school_id%' AND with_check LIKE '%= ''SCHOOL_ADMIN''%'
         AND with_check ~ 'current_user_may\(''DRIFT''::"AdminArea", true\)'
       WHEN policyname LIKE '%\_admin\_delete' THEN
         with_check IS NULL AND qual LIKE '%current_school_id%' AND qual LIKE '%= ''SCHOOL_ADMIN''%'
         AND qual ~ 'current_user_may\(''DRIFT''::"AdminArea", true\)'
       ELSE false END;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'sa310: arms that ask something else than the migration wrote: %', bad; END IF;
END $$;

-- The grants, role by role and privilege by privilege.
DO $$
DECLARE
  tables constant text[] := ARRAY['public."ScheduleActivities"', 'public."ScheduleActivityTeachers"',
                                  'public."ScheduleActivityLessons"'];
  tbl text;
  r text;
  priv text;
  wanted boolean;
  wrong text[] := '{}';
  grantees text;
BEGIN
  FOREACH tbl IN ARRAY tables LOOP
    FOREACH r IN ARRAY ARRAY['app_authenticated', 'authenticated', 'anon', 'service_role'] LOOP
      IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
        IF r = 'app_authenticated' THEN RAISE EXCEPTION 'sa310: the API''s role does not exist'; END IF;
        CONTINUE;
      END IF;
      FOREACH priv IN ARRAY ARRAY['SELECT', 'INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'] LOOP
        wanted := (r = 'app_authenticated' AND priv IN ('SELECT', 'INSERT', 'UPDATE', 'DELETE'))
               OR (r = 'service_role' AND priv = 'SELECT');
        IF has_table_privilege(r, tbl, priv) IS DISTINCT FROM wanted THEN
          wrong := wrong || format('%s %s on %s: %s', r, priv, tbl, NOT wanted);
        END IF;
      END LOOP;
      -- MAINTAIN (REINDEX, CLUSTER, VACUUM, LOCK) is the owner's alone.
      IF current_setting('server_version_num')::int >= 170000 THEN
        IF has_table_privilege(r, tbl, 'MAINTAIN') THEN
          wrong := wrong || format('%s MAINTAIN on %s', r, tbl);
        END IF;
      END IF;
      -- No column grant either: PostgREST's roles and the service key hold
      -- no column of these tables, and the service key writes none.
      FOREACH priv IN ARRAY ARRAY['SELECT', 'INSERT', 'UPDATE', 'REFERENCES'] LOOP
        wanted := (r = 'app_authenticated' AND priv IN ('SELECT', 'INSERT', 'UPDATE'))
               OR (r = 'service_role' AND priv = 'SELECT');
        IF has_any_column_privilege(r, tbl, priv) IS DISTINCT FROM wanted THEN
          wrong := wrong || format('%s holds a column %s of %s: %s', r, priv, tbl, NOT wanted);
        END IF;
      END LOOP;
    END LOOP;
  END LOOP;
  IF cardinality(wrong) > 0 THEN RAISE EXCEPTION 'sa310: grants: %', array_to_string(wrong, '; '); END IF;

  -- Nobody but the owner, the API's role and the service key appears in the
  -- ACL, and PUBLIC does not.
  SELECT string_agg(DISTINCT coalesce(ro.rolname, 'PUBLIC'), ', ' ORDER BY coalesce(ro.rolname, 'PUBLIC')) INTO grantees
    FROM pg_class c
    CROSS JOIN LATERAL aclexplode(c.relacl) a
    LEFT JOIN pg_roles ro ON ro.oid = a.grantee
   WHERE c.oid = ANY (tables::regclass[]) AND a.grantee <> c.relowner;
  IF grantees IS DISTINCT FROM 'app_authenticated, service_role' THEN
    RAISE EXCEPTION 'sa310: the ACLs name % beside the owner', grantees;
  END IF;
END $$;

-- The columns that keep a row in its school and its place are NOT NULL; the
-- ones that may be empty are the ones the migration says may.
DO $$
DECLARE
  bad text;
BEGIN
  SELECT string_agg(format('%s.%s (%s)', e.tbl, e.col, CASE WHEN a.attnotnull THEN 'NOT NULL' ELSE 'nullable' END), ', ') INTO bad
    FROM (VALUES
      ('ScheduleActivities', 'id', true, 'uuid'), ('ScheduleActivities', 'schoolId', true, 'uuid'),
      ('ScheduleActivities', 'academicYearId', true, 'uuid'), ('ScheduleActivities', 'batchId', true, 'uuid'),
      ('ScheduleActivities', 'replacementSubjectId', true, 'uuid'), ('ScheduleActivities', 'description', false, 'text'),
      ('ScheduleActivities', 'scopeGroupIds', true, 'uuid[]'), ('ScheduleActivities', 'createdAt', true, 'timestamp(6) with time zone'),
      ('ScheduleActivities', 'createdByUserId', false, 'uuid'), ('ScheduleActivities', 'updatedAt', true, 'timestamp(6) with time zone'),
      ('ScheduleActivities', 'removedAt', false, 'timestamp(6) with time zone'), ('ScheduleActivities', 'removedByUserId', false, 'uuid'),
      ('ScheduleActivityTeachers', 'activityId', true, 'uuid'), ('ScheduleActivityTeachers', 'studentGroupId', true, 'uuid'),
      ('ScheduleActivityTeachers', 'teacherId', true, 'uuid'), ('ScheduleActivityTeachers', 'schoolId', true, 'uuid'),
      ('ScheduleActivityTeachers', 'role', true, '"TeacherAssignmentRole"'),
      ('ScheduleActivityLessons', 'activityId', true, 'uuid'), ('ScheduleActivityLessons', 'calendarLessonId', true, 'uuid'),
      ('ScheduleActivityLessons', 'studentGroupId', true, 'uuid'), ('ScheduleActivityLessons', 'date', true, 'date'),
      ('ScheduleActivityLessons', 'schoolId', true, 'uuid')) e(tbl, col, required, typ)
    LEFT JOIN pg_attribute a ON a.attrelid = format('public.%I', e.tbl)::regclass AND a.attname = e.col AND NOT a.attisdropped
   WHERE a.attnum IS NULL OR a.attnotnull IS DISTINCT FROM e.required
      OR format_type(a.atttypid, a.atttypmod) IS DISTINCT FROM e.typ;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'sa310: columns that are not as the migration made them: %', bad; END IF;
  -- The role defaults to LEAD and the selection to none, so a statement that
  -- names neither (the first the API will send) still stores a row.
  IF (SELECT pg_get_expr(d.adbin, d.adrelid) FROM pg_attrdef d JOIN pg_attribute a ON a.attrelid = d.adrelid AND a.attnum = d.adnum
       WHERE d.adrelid = 'public."ScheduleActivityTeachers"'::regclass AND a.attname = 'role') NOT LIKE '''LEAD''%' THEN
    RAISE EXCEPTION 'sa310: the role of a responsible teacher does not default to LEAD';
  END IF;
END $$;

-- The foreign keys, with their columns, targets, ON DELETE and ON UPDATE
-- (a CASCADE, a SET NULL naming one column, or NO ACTION). A key on
-- studentGroupId would be a row more in the dialog that removes a class, and
-- is not there; no key at all points at StudentGroups.
DO $$
DECLARE
  bad text;
BEGIN
  WITH actual AS (
    SELECT (SELECT relname FROM pg_class WHERE oid = c.conrelid) AS tbl, c.conname,
           (SELECT relname FROM pg_class WHERE oid = c.confrelid) AS ref,
           (SELECT string_agg(a.attname::text, ',' ORDER BY k.ord) FROM unnest(c.conkey) WITH ORDINALITY k(attnum, ord)
              JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attnum) AS cols,
           (SELECT string_agg(a.attname::text, ',' ORDER BY k.ord) FROM unnest(c.confkey) WITH ORDINALITY k(attnum, ord)
              JOIN pg_attribute a ON a.attrelid = c.confrelid AND a.attnum = k.attnum) AS refcols,
           c.confdeltype::text AS del, c.confupdtype::text AS upd,
           (SELECT string_agg(a.attname::text, ',' ORDER BY a.attnum) FROM pg_attribute a
             WHERE a.attrelid = c.conrelid AND a.attnum = ANY (c.confdelsetcols)) AS setcols
      FROM pg_constraint c
     WHERE c.contype = 'f' AND c.conrelid IN ('public."ScheduleActivities"'::regclass, 'public."ScheduleActivityTeachers"'::regclass,
                                                'public."ScheduleActivityLessons"'::regclass)
  ), expected(tbl, conname, ref, cols, refcols, del, upd, setcols) AS (VALUES
    ('ScheduleActivities', 'ScheduleActivities_schoolId_fkey', 'Schools', 'schoolId', 'id', 'c', 'c', NULL),
    ('ScheduleActivities', 'ScheduleActivities_academicYearId_schoolId_fkey', 'AcademicYears', 'academicYearId,schoolId', 'id,schoolId', 'c', 'c', NULL),
    ('ScheduleActivities', 'ScheduleActivities_batchId_schoolId_fkey', 'CancellationBatches', 'batchId,schoolId', 'id,schoolId', 'c', 'c', NULL),
    ('ScheduleActivities', 'ScheduleActivities_replacementSubjectId_schoolId_fkey', 'Subjects', 'replacementSubjectId,schoolId', 'id,schoolId', 'c', 'c', NULL),
    ('ScheduleActivities', 'ScheduleActivities_createdByUserId_schoolId_fkey', 'Users', 'createdByUserId,schoolId', 'id,schoolId', 'n', 'a', 'createdByUserId'),
    ('ScheduleActivities', 'ScheduleActivities_removedByUserId_schoolId_fkey', 'Users', 'removedByUserId,schoolId', 'id,schoolId', 'n', 'a', 'removedByUserId'),
    ('ScheduleActivityTeachers', 'ScheduleActivityTeachers_activityId_schoolId_fkey', 'ScheduleActivities', 'activityId,schoolId', 'id,schoolId', 'c', 'c', NULL),
    ('ScheduleActivityTeachers', 'ScheduleActivityTeachers_teacherId_schoolId_fkey', 'Users', 'teacherId,schoolId', 'id,schoolId', 'c', 'a', NULL),
    ('ScheduleActivityLessons', 'ScheduleActivityLessons_activityId_schoolId_fkey', 'ScheduleActivities', 'activityId,schoolId', 'id,schoolId', 'c', 'c', NULL),
    ('ScheduleActivityLessons', 'ScheduleActivityLessons_calendarLessonId_schoolId_fkey', 'CalendarLessons', 'calendarLessonId,schoolId', 'id,schoolId', 'c', 'c', NULL))
  SELECT string_agg(format('%s: %s', coalesce(a.conname, e.conname),
                           CASE WHEN a.conname IS NULL THEN 'missing'
                                WHEN e.conname IS NULL THEN 'not expected'
                                ELSE format('%s(%s) -> %s(%s) ON DELETE %s%s ON UPDATE %s, expected %s(%s) -> %s(%s) ON DELETE %s%s ON UPDATE %s',
                                            a.tbl, a.cols, a.ref, a.refcols, a.del, coalesce(' (' || a.setcols || ')', ''), a.upd,
                                            e.tbl, e.cols, e.ref, e.refcols, e.del, coalesce(' (' || e.setcols || ')', ''), e.upd) END), '; ')
    INTO bad
    FROM actual a FULL JOIN expected e ON e.conname = a.conname
   WHERE (a.tbl, a.ref, a.cols, a.refcols, a.del, a.upd, a.setcols) IS DISTINCT FROM (e.tbl, e.ref, e.cols, e.refcols, e.del, e.upd, e.setcols);
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'sa310: foreign keys: %', bad; END IF;

  -- No key on a studentGroupId, and none to StudentGroups from these tables.
  SELECT string_agg(c.conname, ', ') INTO bad
    FROM pg_constraint c
   WHERE c.contype = 'f'
     AND c.conrelid IN ('public."ScheduleActivities"'::regclass, 'public."ScheduleActivityTeachers"'::regclass,
                        'public."ScheduleActivityLessons"'::regclass)
     AND (c.confrelid = 'public."StudentGroups"'::regclass
          OR EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
                        AND a.attname = 'studentGroupId'));
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'sa310: a key points at the class or sits on its column: %', bad; END IF;

  -- Nothing else points at these tables but their own children, and the exam
  -- an activity may carry (Provplanering, 20270127090000; section 420 holds
  -- that key's ON DELETE and ON UPDATE).
  SELECT string_agg(c.conname, ', ') INTO bad
    FROM pg_constraint c
   WHERE c.contype = 'f'
     AND c.confrelid IN ('public."ScheduleActivities"'::regclass, 'public."ScheduleActivityTeachers"'::regclass,
                         'public."ScheduleActivityLessons"'::regclass)
     AND c.conname NOT IN ('ScheduleActivityTeachers_activityId_schoolId_fkey', 'ScheduleActivityLessons_activityId_schoolId_fkey',
                           'Exams_activityId_schoolId_fkey');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'sa310: keys that point at an activity table: %', bad; END IF;
END $$;

-- The CHECKs (their behaviour is section 313's), and the validated state of
-- every constraint.
DO $$
DECLARE
  bad text;
BEGIN
  SELECT string_agg(format('%s: %s', coalesce(a.conname, e.conname),
                           CASE WHEN a.conname IS NULL THEN 'missing' WHEN e.conname IS NULL THEN 'not expected'
                                ELSE 'is ' || a.def END), '; ')
    INTO bad
    FROM (SELECT c.conname, (SELECT relname FROM pg_class WHERE oid = c.conrelid) AS tbl, pg_get_constraintdef(c.oid) AS def
            FROM pg_constraint c
           WHERE c.contype = 'c' AND c.conrelid IN ('public."ScheduleActivities"'::regclass, 'public."ScheduleActivityTeachers"'::regclass,
                                                    'public."ScheduleActivityLessons"'::regclass)) a
    FULL JOIN (VALUES
      ('ScheduleActivities_description_is_sane', 'ScheduleActivities',
         '^CHECK \(\(\(description IS NULL\) OR \(\(char_length\(btrim\(description\)\) >= 1\) AND \(char_length\(btrim\(description\)\) <= 300\)\)\)\)$'),
      ('ScheduleActivities_scope_ids_are_few', 'ScheduleActivities', '^CHECK \(\(cardinality\("scopeGroupIds"\) <= 200\)\)$'),
      ('ScheduleActivities_removal_is_recorded', 'ScheduleActivities',
         '^CHECK \(\(\("removedAt" IS NOT NULL\) OR \("removedByUserId" IS NULL\)\)\)$'),
      ('ScheduleActivityTeachers_role_is_responsible', 'ScheduleActivityTeachers',
         '^CHECK \(\(role = ANY \(ARRAY\[''LEAD''::"TeacherAssignmentRole", ''ASSISTANT''::"TeacherAssignmentRole"\]\)\)\)$')
    ) e(conname, tbl, pattern) ON e.conname = a.conname
   WHERE a.conname IS NULL OR e.conname IS NULL OR a.tbl <> e.tbl OR a.def !~ e.pattern;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'sa310: CHECKs: %', bad; END IF;

  SELECT string_agg(conname, ', ') INTO bad FROM pg_constraint
   WHERE conrelid IN ('public."ScheduleActivities"'::regclass, 'public."ScheduleActivityTeachers"'::regclass,
                      'public."ScheduleActivityLessons"'::regclass)
     AND (NOT convalidated OR condeferrable);
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'sa310: constraints that are NOT VALID or deferrable: %', bad; END IF;
END $$;

-- The primary keys and every unique index, exactly; and the indexes the
-- person keys and the lookups by class use, at least.
DO $$
DECLARE
  bad text;
  missing text;
BEGIN
  WITH actual AS (
    SELECT (SELECT relname FROM pg_class WHERE oid = i.indrelid) AS tbl, ic.relname AS idx, i.indisprimary AS pk, i.indisunique AS uniq,
           (SELECT string_agg(a.attname::text, ',' ORDER BY k.ord) FROM unnest(i.indkey::int2[]) WITH ORDINALITY k(attnum, ord)
              JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = k.attnum) AS cols,
           pg_get_expr(i.indpred, i.indrelid) AS pred
      FROM pg_index i JOIN pg_class ic ON ic.oid = i.indexrelid
     WHERE i.indrelid IN ('public."ScheduleActivities"'::regclass, 'public."ScheduleActivityTeachers"'::regclass,
                          'public."ScheduleActivityLessons"'::regclass)
  ), unique_expected(tbl, idx, pk, cols, pred) AS (VALUES
    ('ScheduleActivities', 'ScheduleActivities_pkey', true, 'id', NULL),
    ('ScheduleActivities', 'ScheduleActivities_id_schoolId_key', false, 'id,schoolId', NULL),
    ('ScheduleActivities', 'ScheduleActivities_batchId_key', false, 'batchId', NULL),
    ('ScheduleActivityTeachers', 'ScheduleActivityTeachers_pkey', true, 'activityId,studentGroupId,teacherId', NULL),
    ('ScheduleActivityTeachers', 'ScheduleActivityTeachers_one_lead_per_group', false, 'activityId,studentGroupId',
       '(role = ''LEAD''::"TeacherAssignmentRole")'),
    ('ScheduleActivityLessons', 'ScheduleActivityLessons_pkey', true, 'activityId,calendarLessonId', NULL),
    ('ScheduleActivityLessons', 'ScheduleActivityLessons_calendarLessonId_key', false, 'calendarLessonId', NULL),
    ('ScheduleActivityLessons', 'ScheduleActivityLessons_activityId_studentGroupId_date_key', false, 'activityId,studentGroupId,date', NULL)),
  plain_expected(tbl, idx, cols) AS (VALUES
    ('ScheduleActivities', 'ScheduleActivities_academicYearId_schoolId_idx', 'academicYearId,schoolId'),
    ('ScheduleActivities', 'ScheduleActivities_replacementSubjectId_schoolId_idx', 'replacementSubjectId,schoolId'),
    ('ScheduleActivities', 'ScheduleActivities_createdByUserId_schoolId_idx', 'createdByUserId,schoolId'),
    ('ScheduleActivities', 'ScheduleActivities_removedByUserId_schoolId_idx', 'removedByUserId,schoolId'),
    ('ScheduleActivityTeachers', 'ScheduleActivityTeachers_studentGroupId_schoolId_idx', 'studentGroupId,schoolId'),
    ('ScheduleActivityTeachers', 'ScheduleActivityTeachers_teacherId_schoolId_idx', 'teacherId,schoolId'),
    ('ScheduleActivityTeachers', 'ScheduleActivityTeachers_schoolId_idx', 'schoolId'),
    ('ScheduleActivityLessons', 'ScheduleActivityLessons_studentGroupId_schoolId_idx', 'studentGroupId,schoolId'),
    ('ScheduleActivityLessons', 'ScheduleActivityLessons_schoolId_idx', 'schoolId'))
  SELECT (SELECT string_agg(format('%s: %s', coalesce(a.idx, e.idx),
                                   CASE WHEN a.idx IS NULL THEN 'missing' WHEN e.idx IS NULL THEN 'not expected'
                                        ELSE format('%s(%s) WHERE %s, expected %s(%s) WHERE %s', a.tbl, a.cols, a.pred, e.tbl, e.cols, e.pred) END), '; ')
            FROM (SELECT * FROM actual WHERE uniq) a FULL JOIN unique_expected e ON e.idx = a.idx
           WHERE (a.tbl, a.pk, a.cols, a.pred) IS DISTINCT FROM (e.tbl, e.pk, e.cols, e.pred)),
         (SELECT string_agg(e.idx, ', ')
            FROM plain_expected e LEFT JOIN actual a ON a.idx = e.idx AND a.tbl = e.tbl AND a.cols = e.cols AND NOT a.uniq AND a.pred IS NULL
           WHERE a.idx IS NULL)
    INTO bad, missing;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'sa310: unique indexes: %', bad; END IF;
  bad := missing;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'sa310: lookup indexes that are missing or changed: %', bad; END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 311: en schemabrytande aktivitet, vem som läser och skriver
-- (ScheduleActivities, ScheduleActivityTeachers, ScheduleActivityLessons,
-- 20270101090000).
--
-- Each table has a staff arm (an administrator and a teacher read the
-- school's rows) and three administrator arms that ask the area DRIFT
-- (section 310 holds the catalogue). In the matrix school, whose
-- administrators the fixtures give one of each profile, with and without
-- HR-läs, every one of the eight (the full administrator, the rektor, the
-- two schemaläggare, the two expeditioner and the two läsare) is held to the
-- profile's own answer, app.admin_profile_writes(profile) containing DRIFT,
-- and to the brief's: all but the läsare write it.
--   * a profile that writes DRIFT inserts an activity on an avbokning of its
--     own, a responsible teacher and a replacement lesson on it, updates
--     each of the three, and deletes each (one row every time);
--   * a läsare reads the target activity's rows, and is refused every INSERT
--     and every UPDATE by the arm's WITH CHECK (insufficient_privilege, "row-
--     level security"), since the update arm's USING admits every
--     administrator (a row lock needs it); a DELETE finds no row, since the
--     delete arm asks the area in USING. Nothing of the target moves;
--   * a teacher reads all three tables and is refused every INSERT; an UPDATE
--     and a DELETE reach no row. A pupil and a guardian read no row, are
--     refused every INSERT, and their UPDATE and DELETE reach no row;
--   * PostgREST's role (authenticated) holds no grant on the tables, so it is
--     refused every command by a missing privilege, not by row security,
--     whoever it carries the token of; with no principal at all, and with the
--     GUCs of the service and sync paths set, the API's role reads nothing
--     (no arm is TO public).
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
DO $$
DECLARE
  school uuid := app.current_school_id();
  y uuid;
  grp uuid;
  t1 uuid;
  t2 uuid;
  subj uuid;
  b uuid;
  target uuid;
  les uuid;
  who text;
  spare_batch uuid;
  spare_lesson uuid;
  spares jsonb := '{}';
BEGIN
  IF (SELECT slug FROM "Schools" WHERE id = school) IS DISTINCT FROM 'rls-roller-school'
     OR NOT app.current_user_may('DRIFT', true) THEN
    RAISE EXCEPTION 'sa311: expected the matrix school''s full administrator';
  END IF;
  SELECT id INTO y FROM "AcademicYears" WHERE "schoolId" = school AND "isActive";
  SELECT id INTO grp FROM "StudentGroups" WHERE "schoolId" = school AND name = 'Roller 7A';
  SELECT id INTO t1 FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000111';
  IF y IS NULL OR grp IS NULL OR t1 IS NULL THEN
    RAISE EXCEPTION 'sa311: the matrix school lacks its year, its class or its teacher; fixtures did not run';
  END IF;
  INSERT INTO "Subjects" ("schoolId", name, code, "updatedAt") VALUES (school, 'sa311 ersättningsämne', 'SA311', now()) RETURNING id INTO subj;
  INSERT INTO "Users" ("schoolId", email, "firstName", "lastName", role, "authId", "isActive", "updatedAt")
  VALUES (school, 'sa311-lararen@example.invalid', 'Sa', 'Tvåan', 'TEACHER', gen_random_uuid(), true, now())
  RETURNING id INTO t2;

  -- The target every refused statement below is aimed at: an activity on an
  -- avbokning of its own, a lead, and a replacement lesson.
  INSERT INTO "CancellationBatches" ("schoolId", "academicYearId", name, cause, "fromDate", "toDate", scope)
  VALUES (school, y, 'sa311 mål', 'EVENT', '2030-10-07', '2030-10-07', 'SCHOOL') RETURNING id INTO b;
  INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", description, "scopeGroupIds")
  VALUES (school, y, b, subj, 'sa311 mål', ARRAY[grp]) RETURNING id INTO target;
  INSERT INTO "ScheduleActivityTeachers" ("activityId", "studentGroupId", "teacherId", "schoolId", role)
  VALUES (target, grp, t1, school, 'LEAD');
  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", "updatedAt")
  VALUES (school, subj, grp, '2030-10-07', '2030-10-07 09:00+00', '2030-10-07 10:00+00', now()) RETURNING id INTO les;
  INSERT INTO "ScheduleActivityLessons" ("activityId", "calendarLessonId", "studentGroupId", date, "schoolId")
  VALUES (target, les, grp, '2030-10-07', school);

  -- A spare avbokning and a spare lesson for each principal below, planted by
  -- the full administrator, so that what a principal meets is the arms' and
  -- nothing else's (a pupil cannot read an avbokning, a läsare cannot make one).
  FOREACH who IN ARRAY ARRAY[
    '00000000-0000-4000-8000-000000000105', '00000000-0000-4000-8000-000000000106', '00000000-0000-4000-8000-000000000107',
    '00000000-0000-4000-8000-000000000108', '00000000-0000-4000-8000-000000000109', '00000000-0000-4000-8000-000000000110',
    '00000000-0000-4000-8000-000000000115', '00000000-0000-4000-8000-000000000116', '00000000-0000-4000-8000-000000000111',
    '00000000-0000-4000-8000-000000000112', '00000000-0000-4000-8000-000000000113'] LOOP
    INSERT INTO "CancellationBatches" ("schoolId", "academicYearId", name, cause, "fromDate", "toDate", scope)
    VALUES (school, y, 'sa311 ' || who, 'EVENT', '2030-10-08', '2030-10-08', 'SCHOOL') RETURNING id INTO spare_batch;
    INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", note, "updatedAt")
    VALUES (school, subj, grp, '2030-10-08', '2030-10-08 09:00+00', '2030-10-08 10:00+00', 'sa311 ' || who, now())
    RETURNING id INTO spare_lesson;
    spares := spares || jsonb_build_object(who, jsonb_build_object('batch', spare_batch, 'lesson', spare_lesson));
  END LOOP;

  PERFORM set_config('app.test_rls311_spares', spares::text, true);
  PERFORM set_config('app.test_rls311_ids', jsonb_build_object('school', school, 'year', y, 'group', grp, 'subject', subj,
                                                               'teacher2', t2, 'target', target)::text, true);
  -- What the whole of each table holds for the school, as the full
  -- administrator reads it: the fixtures' row, the target, and nothing else.
  PERFORM set_config('app.test_rls311_counts', jsonb_build_object(
    'activities', (SELECT count(*) FROM "ScheduleActivities"),
    'teachers', (SELECT count(*) FROM "ScheduleActivityTeachers"),
    'lessons', (SELECT count(*) FROM "ScheduleActivityLessons"))::text, true);
  IF (SELECT count(*) FROM "ScheduleActivities") <> 2 OR (SELECT count(*) FROM "ScheduleActivityTeachers") <> 2
     OR (SELECT count(*) FROM "ScheduleActivityLessons") <> 2 THEN
    RAISE EXCEPTION 'sa311: the matrix school holds % / % / % rows of the activity tables, expected the fixtures'' one and the target',
      (SELECT count(*) FROM "ScheduleActivities"), (SELECT count(*) FROM "ScheduleActivityTeachers"),
      (SELECT count(*) FROM "ScheduleActivityLessons");
  END IF;
END $$;

-- The eight administrators.
DO $$
DECLARE
  principals constant text[][] := ARRAY[
    ['00000000-0000-4000-8000-000000000105', 'FULL'],
    ['00000000-0000-4000-8000-000000000106', 'REKTOR'],
    ['00000000-0000-4000-8000-000000000107', 'SCHEMALAGGARE'],
    ['00000000-0000-4000-8000-000000000108', 'EXPEDITION'],
    ['00000000-0000-4000-8000-000000000109', 'SCHEMALAGGARE'],
    ['00000000-0000-4000-8000-000000000110', 'EXPEDITION'],
    ['00000000-0000-4000-8000-000000000115', 'LASARE'],
    ['00000000-0000-4000-8000-000000000116', 'LASARE']];
  -- By step, what a profile that does not write DRIFT meets.
  refusals constant text[] := ARRAY['refused', 'refused', 'refused', 'refused', 'refused', 'refused', 'none', 'none', 'none'];
  labels constant text[] := ARRAY['INSERT activity', 'INSERT teacher', 'INSERT lesson', 'UPDATE activity', 'UPDATE teacher',
                                  'UPDATE lesson', 'DELETE lesson', 'DELETE teacher', 'DELETE activity'];
  ids jsonb := current_setting('app.test_rls311_ids')::jsonb;
  spares jsonb := current_setting('app.test_rls311_spares')::jsonb;
  school uuid := (ids ->> 'school')::uuid;
  y uuid := (ids ->> 'year')::uuid;
  grp uuid := (ids ->> 'group')::uuid;
  subj uuid := (ids ->> 'subject')::uuid;
  t2 uuid := (ids ->> 'teacher2')::uuid;
  target uuid := (ids ->> 'target')::uuid;
  i integer;
  step integer;
  profile text;
  writes boolean;
  own uuid;
  parent uuid;
  stmt text;
  n bigint;
  msg text;
  st text;
  outcome text;
  expected text;
  seen bigint;
  wrong text[] := '{}';
BEGIN
  FOR i IN 1 .. array_length(principals, 1) LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', principals[i][1])::text, true);
    SELECT u."adminProfile"::text INTO profile FROM "Users" u WHERE u.id = app.current_user_id();
    IF app.current_user_role() IS DISTINCT FROM 'SCHOOL_ADMIN' OR app.current_school_id() IS DISTINCT FROM school
       OR profile IS DISTINCT FROM principals[i][2] THEN
      RAISE EXCEPTION 'sa311: % resolved as % % in %, expected % in the matrix school', principals[i][1],
        app.current_user_role(), profile, app.current_school_id(), principals[i][2];
    END IF;
    -- The profile's own answer, and the brief's: all but the läsare write DRIFT.
    writes := 'DRIFT' = ANY (app.admin_profile_writes(profile::"AdminProfile"));
    IF writes IS DISTINCT FROM (profile <> 'LASARE') OR app.current_user_may('DRIFT', true) IS DISTINCT FROM writes THEN
      RAISE EXCEPTION 'sa311: % (%) writes DRIFT: % by the profile, % by the session', principals[i][1], profile, writes,
        app.current_user_may('DRIFT', true);
    END IF;

    own := NULL;
    FOR step IN 1 .. 9 LOOP
      parent := coalesce(own, target);
      stmt := CASE step
        WHEN 1 THEN format($q$INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", description, "scopeGroupIds")
                              VALUES (%L, %L, %L, %L, %L, ARRAY[%L]::uuid[]) RETURNING id$q$,
                           school, y, (spares -> principals[i][1] ->> 'batch')::uuid, subj, 'sa311 ' || principals[i][2], grp)
        WHEN 2 THEN format($q$INSERT INTO "ScheduleActivityTeachers" ("activityId", "studentGroupId", "teacherId", "schoolId", role)
                              VALUES (%L, %L, %L, %L, 'ASSISTANT')$q$, parent, grp, t2, school)
        WHEN 3 THEN format($q$INSERT INTO "ScheduleActivityLessons" ("activityId", "calendarLessonId", "studentGroupId", date, "schoolId")
                              VALUES (%L, %L, %L, '2030-10-08', %L)$q$,
                           parent, (spares -> principals[i][1] ->> 'lesson')::uuid, grp, school)
        WHEN 4 THEN format($q$UPDATE "ScheduleActivities" SET description = %L WHERE id = %L$q$, 'sa311 ändrad av ' || principals[i][2], parent)
        WHEN 5 THEN format($q$UPDATE "ScheduleActivityTeachers" SET role = 'ASSISTANT' WHERE "activityId" = %L$q$, parent)
        WHEN 6 THEN format($q$UPDATE "ScheduleActivityLessons" SET date = date + 1 WHERE "activityId" = %L$q$, parent)
        WHEN 7 THEN format($q$DELETE FROM "ScheduleActivityLessons" WHERE "activityId" = %L$q$, parent)
        WHEN 8 THEN format($q$DELETE FROM "ScheduleActivityTeachers" WHERE "activityId" = %L$q$, parent)
        ELSE format($q$DELETE FROM "ScheduleActivities" WHERE id = %L$q$, parent)
      END;
      outcome := NULL;
      BEGIN
        IF step = 1 THEN EXECUTE stmt INTO own; ELSE EXECUTE stmt; END IF;
        GET DIAGNOSTICS n = ROW_COUNT;
        outcome := CASE WHEN n = 0 THEN 'none' WHEN n = 1 THEN 'admitted' ELSE n || ' rows' END;
      EXCEPTION
        WHEN insufficient_privilege THEN
          GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
          outcome := CASE WHEN msg LIKE '%row-level security%' THEN 'refused' ELSE 'denied' END;
        WHEN OTHERS THEN
          GET STACKED DIAGNOSTICS st = RETURNED_SQLSTATE, msg = MESSAGE_TEXT;
          outcome := 'error ' || st || ' ' || left(msg, 100);
      END;
      expected := CASE WHEN writes THEN 'admitted' ELSE refusals[step] END;
      IF outcome IS DISTINCT FROM expected THEN
        wrong := wrong || format('%s (%s) met %s on %s, expected %s', principals[i][1], principals[i][2], outcome, labels[step], expected);
      END IF;
    END LOOP;
    IF writes IS DISTINCT FROM (own IS NOT NULL) THEN
      wrong := wrong || format('%s (%s): the activity it inserted %s', principals[i][1], principals[i][2],
                               CASE WHEN own IS NULL THEN 'was not returned' ELSE 'exists although it was refused' END);
    END IF;

    -- Every administrator reads the target's rows, as the full one does.
    SELECT (SELECT count(*) FROM "ScheduleActivities" WHERE id = target)
         + (SELECT count(*) FROM "ScheduleActivityTeachers" WHERE "activityId" = target)
         + (SELECT count(*) FROM "ScheduleActivityLessons" WHERE "activityId" = target) INTO seen;
    IF seen <> 3 THEN
      wrong := wrong || format('%s (%s) reads %s of the target''s 3 rows', principals[i][1], principals[i][2], seen);
    END IF;
  END LOOP;
  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'sa311: %', array_to_string(wrong, '; ');
  END IF;
END $$;

-- Nothing of the target moved, and every row a writer made is gone again.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
DO $$
DECLARE
  target uuid := (current_setting('app.test_rls311_ids')::jsonb ->> 'target')::uuid;
  counts jsonb := current_setting('app.test_rls311_counts')::jsonb;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM "ScheduleActivities" WHERE id = target AND description = 'sa311 mål' AND "removedAt" IS NULL)
     OR NOT EXISTS (SELECT 1 FROM "ScheduleActivityTeachers" WHERE "activityId" = target AND role = 'LEAD')
     OR NOT EXISTS (SELECT 1 FROM "ScheduleActivityLessons" WHERE "activityId" = target AND date = '2030-10-07') THEN
    RAISE EXCEPTION 'sa311: a refused statement moved the target';
  END IF;
  IF (SELECT count(*) FROM "ScheduleActivities") <> (counts ->> 'activities')::bigint
     OR (SELECT count(*) FROM "ScheduleActivityTeachers") <> (counts ->> 'teachers')::bigint
     OR (SELECT count(*) FROM "ScheduleActivityLessons") <> (counts ->> 'lessons')::bigint THEN
    RAISE EXCEPTION 'sa311: the tables hold rows nobody should have left behind';
  END IF;
END $$;

-- A teacher reads, and writes nothing. A pupil and a guardian read nothing.
DO $$
DECLARE
  principals constant text[][] := ARRAY[
    ['00000000-0000-4000-8000-000000000111', 'TEACHER'],
    ['00000000-0000-4000-8000-000000000112', 'STUDENT'],
    ['00000000-0000-4000-8000-000000000113', 'GUARDIAN']];
  refusals constant text[] := ARRAY['refused', 'refused', 'refused', 'none', 'none', 'none', 'none', 'none', 'none'];
  labels constant text[] := ARRAY['INSERT activity', 'INSERT teacher', 'INSERT lesson', 'UPDATE activity', 'UPDATE teacher',
                                  'UPDATE lesson', 'DELETE lesson', 'DELETE teacher', 'DELETE activity'];
  ids jsonb := current_setting('app.test_rls311_ids')::jsonb;
  spares jsonb := current_setting('app.test_rls311_spares')::jsonb;
  counts jsonb := current_setting('app.test_rls311_counts')::jsonb;
  school uuid := (ids ->> 'school')::uuid;
  y uuid := (ids ->> 'year')::uuid;
  grp uuid := (ids ->> 'group')::uuid;
  subj uuid := (ids ->> 'subject')::uuid;
  t2 uuid := (ids ->> 'teacher2')::uuid;
  target uuid := (ids ->> 'target')::uuid;
  i integer;
  step integer;
  stmt text;
  n bigint;
  msg text;
  st text;
  outcome text;
  expected_rows bigint;
  seen bigint;
  wrong text[] := '{}';
BEGIN
  FOR i IN 1 .. array_length(principals, 1) LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', principals[i][1])::text, true);
    IF app.current_user_role()::text IS DISTINCT FROM principals[i][2] OR app.current_school_id() IS DISTINCT FROM school THEN
      RAISE EXCEPTION 'sa311: % resolved as % in %, expected % in the matrix school', principals[i][1],
        app.current_user_role(), app.current_school_id(), principals[i][2];
    END IF;

    -- A teacher reads every row the full administrator does; the others none.
    SELECT (SELECT count(*) FROM "ScheduleActivities"), (SELECT count(*) FROM "ScheduleActivityTeachers"),
           (SELECT count(*) FROM "ScheduleActivityLessons") INTO n, seen, expected_rows;
    IF principals[i][2] = 'TEACHER' THEN
      IF n <> (counts ->> 'activities')::bigint OR seen <> (counts ->> 'teachers')::bigint OR expected_rows <> (counts ->> 'lessons')::bigint THEN
        wrong := wrong || format('a teacher reads %s / %s / %s rows, expected %s / %s / %s', n, seen, expected_rows,
                                 counts ->> 'activities', counts ->> 'teachers', counts ->> 'lessons');
      END IF;
      IF (SELECT count(*) FROM "ScheduleActivities" WHERE id = target AND description = 'sa311 mål')
         + (SELECT count(*) FROM "ScheduleActivityTeachers" WHERE "activityId" = target)
         + (SELECT count(*) FROM "ScheduleActivityLessons" WHERE "activityId" = target) <> 3 THEN
        wrong := wrong || 'a teacher does not read the target''s three rows';
      END IF;
    ELSIF n + seen + expected_rows <> 0 THEN
      wrong := wrong || format('%s reads %s / %s / %s rows', principals[i][2], n, seen, expected_rows);
    END IF;

    FOR step IN 1 .. 9 LOOP
      stmt := CASE step
        WHEN 1 THEN format($q$INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", description, "scopeGroupIds")
                              VALUES (%L, %L, %L, %L, %L, ARRAY[%L]::uuid[])$q$,
                           school, y, (spares -> principals[i][1] ->> 'batch')::uuid, subj, 'sa311 ' || principals[i][2], grp)
        WHEN 2 THEN format($q$INSERT INTO "ScheduleActivityTeachers" ("activityId", "studentGroupId", "teacherId", "schoolId", role)
                              VALUES (%L, %L, %L, %L, 'ASSISTANT')$q$, target, grp, t2, school)
        WHEN 3 THEN format($q$INSERT INTO "ScheduleActivityLessons" ("activityId", "calendarLessonId", "studentGroupId", date, "schoolId")
                              VALUES (%L, %L, %L, '2030-10-08', %L)$q$,
                           target, (spares -> principals[i][1] ->> 'lesson')::uuid, grp, school)
        WHEN 4 THEN format($q$UPDATE "ScheduleActivities" SET description = %L WHERE id = %L$q$, 'sa311 ändrad av ' || principals[i][2], target)
        WHEN 5 THEN format($q$UPDATE "ScheduleActivityTeachers" SET role = 'ASSISTANT' WHERE "activityId" = %L$q$, target)
        WHEN 6 THEN format($q$UPDATE "ScheduleActivityLessons" SET date = date + 1 WHERE "activityId" = %L$q$, target)
        WHEN 7 THEN format($q$DELETE FROM "ScheduleActivityLessons" WHERE "activityId" = %L$q$, target)
        WHEN 8 THEN format($q$DELETE FROM "ScheduleActivityTeachers" WHERE "activityId" = %L$q$, target)
        ELSE format($q$DELETE FROM "ScheduleActivities" WHERE id = %L$q$, target)
      END;
      outcome := NULL;
      BEGIN
        EXECUTE stmt;
        GET DIAGNOSTICS n = ROW_COUNT;
        outcome := CASE WHEN n = 0 THEN 'none' WHEN n = 1 THEN 'admitted' ELSE n || ' rows' END;
      EXCEPTION
        WHEN insufficient_privilege THEN
          GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
          outcome := CASE WHEN msg LIKE '%row-level security%' THEN 'refused' ELSE 'denied' END;
        WHEN OTHERS THEN
          GET STACKED DIAGNOSTICS st = RETURNED_SQLSTATE, msg = MESSAGE_TEXT;
          outcome := 'error ' || st || ' ' || left(msg, 100);
      END;
      IF outcome IS DISTINCT FROM refusals[step] THEN
        wrong := wrong || format('%s met %s on %s, expected %s', principals[i][2], outcome, labels[step], refusals[step]);
      END IF;
    END LOOP;
  END LOOP;
  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'sa311: %', array_to_string(wrong, '; ');
  END IF;
END $$;

-- PostgREST's role holds no grant: every command meets a missing privilege,
-- not row security, whether the token is an administrator's or a teacher's.
DO $$
DECLARE
  school uuid := (current_setting('app.test_rls311_ids')::jsonb ->> 'school')::uuid;
  sub text;
  tbl text;
  cmd text;
  n bigint;
  msg text;
  st text;
  outcome text;
  wrong text[] := '{}';
BEGIN
  FOREACH sub IN ARRAY ARRAY['00000000-0000-4000-8000-000000000105', '00000000-0000-4000-8000-000000000111'] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', sub)::text, true);
    EXECUTE 'SET LOCAL ROLE authenticated';
    IF current_user <> 'authenticated' OR app.current_school_id() IS DISTINCT FROM school THEN
      RAISE EXCEPTION 'sa311: expected to be authenticated in the matrix school, am % in %', current_user, app.current_school_id();
    END IF;
    FOREACH tbl IN ARRAY ARRAY['ScheduleActivities', 'ScheduleActivityTeachers', 'ScheduleActivityLessons'] LOOP
      FOREACH cmd IN ARRAY ARRAY['SELECT', 'INSERT', 'UPDATE', 'DELETE'] LOOP
        outcome := NULL;
        BEGIN
          IF cmd = 'SELECT' THEN EXECUTE format('SELECT count(*) FROM %I', tbl);
          ELSIF cmd = 'INSERT' THEN EXECUTE format('INSERT INTO %I ("schoolId") VALUES (%L)', tbl, school);
          ELSIF cmd = 'UPDATE' THEN EXECUTE format('UPDATE %I SET "schoolId" = "schoolId"', tbl);
          ELSE EXECUTE format('DELETE FROM %I', tbl);
          END IF;
          GET DIAGNOSTICS n = ROW_COUNT;
          outcome := 'ran';
        EXCEPTION
          WHEN insufficient_privilege THEN
            GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
            outcome := CASE WHEN msg LIKE '%row-level security%' THEN 'refused' ELSE 'denied' END;
          WHEN OTHERS THEN
            GET STACKED DIAGNOSTICS st = RETURNED_SQLSTATE, msg = MESSAGE_TEXT;
            outcome := 'error ' || st || ' ' || left(msg, 100);
        END;
        IF outcome <> 'denied' THEN
          wrong := wrong || format('%s as authenticated met %s on %s, expected a missing privilege', cmd, outcome, tbl);
        END IF;
      END LOOP;
    END LOOP;
    EXECUTE 'SET LOCAL ROLE app_authenticated';
  END LOOP;
  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'sa311: %', array_to_string(wrong, '; ');
  END IF;
END $$;

-- With no principal, and with the service and sync paths' GUCs set (which
-- admit a row of a table with a TO public arm), the API's role reads none of
-- it and is refused an INSERT.
SELECT set_config('request.jwt.claims', '', true);
SELECT set_config('app.service_school_id', (current_setting('app.test_rls311_ids')::jsonb ->> 'school'), true);
SELECT set_config('app.sync_school_id', (current_setting('app.test_rls311_ids')::jsonb ->> 'school'), true);
SELECT set_config('app.service_key_lookup', 'on', true);
DO $$
DECLARE
  ids jsonb := current_setting('app.test_rls311_ids')::jsonb;
  n bigint;
BEGIN
  IF app.current_user_id() IS NOT NULL THEN
    RAISE EXCEPTION 'sa311: expected no principal';
  END IF;
  SELECT (SELECT count(*) FROM "ScheduleActivities") + (SELECT count(*) FROM "ScheduleActivityTeachers")
       + (SELECT count(*) FROM "ScheduleActivityLessons") INTO n;
  IF n <> 0 THEN RAISE EXCEPTION 'sa311: % row(s) read with no principal', n; END IF;
  BEGIN
    INSERT INTO "ScheduleActivityTeachers" ("activityId", "studentGroupId", "teacherId", "schoolId")
    VALUES ((ids ->> 'target')::uuid, (ids ->> 'group')::uuid, (ids ->> 'teacher2')::uuid, (ids ->> 'school')::uuid);
    RAISE EXCEPTION 'sa311: a row was written with no principal';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 312: en schemabrytande aktivitet, skolgränsen (ScheduleActivities,
-- ScheduleActivityTeachers, ScheduleActivityLessons, 20270101090000).
--
-- Two schools, each with an activity of its own: an avbokning, a replacement
-- subject, a responsible teacher and a replacement lesson, planted by its own
-- administrator. Then, for the administrator of either school against the
-- other's rows:
--   * the other school's activity, teacher row and lesson mark are not read
--     (no row of the other school at all), and an UPDATE or a DELETE of them
--     reaches no row;
--   * a row written with the other school's schoolId is refused by the arm's
--     WITH CHECK (insufficient_privilege, "row-level security"), though
--     everything else about it is valid for that school, and so is moving
--     the administrator's own row to it by an UPDATE;
--   * a row of the administrator's own school cannot point across the
--     boundary: the composite keys (id, schoolId) refuse an avbokning, a
--     year, a subject, a teacher, an activity, a lesson or a person that
--     belongs to the other school (foreign_key_violation), on an INSERT and
--     on an UPDATE, with the same statements admitted when they name the
--     administrator's own school's rows (so the refusal is the key's);
--   * a teacher reads its own school's activity and none of the other's, and
--     a pupil of the other school reads nothing of either.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('app.test_rls312_admin_a', :'admin_auth_id', true);
DO $$
DECLARE
  admins constant text[] := ARRAY['00000000-0000-4000-8000-000000000006', current_setting('app.test_rls312_admin_a')];
  sub text;
  school uuid;
  side text;
  y uuid;
  grp uuid;
  teacher uuid;
  teacher_auth text;
  subj uuid;
  b uuid;
  spare uuid;
  control uuid;
  les uuid;
  spare_les uuid;
  control_les uuid;
  extra uuid;
  extra_les uuid;
  act uuid;
  sides jsonb := '{}';
BEGIN
  FOREACH sub IN ARRAY admins LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', sub)::text, true);
    school := app.current_school_id();
    IF app.current_user_role() IS DISTINCT FROM 'SCHOOL_ADMIN' OR NOT app.current_user_may('DRIFT', true) THEN
      RAISE EXCEPTION 'sa312: % is not an administrator who writes DRIFT', sub;
    END IF;
    side := CASE WHEN (SELECT slug FROM "Schools" WHERE id = school) = 'rls-fixture-school' THEN 'b' ELSE 'a' END;
    SELECT id INTO y FROM "AcademicYears" WHERE "schoolId" = school ORDER BY "isActive" DESC, "startDate" LIMIT 1;
    SELECT id INTO grp FROM "StudentGroups" WHERE "schoolId" = school AND "academicYearId" = y ORDER BY id LIMIT 1;
    IF side = 'b' THEN
      SELECT id, "authId"::text INTO teacher, teacher_auth FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000001';
    ELSE
      SELECT id, "authId"::text INTO teacher, teacher_auth FROM "Users"
       WHERE "schoolId" = school AND role = 'TEACHER' AND "isActive" ORDER BY "authId" LIMIT 1;
    END IF;
    IF y IS NULL OR grp IS NULL OR teacher IS NULL THEN
      RAISE EXCEPTION 'sa312: school % lacks a year, a class or a teacher to plant on; fixtures did not run', side;
    END IF;
    INSERT INTO "Subjects" ("schoolId", name, code, "updatedAt") VALUES (school, 'sa312 ersättningsämne ' || side, 'SA312' || upper(side), now())
    RETURNING id INTO subj;
    -- Four avbokningar (the activity's; a spare for the statements that must
    -- be refused; one for a second activity and one to move the first onto,
    -- both for statements that must be admitted) and four lessons.
    INSERT INTO "CancellationBatches" ("schoolId", "academicYearId", name, cause, "fromDate", "toDate", scope)
    SELECT school, y, 'sa312 ' || side || ' ' || n, 'EVENT', '2030-10-07', '2030-10-07', 'SCHOOL' FROM generate_series(1, 4) n;
    SELECT id INTO b FROM "CancellationBatches" WHERE "schoolId" = school AND name = 'sa312 ' || side || ' 1';
    SELECT id INTO spare FROM "CancellationBatches" WHERE "schoolId" = school AND name = 'sa312 ' || side || ' 2';
    SELECT id INTO control FROM "CancellationBatches" WHERE "schoolId" = school AND name = 'sa312 ' || side || ' 3';
    SELECT id INTO extra FROM "CancellationBatches" WHERE "schoolId" = school AND name = 'sa312 ' || side || ' 4';
    INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", note, "updatedAt")
    SELECT school, subj, grp, '2030-10-07', '2030-10-07 09:00+00', '2030-10-07 10:00+00', 'sa312 ' || side || ' ' || n, now()
      FROM generate_series(1, 4) n;
    SELECT id INTO les FROM "CalendarLessons" WHERE "schoolId" = school AND note = 'sa312 ' || side || ' 1';
    SELECT id INTO spare_les FROM "CalendarLessons" WHERE "schoolId" = school AND note = 'sa312 ' || side || ' 2';
    SELECT id INTO control_les FROM "CalendarLessons" WHERE "schoolId" = school AND note = 'sa312 ' || side || ' 3';
    SELECT id INTO extra_les FROM "CalendarLessons" WHERE "schoolId" = school AND note = 'sa312 ' || side || ' 4';

    INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", description, "scopeGroupIds")
    VALUES (school, y, b, subj, 'sa312 ' || side, ARRAY[grp]) RETURNING id INTO act;
    INSERT INTO "ScheduleActivityTeachers" ("activityId", "studentGroupId", "teacherId", "schoolId", role)
    VALUES (act, grp, teacher, school, 'LEAD');
    INSERT INTO "ScheduleActivityLessons" ("activityId", "calendarLessonId", "studentGroupId", date, "schoolId")
    VALUES (act, les, grp, '2030-10-07', school);

    sides := sides || jsonb_build_object(side, jsonb_build_object('school', school, 'year', y, 'group', grp, 'teacher', teacher,
      'teacherAuth', teacher_auth, 'subject', subj, 'batch', b, 'spare', spare, 'control', control, 'lesson', les,
      'spareLesson', spare_les, 'controlLesson', control_les, 'extra', extra, 'extraLesson', extra_les,
      'activity', act, 'admin', sub));
  END LOOP;
  IF (sides -> 'a' ->> 'school') = (sides -> 'b' ->> 'school') THEN
    RAISE EXCEPTION 'sa312: both administrators are in the same school';
  END IF;
  PERFORM set_config('app.test_rls312_sides', sides::text, true);
END $$;

-- Each administrator against the other school's rows.
DO $$
DECLARE
  sides jsonb := current_setting('app.test_rls312_sides')::jsonb;
  mine_key text;
  m jsonb;
  o jsonb;
  c record;
  n bigint;
  msg text;
  st text;
  outcome text;
  seen bigint;
  total bigint;
  wrong text[] := '{}';
BEGIN
  FOREACH mine_key IN ARRAY ARRAY['a', 'b'] LOOP
    m := sides -> mine_key;
    o := sides -> CASE mine_key WHEN 'a' THEN 'b' ELSE 'a' END;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', m ->> 'admin')::text, true);
    IF app.current_school_id() IS DISTINCT FROM (m ->> 'school')::uuid THEN
      RAISE EXCEPTION 'sa312: the administrator of school % resolved in %', mine_key, app.current_school_id();
    END IF;

    -- Reading: the administrator's own rows, none of the other school's.
    SELECT (SELECT count(*) FROM "ScheduleActivities" WHERE id = (m ->> 'activity')::uuid)
         + (SELECT count(*) FROM "ScheduleActivityTeachers" WHERE "activityId" = (m ->> 'activity')::uuid)
         + (SELECT count(*) FROM "ScheduleActivityLessons" WHERE "activityId" = (m ->> 'activity')::uuid) INTO seen;
    IF seen <> 3 THEN wrong := wrong || format('school %s''s administrator reads %s of its own 3 rows', mine_key, seen); END IF;
    SELECT (SELECT count(*) FROM "ScheduleActivities" WHERE id = (o ->> 'activity')::uuid OR "schoolId" = (o ->> 'school')::uuid)
         + (SELECT count(*) FROM "ScheduleActivityTeachers" WHERE "activityId" = (o ->> 'activity')::uuid OR "schoolId" = (o ->> 'school')::uuid)
         + (SELECT count(*) FROM "ScheduleActivityLessons" WHERE "activityId" = (o ->> 'activity')::uuid OR "schoolId" = (o ->> 'school')::uuid)
         INTO seen;
    IF seen <> 0 THEN wrong := wrong || format('school %s''s administrator reads %s row(s) of school %s',
                                               mine_key, seen, CASE mine_key WHEN 'a' THEN 'b' ELSE 'a' END); END IF;
    SELECT (SELECT count(*) FROM "ScheduleActivities") + (SELECT count(*) FROM "ScheduleActivityTeachers")
         + (SELECT count(*) FROM "ScheduleActivityLessons") INTO total;
    SELECT (SELECT count(*) FROM "ScheduleActivities" WHERE "schoolId" = (m ->> 'school')::uuid)
         + (SELECT count(*) FROM "ScheduleActivityTeachers" WHERE "schoolId" = (m ->> 'school')::uuid)
         + (SELECT count(*) FROM "ScheduleActivityLessons" WHERE "schoolId" = (m ->> 'school')::uuid) INTO seen;
    IF total <> seen THEN wrong := wrong || format('school %s''s administrator reads %s rows, %s of them its own', mine_key, total, seen); END IF;

    FOR c IN SELECT * FROM (VALUES
      -- The other school's rows, written to, changed or removed.
      (1, 'INSERT activity with the other school''s schoolId', 'refused',
         format($q$INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", description)
                   VALUES (%L, %L, %L, %L, 'sa312 intrång')$q$, o ->> 'school', o ->> 'year', o ->> 'spare', o ->> 'subject')),
      (2, 'INSERT teacher with the other school''s schoolId', 'refused',
         format($q$INSERT INTO "ScheduleActivityTeachers" ("activityId", "studentGroupId", "teacherId", "schoolId", role)
                   VALUES (%L, %L, %L, %L, 'ASSISTANT')$q$, o ->> 'activity', o ->> 'group', o ->> 'teacher', o ->> 'school')),
      (3, 'INSERT lesson with the other school''s schoolId', 'refused',
         format($q$INSERT INTO "ScheduleActivityLessons" ("activityId", "calendarLessonId", "studentGroupId", date, "schoolId")
                   VALUES (%L, %L, %L, '2030-10-07', %L)$q$, o ->> 'activity', o ->> 'spareLesson', o ->> 'group', o ->> 'school')),
      (4, 'UPDATE the other school''s activity', 'none',
         format($q$UPDATE "ScheduleActivities" SET description = 'sa312 intrång' WHERE id = %L$q$, o ->> 'activity')),
      (5, 'UPDATE the other school''s teacher row', 'none',
         format($q$UPDATE "ScheduleActivityTeachers" SET role = 'ASSISTANT' WHERE "activityId" = %L$q$, o ->> 'activity')),
      (6, 'UPDATE the other school''s lesson mark', 'none',
         format($q$UPDATE "ScheduleActivityLessons" SET date = date + 1 WHERE "activityId" = %L$q$, o ->> 'activity')),
      (7, 'DELETE the other school''s lesson mark', 'none',
         format($q$DELETE FROM "ScheduleActivityLessons" WHERE "activityId" = %L$q$, o ->> 'activity')),
      (8, 'DELETE the other school''s teacher row', 'none',
         format($q$DELETE FROM "ScheduleActivityTeachers" WHERE "activityId" = %L$q$, o ->> 'activity')),
      (9, 'DELETE the other school''s activity', 'none',
         format($q$DELETE FROM "ScheduleActivities" WHERE id = %L$q$, o ->> 'activity')),
      -- The administrator's own rows, moved to the other school.
      (10, 'UPDATE own activity to the other school', 'refused',
         format($q$UPDATE "ScheduleActivities" SET "schoolId" = %L WHERE id = %L$q$, o ->> 'school', m ->> 'activity')),
      (11, 'UPDATE own teacher row to the other school', 'refused',
         format($q$UPDATE "ScheduleActivityTeachers" SET "schoolId" = %L WHERE "activityId" = %L$q$, o ->> 'school', m ->> 'activity')),
      (12, 'UPDATE own lesson mark to the other school', 'refused',
         format($q$UPDATE "ScheduleActivityLessons" SET "schoolId" = %L WHERE "activityId" = %L$q$, o ->> 'school', m ->> 'activity')),
      -- Own rows pointing at the other school's: the composite keys refuse.
      (20, 'INSERT activity on the other school''s avbokning', 'fk',
         format($q$INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId")
                   VALUES (%L, %L, %L, %L)$q$, m ->> 'school', m ->> 'year', o ->> 'spare', m ->> 'subject')),
      (21, 'INSERT activity in the other school''s year', 'fk',
         format($q$INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId")
                   VALUES (%L, %L, %L, %L)$q$, m ->> 'school', o ->> 'year', m ->> 'spare', m ->> 'subject')),
      (22, 'INSERT activity with the other school''s subject', 'fk',
         format($q$INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId")
                   VALUES (%L, %L, %L, %L)$q$, m ->> 'school', m ->> 'year', m ->> 'spare', o ->> 'subject')),
      (23, 'INSERT activity created by the other school''s person', 'fk',
         format($q$INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", "createdByUserId")
                   VALUES (%L, %L, %L, %L, %L)$q$, m ->> 'school', m ->> 'year', m ->> 'spare', m ->> 'subject', o ->> 'teacher')),
      (24, 'INSERT activity removed by the other school''s person', 'fk',
         format($q$INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", "removedAt", "removedByUserId")
                   VALUES (%L, %L, %L, %L, now(), %L)$q$, m ->> 'school', m ->> 'year', m ->> 'spare', m ->> 'subject', o ->> 'teacher')),
      (25, 'UPDATE own activity to the other school''s avbokning', 'fk',
         format($q$UPDATE "ScheduleActivities" SET "batchId" = %L WHERE id = %L$q$, o ->> 'spare', m ->> 'activity')),
      (26, 'UPDATE own activity to the other school''s subject', 'fk',
         format($q$UPDATE "ScheduleActivities" SET "replacementSubjectId" = %L WHERE id = %L$q$, o ->> 'subject', m ->> 'activity')),
      (27, 'UPDATE own activity to the other school''s year', 'fk',
         format($q$UPDATE "ScheduleActivities" SET "academicYearId" = %L WHERE id = %L$q$, o ->> 'year', m ->> 'activity')),
      (28, 'INSERT teacher row with the other school''s teacher', 'fk',
         format($q$INSERT INTO "ScheduleActivityTeachers" ("activityId", "studentGroupId", "teacherId", "schoolId", role)
                   VALUES (%L, %L, %L, %L, 'ASSISTANT')$q$, m ->> 'activity', m ->> 'group', o ->> 'teacher', m ->> 'school')),
      (29, 'INSERT teacher row on the other school''s activity', 'fk',
         format($q$INSERT INTO "ScheduleActivityTeachers" ("activityId", "studentGroupId", "teacherId", "schoolId", role)
                   VALUES (%L, %L, %L, %L, 'ASSISTANT')$q$, o ->> 'activity', m ->> 'group', m ->> 'teacher', m ->> 'school')),
      (30, 'UPDATE own teacher row to the other school''s teacher', 'fk',
         format($q$UPDATE "ScheduleActivityTeachers" SET "teacherId" = %L WHERE "activityId" = %L$q$, o ->> 'teacher', m ->> 'activity')),
      (31, 'INSERT lesson mark on the other school''s lesson', 'fk',
         format($q$INSERT INTO "ScheduleActivityLessons" ("activityId", "calendarLessonId", "studentGroupId", date, "schoolId")
                   VALUES (%L, %L, %L, '2030-10-08', %L)$q$, m ->> 'activity', o ->> 'spareLesson', m ->> 'group', m ->> 'school')),
      (32, 'INSERT lesson mark on the other school''s activity', 'fk',
         format($q$INSERT INTO "ScheduleActivityLessons" ("activityId", "calendarLessonId", "studentGroupId", date, "schoolId")
                   VALUES (%L, %L, %L, '2030-10-08', %L)$q$, o ->> 'activity', m ->> 'spareLesson', m ->> 'group', m ->> 'school')),
      (33, 'UPDATE own lesson mark to the other school''s lesson', 'fk',
         format($q$UPDATE "ScheduleActivityLessons" SET "calendarLessonId" = %L WHERE "activityId" = %L$q$, o ->> 'spareLesson', m ->> 'activity')),
      -- The same statements about the administrator's own school's rows.
      (40, 'INSERT activity on its own avbokning, year and subject', 'admitted',
         format($q$INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", "createdByUserId")
                   VALUES (%L, %L, %L, %L, %L)$q$, m ->> 'school', m ->> 'year', m ->> 'control', m ->> 'subject', m ->> 'teacher')),
      (41, 'INSERT teacher row with its own teacher', 'admitted',
         format($q$INSERT INTO "ScheduleActivityTeachers" ("activityId", "studentGroupId", "teacherId", "schoolId", role)
                   SELECT id, %L, %L, %L, 'ASSISTANT' FROM "ScheduleActivities" WHERE "batchId" = %L$q$,
                m ->> 'group', m ->> 'teacher', m ->> 'school', m ->> 'control')),
      (42, 'INSERT lesson mark on its own lesson', 'admitted',
         format($q$INSERT INTO "ScheduleActivityLessons" ("activityId", "calendarLessonId", "studentGroupId", date, "schoolId")
                   SELECT id, %L, %L, '2030-10-08', %L FROM "ScheduleActivities" WHERE "batchId" = %L$q$,
                m ->> 'controlLesson', m ->> 'group', m ->> 'school', m ->> 'control')),
      (43, 'UPDATE own activity to its own other avbokning', 'admitted',
         format($q$UPDATE "ScheduleActivities" SET "batchId" = %L, "createdByUserId" = %L WHERE id = %L$q$,
                m ->> 'extra', m ->> 'teacher', m ->> 'activity')),
      (44, 'UPDATE own lesson mark to its own other lesson', 'admitted',
         format($q$UPDATE "ScheduleActivityLessons" SET "calendarLessonId" = %L WHERE "activityId" = %L$q$,
                m ->> 'extraLesson', m ->> 'activity'))
    ) v(ord, label, expected, stmt) ORDER BY ord LOOP
      outcome := NULL;
      BEGIN
        EXECUTE c.stmt;
        GET DIAGNOSTICS n = ROW_COUNT;
        outcome := CASE WHEN n = 0 THEN 'none' WHEN n = 1 THEN 'admitted' ELSE n || ' rows' END;
      EXCEPTION
        WHEN insufficient_privilege THEN
          GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
          outcome := CASE WHEN msg LIKE '%row-level security%' THEN 'refused' ELSE 'denied' END;
        WHEN foreign_key_violation THEN
          outcome := 'fk';
        WHEN OTHERS THEN
          GET STACKED DIAGNOSTICS st = RETURNED_SQLSTATE, msg = MESSAGE_TEXT;
          outcome := 'error ' || st || ' ' || left(msg, 100);
      END;
      IF outcome IS DISTINCT FROM c.expected THEN
        wrong := wrong || format('school %s''s administrator met %s on "%s", expected %s', mine_key, outcome, c.label, c.expected);
      END IF;
    END LOOP;
  END LOOP;
  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'sa312: %', array_to_string(wrong, '; ');
  END IF;
END $$;

-- Nothing of either school moved: each activity is still its school's, and
-- the other administrator reads none of it.
DO $$
DECLARE
  sides jsonb := current_setting('app.test_rls312_sides')::jsonb;
  side text;
BEGIN
  FOREACH side IN ARRAY ARRAY['a', 'b'] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', sides -> side ->> 'admin')::text, true);
    IF NOT EXISTS (SELECT 1 FROM "ScheduleActivities"
                    WHERE id = (sides -> side ->> 'activity')::uuid AND "schoolId" = (sides -> side ->> 'school')::uuid
                      AND description = 'sa312 ' || side AND "batchId" = (sides -> side ->> 'extra')::uuid) THEN
      RAISE EXCEPTION 'sa312: the activity of school % was moved, renamed or lost', side;
    END IF;
    IF (SELECT count(*) FROM "ScheduleActivityTeachers" WHERE "activityId" = (sides -> side ->> 'activity')::uuid
                                                         AND "schoolId" = (sides -> side ->> 'school')::uuid) <> 1
       OR (SELECT count(*) FROM "ScheduleActivityLessons" WHERE "activityId" = (sides -> side ->> 'activity')::uuid
                                                           AND "schoolId" = (sides -> side ->> 'school')::uuid
                                                           AND date = '2030-10-07') <> 1 THEN
      RAISE EXCEPTION 'sa312: the teacher row or the lesson mark of school % was moved or lost', side;
    END IF;
  END LOOP;
END $$;

-- A teacher reads its own school's activity and none of the other's; a pupil
-- of the second school reads nothing of either.
DO $$
DECLARE
  sides jsonb := current_setting('app.test_rls312_sides')::jsonb;
  side text;
  other text;
  who record;
  seen bigint;
  total bigint;
BEGIN
  FOREACH side IN ARRAY ARRAY['a', 'b'] LOOP
    other := CASE side WHEN 'a' THEN 'b' ELSE 'a' END;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', sides -> side ->> 'teacherAuth')::text, true);
    IF app.current_user_role() IS DISTINCT FROM 'TEACHER' OR app.current_school_id() IS DISTINCT FROM (sides -> side ->> 'school')::uuid THEN
      RAISE EXCEPTION 'sa312: the teacher of school % resolved as % in %', side, app.current_user_role(), app.current_school_id();
    END IF;
    SELECT (SELECT count(*) FROM "ScheduleActivities" WHERE id = (sides -> side ->> 'activity')::uuid)
         + (SELECT count(*) FROM "ScheduleActivityTeachers" WHERE "activityId" = (sides -> side ->> 'activity')::uuid)
         + (SELECT count(*) FROM "ScheduleActivityLessons" WHERE "activityId" = (sides -> side ->> 'activity')::uuid) INTO seen;
    IF seen <> 3 THEN RAISE EXCEPTION 'sa312: the teacher of school % reads % of its school''s 3 rows', side, seen; END IF;
    SELECT (SELECT count(*) FROM "ScheduleActivities" WHERE id = (sides -> other ->> 'activity')::uuid OR "schoolId" = (sides -> other ->> 'school')::uuid)
         + (SELECT count(*) FROM "ScheduleActivityTeachers" WHERE "activityId" = (sides -> other ->> 'activity')::uuid OR "schoolId" = (sides -> other ->> 'school')::uuid)
         + (SELECT count(*) FROM "ScheduleActivityLessons" WHERE "activityId" = (sides -> other ->> 'activity')::uuid OR "schoolId" = (sides -> other ->> 'school')::uuid)
         INTO seen;
    IF seen <> 0 THEN RAISE EXCEPTION 'sa312: the teacher of school % reads % row(s) of school %', side, seen, other; END IF;
    SELECT (SELECT count(*) FROM "ScheduleActivities") + (SELECT count(*) FROM "ScheduleActivityTeachers")
         + (SELECT count(*) FROM "ScheduleActivityLessons") INTO total;
    SELECT (SELECT count(*) FROM "ScheduleActivities" WHERE "schoolId" = (sides -> side ->> 'school')::uuid)
         + (SELECT count(*) FROM "ScheduleActivityTeachers" WHERE "schoolId" = (sides -> side ->> 'school')::uuid)
         + (SELECT count(*) FROM "ScheduleActivityLessons" WHERE "schoolId" = (sides -> side ->> 'school')::uuid) INTO seen;
    IF total <> seen THEN RAISE EXCEPTION 'sa312: the teacher of school % reads % rows, % of them its school''s', side, total, seen; END IF;
  END LOOP;

  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000002')::text, true);
  IF app.current_user_role() IS DISTINCT FROM 'STUDENT' OR app.current_school_id() IS DISTINCT FROM (sides -> 'b' ->> 'school')::uuid THEN
    RAISE EXCEPTION 'sa312: expected the pupil of school b';
  END IF;
  SELECT (SELECT count(*) FROM "ScheduleActivities") + (SELECT count(*) FROM "ScheduleActivityTeachers")
       + (SELECT count(*) FROM "ScheduleActivityLessons") INTO total;
  IF total <> 0 THEN RAISE EXCEPTION 'sa312: a pupil of school b reads % row(s)', total; END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 313: en schemabrytande aktivitet, radens liv (ScheduleActivities,
-- ScheduleActivityTeachers, ScheduleActivityLessons, 20270101090000).
--
-- What the keys and constraints of section 310 do to a row, run by the matrix
-- school's full administrator on rows planted here. Each cascade has its own
-- activity:
--   * the avbokning removed takes the activity, its teacher rows and its
--     lesson marks with it; the lessons themselves stay (they are the
--     calendar's);
--   * a lesson removed takes its mark and nothing else of the activity;
--   * a replacement subject removed takes the activity, its teacher rows and
--     its marks, and leaves the avbokning and the lessons;
--   * a teacher removed (a Users row) takes that teacher's rows and the
--     colleagues' stay with the activity;
--   * an administrator who made or removed an activity leaves it: SET NULL on
--     that column alone (createdByUserId, removedByUserId), so removedAt, the
--     other person, the description and the selection stay, and the row stays;
--   * a class removed takes its lessons (CalendarLessons) and so their marks,
--     and leaves the teacher rows that name it and the selection that holds
--     its id: there is no key on studentGroupId, on purpose;
--   * an academic year removed takes its activities.
-- Then the constraints at work: the description (1–300 characters after
-- trimming, counted as characters), at most 200 groups in the selection, a
-- removal recorded with its time; one activity per avbokning; one lead per
-- activity and class, no substitute, no teacher twice in a class; one
-- replacement lesson per class and day, a lesson marked once; and the
-- defaults a statement that names neither the role nor the selection meets.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
DO $$
DECLARE
  school uuid := app.current_school_id();
  y uuid;
  y2 uuid;
  grp uuid;
  tgrp uuid;
  g uuid;
  subj uuid;
  subj_x uuid;
  ta uuid;
  tb uuid;
  adm1 uuid;
  adm2 uuid;
  adm3 uuid;
  b uuid;
  act uuid;
  act_b uuid;
  act_c uuid;
  l1 uuid;
  l2 uuid;
  lg uuid;
  rec record;
  n bigint;
BEGIN
  IF (SELECT slug FROM "Schools" WHERE id = school) IS DISTINCT FROM 'rls-roller-school'
     OR NOT app.current_user_may('PLANERING', true) OR NOT app.current_user_may('DRIFT', true)
     OR NOT app.current_user_decides() THEN
    RAISE EXCEPTION 'sa313: expected the matrix school''s full administrator';
  END IF;
  SELECT id INTO y FROM "AcademicYears" WHERE "schoolId" = school AND "isActive";
  SELECT id INTO grp FROM "StudentGroups" WHERE "schoolId" = school AND name = 'Roller 7A';
  SELECT id INTO tgrp FROM "StudentGroups" WHERE "schoolId" = school AND name = 'Roller Spanska';
  IF y IS NULL OR grp IS NULL OR tgrp IS NULL THEN
    RAISE EXCEPTION 'sa313: the matrix school lacks its year or its classes; fixtures did not run';
  END IF;
  INSERT INTO "Subjects" ("schoolId", name, code, "updatedAt") VALUES (school, 'sa313 ersättningsämne', 'SA313', now()) RETURNING id INTO subj;
  INSERT INTO "Subjects" ("schoolId", name, code, "updatedAt") VALUES (school, 'sa313 ämne som tas bort', 'SA313X', now()) RETURNING id INTO subj_x;

  -- 1. The avbokning goes.
  INSERT INTO "Users" ("schoolId", email, "firstName", "lastName", role, "authId", "isActive", "updatedAt")
  VALUES (school, 'sa313-a@example.invalid', 'Sa', 'A', 'TEACHER', gen_random_uuid(), true, now()) RETURNING id INTO ta;
  INSERT INTO "Users" ("schoolId", email, "firstName", "lastName", role, "authId", "isActive", "updatedAt")
  VALUES (school, 'sa313-b@example.invalid', 'Sa', 'B', 'TEACHER', gen_random_uuid(), true, now()) RETURNING id INTO tb;
  INSERT INTO "CancellationBatches" ("schoolId", "academicYearId", name, cause, "fromDate", "toDate", scope)
  VALUES (school, y, 'sa313 1', 'EVENT', '2030-10-14', '2030-10-14', 'SCHOOL') RETURNING id INTO b;
  INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", description, "scopeGroupIds")
  VALUES (school, y, b, subj, 'sa313 1', ARRAY[grp, tgrp]) RETURNING id INTO act;
  INSERT INTO "ScheduleActivityTeachers" ("activityId", "studentGroupId", "teacherId", "schoolId", role)
  VALUES (act, grp, ta, school, 'LEAD'), (act, grp, tb, school, 'ASSISTANT'), (act, tgrp, ta, school, 'LEAD');
  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", note, "updatedAt")
  VALUES (school, subj, grp, '2030-10-14', '2030-10-14 09:00+00', '2030-10-14 10:00+00', 'sa313 1a', now()),
         (school, subj, tgrp, '2030-10-14', '2030-10-14 09:00+00', '2030-10-14 10:00+00', 'sa313 1b', now());
  INSERT INTO "ScheduleActivityLessons" ("activityId", "calendarLessonId", "studentGroupId", date, "schoolId")
  SELECT act, id, "studentGroupId", date, school FROM "CalendarLessons" WHERE "schoolId" = school AND note IN ('sa313 1a', 'sa313 1b');
  IF (SELECT count(*) FROM "ScheduleActivityTeachers" WHERE "activityId" = act) <> 3
     OR (SELECT count(*) FROM "ScheduleActivityLessons" WHERE "activityId" = act) <> 2 THEN
    RAISE EXCEPTION 'sa313: the first activity was not planted whole';
  END IF;
  DELETE FROM "CancellationBatches" WHERE id = b;
  IF EXISTS (SELECT 1 FROM "ScheduleActivities" WHERE id = act)
     OR EXISTS (SELECT 1 FROM "ScheduleActivityTeachers" WHERE "activityId" = act)
     OR EXISTS (SELECT 1 FROM "ScheduleActivityLessons" WHERE "activityId" = act) THEN
    RAISE EXCEPTION 'sa313: the avbokning was removed and its activity, teacher rows or lesson marks stayed';
  END IF;
  IF (SELECT count(*) FROM "CalendarLessons" WHERE "schoolId" = school AND note IN ('sa313 1a', 'sa313 1b')) <> 2 THEN
    RAISE EXCEPTION 'sa313: the avbokning was removed and took the replacement lessons themselves';
  END IF;

  -- 2. A lesson goes: its mark goes, and only its mark.
  INSERT INTO "CancellationBatches" ("schoolId", "academicYearId", name, cause, "fromDate", "toDate", scope)
  VALUES (school, y, 'sa313 2', 'EVENT', '2030-10-15', '2030-10-16', 'SCHOOL') RETURNING id INTO b;
  INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", description)
  VALUES (school, y, b, subj, 'sa313 2') RETURNING id INTO act;
  INSERT INTO "ScheduleActivityTeachers" ("activityId", "studentGroupId", "teacherId", "schoolId", role) VALUES (act, grp, ta, school, 'LEAD');
  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", note, "updatedAt")
  VALUES (school, subj, grp, '2030-10-15', '2030-10-15 09:00+00', '2030-10-15 10:00+00', 'sa313 2a', now()) RETURNING id INTO l1;
  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", note, "updatedAt")
  VALUES (school, subj, grp, '2030-10-16', '2030-10-16 09:00+00', '2030-10-16 10:00+00', 'sa313 2b', now()) RETURNING id INTO l2;
  INSERT INTO "ScheduleActivityLessons" ("activityId", "calendarLessonId", "studentGroupId", date, "schoolId")
  VALUES (act, l1, grp, '2030-10-15', school), (act, l2, grp, '2030-10-16', school);
  DELETE FROM "CalendarLessons" WHERE id = l1;
  IF EXISTS (SELECT 1 FROM "ScheduleActivityLessons" WHERE "calendarLessonId" = l1) THEN
    RAISE EXCEPTION 'sa313: a lesson was removed and its mark stayed';
  END IF;
  IF (SELECT count(*) FROM "ScheduleActivityLessons" WHERE "activityId" = act AND "calendarLessonId" = l2) <> 1
     OR NOT EXISTS (SELECT 1 FROM "ScheduleActivities" WHERE id = act)
     OR NOT EXISTS (SELECT 1 FROM "ScheduleActivityTeachers" WHERE "activityId" = act)
     OR NOT EXISTS (SELECT 1 FROM "CancellationBatches" WHERE id = b) THEN
    RAISE EXCEPTION 'sa313: a lesson was removed and took more than its mark';
  END IF;

  -- 3. A replacement subject goes: the activity goes, with its rows; the
  -- avbokning and the lesson (of another subject) stay.
  INSERT INTO "CancellationBatches" ("schoolId", "academicYearId", name, cause, "fromDate", "toDate", scope)
  VALUES (school, y, 'sa313 3', 'EVENT', '2030-10-17', '2030-10-17', 'SCHOOL') RETURNING id INTO b;
  INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", description)
  VALUES (school, y, b, subj_x, 'sa313 3') RETURNING id INTO act;
  INSERT INTO "ScheduleActivityTeachers" ("activityId", "studentGroupId", "teacherId", "schoolId", role) VALUES (act, grp, ta, school, 'LEAD');
  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", note, "updatedAt")
  VALUES (school, subj, grp, '2030-10-17', '2030-10-17 09:00+00', '2030-10-17 10:00+00', 'sa313 3', now()) RETURNING id INTO l1;
  INSERT INTO "ScheduleActivityLessons" ("activityId", "calendarLessonId", "studentGroupId", date, "schoolId")
  VALUES (act, l1, grp, '2030-10-17', school);
  DELETE FROM "Subjects" WHERE id = subj_x;
  IF EXISTS (SELECT 1 FROM "ScheduleActivities" WHERE id = act)
     OR EXISTS (SELECT 1 FROM "ScheduleActivityTeachers" WHERE "activityId" = act)
     OR EXISTS (SELECT 1 FROM "ScheduleActivityLessons" WHERE "activityId" = act) THEN
    RAISE EXCEPTION 'sa313: the replacement subject was removed and its activity or the activity''s rows stayed';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM "CancellationBatches" WHERE id = b) OR NOT EXISTS (SELECT 1 FROM "CalendarLessons" WHERE id = l1) THEN
    RAISE EXCEPTION 'sa313: the replacement subject was removed and took the avbokning or a lesson of another subject';
  END IF;

  -- 4. A teacher goes: that teacher's rows go; the colleague's stay.
  INSERT INTO "CancellationBatches" ("schoolId", "academicYearId", name, cause, "fromDate", "toDate", scope)
  VALUES (school, y, 'sa313 4', 'EVENT', '2030-10-18', '2030-10-18', 'SCHOOL') RETURNING id INTO b;
  INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", description)
  VALUES (school, y, b, subj, 'sa313 4') RETURNING id INTO act;
  INSERT INTO "ScheduleActivityTeachers" ("activityId", "studentGroupId", "teacherId", "schoolId", role)
  VALUES (act, grp, ta, school, 'LEAD'), (act, grp, tb, school, 'ASSISTANT'), (act, tgrp, ta, school, 'ASSISTANT');
  DELETE FROM "Users" WHERE id = ta;
  IF EXISTS (SELECT 1 FROM "ScheduleActivityTeachers" WHERE "teacherId" = ta) THEN
    RAISE EXCEPTION 'sa313: a teacher was removed and their rows stayed';
  END IF;
  IF (SELECT count(*) FROM "ScheduleActivityTeachers" WHERE "activityId" = act) <> 1
     OR NOT EXISTS (SELECT 1 FROM "ScheduleActivityTeachers" WHERE "activityId" = act AND "teacherId" = tb)
     OR NOT EXISTS (SELECT 1 FROM "ScheduleActivities" WHERE id = act) THEN
    RAISE EXCEPTION 'sa313: a teacher was removed and took the colleague''s row or the activity';
  END IF;

  -- 5. An administrator goes: the column that names them is emptied, and only
  -- that column; the row stays.
  INSERT INTO "Users" ("schoolId", email, "firstName", "lastName", role, "adminProfile", "authId", "isActive", "updatedAt")
  VALUES (school, 'sa313-adm1@example.invalid', 'Sa', 'Admin1', 'SCHOOL_ADMIN', 'EXPEDITION', gen_random_uuid(), true, now()) RETURNING id INTO adm1;
  INSERT INTO "Users" ("schoolId", email, "firstName", "lastName", role, "adminProfile", "authId", "isActive", "updatedAt")
  VALUES (school, 'sa313-adm2@example.invalid', 'Sa', 'Admin2', 'SCHOOL_ADMIN', 'EXPEDITION', gen_random_uuid(), true, now()) RETURNING id INTO adm2;
  INSERT INTO "Users" ("schoolId", email, "firstName", "lastName", role, "adminProfile", "authId", "isActive", "updatedAt")
  VALUES (school, 'sa313-adm3@example.invalid', 'Sa', 'Admin3', 'SCHOOL_ADMIN', 'EXPEDITION', gen_random_uuid(), true, now()) RETURNING id INTO adm3;
  INSERT INTO "CancellationBatches" ("schoolId", "academicYearId", name, cause, "fromDate", "toDate", scope)
  SELECT school, y, 'sa313 5' || x, 'EVENT', '2030-10-21', '2030-10-21', 'SCHOOL' FROM unnest(ARRAY['a', 'b', 'c']) x;
  INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", description, "scopeGroupIds",
                                    "createdByUserId", "removedAt", "removedByUserId")
  SELECT school, y, id, subj, 'sa313 5' || right(name, 1), ARRAY[grp, tgrp],
         CASE right(name, 1) WHEN 'c' THEN adm3 ELSE adm1 END,
         CASE right(name, 1) WHEN 'b' THEN NULL ELSE '2030-10-22 08:00+00'::timestamptz END,
         CASE right(name, 1) WHEN 'a' THEN adm2 WHEN 'c' THEN adm3 ELSE NULL END
    FROM "CancellationBatches" WHERE "schoolId" = school AND name IN ('sa313 5a', 'sa313 5b', 'sa313 5c');
  DELETE FROM "Users" WHERE id = adm1;
  SELECT "createdByUserId" AS c, "removedByUserId" AS r, "removedAt" AS at, "scopeGroupIds" AS s INTO rec FROM "ScheduleActivities" WHERE description = 'sa313 5a';
  IF NOT FOUND OR rec.c IS NOT NULL OR rec.r IS DISTINCT FROM adm2 OR rec.at IS DISTINCT FROM '2030-10-22 08:00+00'::timestamptz
     OR rec.s IS DISTINCT FROM ARRAY[grp, tgrp] THEN
    RAISE EXCEPTION 'sa313: the maker was removed and the activity became (%)', rec;
  END IF;
  SELECT "createdByUserId" AS c, "removedAt" AS at INTO rec FROM "ScheduleActivities" WHERE description = 'sa313 5b';
  IF NOT FOUND OR rec.c IS NOT NULL OR rec.at IS NOT NULL THEN
    RAISE EXCEPTION 'sa313: the maker of a live activity was removed and the activity became (%)', rec;
  END IF;
  DELETE FROM "Users" WHERE id = adm2;
  SELECT "createdByUserId" AS c, "removedByUserId" AS r, "removedAt" AS at INTO rec FROM "ScheduleActivities" WHERE description = 'sa313 5a';
  IF NOT FOUND OR rec.c IS NOT NULL OR rec.r IS NOT NULL OR rec.at IS DISTINCT FROM '2030-10-22 08:00+00'::timestamptz THEN
    RAISE EXCEPTION 'sa313: the remover was removed and the activity became (%)', rec;
  END IF;
  DELETE FROM "Users" WHERE id = adm3;
  SELECT "createdByUserId" AS c, "removedByUserId" AS r, "removedAt" AS at INTO rec FROM "ScheduleActivities" WHERE description = 'sa313 5c';
  IF NOT FOUND OR rec.c IS NOT NULL OR rec.r IS NOT NULL OR rec.at IS NULL THEN
    RAISE EXCEPTION 'sa313: a person who both made and removed an activity was removed and the activity became (%)', rec;
  END IF;

  -- 6. A class goes: its lessons go (CalendarLessons), and so their marks.
  -- The teacher row that names it stays, and so does the selection.
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, "gradeLevel", "updatedAt") VALUES (school, y, 'sa313 klass', 7, now()) RETURNING id INTO g;
  INSERT INTO "CancellationBatches" ("schoolId", "academicYearId", name, cause, "fromDate", "toDate", scope)
  VALUES (school, y, 'sa313 6', 'EVENT', '2030-10-23', '2030-10-23', 'SCHOOL') RETURNING id INTO b;
  INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", description, "scopeGroupIds")
  VALUES (school, y, b, subj, 'sa313 6', ARRAY[g, grp]) RETURNING id INTO act;
  INSERT INTO "ScheduleActivityTeachers" ("activityId", "studentGroupId", "teacherId", "schoolId", role) VALUES (act, g, tb, school, 'LEAD');
  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", note, "updatedAt")
  VALUES (school, subj, g, '2030-10-23', '2030-10-23 09:00+00', '2030-10-23 10:00+00', 'sa313 6g', now()) RETURNING id INTO lg;
  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", note, "updatedAt")
  VALUES (school, subj, grp, '2030-10-23', '2030-10-23 09:00+00', '2030-10-23 10:00+00', 'sa313 6h', now()) RETURNING id INTO l1;
  INSERT INTO "ScheduleActivityLessons" ("activityId", "calendarLessonId", "studentGroupId", date, "schoolId")
  VALUES (act, lg, g, '2030-10-23', school), (act, l1, grp, '2030-10-23', school);
  DELETE FROM "StudentGroups" WHERE id = g;
  IF EXISTS (SELECT 1 FROM "CalendarLessons" WHERE id = lg) OR EXISTS (SELECT 1 FROM "ScheduleActivityLessons" WHERE "calendarLessonId" = lg) THEN
    RAISE EXCEPTION 'sa313: a class was removed and its replacement lesson or its mark stayed';
  END IF;
  IF (SELECT count(*) FROM "ScheduleActivityLessons" WHERE "activityId" = act) <> 1
     OR NOT EXISTS (SELECT 1 FROM "ScheduleActivityTeachers" WHERE "activityId" = act AND "studentGroupId" = g AND "teacherId" = tb)
     OR NOT EXISTS (SELECT 1 FROM "ScheduleActivities" WHERE id = act AND g = ANY ("scopeGroupIds")) THEN
    RAISE EXCEPTION 'sa313: a class was removed and the activity lost more than the class''s lesson mark (or the teacher row did not stay)';
  END IF;

  -- 7. An academic year goes: its activities go with its avbokningar.
  INSERT INTO "AcademicYears" ("schoolId", name, "startDate", "endDate", "isActive", "updatedAt")
  VALUES (school, 'sa313 år', '2041-08-15', '2042-06-15', false, now()) RETURNING id INTO y2;
  INSERT INTO "CancellationBatches" ("schoolId", "academicYearId", name, cause, "fromDate", "toDate", scope)
  VALUES (school, y2, 'sa313 7', 'EVENT', '2041-10-14', '2041-10-14', 'SCHOOL') RETURNING id INTO b;
  INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", description)
  VALUES (school, y2, b, subj, 'sa313 7') RETURNING id INTO act;
  INSERT INTO "ScheduleActivityTeachers" ("activityId", "studentGroupId", "teacherId", "schoolId") VALUES (act, grp, tb, school);
  DELETE FROM "AcademicYears" WHERE id = y2;
  IF EXISTS (SELECT 1 FROM "ScheduleActivities" WHERE id = act) OR EXISTS (SELECT 1 FROM "ScheduleActivityTeachers" WHERE "activityId" = act)
     OR EXISTS (SELECT 1 FROM "CancellationBatches" WHERE id = b) THEN
    RAISE EXCEPTION 'sa313: an academic year was removed and an avbokning, an activity or its rows stayed';
  END IF;
END $$;

-- The constraints at work.
DO $$
DECLARE
  school uuid := app.current_school_id();
  y uuid;
  grp uuid;
  tgrp uuid;
  subj uuid;
  ta uuid;
  tb uuid;
  tc uuid;
  td uuid;
  adm uuid;
  bs uuid[];
  ls uuid[];
  act uuid;
  act2 uuid;
  c record;
  st text;
  cn text;
  outcome text;
  rec record;
  wrong text[] := '{}';
BEGIN
  SELECT id INTO y FROM "AcademicYears" WHERE "schoolId" = school AND "isActive";
  SELECT id INTO grp FROM "StudentGroups" WHERE "schoolId" = school AND name = 'Roller 7A';
  SELECT id INTO tgrp FROM "StudentGroups" WHERE "schoolId" = school AND name = 'Roller Spanska';
  INSERT INTO "Subjects" ("schoolId", name, code, "updatedAt") VALUES (school, 'sa313 villkor', 'SA313V', now()) RETURNING id INTO subj;
  INSERT INTO "Users" ("schoolId", email, "firstName", "lastName", role, "authId", "isActive", "updatedAt")
  SELECT school, 'sa313-v' || n || '@example.invalid', 'Sa', 'V' || n, 'TEACHER', gen_random_uuid(), true, now() FROM generate_series(1, 4) n;
  SELECT id INTO ta FROM "Users" WHERE "schoolId" = school AND email = 'sa313-v1@example.invalid';
  SELECT id INTO tb FROM "Users" WHERE "schoolId" = school AND email = 'sa313-v2@example.invalid';
  SELECT id INTO tc FROM "Users" WHERE "schoolId" = school AND email = 'sa313-v3@example.invalid';
  SELECT id INTO td FROM "Users" WHERE "schoolId" = school AND email = 'sa313-v4@example.invalid';
  INSERT INTO "Users" ("schoolId", email, "firstName", "lastName", role, "adminProfile", "authId", "isActive", "updatedAt")
  VALUES (school, 'sa313-vadm@example.invalid', 'Sa', 'VAdmin', 'SCHOOL_ADMIN', 'EXPEDITION', gen_random_uuid(), true, now()) RETURNING id INTO adm;
  INSERT INTO "CancellationBatches" ("schoolId", "academicYearId", name, cause, "fromDate", "toDate", scope)
  SELECT school, y, 'sa313 c' || n, 'EVENT', '2030-11-04', '2030-11-04', 'SCHOOL' FROM generate_series(1, 14) n;
  SELECT array_agg(id ORDER BY substring(name from 8)::int) INTO bs FROM "CancellationBatches" WHERE "schoolId" = school AND name ~ '^sa313 c[0-9]+$';
  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", note, "updatedAt")
  SELECT school, subj, grp, '2030-11-04', '2030-11-04 09:00+00', '2030-11-04 10:00+00', 'sa313 cl' || n, now() FROM generate_series(1, 6) n;
  SELECT array_agg(id ORDER BY substring(note from 9)::int) INTO ls FROM "CalendarLessons" WHERE "schoolId" = school AND note ~ '^sa313 cl[0-9]+$';
  IF cardinality(bs) <> 14 OR cardinality(ls) <> 6 OR ta IS NULL OR td IS NULL THEN
    RAISE EXCEPTION 'sa313: the constraint rows were not planted whole';
  END IF;

  -- The first activity, to compare with and to hang rows on.
  INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", description)
  VALUES (school, y, bs[1], subj, 'sa313 villkor') RETURNING id INTO act;
  INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", description)
  VALUES (school, y, bs[2], subj, 'sa313 villkor 2') RETURNING id INTO act2;

  FOR c IN SELECT * FROM (VALUES
    -- ScheduleActivities.
    (1, 'description empty', '23514:ScheduleActivities_description_is_sane',
       format($q$INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", description)
                 VALUES (%L, %L, %L, %L, '')$q$, school, y, bs[3], subj)),
    (2, 'description only spaces', '23514:ScheduleActivities_description_is_sane',
       format($q$INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", description)
                 VALUES (%L, %L, %L, %L, '    ')$q$, school, y, bs[3], subj)),
    (3, 'description of 301 characters', '23514:ScheduleActivities_description_is_sane',
       format($q$INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", description)
                 VALUES (%L, %L, %L, %L, repeat('a', 301))$q$, school, y, bs[3], subj)),
    (4, 'description of 301 multibyte characters', '23514:ScheduleActivities_description_is_sane',
       format($q$INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", description)
                 VALUES (%L, %L, %L, %L, repeat('å', 301))$q$, school, y, bs[3], subj)),
    (5, 'description of 300 characters', 'admitted',
       format($q$INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", description)
                 VALUES (%L, %L, %L, %L, repeat('a', 300))$q$, school, y, bs[3], subj)),
    (6, 'description of 300 multibyte characters (600 bytes)', 'admitted',
       format($q$INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", description)
                 VALUES (%L, %L, %L, %L, repeat('å', 300))$q$, school, y, bs[4], subj)),
    (7, 'description of one character between blanks', 'admitted',
       format($q$INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", description)
                 VALUES (%L, %L, %L, %L, '  x ')$q$, school, y, bs[5], subj)),
    (8, 'no description', 'admitted',
       format($q$INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", description)
                 VALUES (%L, %L, %L, %L, NULL)$q$, school, y, bs[6], subj)),
    (9, 'UPDATE description to empty', '23514:ScheduleActivities_description_is_sane',
       format($q$UPDATE "ScheduleActivities" SET description = '' WHERE id = %L$q$, act)),
    (10, 'selection of 201 groups', '23514:ScheduleActivities_scope_ids_are_few',
       format($q$INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", "scopeGroupIds")
                 VALUES (%L, %L, %L, %L, ARRAY(SELECT gen_random_uuid() FROM generate_series(1, 201)))$q$, school, y, bs[7], subj)),
    (11, 'selection of 200 groups', 'admitted',
       format($q$INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", "scopeGroupIds")
                 VALUES (%L, %L, %L, %L, ARRAY(SELECT gen_random_uuid() FROM generate_series(1, 200)))$q$, school, y, bs[7], subj)),
    (12, 'removed by somebody at no time', '23514:ScheduleActivities_removal_is_recorded',
       format($q$INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId", "removedByUserId")
                 VALUES (%L, %L, %L, %L, %L)$q$, school, y, bs[8], subj, adm)),
    (13, 'UPDATE: removed by somebody at no time', '23514:ScheduleActivities_removal_is_recorded',
       format($q$UPDATE "ScheduleActivities" SET "removedByUserId" = %L WHERE id = %L$q$, adm, act)),
    (14, 'removed at a time, by nobody known', 'admitted',
       format($q$UPDATE "ScheduleActivities" SET "removedAt" = now() WHERE id = %L$q$, act)),
    (15, 'then removed by somebody', 'admitted',
       format($q$UPDATE "ScheduleActivities" SET "removedByUserId" = %L WHERE id = %L$q$, adm, act)),
    (16, 'removed by somebody, the time taken away', '23514:ScheduleActivities_removal_is_recorded',
       format($q$UPDATE "ScheduleActivities" SET "removedAt" = NULL WHERE id = %L$q$, act)),
    (17, 'a second activity on the same avbokning', '23505:ScheduleActivities_batchId_key',
       format($q$INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId")
                 VALUES (%L, %L, %L, %L)$q$, school, y, bs[1], subj)),
    -- ScheduleActivityTeachers.
    (20, 'a lead', 'admitted',
       format($q$INSERT INTO "ScheduleActivityTeachers" ("activityId", "studentGroupId", "teacherId", "schoolId", role)
                 VALUES (%L, %L, %L, %L, 'LEAD')$q$, act, grp, ta, school)),
    (21, 'a second lead of the same class', '23505:ScheduleActivityTeachers_one_lead_per_group',
       format($q$INSERT INTO "ScheduleActivityTeachers" ("activityId", "studentGroupId", "teacherId", "schoolId", role)
                 VALUES (%L, %L, %L, %L, 'LEAD')$q$, act, grp, tb, school)),
    (22, 'a lead of another class', 'admitted',
       format($q$INSERT INTO "ScheduleActivityTeachers" ("activityId", "studentGroupId", "teacherId", "schoolId", role)
                 VALUES (%L, %L, %L, %L, 'LEAD')$q$, act, tgrp, tb, school)),
    (23, 'the lead of the same class in another activity', 'admitted',
       format($q$INSERT INTO "ScheduleActivityTeachers" ("activityId", "studentGroupId", "teacherId", "schoolId", role)
                 VALUES (%L, %L, %L, %L, 'LEAD')$q$, act2, grp, ta, school)),
    (24, 'an assistant', 'admitted',
       format($q$INSERT INTO "ScheduleActivityTeachers" ("activityId", "studentGroupId", "teacherId", "schoolId", role)
                 VALUES (%L, %L, %L, %L, 'ASSISTANT')$q$, act, grp, tb, school)),
    (25, 'a second assistant of the same class', 'admitted',
       format($q$INSERT INTO "ScheduleActivityTeachers" ("activityId", "studentGroupId", "teacherId", "schoolId", role)
                 VALUES (%L, %L, %L, %L, 'ASSISTANT')$q$, act, grp, tc, school)),
    (26, 'the same teacher twice in a class', '23505:ScheduleActivityTeachers_pkey',
       format($q$INSERT INTO "ScheduleActivityTeachers" ("activityId", "studentGroupId", "teacherId", "schoolId", role)
                 VALUES (%L, %L, %L, %L, 'ASSISTANT')$q$, act, grp, ta, school)),
    (27, 'a substitute', '23514:ScheduleActivityTeachers_role_is_responsible',
       format($q$INSERT INTO "ScheduleActivityTeachers" ("activityId", "studentGroupId", "teacherId", "schoolId", role)
                 VALUES (%L, %L, %L, %L, 'SUBSTITUTE')$q$, act, grp, td, school)),
    (28, 'an assistant made the second lead', '23505:ScheduleActivityTeachers_one_lead_per_group',
       format($q$UPDATE "ScheduleActivityTeachers" SET role = 'LEAD' WHERE "activityId" = %L AND "studentGroupId" = %L AND "teacherId" = %L$q$,
              act, grp, tb)),
    (29, 'the lead made a substitute', '23514:ScheduleActivityTeachers_role_is_responsible',
       format($q$UPDATE "ScheduleActivityTeachers" SET role = 'SUBSTITUTE' WHERE "activityId" = %L AND "studentGroupId" = %L AND "teacherId" = %L$q$,
              act, grp, ta)),
    (30, 'the lead made an assistant', 'admitted',
       format($q$UPDATE "ScheduleActivityTeachers" SET role = 'ASSISTANT' WHERE "activityId" = %L AND "studentGroupId" = %L AND "teacherId" = %L$q$,
              act, grp, ta)),
    (31, 'and an assistant the lead', 'admitted',
       format($q$UPDATE "ScheduleActivityTeachers" SET role = 'LEAD' WHERE "activityId" = %L AND "studentGroupId" = %L AND "teacherId" = %L$q$,
              act, grp, tb)),
    (32, 'a class that exists nowhere, no role named', 'admitted',
       format($q$INSERT INTO "ScheduleActivityTeachers" ("activityId", "studentGroupId", "teacherId", "schoolId")
                 VALUES (%L, gen_random_uuid(), %L, %L)$q$, act, ta, school)),
    -- ScheduleActivityLessons.
    (40, 'a replacement lesson', 'admitted',
       format($q$INSERT INTO "ScheduleActivityLessons" ("activityId", "calendarLessonId", "studentGroupId", date, "schoolId")
                 VALUES (%L, %L, %L, '2030-11-04', %L)$q$, act, ls[1], grp, school)),
    (41, 'a second lesson of the same class and day', '23505:ScheduleActivityLessons_activityId_studentGroupId_date_key',
       format($q$INSERT INTO "ScheduleActivityLessons" ("activityId", "calendarLessonId", "studentGroupId", date, "schoolId")
                 VALUES (%L, %L, %L, '2030-11-04', %L)$q$, act, ls[2], grp, school)),
    (42, 'a lesson of another class the same day', 'admitted',
       format($q$INSERT INTO "ScheduleActivityLessons" ("activityId", "calendarLessonId", "studentGroupId", date, "schoolId")
                 VALUES (%L, %L, %L, '2030-11-04', %L)$q$, act, ls[2], tgrp, school)),
    (43, 'a lesson of the same class another day', 'admitted',
       format($q$INSERT INTO "ScheduleActivityLessons" ("activityId", "calendarLessonId", "studentGroupId", date, "schoolId")
                 VALUES (%L, %L, %L, '2030-11-05', %L)$q$, act, ls[3], grp, school)),
    (44, 'a lesson marked by two activities', '23505:ScheduleActivityLessons_calendarLessonId_key',
       format($q$INSERT INTO "ScheduleActivityLessons" ("activityId", "calendarLessonId", "studentGroupId", date, "schoolId")
                 VALUES (%L, %L, %L, '2030-11-06', %L)$q$, act2, ls[1], grp, school)),
    (45, 'a lesson marked twice by one activity', '23505',
       format($q$INSERT INTO "ScheduleActivityLessons" ("activityId", "calendarLessonId", "studentGroupId", date, "schoolId")
                 VALUES (%L, %L, %L, '2030-11-07', %L)$q$, act, ls[1], grp, school)),
    (46, 'the same class and day in another activity', 'admitted',
       format($q$INSERT INTO "ScheduleActivityLessons" ("activityId", "calendarLessonId", "studentGroupId", date, "schoolId")
                 VALUES (%L, %L, %L, '2030-11-04', %L)$q$, act2, ls[4], grp, school)),
    (47, 'a class that exists nowhere, named on a lesson of another class', 'admitted',
       format($q$INSERT INTO "ScheduleActivityLessons" ("activityId", "calendarLessonId", "studentGroupId", date, "schoolId")
                 VALUES (%L, %L, gen_random_uuid(), '2030-11-08', %L)$q$, act, ls[5], school))
  ) v(ord, label, expected, stmt) ORDER BY ord LOOP
    outcome := NULL;
    BEGIN
      EXECUTE c.stmt;
      outcome := 'admitted';
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS st = RETURNED_SQLSTATE, cn = CONSTRAINT_NAME;
      outcome := st || ':' || coalesce(cn, '');
    END;
    IF NOT (outcome = c.expected OR (position(':' IN c.expected) = 0 AND split_part(outcome, ':', 1) = c.expected)) THEN
      wrong := wrong || format('"%s" met %s, expected %s', c.label, outcome, c.expected);
    END IF;
  END LOOP;
  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'sa313: %', array_to_string(wrong, '; ');
  END IF;

  -- What the admitted statements left: the lead is the one made lead last,
  -- the two leads of the two classes and the assistants are as written.
  IF (SELECT string_agg(role::text || ':' || ("teacherId" = tb)::text, ',' ORDER BY role, "teacherId" = tb)
        FROM "ScheduleActivityTeachers" WHERE "activityId" = act AND "studentGroupId" = grp AND "teacherId" IN (ta, tb, tc))
     IS DISTINCT FROM 'LEAD:true,ASSISTANT:false,ASSISTANT:false' THEN
    RAISE EXCEPTION 'sa313: the roles of the class are not as the admitted statements left them';
  END IF;

  -- The defaults: a statement that names neither the role nor the selection,
  -- nor a description or a person, stores an activity that is alive, with an
  -- empty selection, and a responsible teacher who leads.
  INSERT INTO "ScheduleActivities" ("schoolId", "academicYearId", "batchId", "replacementSubjectId") VALUES (school, y, bs[9], subj)
  RETURNING id INTO act;
  INSERT INTO "ScheduleActivityTeachers" ("activityId", "studentGroupId", "teacherId", "schoolId") VALUES (act, grp, ta, school);
  SELECT description IS NULL AS d, "scopeGroupIds" = '{}'::uuid[] AS s, "removedAt" IS NULL AS r, "createdByUserId" IS NULL AS c,
         "removedByUserId" IS NULL AS rb, "createdAt" = now() AS ca, "updatedAt" = now() AS ua
    INTO rec FROM "ScheduleActivities" WHERE id = act;
  IF NOT (rec.d AND rec.s AND rec.r AND rec.c AND rec.rb AND rec.ca AND rec.ua) THEN
    RAISE EXCEPTION 'sa313: an activity stored with no optional column named is not alive and empty: %', rec;
  END IF;
  IF (SELECT role FROM "ScheduleActivityTeachers" WHERE "activityId" = act AND "teacherId" = ta) IS DISTINCT FROM 'LEAD' THEN
    RAISE EXCEPTION 'sa313: a responsible teacher stored with no role named does not lead';
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 314: en schemabrytande aktivitet rör ingenting annat
-- (20270101090000 is additive: three new tables and no change to what was).
--
-- The avbokning's own tables are as section 27g left them: the same 13 arms
-- (four on the batch, four on its lessons, five on its credits, the fifth
-- being the teacher's read of the credit link) under the same names,
-- commands and roles (TO authenticated, which the API's role is a member of),
-- the same grants (the API's role and PostgREST's authenticated hold SELECT,
-- INSERT, UPDATE and DELETE, service_role SELECT, nobody anything else), and
-- no key from any of them to the new tables; the only key between the
-- two families is the activity's own, ScheduleActivities.batchId. Then the
-- statements of the API that serves before the migration, which name no new
-- table, run as the matrix school's full administrator against a lesson and
-- a credit planted here: an avbokning is made, takes a lesson and a credit,
-- is counted, reversed, and removed, and no activity is born, owned or left
-- behind by any of it.
-- ---------------------------------------------------------------------------

BEGIN;
DO $$
DECLARE
  old_tables constant regclass[] := ARRAY['public."CancellationBatches"', 'public."CancellationBatchLessons"',
                                          'public."CancellationBatchCredits"']::regclass[];
  auth oid := (SELECT oid FROM pg_roles WHERE rolname = 'authenticated');
  bad text;
BEGIN
  IF auth IS NULL THEN RAISE EXCEPTION 'sa314: the role authenticated does not exist'; END IF;

  SELECT string_agg(polname || ':' || polcmd::text, ',' ORDER BY polname COLLATE "C") INTO bad FROM pg_policy
   WHERE polrelid = ANY (old_tables);
  IF bad IS DISTINCT FROM
       'cancellation_batch_credits_admin_delete:d,cancellation_batch_credits_admin_insert:a,cancellation_batch_credits_admin_select:r,cancellation_batch_credits_admin_update:w,'
       'cancellation_batch_credits_staff_select:r,'
       'cancellation_batch_lessons_admin_delete:d,cancellation_batch_lessons_admin_insert:a,cancellation_batch_lessons_admin_select:r,cancellation_batch_lessons_admin_update:w,'
       'cancellation_batches_admin_delete:d,cancellation_batches_admin_insert:a,cancellation_batches_admin_select:r,cancellation_batches_admin_update:w' THEN
    RAISE EXCEPTION 'sa314: the avbokning''s policies are %', bad;
  END IF;
  IF (SELECT count(*) FROM pg_policy WHERE polrelid = 'public."CancellationBatches"'::regclass) <> 4
     OR (SELECT count(*) FROM pg_policy WHERE polrelid = 'public."CancellationBatchLessons"'::regclass) <> 4
     OR (SELECT count(*) FROM pg_policy WHERE polrelid = 'public."CancellationBatchCredits"'::regclass) <> 5 THEN
    RAISE EXCEPTION 'sa314: the avbokning''s tables do not hold 4, 4 and 5 arms';
  END IF;
  SELECT string_agg(polname, ', ') INTO bad FROM pg_policy
   WHERE polrelid = ANY (old_tables) AND (polroles <> ARRAY[auth] OR NOT polpermissive);
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'sa314: arms that are not authenticated''s permissive ones: %', bad; END IF;

  -- Nothing in an arm of theirs reaches for the new tables.
  SELECT string_agg(polname, ', ') INTO bad FROM pg_policy
   WHERE polrelid = ANY (old_tables)
     AND (coalesce(pg_get_expr(polqual, polrelid), '') || coalesce(pg_get_expr(polwithcheck, polrelid), '')) LIKE '%ScheduleActivit%';
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'sa314: arms of the avbokning that read the activity: %', bad; END IF;

  -- The grants, table by table, exactly: the owner aside, the API's role and
  -- PostgREST's authenticated hold the four, service_role the read.
  SELECT string_agg(c.relname || ' ' || x.acl, '; ' ORDER BY c.relname COLLATE "C") INTO bad
    FROM pg_class c
    CROSS JOIN LATERAL (
      SELECT coalesce(string_agg(coalesce(r.rolname, 'PUBLIC') || ':' || a.privilege_type, ',' ORDER BY coalesce(r.rolname, 'PUBLIC') COLLATE "C",
                                                                                              a.privilege_type COLLATE "C"), '') AS acl
        FROM aclexplode(c.relacl) a LEFT JOIN pg_roles r ON r.oid = a.grantee WHERE a.grantee <> c.relowner) x
   WHERE c.oid = ANY (old_tables)
     AND x.acl <> 'app_authenticated:DELETE,app_authenticated:INSERT,app_authenticated:SELECT,app_authenticated:UPDATE,'
                  'authenticated:DELETE,authenticated:INSERT,authenticated:SELECT,authenticated:UPDATE,service_role:SELECT';
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'sa314: the avbokning''s grants moved: %', bad; END IF;

  -- No key from the avbokning's tables to the new ones, and the new tables
  -- reach the avbokning through the activity's batchId alone.
  SELECT string_agg(conname, ', ') INTO bad FROM pg_constraint
   WHERE contype = 'f' AND conrelid = ANY (old_tables)
     AND confrelid IN ('public."ScheduleActivities"'::regclass, 'public."ScheduleActivityTeachers"'::regclass,
                       'public."ScheduleActivityLessons"'::regclass);
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'sa314: keys from the avbokning to the activity: %', bad; END IF;
  SELECT string_agg(conname, ', ') INTO bad FROM pg_constraint
   WHERE contype = 'f' AND confrelid = ANY (old_tables)
     AND conrelid IN ('public."ScheduleActivities"'::regclass, 'public."ScheduleActivityTeachers"'::regclass,
                      'public."ScheduleActivityLessons"'::regclass)
     AND conname <> 'ScheduleActivities_batchId_schoolId_fkey';
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'sa314: keys from the activity to the avbokning''s tables other than its batchId: %', bad; END IF;
  -- And no trigger on the avbokning's tables, before or after: nothing there
  -- to learn of an activity.
  SELECT string_agg(tgname, ', ') INTO bad FROM pg_trigger WHERE tgrelid = ANY (old_tables) AND NOT tgisinternal;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'sa314: triggers on the avbokning''s tables: %', bad; END IF;
END $$;

-- The old API's own statements (src/publication/cancellation-batches.service.ts
-- at the commit before the activity), none of which names a new table.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
DO $$
DECLARE
  school uuid := app.current_school_id();
  me uuid := app.current_user_id();
  y uuid;
  grp uuid;
  subj uuid;
  lesson uuid;
  b uuid;
  credit uuid;
  n bigint;
  rec record;
BEGIN
  IF (SELECT slug FROM "Schools" WHERE id = school) IS DISTINCT FROM 'rls-roller-school' THEN
    RAISE EXCEPTION 'sa314: expected the matrix school''s full administrator';
  END IF;
  SELECT id INTO y FROM "AcademicYears" WHERE "schoolId" = school AND "isActive";
  SELECT id INTO grp FROM "StudentGroups" WHERE "schoolId" = school AND name = 'Roller 7A';
  SELECT id INTO subj FROM "Subjects" WHERE "schoolId" = school AND code = 'RLSR';
  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", note, "updatedAt")
  VALUES (school, subj, grp, '2030-11-11', '2030-11-11 09:00+00', '2030-11-11 10:00+00', 'sa314 anteckning', now()) RETURNING id INTO lesson;

  -- Create: the batch (the columns create() names), its lessons, the
  -- lessons cancelled, a credit and its link, the count.
  INSERT INTO "CancellationBatches" ("schoolId", "academicYearId", name, cause, "fromDate", "toDate", "startTime", "endTime", scope,
                                     "minGradeLevel", "maxGradeLevel", "groupIds", "createdByUserId", notifies)
  VALUES (school, y, 'sa314 prao', 'EVENT', '2030-11-11', '2030-11-12', NULL, NULL, 'GRADES', 7, 9, '{}', me, false)
  RETURNING id INTO b;
  INSERT INTO "CancellationBatchLessons" ("batchId", "calendarLessonId", "schoolId", "previousNote") VALUES (b, lesson, school, 'sa314 anteckning');
  UPDATE "CalendarLessons" SET status = 'CANCELLED', "cancelCause" = 'EVENT', note = 'Inställd: sa314 prao'
   WHERE id = lesson AND status = 'SCHEDULED';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'sa314: the old API could not cancel the lesson'; END IF;
  INSERT INTO "TimplanCredits" ("schoolId", "academicYearId", date, minutes, name, "updatedAt")
  VALUES (school, y, '2030-11-11', 300, 'sa314 prao', now()) RETURNING id INTO credit;
  INSERT INTO "CancellationBatchCredits" ("batchId", "creditId", "schoolId") VALUES (b, credit, school);
  UPDATE "CancellationBatches" SET cancelled = 1 WHERE id = b;
  SELECT cancelled AS c, "createdByUserId" AS u INTO rec FROM "CancellationBatches" WHERE id = b;
  IF rec.c <> 1 OR rec.u IS DISTINCT FROM me THEN
    RAISE EXCEPTION 'sa314: the avbokning the old API made is not as it wrote it (%)', rec;
  END IF;
  -- No activity owns it, and none came of it.
  IF EXISTS (SELECT 1 FROM "ScheduleActivities" WHERE "batchId" = b)
     OR EXISTS (SELECT 1 FROM "ScheduleActivityLessons" WHERE "calendarLessonId" = lesson) THEN
    RAISE EXCEPTION 'sa314: an avbokning made without an activity has one';
  END IF;

  -- Reverse: the lesson back, the credit removed (its link with it), the
  -- batch stamped.
  UPDATE "CalendarLessons" SET status = 'SCHEDULED', "cancelCause" = NULL, note = 'sa314 anteckning'
   WHERE id = lesson AND status = 'CANCELLED' AND "cancelCause" = 'EVENT';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'sa314: the old API could not reinstate the lesson'; END IF;
  DELETE FROM "TimplanCredits" WHERE id = credit;
  IF EXISTS (SELECT 1 FROM "CancellationBatchCredits" WHERE "batchId" = b) THEN
    RAISE EXCEPTION 'sa314: a credit removed by the old API left its link';
  END IF;
  UPDATE "CancellationBatches" SET "reversedAt" = now(), "reversedByUserId" = me, reinstated = 1, "skippedRoomTaken" = 0 WHERE id = b;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'sa314: the old API could not reverse the avbokning'; END IF;

  -- Removed: the lesson link goes with it, and nothing else is asked.
  DELETE FROM "CancellationBatches" WHERE id = b;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 OR EXISTS (SELECT 1 FROM "CancellationBatchLessons" WHERE "batchId" = b) THEN
    RAISE EXCEPTION 'sa314: an avbokning made and reversed by the old API was not removed whole';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM "CalendarLessons" WHERE id = lesson AND status = 'SCHEDULED') THEN
    RAISE EXCEPTION 'sa314: the lesson did not survive its avbokning';
  END IF;

  -- The fixtures' own avbokning (an activity's, since 20270101090000) is
  -- still read by every administrator, and by the teacher as 27g says:
  -- the credit link and nothing else of it.
  IF (SELECT count(*) FROM "CancellationBatches" WHERE name = 'Roller prao') <> 1 THEN
    RAISE EXCEPTION 'sa314: the matrix school''s avbokning is not read by its administrator';
  END IF;
END $$;

SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000111')::text, true);
DO $$
BEGIN
  IF app.current_user_role() IS DISTINCT FROM 'TEACHER' THEN RAISE EXCEPTION 'sa314: expected a TEACHER'; END IF;
  IF (SELECT count(*) FROM "CancellationBatches") + (SELECT count(*) FROM "CancellationBatchLessons") <> 0 THEN
    RAISE EXCEPTION 'sa314: a teacher reads an avbokning or its lessons';
  END IF;
  IF (SELECT count(*) FROM "CancellationBatchCredits") < 1 THEN
    RAISE EXCEPTION 'sa314: a teacher no longer reads the credit link';
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Sections 340-344: Skyddad identitet (20270107090000). A school's mark that
-- a person has a protected identity, where it comes from (SS12000 or MANUAL,
-- a row each) and never which protection, and its history. The school's
-- people are in the fixtures ('rls-skyddad-school'): T1, P1, P3 and G2 are
-- marked; T2, P2, P4 and G1 not.
--
-- What the database cannot hold, and these sections do not try to: which
-- reads become a file. Exports are built in the gateway and the browser from
-- ordinary reads under RLS; src/common/people-files.ts and
-- web/lib/people-files.ts decide each by name, and their tests fail a new
-- one. test/skyddad-identitet.e2e-spec.ts runs the files themselves.
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- Section 340: markeringen i katalogen. Four columns, the fourth the
-- register's kind (20270111090000, section 360); a row per person and
-- source, with the school in the key; no column on Users; the keys cascade
-- with the person and the school; eight arms, all app_authenticated's, the
-- delete the decisions', the two updates 20270111090000's; SELECT, INSERT
-- and DELETE of the marks (UPDATE of kind alone) and SELECT of the history for the API,
-- nothing for PostgREST's roles, SELECT for service_role, MAINTAIN nobody's
-- on 17; the history written by its trigger; the sync's change kind and its
-- CHECK; gallring's lines.
-- ---------------------------------------------------------------------------

BEGIN;
DO $$
DECLARE
  v text;
  n bigint;
  r text;
  t text;
BEGIN
  SELECT string_agg(a.attname || ':' || format_type(a.atttypid, a.atttypmod), ',' ORDER BY a.attnum) INTO v
    FROM pg_attribute a WHERE a.attrelid = 'public."PersonProtections"'::regclass AND a.attnum > 0 AND NOT a.attisdropped;
  IF v IS DISTINCT FROM 'userId:uuid,schoolId:uuid,source:"PersonProtectionSource",kind:"PersonProtectionKind"' THEN
    RAISE EXCEPTION 'skyddad 340: PersonProtections holds %, not the person, the school, the source and the register''s kind alone', v;
  END IF;
  SELECT string_agg(a.attname || ':' || format_type(a.atttypid, a.atttypmod), ',' ORDER BY a.attnum) INTO v
    FROM pg_attribute a WHERE a.attrelid = 'public."PersonProtectionEvents"'::regclass AND a.attnum > 0 AND NOT a.attisdropped;
  IF v IS DISTINCT FROM 'id:uuid,schoolId:uuid,userId:uuid,action:"PersonProtectionAction",source:"PersonProtectionSource",actorId:uuid,at:timestamp(6) with time zone' THEN
    RAISE EXCEPTION 'skyddad 340: PersonProtectionEvents holds %', v;
  END IF;
  IF enum_range(NULL::"PersonProtectionSource")::text <> '{SS12000,MANUAL}' OR enum_range(NULL::"PersonProtectionAction")::text <> '{ADDED,REMOVED}' THEN
    RAISE EXCEPTION 'skyddad 340: the sources are %, the actions %', enum_range(NULL::"PersonProtectionSource"), enum_range(NULL::"PersonProtectionAction");
  END IF;
  SELECT string_agg(a.attname, ', ') INTO v FROM pg_attribute a
   WHERE a.attrelid = 'public."Users"'::regclass AND a.attnum > 0 AND NOT a.attisdropped
     AND a.attname ~* 'protect|skydd|secur|marking|sekretess';
  IF v IS NOT NULL THEN
    RAISE EXCEPTION 'skyddad 340: Users has % (teachers, guardians and the person read Users)', v;
  END IF;
  FOREACH t IN ARRAY ARRAY['PersonProtections', 'PersonProtectionEvents'] LOOP
    IF (SELECT relrowsecurity FROM pg_class WHERE oid = format('public.%I', t)::regclass) IS NOT TRUE THEN
      RAISE EXCEPTION 'skyddad 340: row security is off on %', t;
    END IF;
  END LOOP;

  -- The keys: with the person, with the school; ids never rewritten. A row
  -- per person and source, the school in the key; the history keyed to
  -- the school alone, so it outlives the person.
  SELECT string_agg(c.conname || '=' || c.confdeltype::text || c.confupdtype::text || ':' || c.confrelid::regclass::text, ',' ORDER BY c.conname) INTO v
    FROM pg_constraint c WHERE c.conrelid IN ('public."PersonProtections"'::regclass, 'public."PersonProtectionEvents"'::regclass) AND c.contype = 'f';
  IF v IS DISTINCT FROM 'PersonProtectionEvents_schoolId_fkey=ca:"Schools",PersonProtections_schoolId_fkey=ca:"Schools",PersonProtections_userId_schoolId_fkey=ca:"Users"' THEN
    RAISE EXCEPTION 'skyddad 340: the keys are %', v;
  END IF;
  SELECT pg_get_constraintdef(c.oid) INTO v FROM pg_constraint c WHERE c.conname = 'PersonProtections_pkey';
  IF v IS DISTINCT FROM 'PRIMARY KEY ("userId", "schoolId", source)' THEN
    RAISE EXCEPTION 'skyddad 340: the marks'' key is %', v;
  END IF;

  -- Eight arms, the API's alone; the delete the decisions'.
  SELECT string_agg(policyname || ':' || cmd || ':' || roles::text, ',' ORDER BY policyname) INTO v
    FROM pg_policies WHERE schemaname = 'public' AND tablename IN ('PersonProtections', 'PersonProtectionEvents');
  IF v IS DISTINCT FROM 'person_protection_events_admin_select:SELECT:{app_authenticated},person_protections_admin_delete:DELETE:{app_authenticated},person_protections_admin_insert:INSERT:{app_authenticated},person_protections_admin_select:SELECT:{app_authenticated},person_protections_admin_update:UPDATE:{app_authenticated},person_protections_sync_insert:INSERT:{app_authenticated},person_protections_sync_select:SELECT:{app_authenticated},person_protections_sync_update:UPDATE:{app_authenticated}' THEN
    RAISE EXCEPTION 'skyddad 340: the arms are %', v;
  END IF;
  IF (SELECT qual FROM pg_policies WHERE policyname = 'person_protections_admin_delete') NOT LIKE '%current_user_decides()%' THEN
    RAISE EXCEPTION 'skyddad 340: a mark is removed by others than those who decide';
  END IF;

  -- Grants.
  IF NOT (has_table_privilege('app_authenticated', 'public."PersonProtections"', 'SELECT')
          AND has_table_privilege('app_authenticated', 'public."PersonProtections"', 'INSERT')
          AND has_table_privilege('app_authenticated', 'public."PersonProtections"', 'DELETE')
          AND has_table_privilege('app_authenticated', 'public."PersonProtectionEvents"', 'SELECT'))
     OR has_table_privilege('app_authenticated', 'public."PersonProtections"', 'UPDATE')
     OR has_table_privilege('app_authenticated', 'public."PersonProtections"', 'TRUNCATE')
     OR has_table_privilege('app_authenticated', 'public."PersonProtections"', 'REFERENCES')
     OR has_table_privilege('app_authenticated', 'public."PersonProtections"', 'TRIGGER')
     OR has_table_privilege('app_authenticated', 'public."PersonProtectionEvents"', 'INSERT')
     OR has_table_privilege('app_authenticated', 'public."PersonProtectionEvents"', 'UPDATE')
     OR has_table_privilege('app_authenticated', 'public."PersonProtectionEvents"', 'DELETE')
     OR has_table_privilege('app_authenticated', 'public."PersonProtectionEvents"', 'TRUNCATE') THEN
    RAISE EXCEPTION 'skyddad 340: the API''s role holds % on the marks and % on the history',
      (SELECT relacl FROM pg_class WHERE oid = 'public."PersonProtections"'::regclass),
      (SELECT relacl FROM pg_class WHERE oid = 'public."PersonProtectionEvents"'::regclass);
  END IF;
  FOREACH t IN ARRAY ARRAY['PersonProtections', 'PersonProtectionEvents'] LOOP
    FOREACH r IN ARRAY ARRAY['authenticated', 'anon'] LOOP
      IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r)
         AND (has_table_privilege(r, format('public.%I', t), 'SELECT') OR has_table_privilege(r, format('public.%I', t), 'INSERT')
              OR has_table_privilege(r, format('public.%I', t), 'UPDATE') OR has_table_privilege(r, format('public.%I', t), 'DELETE')
              OR has_table_privilege(r, format('public.%I', t), 'TRUNCATE') OR has_table_privilege(r, format('public.%I', t), 'REFERENCES')
              OR has_table_privilege(r, format('public.%I', t), 'TRIGGER')) THEN
        RAISE EXCEPTION 'skyddad 340: % holds a privilege on %', r, t;
      END IF;
    END LOOP;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role')
       AND (has_table_privilege('service_role', format('public.%I', t), 'INSERT') OR has_table_privilege('service_role', format('public.%I', t), 'UPDATE')
            OR has_table_privilege('service_role', format('public.%I', t), 'DELETE') OR has_table_privilege('service_role', format('public.%I', t), 'TRUNCATE')) THEN
      RAISE EXCEPTION 'skyddad 340: service_role writes %', t;
    END IF;
    IF current_setting('server_version_num')::int >= 170000 THEN
      FOREACH r IN ARRAY ARRAY['authenticated', 'app_authenticated', 'service_role', 'anon'] LOOP
        IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
          EXECUTE format('SELECT has_table_privilege(%L, %L, %L)', r, format('public.%I', t), 'MAINTAIN') INTO v;
          IF v::boolean THEN RAISE EXCEPTION 'skyddad 340: % holds MAINTAIN on %', r, t; END IF;
        END IF;
      END LOOP;
    END IF;
  END LOOP;

  -- The history is written by its trigger, on every write of a mark.
  SELECT string_agg(tgname, ',' ORDER BY tgname) INTO v FROM pg_trigger
   WHERE tgrelid IN ('public."PersonProtections"'::regclass, 'public."PersonProtectionEvents"'::regclass) AND NOT tgisinternal;
  IF v IS DISTINCT FROM 'PersonProtectionEvents_no_truncate,PersonProtectionEvents_written_by_trigger,PersonProtections_events,PersonProtections_ss12000_versions' THEN
    RAISE EXCEPTION 'skyddad 340: the triggers are %', v;
  END IF;

  -- The sync's change, and the CHECK that keeps its person out of the ids a finished run keeps.
  IF NOT ('PROTECTION' = ANY (enum_range(NULL::"Ss12000ChangeEntity")::text[])) THEN
    RAISE EXCEPTION 'skyddad 340: Ss12000ChangeEntity has no PROTECTION';
  END IF;
  SELECT pg_get_constraintdef(c.oid) INTO v FROM pg_constraint c
   WHERE c.conrelid = 'public."Ss12000SyncChanges"'::regclass AND c.conname = 'Ss12000SyncChanges_a_mark_names_its_person_in_after_alone';
  IF v IS NULL OR v NOT LIKE '%"externalId" IS NULL%' OR v NOT LIKE '%"localId" IS NULL%' THEN
    RAISE EXCEPTION 'skyddad 340: the CHECK on a mark''s change is %', v;
  END IF;

  -- Gallring's lines.
  IF (SELECT prosrc FROM pg_proc WHERE oid = 'app.gallring_pseudonymise(uuid, uuid[])'::regprocedure) NOT LIKE '%DELETE FROM "PersonProtections"%' THEN
    RAISE EXCEPTION 'skyddad 340: pseudonymisation leaves the mark';
  END IF;
  IF (SELECT prosrc FROM pg_proc WHERE oid = 'app.gallring_due(uuid, "RetentionDataType", date, date)'::regprocedure) NOT LIKE '%"PersonProtectionEvents"%'
     OR (SELECT prosrc FROM pg_proc WHERE oid = 'app.gallring_purge(uuid, "RetentionDataType", integer)'::regprocedure) NOT LIKE '%DELETE FROM "PersonProtectionEvents"%' THEN
    RAISE EXCEPTION 'skyddad 340: gallring does not purge the marks'' history';
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 341: vem som läser och skriver markeringen och historiken. Every
-- administrator profile reads the school's four marks and their history, and
-- nothing of the other school's; full, rektor and the expedition (Personal)
-- set a mark by hand, beside the register's too; only full and rektor (the
-- decisions) remove one; the planner and the läsare are refused the set.
-- The history names who did what. A teacher (a marked one too), a pupil and
-- a guardian read nothing and write nothing. Nobody changes a mark's
-- person, school or source (the kind: section 361), or writes the history. The other school's administrator reads its own, cannot write
-- for this school, and is answered the same (23503, the person key) whether
-- this school's person is marked or not. PostgREST's role is refused both.
-- ---------------------------------------------------------------------------

BEGIN;
CREATE FUNCTION pg_temp.sk_refuses(stmt text, expected text, what text) RETURNS void LANGUAGE plpgsql AS $f$
DECLARE got text := 'none';
BEGIN
  BEGIN
    EXECUTE stmt;
  EXCEPTION WHEN OTHERS THEN
    got := SQLSTATE;
  END;
  IF got IS DISTINCT FROM expected THEN
    RAISE EXCEPTION 'skyddad: % should be refused with %, was %', what, expected, got USING ERRCODE = 'P0001';
  END IF;
END
$f$;
CREATE FUNCTION pg_temp.sk_as(auth text) RETURNS void LANGUAGE sql AS $f$
  SELECT set_config('request.jwt.claims', json_build_object('sub', auth)::text, true);
  SELECT set_config('request.headers', '', true);
$f$;
DO $$
DECLARE
  school uuid;
  other uuid;
  p2 uuid;
  p1 uuid;
  t1 uuid;
  full_admin uuid;
  other_pupil uuid;
  other_admin uuid;
  who text;
  n bigint;
  v text;
BEGIN
  PERFORM pg_temp.sk_as('00000000-0000-4000-8000-e50000000001');
  school := app.current_school_id();
  full_admin := app.current_user_id();
  IF school IS NULL OR (SELECT slug FROM "Schools" WHERE id = school) IS DISTINCT FROM 'rls-skyddad-school' THEN
    RAISE EXCEPTION 'skyddad 341: the full administrator is not in rls-skyddad-school; fixtures did not run';
  END IF;
  SELECT id INTO p1 FROM "Users" WHERE "schoolId" = school AND email = 'sk-p1@example.invalid';
  SELECT id INTO p2 FROM "Users" WHERE "schoolId" = school AND email = 'sk-p2@example.invalid';
  SELECT id INTO t1 FROM "Users" WHERE "schoolId" = school AND email = 'sk-t1@example.invalid';
  PERFORM pg_temp.sk_as('00000000-0000-4000-8000-e50000000031');
  other := app.current_school_id();
  SELECT id INTO other_pupil FROM "Users" WHERE "schoolId" = other AND role = 'STUDENT';
  other_admin := app.current_user_id();
  IF p1 IS NULL OR p2 IS NULL OR other_pupil IS NULL OR other_admin IS NULL THEN
    RAISE EXCEPTION 'skyddad 341: the fixtures lack P1, P2 or the other school''s people';
  END IF;

  -- Every administrator profile reads the four marks and the history, none of the other school's.
  FOREACH who IN ARRAY ARRAY['01', '02', '03', '04', '05'] LOOP
    PERFORM pg_temp.sk_as('00000000-0000-4000-8000-e500000000' || who);
    IF app.current_user_role() IS DISTINCT FROM 'SCHOOL_ADMIN' THEN RAISE EXCEPTION 'skyddad 341: …%: expected an administrator', who; END IF;
    SELECT count(*) INTO n FROM "PersonProtections";
    IF n <> 4 THEN RAISE EXCEPTION 'skyddad 341: administrator …% reads % marks, not the school''s four', who, n; END IF;
    SELECT count(*) INTO n FROM "PersonProtectionEvents" WHERE action = 'ADDED';
    IF n < 4 THEN RAISE EXCEPTION 'skyddad 341: administrator …% reads % ADDED events, not the four marks''', who, n; END IF;
    SELECT count(*) INTO n FROM "PersonProtectionEvents" WHERE "schoolId" <> school;
    IF n <> 0 THEN RAISE EXCEPTION 'skyddad 341: administrator …% reads another school''s history', who; END IF;
    PERFORM pg_temp.sk_refuses(format($q$UPDATE "PersonProtections" SET source = 'MANUAL' WHERE "userId" = %L$q$, p1),
                               '42501', 'an administrator''s update of a mark');
    PERFORM pg_temp.sk_refuses(format($q$INSERT INTO "PersonProtectionEvents" ("schoolId", "userId", action, source) VALUES (%L, %L, 'ADDED', 'MANUAL')$q$, school, p2),
                               '42501', 'an administrator writing the history');
    PERFORM pg_temp.sk_refuses(format($q$DELETE FROM "PersonProtectionEvents" WHERE "schoolId" = %L$q$, school),
                               '42501', 'an administrator removing the history');
  END LOOP;

  -- Personal's writers set a mark by hand; never in another school's name.
  FOREACH who IN ARRAY ARRAY['01', '02', '03'] LOOP
    PERFORM pg_temp.sk_as('00000000-0000-4000-8000-e500000000' || who);
    INSERT INTO "PersonProtections" ("userId", "schoolId", source) VALUES (p2, school, 'MANUAL');
    -- A mark by hand beside the register's: a row of its own.
    INSERT INTO "PersonProtections" ("userId", "schoolId", source) VALUES (p1, school, 'MANUAL');
    SELECT count(*) INTO n FROM "PersonProtections" WHERE "userId" = p1;
    IF n <> 2 THEN RAISE EXCEPTION 'skyddad 341: P1 holds % marks, not the register''s and one by hand', n; END IF;
    PERFORM pg_temp.sk_refuses(format($q$INSERT INTO "PersonProtections" ("userId", "schoolId", source) VALUES (%L, %L, 'MANUAL')$q$, other_pupil, other),
                               '42501', 'a mark in another school');
    -- The person key decides, marked or not: no answer tells one school of another's marks.
    PERFORM pg_temp.sk_refuses(format($q$INSERT INTO "PersonProtections" ("userId", "schoolId", source) VALUES (%L, %L, 'MANUAL')$q$, other_admin, school),
                               '23503', 'another school''s unmarked person marked in this school''s name');
    PERFORM pg_temp.sk_refuses(format($q$INSERT INTO "PersonProtections" ("userId", "schoolId", source) VALUES (%L, %L, 'MANUAL')$q$, other_pupil, school),
                               '23503', 'another school''s marked person marked in this school''s name');
    IF who = '03' THEN
      -- The expedition does not remove one: a decision.
      DELETE FROM "PersonProtections" WHERE "userId" IN (p1, p2) AND source = 'MANUAL';
      GET DIAGNOSTICS n = ROW_COUNT;
      IF n <> 0 THEN RAISE EXCEPTION 'skyddad 341: the expedition removed % marks', n; END IF;
      PERFORM pg_temp.sk_as('00000000-0000-4000-8000-e50000000001');
    END IF;
    DELETE FROM "PersonProtections" WHERE "userId" IN (p1, p2) AND source = 'MANUAL';
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n <> 2 THEN RAISE EXCEPTION 'skyddad 341: removed % marks by hand, not the two set (…%)', n, who; END IF;
    SELECT count(*) INTO n FROM "PersonProtections" WHERE "userId" = p1 AND source = 'SS12000';
    IF n <> 1 THEN RAISE EXCEPTION 'skyddad 341: removing the mark by hand took the register''s'; END IF;
  END LOOP;

  -- The history says who: the expedition set P2's mark, the full administrator removed it.
  PERFORM pg_temp.sk_as('00000000-0000-4000-8000-e50000000001');
  SELECT string_agg(e.action || ':' || e.source || ':' || coalesce(u.email, '-'), ',' ORDER BY e."at", e.action) INTO v
    FROM "PersonProtectionEvents" e LEFT JOIN "Users" u ON u.id = e."actorId"
   WHERE e."userId" = p2 AND e."at" > now() - interval '1 minute' AND e."actorId" IS NOT NULL;
  IF v IS NULL OR v NOT LIKE '%ADDED:MANUAL:sk-expedition@example.invalid%' OR v NOT LIKE '%REMOVED:MANUAL:sk-full@example.invalid%' THEN
    RAISE EXCEPTION 'skyddad 341: the history of P2''s marks is %', v;
  END IF;

  -- The planner and the läsare read and do not write.
  FOREACH who IN ARRAY ARRAY['04', '05'] LOOP
    PERFORM pg_temp.sk_as('00000000-0000-4000-8000-e500000000' || who);
    PERFORM pg_temp.sk_refuses(format($q$INSERT INTO "PersonProtections" ("userId", "schoolId", source) VALUES (%L, %L, 'MANUAL')$q$, p2, school),
                               '42501', format('administrator …%s setting a mark', who));
    DELETE FROM "PersonProtections" WHERE "userId" = p1;
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n <> 0 THEN RAISE EXCEPTION 'skyddad 341: administrator …% removed a mark', who; END IF;
  END LOOP;

  -- A teacher (the marked one too), a pupil, a guardian: nothing, of the marks or the history.
  FOREACH who IN ARRAY ARRAY['06', '07', '11', '12', '21', '22'] LOOP
    PERFORM pg_temp.sk_as('00000000-0000-4000-8000-e500000000' || who);
    IF app.current_user_role() IS NULL OR app.current_user_role() = 'SCHOOL_ADMIN' THEN
      RAISE EXCEPTION 'skyddad 341: …% did not resolve as a teacher, pupil or guardian', who;
    END IF;
    SELECT (SELECT count(*) FROM "PersonProtections") + (SELECT count(*) FROM "PersonProtectionEvents") INTO n;
    IF n <> 0 THEN RAISE EXCEPTION 'skyddad 341: % …% reads % marks or events', app.current_user_role(), who, n; END IF;
    PERFORM pg_temp.sk_refuses(format($q$INSERT INTO "PersonProtections" ("userId", "schoolId", source) VALUES (%L, %L, 'MANUAL')$q$, p2, school),
                               '42501', format('%s …%s setting a mark', app.current_user_role(), who));
    DELETE FROM "PersonProtections" WHERE "schoolId" = school;
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n <> 0 THEN RAISE EXCEPTION 'skyddad 341: % …% removed % marks', app.current_user_role(), who, n; END IF;
  END LOOP;

  -- The other school's administrator: its one mark and its history, none of these.
  PERFORM pg_temp.sk_as('00000000-0000-4000-8000-e50000000031');
  SELECT count(*) INTO n FROM "PersonProtections";
  IF n <> 1 THEN RAISE EXCEPTION 'skyddad 341: the other school''s administrator reads % marks, not its one', n; END IF;
  SELECT (SELECT count(*) FROM "PersonProtections" WHERE "schoolId" = school) + (SELECT count(*) FROM "PersonProtectionEvents" WHERE "schoolId" = school) INTO n;
  IF n <> 0 THEN RAISE EXCEPTION 'skyddad 341: the other school reads this school''s marks or history'; END IF;

  PERFORM set_config('app.test_rls34_p2', p2::text, true);
  PERFORM set_config('app.test_rls34_school', school::text, true);
END $$;

-- PostgREST's role, as the full administrator: no grant at all.
SET LOCAL ROLE authenticated;
DO $$
BEGIN
  IF app.current_user_role() IS DISTINCT FROM 'SCHOOL_ADMIN' THEN RAISE EXCEPTION 'skyddad 341: expected the administrator as authenticated'; END IF;
  PERFORM pg_temp.sk_refuses('SELECT count(*) FROM "PersonProtections"', '42501', 'PostgREST''s read of the marks');
  PERFORM pg_temp.sk_refuses('SELECT count(*) FROM "PersonProtectionEvents"', '42501', 'PostgREST''s read of the history');
  PERFORM pg_temp.sk_refuses(format($q$INSERT INTO "PersonProtections" ("userId", "schoolId", source) VALUES (%L, %L, 'MANUAL')$q$,
                                    current_setting('app.test_rls34_p2'), current_setting('app.test_rls34_school')),
                             '42501', 'PostgREST''s write of a mark');
END $$;
SET LOCAL ROLE app_authenticated;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 342: synkens principal. With no login and the school's sync id it
-- reads the school's marks and nobody else's, sets its own beside an
-- administrator's, and is refused one by hand or in another school; it
-- removes nothing (a lift is never automatic: an administrator's apply makes
-- it) and reads no history. Its writes are in the history with no actor.
-- ---------------------------------------------------------------------------

BEGIN;
CREATE FUNCTION pg_temp.sk_refuses(stmt text, expected text, what text) RETURNS void LANGUAGE plpgsql AS $f$
DECLARE got text := 'none';
BEGIN
  BEGIN
    EXECUTE stmt;
  EXCEPTION WHEN OTHERS THEN
    got := SQLSTATE;
  END;
  IF got IS DISTINCT FROM expected THEN
    RAISE EXCEPTION 'skyddad: % should be refused with %, was %', what, expected, got USING ERRCODE = 'P0001';
  END IF;
END
$f$;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-e50000000001')::text, true);
DO $$
BEGIN
  PERFORM set_config('app.test_rls34_school', app.current_school_id()::text, true);
  PERFORM set_config('app.test_rls34_p2', (SELECT id::text FROM "Users" WHERE email = 'sk-p2@example.invalid'), true);
  PERFORM set_config('app.test_rls34_t1', (SELECT id::text FROM "Users" WHERE email = 'sk-t1@example.invalid'), true);
  PERFORM set_config('app.test_rls34_t2', (SELECT id::text FROM "Users" WHERE email = 'sk-t2@example.invalid'), true);
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-e50000000031')::text, true);
DO $$
BEGIN
  PERFORM set_config('app.test_rls34_other', app.current_school_id()::text, true);
  PERFORM set_config('app.test_rls34_other_pupil', (SELECT id::text FROM "Users" WHERE role = 'STUDENT'), true);
END $$;
SELECT set_config('request.jwt.claims', '', true);
SELECT set_config('app.sync_school_id', current_setting('app.test_rls34_school'), true);
DO $$
DECLARE
  school uuid := current_setting('app.test_rls34_school')::uuid;
  p2 uuid := current_setting('app.test_rls34_p2')::uuid;
  t1 uuid := current_setting('app.test_rls34_t1')::uuid;
  n bigint;
BEGIN
  IF app.current_user_id() IS NOT NULL OR app.current_sync_school_id() IS DISTINCT FROM school THEN
    RAISE EXCEPTION 'skyddad 342: expected the sync principal and no login';
  END IF;
  SELECT count(*) INTO n FROM "PersonProtections";
  IF n <> 4 THEN RAISE EXCEPTION 'skyddad 342: the sync reads % marks, not the school''s four', n; END IF;
  SELECT count(*) INTO n FROM "PersonProtectionEvents";
  IF n <> 0 THEN RAISE EXCEPTION 'skyddad 342: the sync reads % events of the history', n; END IF;
  INSERT INTO "PersonProtections" ("userId", "schoolId", source) VALUES (p2, school, 'SS12000');
  -- T1 is marked by hand: the sync's mark is a row beside it.
  INSERT INTO "PersonProtections" ("userId", "schoolId", source) VALUES (t1, school, 'SS12000');
  SELECT count(*) INTO n FROM "PersonProtections" WHERE "userId" IN (p2, t1) AND source = 'SS12000';
  IF n <> 2 THEN RAISE EXCEPTION 'skyddad 342: the sync''s marks are not there'; END IF;
  DELETE FROM "PersonProtections" WHERE "userId" IN (p2, t1);
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'skyddad 342: the sync removed a mark'; END IF;
  -- An unmarked person (T2), so the arm decides and not the key.
  PERFORM pg_temp.sk_refuses(format($q$INSERT INTO "PersonProtections" ("userId", "schoolId", source) VALUES (%L, %L, 'MANUAL')$q$,
                                    current_setting('app.test_rls34_t2'), school),
                             '42501', 'a mark by hand from the sync');
  PERFORM pg_temp.sk_refuses(format($q$INSERT INTO "PersonProtections" ("userId", "schoolId", source) VALUES (%L, %L, 'SS12000')$q$,
                                    current_setting('app.test_rls34_other_pupil'), current_setting('app.test_rls34_other')),
                             '42501', 'the sync''s mark in another school');
END $$;
SELECT set_config('app.sync_school_id', current_setting('app.test_rls34_other'), true);
DO $$
DECLARE n bigint;
BEGIN
  SELECT count(*) INTO n FROM "PersonProtections" WHERE "schoolId" = current_setting('app.test_rls34_school')::uuid;
  IF n <> 0 THEN RAISE EXCEPTION 'skyddad 342: another school''s sync reads this school''s marks'; END IF;
END $$;
SELECT set_config('app.sync_school_id', '', true);
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-e50000000001')::text, true);
DO $$
DECLARE n bigint;
BEGIN
  SELECT count(*) INTO n FROM "PersonProtectionEvents"
   WHERE "userId" = current_setting('app.test_rls34_t1')::uuid AND action = 'ADDED' AND source = 'SS12000' AND "actorId" IS NULL;
  IF n <> 1 THEN RAISE EXCEPTION 'skyddad 342: the sync''s mark is % times in the history, as nobody''s', n; END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 343: markeringen följer personen, och historiken gallras med
-- ändringsloggarna. A person removed takes their marks with them (the key),
-- and the history says it, outliving the person; gallring's pseudonymisation
-- of a departed person (P3) removes theirs and nobody else's; gallring under
-- CHANGE_LOGS (the school decided 12 months) takes the history's old event
-- and keeps the fresh ones.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-e50000000001')::text, true);
DO $$
DECLARE
  school uuid := app.current_school_id();
  newcomer uuid;
  n bigint;
BEGIN
  INSERT INTO "Users" ("schoolId", email, "firstName", "lastName", role, "authId", "isActive", "updatedAt")
  VALUES (school, 'sk-new@example.invalid', 'Skyddad', 'Ny', 'STUDENT', gen_random_uuid(), true, now()) RETURNING id INTO newcomer;
  INSERT INTO "PersonProtections" ("userId", "schoolId", source) VALUES (newcomer, school, 'MANUAL');
  DELETE FROM "Users" WHERE id = newcomer;
  SELECT count(*) INTO n FROM "PersonProtections" WHERE "userId" = newcomer;
  IF n <> 0 THEN RAISE EXCEPTION 'skyddad 343: a removed person''s mark stayed'; END IF;
  SELECT count(*) INTO n FROM "PersonProtectionEvents" WHERE "userId" = newcomer AND action = 'REMOVED' AND "actorId" = app.current_user_id();
  IF n <> 1 THEN RAISE EXCEPTION 'skyddad 343: the history does not say who removed the person and their mark'; END IF;
  PERFORM set_config('app.test_rls343_school', school::text, true);
  PERFORM set_config('app.test_rls343_p3', (SELECT id::text FROM "Users" WHERE "schoolId" = school AND email = 'sk-p3@example.invalid'), true);
  SELECT count(*) INTO n FROM "PersonProtections";
  IF n <> 4 THEN RAISE EXCEPTION 'skyddad 343: the school has % marks before gallring, not four', n; END IF;
  SELECT count(*) INTO n FROM "PersonProtectionEvents" WHERE "at" < now() - interval '1 year';
  IF n <> 1 THEN RAISE EXCEPTION 'skyddad 343: the fixtures'' old event is not there (% found)', n; END IF;
  PERFORM set_config('app.test_rls343_fresh', (SELECT count(*)::text FROM "PersonProtectionEvents" WHERE "at" > now() - interval '1 month'), true);
END $$;

-- The night, with no principal.
SELECT set_config('request.jwt.claims', '', true);
DO $$
DECLARE
  run uuid := app.gallring_begin(current_setting('app.test_rls343_school')::uuid, now());
BEGIN
  IF app.gallring_pseudonymise(run, ARRAY[current_setting('app.test_rls343_p3')::uuid]) <> 1 THEN
    RAISE EXCEPTION 'skyddad 343: the departed pupil was not pseudonymised';
  END IF;
  IF app.gallring_purge(run, 'CHANGE_LOGS', 5000) <> 1 THEN
    RAISE EXCEPTION 'skyddad 343: the change logs'' gallring took other than the history''s one old event';
  END IF;
END $$;

SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-e50000000001')::text, true);
DO $$
DECLARE
  p3 uuid := current_setting('app.test_rls343_p3')::uuid;
  n bigint;
BEGIN
  IF (SELECT "pseudonymisedAt" FROM "Users" WHERE id = p3) IS NULL THEN
    RAISE EXCEPTION 'skyddad 343: P3 is not a pseudonym';
  END IF;
  SELECT count(*) INTO n FROM "PersonProtections" WHERE "userId" = p3;
  IF n <> 0 THEN RAISE EXCEPTION 'skyddad 343: the pseudonym kept its mark'; END IF;
  SELECT count(*) INTO n FROM "PersonProtections";
  IF n <> 3 THEN RAISE EXCEPTION 'skyddad 343: gallring took % marks, not P3''s alone', 4 - n; END IF;
  SELECT count(*) INTO n FROM "PersonProtectionEvents" WHERE "userId" = p3 AND action = 'REMOVED' AND "actorId" IS NULL;
  IF n <> 1 THEN RAISE EXCEPTION 'skyddad 343: the pseudonymisation is not in the history as nobody''s'; END IF;
  SELECT count(*) INTO n FROM "PersonProtectionEvents" WHERE "at" < now() - interval '1 year';
  IF n <> 0 THEN RAISE EXCEPTION 'skyddad 343: the history''s old event outlived the school''s 12 months'; END IF;
  SELECT count(*) INTO n FROM "PersonProtectionEvents" WHERE "at" > now() - interval '1 month';
  IF n < current_setting('app.test_rls343_fresh')::bigint THEN RAISE EXCEPTION 'skyddad 343: gallring took a fresh event'; END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 344: synkens ändring som sätter eller lyfter en markering. It is
-- PROTECTION ADD, UPDATE (the register's kind, 20270111090000) or END, with
-- no externalId and no localId (the CHECK): the
-- person is in its after alone, which the minimisation nulls when the run
-- ends. A finished run then says how many marks it set, never whose.
-- ---------------------------------------------------------------------------

BEGIN;
CREATE FUNCTION pg_temp.sk_refuses(stmt text, expected text, what text) RETURNS void LANGUAGE plpgsql AS $f$
DECLARE got text := 'none';
BEGIN
  BEGIN
    EXECUTE stmt;
  EXCEPTION WHEN OTHERS THEN
    got := SQLSTATE;
  END;
  IF got IS DISTINCT FROM expected THEN
    RAISE EXCEPTION 'skyddad: % should be refused with %, was %', what, expected, got USING ERRCODE = 'P0001';
  END IF;
END
$f$;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-e50000000001')::text, true);
DO $$
DECLARE
  school uuid := app.current_school_id();
  src uuid;
BEGIN
  INSERT INTO "Ss12000Sources" ("schoolId", name, "baseUrl", "authKind", "tokenUrl", "clientId", "organisationIds")
  VALUES (school, 'RLS 344', 'https://api.ist.example/ss12000v2-api/source/SE00344/v2.0', 'OAUTH2_CLIENT_CREDENTIALS',
          'https://skolid.example/connect/token', 'rls344', ARRAY['aaaaaaaa-0000-4000-8000-000000000344']::uuid[])
  RETURNING id INTO src;
  PERFORM set_config('app.test_rls344_school', school::text, true);
  PERFORM set_config('app.test_rls344_source', src::text, true);
  PERFORM set_config('app.test_rls344_p2', (SELECT id::text FROM "Users" WHERE "schoolId" = school AND email = 'sk-p2@example.invalid'), true);
END $$;
SELECT set_config('request.jwt.claims', '', true);
SELECT set_config('app.sync_school_id', current_setting('app.test_rls344_school'), true);
DO $$
DECLARE
  school uuid := current_setting('app.test_rls344_school')::uuid;
  p2 uuid := current_setting('app.test_rls344_p2')::uuid;
  run uuid;
BEGIN
  INSERT INTO "Ss12000SyncRuns" ("schoolId", "sourceId", "trigger", "mode")
  VALUES (school, current_setting('app.test_rls344_source')::uuid, 'SCHEDULED', 'FULL') RETURNING id INTO run;
  PERFORM set_config('app.test_rls344_run', run::text, true);
  PERFORM pg_temp.sk_refuses(format($q$INSERT INTO "Ss12000SyncChanges" ("runId", "schoolId", seq, entity, op, "externalId", after, selected, "autoApplicable")
                                       VALUES (%L, %L, 0, 'PROTECTION', 'ADD', gen_random_uuid(), '{}', true, true)$q$, run, school),
                             '23514', 'a mark''s change naming its person by the register''s id');
  PERFORM pg_temp.sk_refuses(format($q$INSERT INTO "Ss12000SyncChanges" ("runId", "schoolId", seq, entity, op, "localId", after, selected, "autoApplicable")
                                       VALUES (%L, %L, 0, 'PROTECTION', 'ADD', %L, '{}', true, true)$q$, run, school, p2),
                             '23514', 'a mark''s change naming its person by the row''s id');
  PERFORM pg_temp.sk_refuses(format($q$INSERT INTO "Ss12000SyncChanges" ("runId", "schoolId", seq, entity, op, after, selected)
                                       VALUES (%L, %L, 0, 'PROTECTION', 'MOVE', '{}', true)$q$, run, school),
                             '23514', 'a mark''s change that is neither ADD, UPDATE nor END');
  INSERT INTO "Ss12000SyncChanges" ("runId", "schoolId", seq, entity, op, after, selected, "autoApplicable")
  VALUES (run, school, 0, 'PROTECTION', 'ADD', jsonb_build_object('personExternalId', gen_random_uuid(), 'userLocalId', p2), true, true),
         (run, school, 1, 'PROTECTION', 'END', jsonb_build_object('personExternalId', gen_random_uuid(), 'userLocalId', p2), true, false),
         (run, school, 2, 'PROTECTION', 'UPDATE', jsonb_build_object('personExternalId', gen_random_uuid(), 'userLocalId', p2, 'kind', 'SKYDDAD_FOLKBOKFORING'), true, true);
  UPDATE "Ss12000SyncRuns" SET status = 'DIFF_READY', "basisHash" = repeat('c', 64), "fetchedAt" = now() WHERE id = run;
  UPDATE "Ss12000SyncRuns" SET status = 'APPLIED', "appliedAt" = now(), "finishedAt" = now() WHERE id = run;
END $$;
SELECT set_config('app.sync_school_id', '', true);
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-e50000000001')::text, true);
DO $$
DECLARE
  n bigint;
  named bigint;
BEGIN
  SELECT count(*), count(*) FILTER (WHERE after IS NOT NULL OR before IS NOT NULL OR "externalId" IS NOT NULL OR "localId" IS NOT NULL)
    INTO n, named
    FROM "Ss12000SyncChanges" WHERE "runId" = current_setting('app.test_rls344_run')::uuid AND entity = 'PROTECTION';
  IF n <> 3 THEN RAISE EXCEPTION 'skyddad 344: the finished run has % marks'' changes, not three', n; END IF;
  IF named <> 0 THEN RAISE EXCEPTION 'skyddad 344: % of the finished run''s marks still name their person', named; END IF;
  PERFORM pg_temp.sk_refuses(format($q$UPDATE "Ss12000SyncChanges" SET after = '{"userLocalId": "x"}' WHERE "runId" = %L AND entity = 'PROTECTION'$q$,
                                    current_setting('app.test_rls344_run')),
                             'SS409', 'a finished run''s mark named again');
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 355: hela skolans data i katalogen (K5, 20270114090000). Two
-- tables with their columns, keys and checks; the unique index that lets one
-- order be in hand per school; the four arms and no other, none for a
-- PostgREST role; the API's role may insert two columns and nothing is
-- updated; the six functions of the job are SECURITY DEFINER with a fixed
-- search_path and executable by the API's role alone; the trigger that names
-- whoever orders. PG 17's MAINTAIN is the owner's alone.
-- ---------------------------------------------------------------------------

BEGIN;
DO $$
DECLARE
  cols text;
  n integer;
  r text;
  t text;
  f text;
  def text;
BEGIN
  SELECT string_agg(a.attname || ':' || format_type(a.atttypid, a.atttypmod), ',' ORDER BY a.attnum) INTO cols
    FROM pg_attribute a WHERE a.attrelid = 'public."SchoolExports"'::regclass AND a.attnum > 0 AND NOT a.attisdropped;
  IF cols IS DISTINCT FROM 'id:uuid,schoolId:uuid,requestedById:uuid,status:"SchoolExportStatus",requestedAt:timestamp(6) with time zone,startedAt:timestamp(6) with time zone,heartbeatAt:timestamp(6) with time zone,finishedAt:timestamp(6) with time zone,expiresAt:timestamp(6) with time zone,attempts:integer,byteSize:bigint,chunkCount:integer,sha256:text,files:jsonb,heldOut:jsonb,readAbout:jsonb,errorClass:text' THEN
    RAISE EXCEPTION 'export 355: SchoolExports has the columns %', cols;
  END IF;
  SELECT string_agg(a.attname || ':' || format_type(a.atttypid, a.atttypmod), ',' ORDER BY a.attnum) INTO cols
    FROM pg_attribute a WHERE a.attrelid = 'public."SchoolExportChunks"'::regclass AND a.attnum > 0 AND NOT a.attisdropped;
  IF cols IS DISTINCT FROM 'exportId:uuid,seq:integer,schoolId:uuid,bytes:bytea' THEN
    RAISE EXCEPTION 'export 355: SchoolExportChunks has the columns %', cols;
  END IF;

  -- Row security is on, and the arms are the four, for the API's role alone.
  IF (SELECT count(*) FROM pg_class WHERE oid IN ('public."SchoolExports"'::regclass, 'public."SchoolExportChunks"'::regclass) AND relrowsecurity) <> 2 THEN
    RAISE EXCEPTION 'export 355: row security is not on for both tables';
  END IF;
  SELECT string_agg(tablename || '.' || policyname || ':' || cmd || ':' || roles::text, ',' ORDER BY tablename, policyname) INTO def
    FROM pg_policies WHERE schemaname = 'public' AND tablename IN ('SchoolExports', 'SchoolExportChunks');
  IF def IS DISTINCT FROM 'SchoolExportChunks.school_export_chunks_select:SELECT:{app_authenticated},SchoolExports.school_exports_delete:DELETE:{app_authenticated},SchoolExports.school_exports_insert:INSERT:{app_authenticated},SchoolExports.school_exports_select:SELECT:{app_authenticated}' THEN
    RAISE EXCEPTION 'export 355: the arms are %', def;
  END IF;

  -- Privileges: select and delete the orders, insert two columns, update nothing, read the pieces.
  IF NOT (has_table_privilege('app_authenticated', 'public."SchoolExports"', 'SELECT') AND has_table_privilege('app_authenticated', 'public."SchoolExports"', 'DELETE')) THEN
    RAISE EXCEPTION 'export 355: the API role cannot select and delete its orders';
  END IF;
  FOREACH t IN ARRAY ARRAY['UPDATE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'] LOOP
    IF has_table_privilege('app_authenticated', 'public."SchoolExports"', t) OR has_table_privilege('app_authenticated', 'public."SchoolExportChunks"', t) THEN
      RAISE EXCEPTION 'export 355: the API role holds % on an export table', t;
    END IF;
  END LOOP;
  IF has_table_privilege('app_authenticated', 'public."SchoolExports"', 'INSERT') THEN
    RAISE EXCEPTION 'export 355: the API role may insert every column of SchoolExports';
  END IF;
  SELECT string_agg(a.attname, ',' ORDER BY a.attnum) INTO cols
    FROM pg_attribute a
   WHERE a.attrelid = 'public."SchoolExports"'::regclass AND a.attnum > 0 AND NOT a.attisdropped
     AND has_column_privilege('app_authenticated', 'public."SchoolExports"', a.attname, 'INSERT');
  IF cols IS DISTINCT FROM 'schoolId,requestedById' THEN
    RAISE EXCEPTION 'export 355: the API role may insert the columns %, not the school and the person', cols;
  END IF;
  IF has_any_column_privilege('app_authenticated', 'public."SchoolExports"', 'UPDATE') OR has_any_column_privilege('app_authenticated', 'public."SchoolExportChunks"', 'UPDATE')
     OR has_any_column_privilege('app_authenticated', 'public."SchoolExportChunks"', 'INSERT') THEN
    RAISE EXCEPTION 'export 355: the API role may write a column of the pieces or update an order';
  END IF;
  IF has_table_privilege('app_authenticated', 'public."SchoolExportChunks"', 'DELETE') OR NOT has_table_privilege('app_authenticated', 'public."SchoolExportChunks"', 'SELECT') THEN
    RAISE EXCEPTION 'export 355: the API role reads the pieces and deletes none';
  END IF;
  FOREACH r IN ARRAY ARRAY['authenticated', 'anon'] LOOP
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
      FOREACH t IN ARRAY ARRAY['public."SchoolExports"', 'public."SchoolExportChunks"'] LOOP
        IF has_any_column_privilege(r, t, 'SELECT') OR has_any_column_privilege(r, t, 'INSERT') OR has_any_column_privilege(r, t, 'UPDATE') OR has_table_privilege(r, t, 'DELETE') THEN
          RAISE EXCEPTION 'export 355: % holds a privilege on %', r, t;
        END IF;
      END LOOP;
    END IF;
  END LOOP;
  IF current_setting('server_version_num')::int >= 170000 THEN
    FOREACH r IN ARRAY ARRAY['authenticated', 'app_authenticated', 'service_role', 'anon'] LOOP
      IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) AND (has_table_privilege(r, 'public."SchoolExports"', 'MAINTAIN') OR has_table_privilege(r, 'public."SchoolExportChunks"', 'MAINTAIN')) THEN
        RAISE EXCEPTION 'export 355: % holds MAINTAIN on an export table', r;
      END IF;
    END LOOP;
  END IF;

  -- Keys: the school cascades; the person is set null on the person's column alone; the pieces follow their export.
  SELECT count(*) INTO n FROM pg_constraint c
   WHERE c.conrelid = 'public."SchoolExports"'::regclass AND c.contype = 'f' AND c.confrelid = 'public."Schools"'::regclass AND c.confdeltype = 'c';
  IF n <> 1 THEN RAISE EXCEPTION 'export 355: SchoolExports does not cascade with its school'; END IF;
  SELECT count(*) INTO n FROM pg_constraint c
   WHERE c.conrelid = 'public."SchoolExports"'::regclass AND c.contype = 'f' AND c.confrelid = 'public."Users"'::regclass AND c.confdeltype = 'n'
     AND c.confdelsetcols = ARRAY[(SELECT attnum FROM pg_attribute WHERE attrelid = 'public."SchoolExports"'::regclass AND attname = 'requestedById')];
  IF n <> 1 THEN RAISE EXCEPTION 'export 355: the person key is not SET NULL on requestedById alone'; END IF;
  SELECT count(*) INTO n FROM pg_constraint c
   WHERE c.conrelid = 'public."SchoolExportChunks"'::regclass AND c.contype = 'f' AND c.confrelid = 'public."SchoolExports"'::regclass AND c.confdeltype = 'c';
  IF n <> 1 THEN RAISE EXCEPTION 'export 355: the pieces do not cascade with their export'; END IF;
  FOREACH f IN ARRAY ARRAY['SchoolExports_attempts_are_few', 'SchoolExports_ready_has_its_file', 'SchoolExports_sha256_is_hex', 'SchoolExports_error_is_a_class',
                           'SchoolExports_failed_names_its_class', 'SchoolExports_keeps_for_at_most_fourteen_days', 'SchoolExportChunks_seq_is_counted_from_zero',
                           'SchoolExportChunks_a_piece_is_small'] LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = f AND contype = 'c') THEN RAISE EXCEPTION 'export 355: the check % is missing', f; END IF;
  END LOOP;
  SELECT pg_get_indexdef(i.indexrelid) INTO def FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid WHERE c.relname = 'SchoolExports_one_in_hand_per_school';
  IF def IS NULL OR def NOT LIKE 'CREATE UNIQUE INDEX%("schoolId")%QUEUED%RUNNING%' THEN
    RAISE EXCEPTION 'export 355: the index that allows one order in hand is %', def;
  END IF;
  SELECT attstorage::text INTO def FROM pg_attribute WHERE attrelid = 'public."SchoolExportChunks"'::regclass AND attname = 'bytes';
  IF def <> 'e' THEN RAISE EXCEPTION 'export 355: the pieces are stored %, not EXTERNAL (a zip does not compress twice)', def; END IF;

  -- Functions: definer, a fixed search_path, executable by the API role and by nobody the PUBLIC covers.
  FOREACH f IN ARRAY ARRAY['school_export_claim', 'school_export_heartbeat', 'school_export_put', 'school_export_finish', 'school_export_fail', 'school_export_expire'] LOOP
    SELECT count(*) INTO n FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace
     WHERE s.nspname = 'app' AND p.proname = f AND p.prosecdef AND p.proconfig::text LIKE '%search_path=%public%pg_temp%'
       AND has_function_privilege('app_authenticated', p.oid, 'EXECUTE')
       AND NOT has_function_privilege('authenticated', p.oid, 'EXECUTE') AND NOT has_function_privilege('anon', p.oid, 'EXECUTE');
    IF n <> 1 THEN RAISE EXCEPTION 'export 355: app.% is not a definer with a fixed search_path run by the API role alone', f; END IF;
  END LOOP;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'SchoolExports_name_the_orderer' AND tgrelid = 'public."SchoolExports"'::regclass AND tgtype & 2 = 2 AND tgtype & 4 = 4) THEN
    RAISE EXCEPTION 'export 355: the trigger that names the orderer is not a BEFORE INSERT trigger on SchoolExports';
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 356: vem som beställer och läser. Rektor and a full administrator
-- (those who decide) order for their own school in their own name, read its
-- orders and withdraw them; no other profile, no teacher, pupil or guardian
-- does any of it, and each reads nothing: not an order, not a piece. The
-- statement cannot name another person or another state, nor another school.
-- The other school's administrator orders and reads its own, none of this
-- school's. PostgREST's role is refused all of it.
-- ---------------------------------------------------------------------------

BEGIN;
CREATE FUNCTION pg_temp.se_refuses(stmt text, expected text, what text) RETURNS void LANGUAGE plpgsql AS $f$
DECLARE got text := 'none';
BEGIN
  BEGIN
    EXECUTE stmt;
  EXCEPTION WHEN OTHERS THEN
    got := SQLSTATE;
  END;
  IF got IS DISTINCT FROM expected THEN
    RAISE EXCEPTION 'export: % should be refused with %, was %', what, expected, got USING ERRCODE = 'P0001';
  END IF;
END
$f$;
CREATE FUNCTION pg_temp.se_as(auth text) RETURNS void LANGUAGE sql AS $f$
  SELECT set_config('request.jwt.claims', json_build_object('sub', auth)::text, true);
  SELECT set_config('request.headers', '', true);
$f$;
DO $$
DECLARE
  school uuid;
  other uuid;
  who text;
  mine uuid;
  theirs uuid;
  piece uuid;
  n bigint;
  orderer uuid;
  other_admin uuid;
  rektor uuid;
  full_admin uuid;
BEGIN
  PERFORM pg_temp.se_as('00000000-0000-4000-8000-e50000000001');
  school := app.current_school_id();
  full_admin := app.current_user_id();
  IF school IS NULL OR (SELECT slug FROM "Schools" WHERE id = school) IS DISTINCT FROM 'rls-skyddad-school' THEN
    RAISE EXCEPTION 'export 356: the full administrator is not in rls-skyddad-school; fixtures did not run';
  END IF;
  rektor := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-e50000000002');
  PERFORM pg_temp.se_as('00000000-0000-4000-8000-e50000000031');
  other := app.current_school_id();
  other_admin := app.current_user_id();

  -- The administrators who decide order in their own name, whatever the statement says.
  FOREACH who IN ARRAY ARRAY['01', '02'] LOOP
    PERFORM pg_temp.se_as('00000000-0000-4000-8000-e500000000' || who);
    orderer := app.current_user_id();
    INSERT INTO "SchoolExports" ("schoolId", "requestedById") VALUES (school, CASE WHEN who = '01' THEN rektor ELSE full_admin END) RETURNING id INTO mine;
    SELECT count(*) INTO n FROM "SchoolExports" WHERE id = mine AND "requestedById" = orderer AND status = 'QUEUED' AND "schoolId" = school;
    IF n <> 1 THEN RAISE EXCEPTION 'export 356: …% did not order in their own name as QUEUED', who; END IF;
    SELECT count(*) INTO n FROM "SchoolExports";
    IF n < 1 THEN RAISE EXCEPTION 'export 356: …% reads no order of the school', who; END IF;
    DELETE FROM "SchoolExports" WHERE id = mine;
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n <> 1 THEN RAISE EXCEPTION 'export 356: …% could not withdraw their order', who; END IF;
    PERFORM pg_temp.se_refuses(format($q$INSERT INTO "SchoolExports" ("schoolId", "requestedById") VALUES (%L, %L)$q$, other, orderer),
                               '42501', format('…%s ordering in another school', who));
    PERFORM pg_temp.se_refuses(format($q$INSERT INTO "SchoolExports" ("schoolId", "requestedById", status) VALUES (%L, %L, 'READY')$q$, school, orderer),
                               '42501', format('…%s ordering a file that is READY', who));
    PERFORM pg_temp.se_refuses(format($q$INSERT INTO "SchoolExports" ("schoolId", "requestedById", "byteSize") VALUES (%L, %L, 1)$q$, school, orderer),
                               '42501', format('…%s ordering with a size', who));
    PERFORM pg_temp.se_refuses(format($q$UPDATE "SchoolExports" SET status = 'READY' WHERE "schoolId" = %L$q$, school), '42501', format('…%s updating an order', who));
    PERFORM pg_temp.se_refuses(format($q$INSERT INTO "SchoolExportChunks" ("exportId", seq, "schoolId", bytes) VALUES (gen_random_uuid(), 0, %L, '\x00')$q$, school),
                               '42501', format('…%s writing a piece', who));
  END LOOP;

  -- Plant one finished file as the full administrator, through the job's functions (section 357 proves them).
  PERFORM pg_temp.se_as('00000000-0000-4000-8000-e50000000001');
  INSERT INTO "SchoolExports" ("schoolId", "requestedById") VALUES (school, rektor) RETURNING id INTO mine;
  PERFORM export_id FROM app.school_export_claim(interval '3 minutes') WHERE export_id = mine;
  IF NOT FOUND THEN RAISE EXCEPTION 'export 356: the claim did not take the planted order (is another export queued in the database?)'; END IF;
  PERFORM app.school_export_put(mine, 0, '\x0102030405'::bytea);
  PERFORM app.school_export_finish(mine, 5, 1, repeat('a', 64), '[]'::jsonb, '{"people":0,"links":0}'::jsonb, '{}'::jsonb, interval '72 hours');
  PERFORM set_config('app.test_rls356_export', mine::text, true);

  -- The other school orders and reads its own; this school's it neither sees nor withdraws.
  PERFORM pg_temp.se_as('00000000-0000-4000-8000-e50000000031');
  INSERT INTO "SchoolExports" ("schoolId", "requestedById") VALUES (other, other_admin) RETURNING id INTO theirs;
  SELECT count(*) INTO n FROM "SchoolExports" WHERE "schoolId" = school;
  IF n <> 0 THEN RAISE EXCEPTION 'export 356: the other school reads % of this school''s orders', n; END IF;
  SELECT count(*) INTO n FROM "SchoolExportChunks" WHERE "schoolId" = school;
  IF n <> 0 THEN RAISE EXCEPTION 'export 356: the other school reads % of this school''s pieces', n; END IF;
  DELETE FROM "SchoolExports" WHERE id = mine;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'export 356: the other school withdrew this school''s order'; END IF;
  SELECT count(*) INTO n FROM "SchoolExports" WHERE id = theirs;
  IF n <> 1 THEN RAISE EXCEPTION 'export 356: the other school cannot read its own order'; END IF;
  -- A delete with no WHERE reads no column, so the select arm does not hide the rows from the delete arm: it alone decides.
  DELETE FROM "SchoolExports";
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'export 356: the other school''s bare delete took % orders, not its own one', n; END IF;
  PERFORM pg_temp.se_as('00000000-0000-4000-8000-e50000000001');
  SELECT count(*) INTO n FROM "SchoolExports" WHERE id = mine;
  IF n <> 1 THEN RAISE EXCEPTION 'export 356: the other school''s delete took this school''s order'; END IF;

  -- The decisions read the pieces of a finished file; nobody else does, nor reads the order.
  FOREACH who IN ARRAY ARRAY['01', '02'] LOOP
    PERFORM pg_temp.se_as('00000000-0000-4000-8000-e500000000' || who);
    SELECT count(*) INTO n FROM "SchoolExportChunks" WHERE "exportId" = mine;
    IF n <> 1 THEN RAISE EXCEPTION 'export 356: …% reads % pieces of the finished file, not one', who, n; END IF;
  END LOOP;
  FOREACH who IN ARRAY ARRAY['03', '04', '05', '06', '07', '11', '12', '21', '22'] LOOP
    PERFORM pg_temp.se_as('00000000-0000-4000-8000-e500000000' || who);
    IF app.current_user_role() IS NULL THEN RAISE EXCEPTION 'export 356: …% did not resolve as a person of the school', who; END IF;
    SELECT (SELECT count(*) FROM "SchoolExports") + (SELECT count(*) FROM "SchoolExportChunks") INTO n;
    IF n <> 0 THEN RAISE EXCEPTION 'export 356: % …% reads % orders or pieces', app.current_user_role(), who, n; END IF;
    PERFORM pg_temp.se_refuses(format($q$INSERT INTO "SchoolExports" ("schoolId", "requestedById") VALUES (%L, %L)$q$, school, app.current_user_id()),
                               '42501', format('%s …%s ordering', app.current_user_role(), who));
    -- Bare, so that the delete arm answers alone (a WHERE on a column would be hidden by the select arm first).
    DELETE FROM "SchoolExports";
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n <> 0 THEN RAISE EXCEPTION 'export 356: % …% withdrew % orders', app.current_user_role(), who, n; END IF;
  END LOOP;
  PERFORM set_config('app.test_rls356_school', school::text, true);
  PERFORM set_config('app.test_rls356_piece_export', mine::text, true);
END $$;

-- PostgREST's role, as the full administrator: no grant at all.
SELECT pg_temp.se_as('00000000-0000-4000-8000-e50000000001');
SET LOCAL ROLE authenticated;
DO $$
BEGIN
  PERFORM pg_temp.se_refuses('SELECT count(*) FROM "SchoolExports"', '42501', 'PostgREST''s read of the orders');
  PERFORM pg_temp.se_refuses('SELECT count(*) FROM "SchoolExportChunks"', '42501', 'PostgREST''s read of the pieces');
  PERFORM pg_temp.se_refuses(format($q$INSERT INTO "SchoolExports" ("schoolId") VALUES (%L)$q$, current_setting('app.test_rls356_school')), '42501', 'PostgREST''s order');
  PERFORM pg_temp.se_refuses('SELECT app.school_export_claim(interval ''3 minutes'')', '42501', 'PostgREST''s claim');
END $$;
SET LOCAL ROLE app_authenticated;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 357: jobbets funktioner. The claim takes the oldest order that is
-- QUEUED, or RUNNING with a heartbeat past the lease, and says whose login
-- built it; a taken-over export starts with no pieces; a piece is written to
-- an export that is being built and to no other, in its own school; the file
-- is finished only when the pieces are counted and summed to what the job
-- says and is kept at most fourteen days; a failed build leaves no piece; an
-- expired file loses its pieces and its list of persons. A person who has
-- been demoted since the order fails it ('RequesterGone').
-- ---------------------------------------------------------------------------

BEGIN;
CREATE FUNCTION pg_temp.se_refuses(stmt text, expected text, what text) RETURNS void LANGUAGE plpgsql AS $f$
DECLARE got text := 'none';
BEGIN
  BEGIN
    EXECUTE stmt;
  EXCEPTION WHEN OTHERS THEN
    got := SQLSTATE;
  END;
  IF got IS DISTINCT FROM expected THEN
    RAISE EXCEPTION 'export: % should be refused with %, was %', what, expected, got USING ERRCODE = 'P0001';
  END IF;
END
$f$;
CREATE FUNCTION pg_temp.se_as(auth text) RETURNS void LANGUAGE sql AS $f$
  SELECT set_config('request.jwt.claims', json_build_object('sub', auth)::text, true);
  SELECT set_config('request.headers', '', true);
$f$;
DO $$
DECLARE
  school uuid;
  full_id uuid;
  e uuid;
  e2 uuid;
  c record;
  n bigint;
  s text;
BEGIN
  PERFORM pg_temp.se_as('00000000-0000-4000-8000-e50000000001');
  school := app.current_school_id();
  full_id := app.current_user_id();
  INSERT INTO "SchoolExports" ("schoolId", "requestedById") VALUES (school, full_id) RETURNING id INTO e;

  PERFORM pg_temp.se_refuses('SELECT app.school_export_claim(interval ''5 seconds'')', 'SS409', 'a lease of five seconds');
  PERFORM pg_temp.se_refuses('SELECT app.school_export_claim(interval ''2 hours'')', 'SS409', 'a lease of two hours');
  SELECT * INTO c FROM app.school_export_claim(interval '3 minutes');
  IF c.export_id IS DISTINCT FROM e OR c.school_id IS DISTINCT FROM school OR c.user_id IS DISTINCT FROM full_id
     OR c.auth_id IS DISTINCT FROM '00000000-0000-4000-8000-e50000000001'::uuid OR c.admin_profile IS DISTINCT FROM 'FULL' OR c.attempt <> 1 THEN
    RAISE EXCEPTION 'export 357: the claim returned % for the order of the full administrator', c;
  END IF;
  SELECT status::text, attempts INTO s, n FROM "SchoolExports" WHERE id = e;
  IF s <> 'RUNNING' OR n <> 1 THEN RAISE EXCEPTION 'export 357: the claimed order is % after % attempts', s, n; END IF;
  -- Nothing else to take: the order is running with a fresh heartbeat.
  PERFORM 1 FROM app.school_export_claim(interval '3 minutes');
  IF FOUND THEN RAISE EXCEPTION 'export 357: a second claim took an order with a fresh heartbeat'; END IF;
  IF NOT app.school_export_heartbeat(e) THEN RAISE EXCEPTION 'export 357: the heartbeat of a running export said it was not'; END IF;

  -- Pieces: counted from zero, to a running export only, small, and in the export's own school.
  PERFORM app.school_export_put(e, 0, '\x010203'::bytea);
  PERFORM app.school_export_put(e, 1, '\x0405'::bytea);

  -- A builder that was taken over and woke up holds an earlier attempt, and is fenced out of every function.
  IF app.school_export_heartbeat(e, 2) THEN RAISE EXCEPTION 'export 357: the heartbeat answered an attempt that is not the current'; END IF;
  PERFORM pg_temp.se_refuses(format($q$SELECT app.school_export_put(%L, 9, '\x01'::bytea, 2)$q$, e), 'SS409', 'a piece from an attempt that is not the current');
  PERFORM pg_temp.se_refuses(format($q$SELECT app.school_export_finish(%L, 5, 2, repeat('a', 64), '[]', '{}', '{}', interval '72 hours', 2)$q$, e), 'SS409', 'a finish by an attempt that is not the current');
  PERFORM app.school_export_fail(e, 'Stale', 2);
  SELECT status::text INTO s FROM "SchoolExports" WHERE id = e;
  IF s <> 'RUNNING' THEN RAISE EXCEPTION 'export 357: a stale attempt failed the export (%)', s; END IF;
  IF NOT app.school_export_heartbeat(e, 1) THEN RAISE EXCEPTION 'export 357: the current attempt was not recognised'; END IF;
  PERFORM pg_temp.se_refuses(format($q$SELECT app.school_export_put(%L, 0, '\x01'::bytea, 1)$q$, e), '23505', 'a repeated piece by the current attempt (past the fence, stopped by the key)');
  PERFORM pg_temp.se_refuses(format($q$SELECT app.school_export_put(%L, 0, '\x01'::bytea)$q$, e), '23505', 'a piece written twice');
  PERFORM pg_temp.se_refuses(format($q$SELECT app.school_export_put(%L, -1, '\x01'::bytea)$q$, e), '23514', 'a piece before the first');
  PERFORM pg_temp.se_refuses(format($q$SELECT app.school_export_put(%L, 2, ''::bytea)$q$, e), '23514', 'an empty piece');
  PERFORM pg_temp.se_refuses(format($q$SELECT app.school_export_put(%L, 2, decode(repeat('00', 4194305), 'hex'))$q$, e), '23514', 'a piece over 4 MiB');
  PERFORM pg_temp.se_refuses(format($q$SELECT app.school_export_put(%L, 0, '\x01'::bytea)$q$, gen_random_uuid()), 'SS409', 'a piece of an export that is not');
  -- Finish: counted against the pieces, kept at most fourteen days, once.
  PERFORM pg_temp.se_refuses(format($q$SELECT app.school_export_finish(%L, 5, 3, repeat('a', 64), '[]', '{}', '{}', interval '72 hours')$q$, e), 'SS409', 'a finish naming three pieces of two');
  PERFORM pg_temp.se_refuses(format($q$SELECT app.school_export_finish(%L, 6, 2, repeat('a', 64), '[]', '{}', '{}', interval '72 hours')$q$, e), 'SS409', 'a finish naming six bytes of five');
  PERFORM pg_temp.se_refuses(format($q$SELECT app.school_export_finish(%L, 5, 2, repeat('a', 64), '[]', '{}', '{}', interval '15 days')$q$, e), 'SS409', 'a file kept fifteen days');
  PERFORM pg_temp.se_refuses(format($q$SELECT app.school_export_finish(%L, 5, 2, repeat('a', 64), '[]', '{}', '{}', interval '0 seconds')$q$, e), 'SS409', 'a file kept no time');
  PERFORM pg_temp.se_refuses(format($q$SELECT app.school_export_finish(%L, 5, 2, 'not hex', '[]', '{}', '{}', interval '72 hours')$q$, e), '23514', 'a checksum that is not a SHA-256');
  PERFORM app.school_export_finish(e, 5, 2, repeat('a', 64), '[{"path":"x","rows":1,"bytes":1}]'::jsonb, '{"people":1,"links":0}'::jsonb, '{"PEOPLE":["x"]}'::jsonb, interval '72 hours');
  SELECT status::text INTO s FROM "SchoolExports" WHERE id = e;
  IF s <> 'READY' THEN RAISE EXCEPTION 'export 357: the finished export is %', s; END IF;
  -- Its two pieces are the export's own, in its school, and readable now that the file is READY.
  SELECT count(*) INTO n FROM "SchoolExportChunks" WHERE "exportId" = e AND "schoolId" = school;
  IF n <> 2 THEN RAISE EXCEPTION 'export 357: % pieces are stored in the export''s school, not two', n; END IF;
  PERFORM pg_temp.se_refuses(format($q$SELECT app.school_export_finish(%L, 5, 2, repeat('a', 64), '[]', '{}', '{}', interval '72 hours')$q$, e), 'SS409', 'a second finish');
  PERFORM pg_temp.se_refuses(format($q$SELECT app.school_export_put(%L, 2, '\x01'::bytea)$q$, e), 'SS409', 'a piece of a finished file');
  IF app.school_export_heartbeat(e) THEN RAISE EXCEPTION 'export 357: a finished export still has a heartbeat'; END IF;
  SELECT count(*) INTO n FROM "SchoolExports" WHERE id = e AND "byteSize" = 5 AND "chunkCount" = 2 AND "expiresAt" > now() + interval '71 hours' AND "expiresAt" < now() + interval '73 hours';
  IF n <> 1 THEN RAISE EXCEPTION 'export 357: the finished export does not say 5 bytes in 2 pieces kept 72 hours'; END IF;

  -- A failed build leaves no piece, and names its class; a class that is a message becomes 'Error'.
  DELETE FROM "SchoolExports" WHERE id = e;
  INSERT INTO "SchoolExports" ("schoolId", "requestedById") VALUES (school, full_id) RETURNING id INTO e;
  PERFORM 1 FROM app.school_export_claim(interval '3 minutes');
  PERFORM app.school_export_put(e, 0, '\x01'::bytea);
  PERFORM app.school_export_fail(e, 'ECONNRESET');
  SELECT status::text || ':' || "errorClass" INTO s FROM "SchoolExports" WHERE id = e;
  IF s <> 'FAILED:ECONNRESET' THEN RAISE EXCEPTION 'export 357: the failed export is %', s; END IF;
  DELETE FROM "SchoolExports" WHERE id = e;
  INSERT INTO "SchoolExports" ("schoolId", "requestedById") VALUES (school, full_id) RETURNING id INTO e;
  PERFORM 1 FROM app.school_export_claim(interval '3 minutes');
  PERFORM app.school_export_fail(e, 'a message with spaces: person@example.com');
  SELECT "errorClass" INTO s FROM "SchoolExports" WHERE id = e;
  IF s <> 'Error' THEN RAISE EXCEPTION 'export 357: an error that is a message was stored as %', s; END IF;
  DELETE FROM "SchoolExports" WHERE id = e;

  -- A file kept a second expires: its pieces and its list of persons go, the order stays as EXPIRED.
  INSERT INTO "SchoolExports" ("schoolId", "requestedById") VALUES (school, full_id) RETURNING id INTO e;
  PERFORM 1 FROM app.school_export_claim(interval '3 minutes');
  PERFORM app.school_export_put(e, 0, '\x01'::bytea);
  PERFORM app.school_export_finish(e, 1, 1, repeat('b', 64), '[]'::jsonb, '{}'::jsonb, '{"PEOPLE":["x"]}'::jsonb, interval '1 second');
  PERFORM pg_sleep(1.2);
  PERFORM pg_temp.se_refuses('SELECT app.school_export_expire(interval ''1 day'')', 'SS409', 'a ledger of one day');
  SELECT expired INTO n FROM app.school_export_expire(interval '13 months');
  IF n < 1 THEN RAISE EXCEPTION 'export 357: expire counted % expired files', n; END IF;
  SELECT status::text || ':' || coalesce("readAbout"::text, 'null') INTO s FROM "SchoolExports" WHERE id = e;
  IF s <> 'EXPIRED:null' THEN RAISE EXCEPTION 'export 357: the expired order is %', s; END IF;
  DELETE FROM "SchoolExports" WHERE id = e;

  -- A person demoted since the order: the claim fails it, and names why.
  PERFORM pg_temp.se_as('00000000-0000-4000-8000-e50000000002');
  INSERT INTO "SchoolExports" ("schoolId", "requestedById") VALUES (school, app.current_user_id()) RETURNING id INTO e;
  PERFORM pg_temp.se_as('00000000-0000-4000-8000-e50000000001');
  -- The full administrator demotes the rektor to the expedition (a decision: a decider may).
  UPDATE "Users" SET "adminProfile" = 'EXPEDITION' WHERE "authId" = '00000000-0000-4000-8000-e50000000002';
  PERFORM 1 FROM app.school_export_claim(interval '3 minutes');
  IF FOUND THEN RAISE EXCEPTION 'export 357: the order of a demoted administrator was claimed'; END IF;
  SELECT status::text || ':' || "errorClass" INTO s FROM "SchoolExports" WHERE id = e;
  IF s <> 'FAILED:RequesterGone' THEN RAISE EXCEPTION 'export 357: the demoted administrator''s order is %', s; END IF;
  DELETE FROM "SchoolExports" WHERE id = e;

  -- A RUNNING export whose heartbeat is older than the lease is taken over, with no pieces, as the second attempt.
  INSERT INTO "SchoolExports" ("schoolId", "requestedById") VALUES (school, full_id) RETURNING id INTO e;
  PERFORM 1 FROM app.school_export_claim(interval '10 seconds');
  PERFORM app.school_export_put(e, 0, '\x01'::bytea);
  PERFORM pg_sleep(10.5);
  SELECT * INTO c FROM app.school_export_claim(interval '10 seconds');
  IF c.export_id IS DISTINCT FROM e OR c.attempt <> 2 THEN RAISE EXCEPTION 'export 357: the stale export was claimed as %', c; END IF;
  -- It starts from nothing: a finish that names the half file's piece is refused, one that names none is whole.
  PERFORM pg_temp.se_refuses(format($q$SELECT app.school_export_finish(%L, 1, 1, repeat('a', 64), '[]', '{}', '{}', interval '72 hours')$q$, e), 'SS409', 'a finish naming the piece of the attempt that was taken over');
  PERFORM app.school_export_finish(e, 0, 0, repeat('a', 64), '[]'::jsonb, '{}'::jsonb, '{}'::jsonb, interval '72 hours');
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 358: tidsgränsen och nycklarna. A file is readable while it is
-- READY and before its expiry and not otherwise: a file still being built,
-- a failed one, and one past its time show the deciders no piece even before
-- the job deletes them. Withdrawing an order takes its pieces. A removed
-- person leaves the order with its school and no one named.
-- ---------------------------------------------------------------------------

BEGIN;
CREATE FUNCTION pg_temp.se_as(auth text) RETURNS void LANGUAGE sql AS $f$
  SELECT set_config('request.jwt.claims', json_build_object('sub', auth)::text, true);
  SELECT set_config('request.headers', '', true);
$f$;
DO $$
DECLARE
  school uuid;
  full_id uuid;
  rektor uuid;
  e uuid;
  n bigint;
  v text;
BEGIN
  PERFORM pg_temp.se_as('00000000-0000-4000-8000-e50000000001');
  school := app.current_school_id();
  full_id := app.current_user_id();
  INSERT INTO "SchoolExports" ("schoolId", "requestedById") VALUES (school, full_id) RETURNING id INTO e;
  PERFORM 1 FROM app.school_export_claim(interval '3 minutes') WHERE export_id = e;
  IF NOT FOUND THEN RAISE EXCEPTION 'export 358: the claim did not take the order (is another export queued in the database?)'; END IF;
  PERFORM app.school_export_put(e, 0, '\x0a0b'::bytea);

  SELECT count(*) INTO n FROM "SchoolExportChunks" WHERE "exportId" = e;
  IF n <> 0 THEN RAISE EXCEPTION 'export 358: a file still being built shows % pieces', n; END IF;

  PERFORM app.school_export_finish(e, 2, 1, repeat('c', 64), '[]'::jsonb, '{}'::jsonb, '{}'::jsonb, interval '2 seconds');
  SELECT count(*) INTO n FROM "SchoolExportChunks" WHERE "exportId" = e;
  IF n <> 1 THEN RAISE EXCEPTION 'export 358: a fresh file shows % pieces, not one', n; END IF;

  PERFORM pg_sleep(2.2);
  SELECT count(*) INTO n FROM "SchoolExportChunks" WHERE "exportId" = e;
  IF n <> 0 THEN RAISE EXCEPTION 'export 358: a file past its time shows % pieces before the job has run', n; END IF;
  SELECT count(*) INTO n FROM "SchoolExports" WHERE id = e AND status = 'READY';
  IF n <> 1 THEN RAISE EXCEPTION 'export 358: the order of an expired file is not read as READY until the job has run'; END IF;

  -- Withdrawing takes the pieces; a fresh file's pieces are read until then.
  DELETE FROM "SchoolExports" WHERE id = e;
  INSERT INTO "SchoolExports" ("schoolId", "requestedById") VALUES (school, full_id) RETURNING id INTO e;
  PERFORM 1 FROM app.school_export_claim(interval '3 minutes') WHERE export_id = e;
  PERFORM app.school_export_put(e, 0, '\x0a'::bytea);
  PERFORM app.school_export_finish(e, 1, 1, repeat('c', 64), '[]'::jsonb, '{}'::jsonb, '{}'::jsonb, interval '72 hours');
  SELECT count(*) INTO n FROM "SchoolExportChunks" WHERE "exportId" = e;
  IF n <> 1 THEN RAISE EXCEPTION 'export 358: a fresh file shows % pieces', n; END IF;
  -- A late failure of a build that has finished does nothing to the file.
  PERFORM app.school_export_fail(e, 'Error');
  SELECT count(*) INTO n FROM "SchoolExportChunks" WHERE "exportId" = e;
  IF n <> 1 THEN RAISE EXCEPTION 'export 358: a failure of a finished file took % pieces', 1 - n; END IF;
  DELETE FROM "SchoolExports" WHERE id = e;
  PERFORM set_config('request.jwt.claims', '', true);
  PERFORM pg_temp.se_as('00000000-0000-4000-8000-e50000000001');
  SELECT count(*) INTO n FROM "SchoolExportChunks" WHERE "exportId" = e;
  IF n <> 0 THEN RAISE EXCEPTION 'export 358: a withdrawn order left % pieces', n; END IF;

  -- A removed person: the order stays with its school, naming no one. The rektor orders; the full administrator removes the rektor.
  PERFORM pg_temp.se_as('00000000-0000-4000-8000-e50000000002');
  rektor := app.current_user_id();
  INSERT INTO "SchoolExports" ("schoolId", "requestedById") VALUES (school, rektor) RETURNING id INTO e;
  PERFORM pg_temp.se_as('00000000-0000-4000-8000-e50000000001');
  DELETE FROM "Users" WHERE id = rektor;
  SELECT "schoolId"::text || ':' || coalesce("requestedById"::text, 'null') INTO v FROM "SchoolExports" WHERE id = e;
  IF v IS DISTINCT FROM school::text || ':null' THEN RAISE EXCEPTION 'export 358: after the person was removed the order says %', v; END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 359: en beställning i taget. The school with an order QUEUED or
-- RUNNING is refused a second (23505), whoever places it; a finished or a
-- failed order is not in hand; another school is not held back. The ledger
-- is kept at least thirty days.
-- ---------------------------------------------------------------------------

BEGIN;
CREATE FUNCTION pg_temp.se_refuses(stmt text, expected text, what text) RETURNS void LANGUAGE plpgsql AS $f$
DECLARE got text := 'none';
BEGIN
  BEGIN
    EXECUTE stmt;
  EXCEPTION WHEN OTHERS THEN
    got := SQLSTATE;
  END;
  IF got IS DISTINCT FROM expected THEN
    RAISE EXCEPTION 'export: % should be refused with %, was %', what, expected, got USING ERRCODE = 'P0001';
  END IF;
END
$f$;
CREATE FUNCTION pg_temp.se_as(auth text) RETURNS void LANGUAGE sql AS $f$
  SELECT set_config('request.jwt.claims', json_build_object('sub', auth)::text, true);
  SELECT set_config('request.headers', '', true);
$f$;
DO $$
DECLARE
  school uuid;
  other uuid;
  full_id uuid;
  rektor uuid;
  other_admin uuid;
  e uuid;
  n bigint;
BEGIN
  PERFORM pg_temp.se_as('00000000-0000-4000-8000-e50000000031');
  other := app.current_school_id();
  other_admin := app.current_user_id();
  PERFORM pg_temp.se_as('00000000-0000-4000-8000-e50000000002');
  rektor := app.current_user_id();
  PERFORM pg_temp.se_as('00000000-0000-4000-8000-e50000000001');
  school := app.current_school_id();
  full_id := app.current_user_id();

  INSERT INTO "SchoolExports" ("schoolId", "requestedById") VALUES (school, full_id) RETURNING id INTO e;
  PERFORM pg_temp.se_refuses(format($q$INSERT INTO "SchoolExports" ("schoolId", "requestedById") VALUES (%L, %L)$q$, school, full_id), '23505', 'a second order while one is QUEUED');
  PERFORM pg_temp.se_as('00000000-0000-4000-8000-e50000000002');
  PERFORM pg_temp.se_refuses(format($q$INSERT INTO "SchoolExports" ("schoolId", "requestedById") VALUES (%L, %L)$q$, school, rektor), '23505', 'rektor ordering while the full administrator''s is QUEUED');
  PERFORM pg_temp.se_as('00000000-0000-4000-8000-e50000000001');
  PERFORM 1 FROM app.school_export_claim(interval '3 minutes') WHERE export_id = e;
  PERFORM pg_temp.se_refuses(format($q$INSERT INTO "SchoolExports" ("schoolId", "requestedById") VALUES (%L, %L)$q$, school, full_id), '23505', 'a second order while one is RUNNING');

  -- Failed, then finished: not in hand.
  PERFORM app.school_export_fail(e, 'Error');
  INSERT INTO "SchoolExports" ("schoolId", "requestedById") VALUES (school, full_id) RETURNING id INTO e;
  PERFORM 1 FROM app.school_export_claim(interval '3 minutes') WHERE export_id = e;
  PERFORM app.school_export_put(e, 0, '\x01'::bytea);
  PERFORM app.school_export_finish(e, 1, 1, repeat('d', 64), '[]'::jsonb, '{}'::jsonb, '{}'::jsonb, interval '72 hours');
  INSERT INTO "SchoolExports" ("schoolId", "requestedById") VALUES (school, full_id);
  SELECT count(*) INTO n FROM "SchoolExports" WHERE "schoolId" = school AND status IN ('QUEUED', 'RUNNING');
  IF n <> 1 THEN RAISE EXCEPTION 'export 359: % orders are in hand, not one', n; END IF;

  -- Another school is not held back by this school's order in hand.
  PERFORM pg_temp.se_as('00000000-0000-4000-8000-e50000000031');
  INSERT INTO "SchoolExports" ("schoolId", "requestedById") VALUES (other, other_admin);
  PERFORM pg_temp.se_refuses(format($q$INSERT INTO "SchoolExports" ("schoolId", "requestedById") VALUES (%L, %L)$q$, other, other_admin), '23505', 'the other school''s second order');
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Sections 360-364: registrets sort av skydd (20270111090000). The kind the
-- register gives, on the sync's mark alone, written by the sync and by an
-- administrator's apply (Personal), read by the same people as the mark,
-- and by the SS12000 provider through app.ss12000_security_markings() alone;
-- a Person's version moves when what is sent about it moves.
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- Section 360: sorten i katalogen. The two kinds; a CHECK holding a mark by
-- hand to none; UPDATE of kind and of no other column for the API's role,
-- nothing for PostgREST's roles or service_role; the provider's read a
-- SECURITY DEFINER function only the API executes; the version trigger; the
-- sync's change admits UPDATE.
-- ---------------------------------------------------------------------------

BEGIN;
DO $$
DECLARE
  v text;
  r text;
  c text;
BEGIN
  IF enum_range(NULL::"PersonProtectionKind")::text <> '{SEKRETESSMARKERING,SKYDDAD_FOLKBOKFORING}' THEN
    RAISE EXCEPTION 'skyddad 360: the kinds are %', enum_range(NULL::"PersonProtectionKind");
  END IF;
  SELECT pg_get_constraintdef(c.oid) INTO v FROM pg_constraint c
   WHERE c.conrelid = 'public."PersonProtections"'::regclass AND c.conname = 'PersonProtections_a_kind_is_the_registers';
  IF v IS DISTINCT FROM 'CHECK (((source = ''SS12000''::"PersonProtectionSource") OR (kind IS NULL)))' THEN
    RAISE EXCEPTION 'skyddad 360: the kind''s CHECK is %', v;
  END IF;
  IF has_table_privilege('app_authenticated', 'public."PersonProtections"', 'UPDATE') THEN
    RAISE EXCEPTION 'skyddad 360: the API''s role updates the whole mark';
  END IF;
  FOREACH c IN ARRAY ARRAY['userId', 'schoolId', 'source', 'kind'] LOOP
    IF has_column_privilege('app_authenticated', 'public."PersonProtections"', c, 'UPDATE') IS DISTINCT FROM (c = 'kind') THEN
      RAISE EXCEPTION 'skyddad 360: the API''s role % update the column %', CASE WHEN c = 'kind' THEN 'cannot' ELSE 'can' END, c;
    END IF;
    FOREACH r IN ARRAY ARRAY['authenticated', 'anon', 'service_role'] LOOP
      IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) AND has_column_privilege(r, 'public."PersonProtections"', c, 'UPDATE') THEN
        RAISE EXCEPTION 'skyddad 360: % updates the column %', r, c;
      END IF;
    END LOOP;
  END LOOP;

  IF NOT (SELECT prosecdef FROM pg_proc WHERE oid = 'app.ss12000_security_markings()'::regprocedure) THEN
    RAISE EXCEPTION 'skyddad 360: the provider''s read is not SECURITY DEFINER, and would read under the caller''s arms';
  END IF;
  SELECT prosrc INTO v FROM pg_proc WHERE oid = 'app.ss12000_security_markings()'::regprocedure;
  IF v NOT LIKE '%p."schoolId" = app.current_service_school_id()%' OR v NOT LIKE '%p."source" = ''SS12000''%' OR v NOT LIKE '%p."kind" IS NOT NULL%'
     OR v NOT LIKE '%u."ss12000Id" IS NOT NULL%' THEN
    RAISE EXCEPTION 'skyddad 360: the provider''s read is %', v;
  END IF;
  IF NOT has_function_privilege('app_authenticated', 'app.ss12000_security_markings()', 'EXECUTE') THEN
    RAISE EXCEPTION 'skyddad 360: the API cannot read the kinds it sends';
  END IF;
  FOREACH r IN ARRAY ARRAY['authenticated', 'anon', 'service_role'] LOOP
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) AND has_function_privilege(r, 'app.ss12000_security_markings()', 'EXECUTE') THEN
      RAISE EXCEPTION 'skyddad 360: % reads the kinds', r;
    END IF;
  END LOOP;
  IF (SELECT proacl FROM pg_proc WHERE oid = 'app.ss12000_security_markings()'::regprocedure)::text LIKE '%{=X%'
     OR (SELECT proacl FROM pg_proc WHERE oid = 'app.ss12000_security_markings()'::regprocedure)::text LIKE '%,=X%' THEN
    RAISE EXCEPTION 'skyddad 360: PUBLIC reads the kinds';
  END IF;
  IF has_function_privilege('app_authenticated', 'app.ss12000_v_protections()', 'EXECUTE') THEN
    RAISE EXCEPTION 'skyddad 360: the API calls the version trigger''s function';
  END IF;

  SELECT pg_get_triggerdef(t.oid) INTO v FROM pg_trigger t
   WHERE t.tgrelid = 'public."PersonProtections"'::regclass AND t.tgname = 'PersonProtections_ss12000_versions';
  IF v IS DISTINCT FROM 'CREATE TRIGGER "PersonProtections_ss12000_versions" AFTER INSERT OR DELETE OR UPDATE OF kind ON public."PersonProtections" FOR EACH ROW EXECUTE FUNCTION app.ss12000_v_protections()' THEN
    RAISE EXCEPTION 'skyddad 360: the version trigger is %', v;
  END IF;

  SELECT pg_get_constraintdef(c.oid) INTO v FROM pg_constraint c
   WHERE c.conrelid = 'public."Ss12000SyncChanges"'::regclass AND c.conname = 'Ss12000SyncChanges_a_mark_names_its_person_in_after_alone';
  IF v NOT LIKE '%''UPDATE''%' OR v NOT LIKE '%"externalId" IS NULL%' OR v NOT LIKE '%"localId" IS NULL%' THEN
    RAISE EXCEPTION 'skyddad 360: the CHECK on a mark''s change is %', v;
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 361: vem som skriver sorten. Full, rektor and the expedition
-- (Personal: an administrator's apply of a run) give the register's mark its
-- kind; the planner and the läsare change nothing. A mark by hand takes no
-- kind, in an update or an insert (the CHECK); no column but kind changes; a
-- teacher, a pupil and a guardian change nothing; another school's mark is
-- out of reach. A change of kind writes no history.
-- ---------------------------------------------------------------------------

BEGIN;
CREATE FUNCTION pg_temp.sk_refuses(stmt text, expected text, what text) RETURNS void LANGUAGE plpgsql AS $f$
DECLARE got text := 'none';
BEGIN
  BEGIN
    EXECUTE stmt;
  EXCEPTION WHEN OTHERS THEN
    got := SQLSTATE;
  END;
  IF got IS DISTINCT FROM expected THEN
    RAISE EXCEPTION 'skyddad: % should be refused with %, was %', what, expected, got USING ERRCODE = 'P0001';
  END IF;
END
$f$;
CREATE FUNCTION pg_temp.sk_as(auth text) RETURNS void LANGUAGE sql AS $f$
  SELECT set_config('request.jwt.claims', json_build_object('sub', auth)::text, true);
  SELECT set_config('request.headers', '', true);
$f$;
DO $$
DECLARE
  school uuid;
  p1 uuid;
  p2 uuid;
  t1 uuid;
  t2 uuid;
  other_pupil uuid;
  who text;
  n bigint;
  events bigint;
BEGIN
  PERFORM pg_temp.sk_as('00000000-0000-4000-8000-e50000000001');
  school := app.current_school_id();
  SELECT id INTO p1 FROM "Users" WHERE "schoolId" = school AND email = 'sk-p1@example.invalid';
  SELECT id INTO p2 FROM "Users" WHERE "schoolId" = school AND email = 'sk-p2@example.invalid';
  SELECT id INTO t1 FROM "Users" WHERE "schoolId" = school AND email = 'sk-t1@example.invalid';
  SELECT id INTO t2 FROM "Users" WHERE "schoolId" = school AND email = 'sk-t2@example.invalid';
  IF (SELECT kind FROM "PersonProtections" WHERE "userId" = p1 AND source = 'SS12000') IS DISTINCT FROM 'SEKRETESSMARKERING' THEN
    RAISE EXCEPTION 'skyddad 361: the fixtures did not give P1''s register mark its kind';
  END IF;
  SELECT count(*) INTO events FROM "PersonProtectionEvents";
  PERFORM pg_temp.sk_as('00000000-0000-4000-8000-e50000000031');
  SELECT "userId" INTO other_pupil FROM "PersonProtections" LIMIT 1;

  -- Personal: full, rektor, the expedition.
  FOREACH who IN ARRAY ARRAY['01', '02', '03'] LOOP
    PERFORM pg_temp.sk_as('00000000-0000-4000-8000-e500000000' || who);
    UPDATE "PersonProtections" SET kind = 'SKYDDAD_FOLKBOKFORING' WHERE "userId" = p1 AND source = 'SS12000';
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n <> 1 THEN RAISE EXCEPTION 'skyddad 361: administrator …% gives the register''s mark no kind (% rows)', who, n; END IF;
    UPDATE "PersonProtections" SET kind = 'SEKRETESSMARKERING' WHERE "userId" = p1;
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n <> 1 THEN RAISE EXCEPTION 'skyddad 361: administrator …% reached % rows of P1''s, not the register''s one', who, n; END IF;
    -- A mark by hand is not reached by an update: no kind on it.
    UPDATE "PersonProtections" SET kind = 'SEKRETESSMARKERING' WHERE "userId" = t1;
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n <> 0 THEN RAISE EXCEPTION 'skyddad 361: administrator …% gave a mark by hand a kind', who; END IF;
    -- The same value written back, so the arms admit it and the column's
    -- grant alone refuses.
    PERFORM pg_temp.sk_refuses(format($q$UPDATE "PersonProtections" SET source = source WHERE "userId" = %L$q$, p1),
                               '42501', 'an administrator''s write of a mark''s source');
    PERFORM pg_temp.sk_refuses(format($q$UPDATE "PersonProtections" SET "userId" = "userId", "schoolId" = "schoolId" WHERE "userId" = %L$q$, p1),
                               '42501', 'an administrator''s write of a mark''s person or school');
    UPDATE "PersonProtections" SET kind = 'SKYDDAD_FOLKBOKFORING' WHERE "userId" = other_pupil;
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n <> 0 THEN RAISE EXCEPTION 'skyddad 361: administrator …% reached another school''s mark', who; END IF;
  END LOOP;
  -- The other school's administrator, with no WHERE (so the read arms do not
  -- filter first): the update arm alone keeps this school's marks out.
  PERFORM pg_temp.sk_as('00000000-0000-4000-8000-e50000000031');
  UPDATE "PersonProtections" SET kind = 'SKYDDAD_FOLKBOKFORING';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'skyddad 361: the other school''s administrator changed % kinds', n; END IF;
  -- An insert of a mark by hand with a kind: the CHECK.
  PERFORM pg_temp.sk_as('00000000-0000-4000-8000-e50000000001');
  PERFORM pg_temp.sk_refuses(format($q$INSERT INTO "PersonProtections" ("userId", "schoolId", source, kind) VALUES (%L, %L, 'MANUAL', 'SEKRETESSMARKERING')$q$, t2, school),
                             '23514', 'a mark by hand with a kind');
  -- An administrator's apply writes the register's mark with its kind.
  INSERT INTO "PersonProtections" ("userId", "schoolId", source, kind) VALUES (p2, school, 'SS12000', 'SKYDDAD_FOLKBOKFORING');

  -- The planner and the läsare: refused (the area is asked in WITH CHECK).
  FOREACH who IN ARRAY ARRAY['04', '05'] LOOP
    PERFORM pg_temp.sk_as('00000000-0000-4000-8000-e500000000' || who);
    PERFORM pg_temp.sk_refuses(format($q$UPDATE "PersonProtections" SET kind = 'SKYDDAD_FOLKBOKFORING' WHERE "userId" = %L$q$, p1),
                               '42501', format('administrator …%s without Personal giving a kind', who));
  END LOOP;
  -- A teacher (marked by hand), a pupil (marked by the register), a guardian.
  FOREACH who IN ARRAY ARRAY['06', '11', '21'] LOOP
    PERFORM pg_temp.sk_as('00000000-0000-4000-8000-e500000000' || who);
    UPDATE "PersonProtections" SET kind = 'SKYDDAD_FOLKBOKFORING' WHERE "userId" IN (p1, p2, t1);
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n <> 0 THEN RAISE EXCEPTION 'skyddad 361: …% changed % kinds', who, n; END IF;
    SELECT count(*) INTO n FROM "PersonProtections";
    IF n <> 0 THEN RAISE EXCEPTION 'skyddad 361: …% reads % marks', who, n; END IF;
  END LOOP;

  -- No history for a kind: the inserted mark is ADDED, the changes nothing.
  PERFORM pg_temp.sk_as('00000000-0000-4000-8000-e50000000001');
  SELECT count(*) - events INTO n FROM "PersonProtectionEvents";
  IF n <> 1 THEN RAISE EXCEPTION 'skyddad 361: the history grew by %, not the one mark added', n; END IF;
  IF EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = 'public."PersonProtectionEvents"'::regclass AND attname = 'kind') THEN
    RAISE EXCEPTION 'skyddad 361: the history keeps the kind';
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 362: synkens principal och sorten. It gives the register's mark of
-- its school the kind, never a mark by hand, never another school's, and no
-- other column; it inserts its mark with the kind; no history for a kind.
-- ---------------------------------------------------------------------------

BEGIN;
CREATE FUNCTION pg_temp.sk_refuses(stmt text, expected text, what text) RETURNS void LANGUAGE plpgsql AS $f$
DECLARE got text := 'none';
BEGIN
  BEGIN
    EXECUTE stmt;
  EXCEPTION WHEN OTHERS THEN
    got := SQLSTATE;
  END;
  IF got IS DISTINCT FROM expected THEN
    RAISE EXCEPTION 'skyddad: % should be refused with %, was %', what, expected, got USING ERRCODE = 'P0001';
  END IF;
END
$f$;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-e50000000001')::text, true);
DO $$
BEGIN
  PERFORM set_config('app.test_rls36_school', app.current_school_id()::text, true);
  PERFORM set_config('app.test_rls36_p1', (SELECT id::text FROM "Users" WHERE email = 'sk-p1@example.invalid'), true);
  PERFORM set_config('app.test_rls36_p2', (SELECT id::text FROM "Users" WHERE email = 'sk-p2@example.invalid'), true);
  PERFORM set_config('app.test_rls36_t1', (SELECT id::text FROM "Users" WHERE email = 'sk-t1@example.invalid'), true);
  PERFORM set_config('app.test_rls36_events', (SELECT count(*)::text FROM "PersonProtectionEvents"), true);
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-e50000000031')::text, true);
DO $$
BEGIN
  PERFORM set_config('app.test_rls36_other', app.current_school_id()::text, true);
  PERFORM set_config('app.test_rls36_other_pupil', (SELECT "userId"::text FROM "PersonProtections" LIMIT 1), true);
END $$;
SELECT set_config('request.jwt.claims', '', true);
SELECT set_config('app.sync_school_id', current_setting('app.test_rls36_school'), true);
DO $$
DECLARE
  school uuid := current_setting('app.test_rls36_school')::uuid;
  p1 uuid := current_setting('app.test_rls36_p1')::uuid;
  p2 uuid := current_setting('app.test_rls36_p2')::uuid;
  t1 uuid := current_setting('app.test_rls36_t1')::uuid;
  n bigint;
BEGIN
  IF app.current_user_id() IS NOT NULL OR app.current_sync_school_id() IS DISTINCT FROM school THEN
    RAISE EXCEPTION 'skyddad 362: expected the sync principal and no login';
  END IF;
  -- With no WHERE, so the read arm does not filter first: the school's two
  -- register marks (P1, P3), and no other school's (the role matrix's school
  -- holds one too).
  UPDATE "PersonProtections" SET kind = 'SEKRETESSMARKERING';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 2 THEN RAISE EXCEPTION 'skyddad 362: the sync changed % kinds, not its school''s two register marks', n; END IF;
  UPDATE "PersonProtections" SET kind = 'SKYDDAD_FOLKBOKFORING' WHERE "userId" = p1;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'skyddad 362: the sync changed % kinds of P1''s, not the register''s one', n; END IF;
  UPDATE "PersonProtections" SET kind = 'SEKRETESSMARKERING' WHERE "userId" = t1;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'skyddad 362: the sync gave a mark by hand a kind'; END IF;
  UPDATE "PersonProtections" SET kind = 'SEKRETESSMARKERING' WHERE "userId" = current_setting('app.test_rls36_other_pupil')::uuid;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'skyddad 362: the sync reached another school''s mark'; END IF;
  PERFORM pg_temp.sk_refuses(format($q$UPDATE "PersonProtections" SET source = source WHERE "userId" = %L$q$, p1),
                             '42501', 'the sync writing a mark''s source');
  INSERT INTO "PersonProtections" ("userId", "schoolId", source, kind) VALUES (p2, school, 'SS12000', 'SEKRETESSMARKERING');
  UPDATE "PersonProtections" SET kind = NULL WHERE "userId" = p2 AND source = 'SS12000';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'skyddad 362: the sync cannot take a kind it no longer recognises off'; END IF;
END $$;
SELECT set_config('app.sync_school_id', '', true);
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-e50000000001')::text, true);
DO $$
DECLARE n bigint;
BEGIN
  SELECT count(*) - current_setting('app.test_rls36_events')::bigint INTO n FROM "PersonProtectionEvents";
  IF n <> 1 THEN RAISE EXCEPTION 'skyddad 362: the history grew by % for one mark added and three kinds', n; END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 363: vad leverantören läser. The service principal of a school
-- reads, through app.ss12000_security_markings(), the person and kind of the
-- register's marks of its school with a kind, on a person linked to the
-- register (P4): not on an unlinked row whatever it holds (P1, T1: the
-- review of #265, N3), not a mark by hand (T1, G2), not one without a kind
-- (P3), not another school's. The table itself it reads not at all. With no
-- service principal (a login, the sync, nobody) the function answers
-- nothing.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-e50000000001')::text, true);
DO $$
DECLARE
  school uuid := app.current_school_id();
BEGIN
  PERFORM set_config('app.test_rls363_school', school::text, true);
  PERFORM set_config('app.test_rls363_p1', (SELECT id::text FROM "Users" WHERE "schoolId" = school AND email = 'sk-p1@example.invalid'), true);
  PERFORM set_config('app.test_rls363_t1', (SELECT id::text FROM "Users" WHERE "schoolId" = school AND email = 'sk-t1@example.invalid'), true);
  PERFORM set_config('app.test_rls363_p4', (SELECT id::text FROM "Users" WHERE "schoolId" = school AND email = 'sk-p4@example.invalid' AND "ss12000Id" IS NOT NULL), true);
  IF current_setting('app.test_rls363_p4', true) IS NULL OR current_setting('app.test_rls363_p4', true) = ''
     OR (SELECT "ss12000Id" FROM "Users" WHERE id = current_setting('app.test_rls363_p1')::uuid) IS NOT NULL
     OR (SELECT "ss12000Id" FROM "Users" WHERE id = current_setting('app.test_rls363_t1')::uuid) IS NOT NULL THEN
    RAISE EXCEPTION 'skyddad 363: the fixtures lack a linked P4, or P1 or T1 is linked';
  END IF;
  IF (SELECT count(*) FROM app.ss12000_security_markings()) <> 0 THEN
    RAISE EXCEPTION 'skyddad 363: a login reads the provider''s kinds';
  END IF;
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-e50000000031')::text, true);
DO $$
BEGIN
  PERFORM set_config('app.test_rls363_other', app.current_school_id()::text, true);
END $$;
-- The sync gives P4 (linked) the register's mark with a kind, and T1 (marked
-- by hand, unlinked) one beside it with a kind too, as a row might hold.
SELECT set_config('request.jwt.claims', '', true);
SELECT set_config('app.sync_school_id', current_setting('app.test_rls363_school'), true);
INSERT INTO "PersonProtections" ("userId", "schoolId", source, kind)
VALUES (current_setting('app.test_rls363_p4')::uuid, current_setting('app.test_rls363_school')::uuid, 'SS12000', 'SKYDDAD_FOLKBOKFORING'),
       (current_setting('app.test_rls363_t1')::uuid, current_setting('app.test_rls363_school')::uuid, 'SS12000', 'SEKRETESSMARKERING');
DO $$
BEGIN
  IF (SELECT count(*) FROM app.ss12000_security_markings()) <> 0 THEN
    RAISE EXCEPTION 'skyddad 363: the sync principal reads the provider''s kinds';
  END IF;
END $$;
SELECT set_config('app.sync_school_id', '', true);
SELECT set_config('app.service_school_id', current_setting('app.test_rls363_school'), true);
DO $$
DECLARE
  v text;
  n bigint;
BEGIN
  SELECT string_agg(m."userId"::text || ':' || coalesce(m.kind::text, 'none'), ',' ORDER BY m."userId"::text) INTO v FROM app.ss12000_security_markings() m;
  IF v IS DISTINCT FROM (
       SELECT string_agg(x.u || ':' || x.k, ',' ORDER BY x.u)
         FROM (VALUES (current_setting('app.test_rls363_p4'), 'SKYDDAD_FOLKBOKFORING')) AS x(u, k)) THEN
    RAISE EXCEPTION 'skyddad 363: the provider reads %, not the linked P4''s register kind alone', v;
  END IF;
  SELECT count(*) INTO n FROM "PersonProtections";
  IF n <> 0 THEN RAISE EXCEPTION 'skyddad 363: the service principal reads % marks of the table', n; END IF;
END $$;
SELECT set_config('app.service_school_id', current_setting('app.test_rls363_other'), true);
DO $$
BEGIN
  IF (SELECT count(*) FROM app.ss12000_security_markings()) <> 0 THEN
    RAISE EXCEPTION 'skyddad 363: the other school''s provider reads kinds (it has a mark by hand alone)';
  END IF;
END $$;
-- P4's mark with no kind (a marking not recognised): nothing to read for P4.
SELECT set_config('app.service_school_id', '', true);
SELECT set_config('app.sync_school_id', current_setting('app.test_rls363_school'), true);
UPDATE "PersonProtections" SET kind = NULL WHERE "userId" = current_setting('app.test_rls363_p4')::uuid AND source = 'SS12000';
SELECT set_config('app.sync_school_id', '', true);
SELECT set_config('app.service_school_id', current_setting('app.test_rls363_school'), true);
DO $$
BEGIN
  IF (SELECT count(*) FROM app.ss12000_security_markings()) <> 0 THEN
    RAISE EXCEPTION 'skyddad 363: the provider reads % rows, a linked mark with no kind among them', (SELECT count(*) FROM app.ss12000_security_markings());
  END IF;
END $$;
SELECT set_config('app.service_school_id', '', true);
DO $$
BEGIN
  IF (SELECT count(*) FROM app.ss12000_security_markings()) <> 0 THEN
    RAISE EXCEPTION 'skyddad 363: nobody reads the provider''s kinds';
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 364: en Persons version följer det som skickas. A mark by hand,
-- and the register's without a kind, move no version; the register's kind
-- set, changed or its mark removed moves the person's, in the transaction
-- that does it. Each case in a transaction of its own: a version moves once
-- per transaction.
-- ---------------------------------------------------------------------------

CREATE TEMP TABLE sk364 (k text PRIMARY KEY, v text);
GRANT ALL ON sk364 TO PUBLIC;
BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-e50000000001')::text, true);
INSERT INTO sk364
SELECT 'school', app.current_school_id()::text
UNION ALL SELECT 'p1', id::text FROM "Users" WHERE email = 'sk-p1@example.invalid'
UNION ALL SELECT 'p2', id::text FROM "Users" WHERE email = 'sk-p2@example.invalid';
COMMIT;
CREATE FUNCTION pg_temp.sk364(k text) RETURNS uuid LANGUAGE sql AS $f$ SELECT v::uuid FROM sk364 WHERE sk364.k = $1 $f$;
CREATE FUNCTION pg_temp.sk364_moved(person uuid) RETURNS boolean LANGUAGE plpgsql AS $f$
DECLARE moved boolean;
BEGIN
  PERFORM set_config('app.service_school_id', pg_temp.sk364('school')::text, true);
  SELECT coalesce(bool_or(v."xid" = pg_current_xact_id()), false) INTO moved
    FROM "Ss12000EntityVersions" v WHERE v.resource = 'Person' AND v."entityId" = person;
  PERFORM set_config('app.service_school_id', '', true);
  RETURN moved;
END
$f$;

-- 364a: a mark by hand, and the register's with no kind: nothing moves.
BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-e50000000001')::text, true);
INSERT INTO "PersonProtections" ("userId", "schoolId", source) VALUES (pg_temp.sk364('p2'), pg_temp.sk364('school'), 'MANUAL');
INSERT INTO "PersonProtections" ("userId", "schoolId", source) VALUES (pg_temp.sk364('p2'), pg_temp.sk364('school'), 'SS12000');
DO $$ BEGIN
  IF pg_temp.sk364_moved(pg_temp.sk364('p2')) THEN RAISE EXCEPTION 'skyddad 364a: a mark with nothing to send moved the person'; END IF;
END $$;
ROLLBACK;

-- 364b: the register's mark with its kind: the person moves.
BEGIN;
SELECT set_config('request.jwt.claims', '', true);
SELECT set_config('app.sync_school_id', (SELECT v FROM sk364 WHERE k = 'school'), true);
INSERT INTO "PersonProtections" ("userId", "schoolId", source, kind) VALUES (pg_temp.sk364('p2'), pg_temp.sk364('school'), 'SS12000', 'SEKRETESSMARKERING');
DO $$ BEGIN
  IF NOT pg_temp.sk364_moved(pg_temp.sk364('p2')) THEN RAISE EXCEPTION 'skyddad 364b: a kind set did not move the person'; END IF;
END $$;
ROLLBACK;

-- 364c: the kind changed: the person moves; the same kind written again does not.
BEGIN;
SELECT set_config('request.jwt.claims', '', true);
SELECT set_config('app.sync_school_id', (SELECT v FROM sk364 WHERE k = 'school'), true);
UPDATE "PersonProtections" SET kind = 'SEKRETESSMARKERING' WHERE "userId" = pg_temp.sk364('p1') AND source = 'SS12000';
DO $$ BEGIN
  IF pg_temp.sk364_moved(pg_temp.sk364('p1')) THEN RAISE EXCEPTION 'skyddad 364c: the same kind moved the person'; END IF;
END $$;
UPDATE "PersonProtections" SET kind = 'SKYDDAD_FOLKBOKFORING' WHERE "userId" = pg_temp.sk364('p1') AND source = 'SS12000';
DO $$ BEGIN
  IF NOT pg_temp.sk364_moved(pg_temp.sk364('p1')) THEN RAISE EXCEPTION 'skyddad 364c: a changed kind did not move the person'; END IF;
END $$;
ROLLBACK;

-- 364d: the register's mark removed (a decision): the person moves, and is sent without it.
BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-e50000000001')::text, true);
DELETE FROM "PersonProtections" WHERE "userId" = pg_temp.sk364('p1');
DO $$ BEGIN
  IF NOT pg_temp.sk364_moved(pg_temp.sk364('p1')) THEN RAISE EXCEPTION 'skyddad 364d: a lifted kind did not move the person'; END IF;
  PERFORM set_config('app.service_school_id', pg_temp.sk364('school')::text, true);
  IF EXISTS (SELECT 1 FROM app.ss12000_security_markings() WHERE "userId" = pg_temp.sk364('p1')) THEN
    RAISE EXCEPTION 'skyddad 364d: the provider still reads the lifted kind';
  END IF;
  PERFORM set_config('app.service_school_id', '', true);
END $$;
ROLLBACK;
DROP TABLE sk364;

-- ---------------------------------------------------------------------------
-- Sections 345-349: Rapporteringsgrad (20270112090100).
--
-- Varje lärares andel hållna lektioner med sparat register, lagrad per lärare
-- och dag, och två påminnelser som skolan slår på. The school is
-- rls-rapporteringsgrad-school (fixtures: …f20000000001 and on), a full
-- administrator, rektor, expedition, schemaläggare and läsare, four teachers
-- (the last deactivated), two pupils and a guardian, and a second school of
-- its own. Lessons are planted by each section, on fixed past days (the
-- Tuesday 2026-09-15 is where the count starts) inside its own transaction,
-- so nothing ages and nothing stays. The teacher's own list of open lessons
-- is the one thing measured from today, and is planted relative to it.
--
--   345  the tables: defaults, the switches' dates, the limit's range
--   346  the count: what a held lesson is and what a saved register is, a
--        cancelled and a rescheduled lesson, a substitute, a co-teacher, an
--        absent teacher, a lov, the summer-time switches, and the night's
--        rewrite (late registers, lessons that go, days that vanish)
--   347  who reads and who writes, role by role, the teacher's own list, and
--        the roles PostgREST uses
--   348  the weekly notice and the reminders' switches
--   (on the owner's side, in rls-owner-checks.sql: 345o the tables' own
--   constraints, keys, indexes, grants and functions, 346o the definition's
--   edges only the owner can ask, 348o the reminders over backdated switches
--   and which weeks are due, 349o gallring over the days and the reminders)
-- ---------------------------------------------------------------------------

-- The helpers the sections share. Temporary, so they die with the session.
CREATE FUNCTION pg_temp.rg_as(p_auth text) RETURNS void LANGUAGE sql AS $$
  SELECT set_config('request.jwt.claims', json_build_object('sub', p_auth)::text, true)
$$;

-- The fixtures' login of a person, by the number they end in.
CREATE FUNCTION pg_temp.rg_auth(p_n integer) RETURNS text LANGUAGE sql AS $$
  SELECT '00000000-0000-4000-8000-f2' || lpad(p_n::text, 10, '0')
$$;

CREATE FUNCTION pg_temp.rg_id(p_email text) RETURNS uuid LANGUAGE sql AS $$
  SELECT id FROM "Users" WHERE "schoolId" = app.current_school_id() AND email = p_email
$$;

-- A lesson of 50 minutes from p_hour (local time) on p_day, with the teachers p_teachers
-- (as LEAD, or in the roles of p_roles) and a mark for the first pupils, one status each in
-- p_marks. Planted the way publish and the register do. Its roster is read from the class
-- p_group (RG7A, with two active pupils, unless it says otherwise), the groups p_extra joined to
-- it and the pupils (by e-mail) p_named on it.
CREATE FUNCTION pg_temp.rg_lesson(p_day date, p_hour integer, p_teachers uuid[] DEFAULT '{}', p_marks text[] DEFAULT '{}',
                                  p_status "LessonStatus" DEFAULT 'SCHEDULED', p_roles text[] DEFAULT NULL,
                                  p_cause "LessonCancelCause" DEFAULT NULL, p_group text DEFAULT 'RG7A',
                                  p_extra text[] DEFAULT '{}', p_named text[] DEFAULT '{}')
RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE
  s uuid := app.current_school_id();
  l uuid;
  starts timestamptz := (p_day + make_time(p_hour, 0, 0)) AT TIME ZONE 'Europe/Stockholm';
  i integer;
  subj uuid := (SELECT id FROM "Subjects" WHERE "schoolId" = s AND code = 'RGSUBJ');
  grp uuid := (SELECT id FROM "StudentGroups" WHERE "schoolId" = s AND name = p_group);
  pupils uuid[] := ARRAY(SELECT id FROM "Users" WHERE "schoolId" = s AND role = 'STUDENT' ORDER BY email);
BEGIN
  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", status, "cancelCause", "updatedAt")
  VALUES (s, subj, grp, p_day, starts, starts + interval '50 minutes', p_status, p_cause, now()) RETURNING id INTO l;
  FOR i IN 1..coalesce(cardinality(p_teachers), 0) LOOP
    INSERT INTO "CalendarLessonTeachers" ("schoolId", "calendarLessonId", "teacherId", role)
    VALUES (s, l, p_teachers[i], coalesce(p_roles[i], 'LEAD')::"TeacherAssignmentRole");
  END LOOP;
  INSERT INTO "CalendarLessonGroups" ("schoolId", "calendarLessonId", "studentGroupId")
  SELECT s, l, g."id" FROM "StudentGroups" g WHERE g."schoolId" = s AND g."name" = ANY (p_extra);
  INSERT INTO "CalendarLessonStudents" ("schoolId", "calendarLessonId", "studentId")
  SELECT s, l, u."id" FROM "Users" u WHERE u."schoolId" = s AND u."email" = ANY (p_named);
  FOR i IN 1..coalesce(cardinality(p_marks), 0) LOOP
    INSERT INTO "AttendanceRecords" ("schoolId", "calendarLessonId", "studentId", status, "updatedAt")
    VALUES (s, l, pupils[i], p_marks[i]::"AttendanceStatus", now());
  END LOOP;
  RETURN l;
END $$;

-- An absence of a teacher between two local wall-clock times.
CREATE FUNCTION pg_temp.rg_absent(p_teacher uuid, p_from timestamp, p_to timestamp, p_status text DEFAULT 'ACTIVE') RETURNS void LANGUAGE sql AS $$
  INSERT INTO "TeacherAbsences" ("schoolId", "userId", "startsAt", "endsAt", status, "withdrawnAt", "updatedAt")
  VALUES (app.current_school_id(), p_teacher, p_from AT TIME ZONE 'Europe/Stockholm', p_to AT TIME ZONE 'Europe/Stockholm',
          p_status::"TeacherAbsenceStatus", CASE WHEN p_status = 'WITHDRAWN' THEN now() END, now())
$$;

-- The school's stored days as one readable text: teacher, day, reported/held.
CREATE FUNCTION pg_temp.rg_days() RETURNS text LANGUAGE sql AS $$
  SELECT coalesce(string_agg(substr(u.email, 4, 2) || ' ' || d.day || ' ' || d.reported || '/' || d.held, E'\n' ORDER BY u.email, d.day), '')
    FROM "TeacherReportingDays" d JOIN "Users" u ON u.id = d."teacherId" AND u."schoolId" = d."schoolId"
   WHERE d."schoolId" = app.current_school_id()
$$;

-- A teacher's reported/held over a stretch of days, as the view adds them up.
CREATE FUNCTION pg_temp.rg_sum(p_teacher text, p_from date, p_to date) RETURNS text LANGUAGE sql AS $$
  SELECT coalesce(sum(d.reported), 0) || '/' || coalesce(sum(d.held), 0)
    FROM "TeacherReportingDays" d JOIN "Users" u ON u.id = d."teacherId" AND u."schoolId" = d."schoolId"
   WHERE d."schoolId" = app.current_school_id() AND substr(u.email, 4, 2) = p_teacher AND d.day BETWEEN p_from AND p_to
$$;

-- The night's count, as the job asks it: what it wrote, removed, and the totals.
CREATE FUNCTION pg_temp.rg_compute(p_as_of date) RETURNS text LANGUAGE sql AS $$
  SELECT 'written ' || written || ', removed ' || removed || ', teachers ' || teachers || ', held ' || held || ', reported ' || reported
    FROM app.reporting_compute(app.current_school_id(), p_as_of)
$$;

-- A statement a CHECK or a unique index must refuse, by the constraint's name.
CREATE FUNCTION pg_temp.rg_refuses(p_sql text, p_constraint text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  EXECUTE p_sql;
  RAISE EXCEPTION 'rapporteringsgrad: accepted: %', p_sql;
EXCEPTION WHEN check_violation OR unique_violation THEN
  IF position(p_constraint IN SQLERRM) = 0 THEN
    RAISE EXCEPTION 'rapporteringsgrad: % was refused, but not by %: %', p_sql, p_constraint, SQLERRM;
  END IF;
END $$;

-- A statement the caller is refused: a missing privilege, a policy's check, or an
-- UPDATE or DELETE that no policy lets reach a row.
CREATE FUNCTION pg_temp.rg_denied(p_sql text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE
  n bigint;
BEGIN
  EXECUTE p_sql;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF p_sql ~* '^(UPDATE|DELETE)' AND n = 0 THEN RETURN; END IF;
  RAISE EXCEPTION 'rapporteringsgrad: not denied (% rows): %', n, p_sql;
EXCEPTION WHEN insufficient_privilege THEN NULL;
END $$;

CREATE FUNCTION pg_temp.rg_expect(p_label text, p_got text, p_want text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  IF p_got IS DISTINCT FROM p_want THEN
    RAISE EXCEPTION E'rapporteringsgrad %: got\n%\nwanted\n%', p_label, p_got, p_want;
  END IF;
END $$;

-- ---------------------------------------------------------------------------
-- Section 345: the tables and what their trigger does.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT pg_temp.rg_as(pg_temp.rg_auth(1));
DO $$
DECLARE
  school uuid := app.current_school_id();
  s record;
  today date := (now() AT TIME ZONE 'Europe/Stockholm')::date;
BEGIN
  IF app.current_user_role() IS DISTINCT FROM 'SCHOOL_ADMIN' THEN RAISE EXCEPTION 'rapporteringsgrad 345: expected the full administrator'; END IF;

  -- No row: both off and two days, as for every school before this migration.
  IF EXISTS (SELECT 1 FROM "ReportingSettings") THEN RAISE EXCEPTION 'rapporteringsgrad 345: the school starts with a row'; END IF;
  -- The row is inserted by those who write Drift: not by the läsare, a teacher, a guardian or a pupil.
  PERFORM pg_temp.rg_as(pg_temp.rg_auth(5));
  PERFORM pg_temp.rg_denied(format('INSERT INTO "ReportingSettings" ("schoolId") VALUES (%L)', school));
  PERFORM pg_temp.rg_as(pg_temp.rg_auth(6));
  PERFORM pg_temp.rg_denied(format('INSERT INTO "ReportingSettings" ("schoolId") VALUES (%L)', school));
  PERFORM pg_temp.rg_as(pg_temp.rg_auth(21));
  PERFORM pg_temp.rg_denied(format('INSERT INTO "ReportingSettings" ("schoolId") VALUES (%L)', school));
  PERFORM pg_temp.rg_as(pg_temp.rg_auth(11));
  PERFORM pg_temp.rg_denied(format('INSERT INTO "ReportingSettings" ("schoolId") VALUES (%L)', school));
  IF EXISTS (SELECT 1 FROM "ReportingSettings") THEN RAISE EXCEPTION 'rapporteringsgrad 345: a refused insert left a row'; END IF;
  PERFORM pg_temp.rg_as(pg_temp.rg_auth(1));
  INSERT INTO "ReportingSettings" ("schoolId") VALUES (school);
  SELECT * INTO s FROM "ReportingSettings";
  IF s."teacherReminders" OR s."rektorDigest" OR s."teacherRemindersOn" IS NOT NULL OR s."rektorDigestOn" IS NOT NULL OR s."openAfterDays" <> 2 THEN
    RAISE EXCEPTION 'rapporteringsgrad 345: the defaults are both off, no dates and two days: %', s;
  END IF;

  -- Each switch is dated with the school's own day when it goes on; a writer's date is the trigger's.
  UPDATE "ReportingSettings" SET "teacherReminders" = true, "teacherRemindersOn" = '2020-01-01', "rektorDigestOn" = '2020-01-01';
  SELECT * INTO s FROM "ReportingSettings";
  IF NOT s."teacherReminders" OR s."teacherRemindersOn" IS DISTINCT FROM today THEN
    RAISE EXCEPTION 'rapporteringsgrad 345: turning the reminders on set the date to %, not %', s."teacherRemindersOn", today;
  END IF;
  IF s."rektorDigest" OR s."rektorDigestOn" IS NOT NULL THEN
    RAISE EXCEPTION 'rapporteringsgrad 345: the weekly notice was dated without being turned on: %', s."rektorDigestOn";
  END IF;
  UPDATE "ReportingSettings" SET "rektorDigest" = true;
  IF (SELECT "rektorDigestOn" FROM "ReportingSettings") IS DISTINCT FROM today THEN RAISE EXCEPTION 'rapporteringsgrad 345: turning the weekly notice on did not date it'; END IF;
  UPDATE "ReportingSettings" SET "openAfterDays" = 5, "teacherRemindersOn" = '2020-01-01', "rektorDigestOn" = '2020-01-01';
  SELECT * INTO s FROM "ReportingSettings";
  IF s."teacherRemindersOn" IS DISTINCT FROM today OR s."rektorDigestOn" IS DISTINCT FROM today OR s."openAfterDays" <> 5 THEN
    RAISE EXCEPTION 'rapporteringsgrad 345: another change moved a date the switches went on: %', s;
  END IF;
  -- Off keeps the date, and a switch left on without a date is not possible.
  UPDATE "ReportingSettings" SET "teacherReminders" = false, "rektorDigest" = false;
  SELECT * INTO s FROM "ReportingSettings";
  IF s."teacherRemindersOn" IS DISTINCT FROM today OR s."rektorDigestOn" IS DISTINCT FROM today THEN
    RAISE EXCEPTION 'rapporteringsgrad 345: turning them off cleared a date: %', s;
  END IF;

  -- The limit: both ends of its range, and nothing outside it.
  UPDATE "ReportingSettings" SET "openAfterDays" = 1;
  UPDATE "ReportingSettings" SET "openAfterDays" = 30;
  PERFORM pg_temp.rg_refuses('UPDATE "ReportingSettings" SET "openAfterDays" = 0', 'open_after_days_is_sane');
  PERFORM pg_temp.rg_refuses('UPDATE "ReportingSettings" SET "openAfterDays" = 31', 'open_after_days_is_sane');
  UPDATE "ReportingSettings" SET "openAfterDays" = 2;

  -- One row per school (the key), and the school's own.
  BEGIN
    INSERT INTO "ReportingSettings" ("schoolId") VALUES (school);
    RAISE EXCEPTION 'rapporteringsgrad 345: a second row for the school was accepted';
  EXCEPTION WHEN unique_violation THEN NULL;
  END;
  BEGIN
    INSERT INTO "ReportingSettings" ("schoolId") VALUES (gen_random_uuid());
    RAISE EXCEPTION 'rapporteringsgrad 345: a row for another school was accepted';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 346: the count.
--
-- One teacher-day per teacher with a held lesson: held lessons, and how many
-- of them have a saved register. Every case below is a lesson on the
-- Tuesday 2026-09-15 unless it says otherwise; the hour is the local one.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT pg_temp.rg_as(pg_temp.rg_auth(1));
DO $$
DECLARE
  school uuid := app.current_school_id();
  t1 uuid := pg_temp.rg_id('rg-t1@example.invalid');
  t2 uuid := pg_temp.rg_id('rg-t2@example.invalid');
  t3 uuid := pg_temp.rg_id('rg-t3@example.invalid');
  t4 uuid := pg_temp.rg_id('rg-t4@example.invalid');
  t5 uuid := pg_temp.rg_id('rg-t5@example.invalid');
  d date := '2026-09-15';
  open_one uuid;
  unknown_one uuid;
  held_one uuid;
  yr uuid := (SELECT id FROM "AcademicYears" WHERE "schoolId" = school);
  wd date;
BEGIN
  -- The kinds of lesson. T1 teaches 8, 9, 12, 13 and 15 (held), not 10 and 11 (never held), and 7 and 19 (cancelled).
  PERFORM pg_temp.rg_lesson(d, 8, ARRAY[t1], ARRAY['PRESENT', 'PRESENT']);                       -- held, register saved
  open_one := pg_temp.rg_lesson(d, 9, ARRAY[t1]);                                                  -- held, nothing saved
  PERFORM pg_temp.rg_lesson(d, 10, ARRAY[t1], ARRAY['PRESENT'], 'CANCELLED', NULL, 'MANUAL');      -- cancelled: never, whatever was saved
  PERFORM pg_temp.rg_lesson(d, 11, ARRAY[t1], ARRAY['PRESENT'], 'RESCHEDULED');                    -- rescheduled: never
  unknown_one := pg_temp.rg_lesson(d, 12, ARRAY[t1], ARRAY['UNKNOWN', 'UNKNOWN']);                 -- held; UNKNOWN is no mark
  PERFORM pg_temp.rg_lesson(d, 13, ARRAY[t1], ARRAY['EXCUSED', 'UNKNOWN'], 'COMPLETED');           -- COMPLETED is held, one mark is a register
  PERFORM pg_temp.rg_lesson(d, 7, ARRAY[t1], ARRAY['PRESENT'], 'CANCELLED', NULL, 'TEACHER_UNAVAILABLE');
  PERFORM pg_temp.rg_lesson(d, 19, ARRAY[t1], ARRAY['PRESENT'], 'CANCELLED', NULL, 'EVENT');       -- an activity's cancelled lesson
  -- A replacement lesson (Schemabrytande aktivitet) is a lesson no template made, held by the teacher it names.
  PERFORM pg_temp.rg_lesson(d, 14, ARRAY[t2], ARRAY['ABSENT'], 'SCHEDULED', ARRAY['SUBSTITUTE']);  -- the substitute's own
  PERFORM pg_temp.rg_lesson(d, 15, ARRAY[t1, t3], ARRAY['LATE'], 'SCHEDULED', ARRAY['LEAD', 'ASSISTANT']); -- co-taught, saved by either: both
  PERFORM pg_temp.rg_lesson(d, 16, ARRAY[t2, t3]);                                                 -- co-taught, open for both
  PERFORM pg_temp.rg_lesson(d, 17, ARRAY[t4], ARRAY['PRESENT']);                                   -- a teacher who has since left: nobody's
  PERFORM pg_temp.rg_lesson(d, 20, ARRAY[t5], ARRAY['PRESENT']);                                   -- a teacher whose only lesson it is
  PERFORM pg_temp.rg_lesson(d, 18, ARRAY[]::uuid[], ARRAY['PRESENT']);                             -- nobody teaches it: nobody's

  PERFORM pg_temp.rg_expect('346 first night', pg_temp.rg_compute('2026-09-30'),
    'written 4, removed 0, teachers 4, held 10, reported 6');
  PERFORM pg_temp.rg_expect('346 the days', pg_temp.rg_days(),
    E't1 2026-09-15 3/5\nt2 2026-09-15 1/2\nt3 2026-09-15 1/2\nt5 2026-09-15 1/1');
  -- Again: the same rows, so nothing is rewritten.
  PERFORM pg_temp.rg_expect('346 again', pg_temp.rg_compute('2026-09-30'), 'written 0, removed 0, teachers 4, held 10, reported 6');

  -- A register saved late moves the day on the next night, and only that row.
  INSERT INTO "AttendanceRecords" ("schoolId", "calendarLessonId", "studentId", status, "updatedAt")
  VALUES (school, open_one, pg_temp.rg_id('rg-p1@example.invalid'), 'PRESENT', now());
  PERFORM pg_temp.rg_expect('346 late register', pg_temp.rg_compute('2026-09-30'), 'written 1, removed 0, teachers 4, held 10, reported 7');
  UPDATE "AttendanceRecords" SET status = 'PRESENT' WHERE "calendarLessonId" = unknown_one AND status = 'UNKNOWN';
  PERFORM pg_temp.rg_expect('346 UNKNOWN made a mark', pg_temp.rg_compute('2026-09-30'), 'written 1, removed 0, teachers 4, held 10, reported 8');
  PERFORM pg_temp.rg_expect('346 the days, late', pg_temp.rg_days(),
    E't1 2026-09-15 5/5\nt2 2026-09-15 1/2\nt3 2026-09-15 1/2\nt5 2026-09-15 1/1');
  -- A lesson that is cancelled afterwards stops counting, saved or not; and a teacher whose only lesson goes loses the day.
  UPDATE "CalendarLessons" SET status = 'CANCELLED', "cancelCause" = 'MANUAL'
   WHERE "studentGroupId" = (SELECT id FROM "StudentGroups" WHERE name = 'RG7A') AND date = d
     AND "startsAt" = (d + time '08:00') AT TIME ZONE 'Europe/Stockholm';
  UPDATE "CalendarLessons" SET status = 'CANCELLED', "cancelCause" = 'MANUAL'
   WHERE "studentGroupId" = (SELECT id FROM "StudentGroups" WHERE name = 'RG7A') AND date = d
     AND "startsAt" = (d + time '20:00') AT TIME ZONE 'Europe/Stockholm';
  PERFORM pg_temp.rg_expect('346 cancelled afterwards', pg_temp.rg_compute('2026-09-30'), 'written 1, removed 1, teachers 3, held 8, reported 6');
  PERFORM pg_temp.rg_expect('346 the days, after', pg_temp.rg_days(),
    E't1 2026-09-15 4/4\nt2 2026-09-15 1/2\nt3 2026-09-15 1/2');
  -- Reinstated: back, with the register it had.
  UPDATE "CalendarLessons" SET status = 'SCHEDULED', "cancelCause" = NULL
   WHERE "studentGroupId" = (SELECT id FROM "StudentGroups" WHERE name = 'RG7A') AND date = d
     AND "startsAt" = (d + time '20:00') AT TIME ZONE 'Europe/Stockholm';
  PERFORM pg_temp.rg_expect('346 reinstated', pg_temp.rg_compute('2026-09-30'), 'written 1, removed 0, teachers 4, held 9, reported 7');

  -- A teacher who is themself away cannot have taken the register: the lesson is not theirs to report while
  -- an active absence overlaps it. 2026-09-16, T1 away 12:00-18:00.
  wd := '2026-09-16';
  PERFORM pg_temp.rg_absent(t1, wd + time '12:00', wd + time '18:00');
  PERFORM pg_temp.rg_lesson(wd, 8, ARRAY[t1]);                              -- before the absence: counted
  PERFORM pg_temp.rg_lesson(wd, 11, ARRAY[t1]);                             -- ends 11:50, ten minutes before: counted
  PERFORM pg_temp.rg_lesson(wd, 12, ARRAY[t1], ARRAY['PRESENT']);           -- starts when the absence does: not counted
  PERFORM pg_temp.rg_lesson(wd, 17, ARRAY[t1]);                             -- inside it: not counted
  PERFORM pg_temp.rg_lesson(wd, 18, ARRAY[t1], ARRAY['PRESENT']);           -- starts when the absence ends: counted
  -- An absence that only touches a lesson does not overlap it, at either end. 2026-09-18, T3 away 09:50-12:00.
  wd := '2026-09-18';
  PERFORM pg_temp.rg_absent(t3, wd + time '09:50', wd + time '12:00');
  PERFORM pg_temp.rg_lesson(wd, 9, ARRAY[t3]);                              -- ends 09:50, as the absence begins: counted
  PERFORM pg_temp.rg_lesson(wd, 10, ARRAY[t3]);                             -- inside it: not counted
  PERFORM pg_temp.rg_lesson(wd, 12, ARRAY[t3]);                             -- starts as it ends: counted
  wd := '2026-09-16';
  -- The substitute who is away too is not counted for the lesson either.
  PERFORM pg_temp.rg_absent(t2, wd + time '09:00', wd + time '10:00');
  PERFORM pg_temp.rg_lesson(wd, 9, ARRAY[t2], ARRAY[]::text[], 'SCHEDULED', ARRAY['SUBSTITUTE']);
  -- A withdrawn absence is no absence.
  PERFORM pg_temp.rg_absent(t1, '2026-09-17'::date + time '08:00', '2026-09-17'::date + time '18:00', 'WITHDRAWN');
  PERFORM pg_temp.rg_lesson('2026-09-17', 13, ARRAY[t1]);
  PERFORM pg_temp.rg_compute('2026-09-30');
  PERFORM pg_temp.rg_expect('346 absent teachers', pg_temp.rg_days(),
    E't1 2026-09-15 4/4\nt1 2026-09-16 1/3\nt1 2026-09-17 0/1\nt2 2026-09-15 1/2\nt3 2026-09-15 1/2\nt3 2026-09-18 0/2\nt5 2026-09-15 1/1');

  -- Lov. The week of 21-25 September is a lov: its lessons are cancelled, with registers or without, and give
  -- no rows; the week after loses Monday to Wednesday and keeps Thursday and Friday.
  INSERT INTO "SchoolBreaks" ("schoolId", "academicYearId", name, kind, "startDate", "endDate", "updatedAt")
  VALUES (school, yr, 'Höstlov', 'HOLIDAY', '2026-09-21', '2026-09-25', now());
  INSERT INTO "SchoolBreaks" ("schoolId", "academicYearId", name, kind, "startDate", "endDate", "updatedAt")
  VALUES (school, yr, 'Studiedagar', 'STAFF_DAY', '2026-09-28', '2026-09-30', now());
  FOR wd IN SELECT g::date FROM generate_series('2026-09-21'::date, '2026-09-30'::date, interval '1 day') g WHERE extract(isodow FROM g) < 6 LOOP
    PERFORM pg_temp.rg_lesson(wd, 8, ARRAY[t1], CASE WHEN extract(day FROM wd)::integer % 2 = 0 THEN ARRAY['PRESENT'] ELSE ARRAY[]::text[] END,
                              'CANCELLED', NULL, 'MANUAL');
  END LOOP;
  PERFORM pg_temp.rg_lesson('2026-10-01', 8, ARRAY[t1]);
  PERFORM pg_temp.rg_lesson('2026-10-02', 8, ARRAY[t1], ARRAY['PRESENT']);
  PERFORM pg_temp.rg_compute('2026-10-04');
  PERFORM pg_temp.rg_expect('346 lov week', pg_temp.rg_sum('t1', '2026-09-21', '2026-09-27'), '0/0');
  IF EXISTS (SELECT 1 FROM "TeacherReportingDays" d WHERE d."schoolId" = school AND d.day BETWEEN '2026-09-21' AND '2026-09-30') THEN
    RAISE EXCEPTION 'rapporteringsgrad 346: a day of the lov has a row';
  END IF;
  PERFORM pg_temp.rg_expect('346 half lov week', pg_temp.rg_sum('t1', '2026-09-28', '2026-10-04'), '1/2');
  -- A week of the lov in the middle of a month leaves the month's figure to the weeks around it.
  PERFORM pg_temp.rg_expect('346 the month', pg_temp.rg_sum('t1', '2026-09-01', '2026-09-30'), '5/8');
  PERFORM pg_temp.rg_expect('346 the läsår so far', pg_temp.rg_sum('t1', '2026-01-01', '2026-12-31'), '6/10');

  -- The night refuses a day that has not passed, and a school it does not know.
  BEGIN
    PERFORM * FROM app.reporting_compute(school, (now() AT TIME ZONE 'Europe/Stockholm')::date);
    RAISE EXCEPTION 'rapporteringsgrad 346: today was counted';
  EXCEPTION WHEN SQLSTATE 'RR400' THEN NULL;
  END;
  BEGIN
    PERFORM * FROM app.reporting_compute(school, (now() AT TIME ZONE 'Europe/Stockholm')::date + 3);
    RAISE EXCEPTION 'rapporteringsgrad 346: a day to come was counted';
  EXCEPTION WHEN SQLSTATE 'RR400' THEN NULL;
  END;
  BEGIN
    PERFORM * FROM app.reporting_compute(school, NULL);
    RAISE EXCEPTION 'rapporteringsgrad 346: no day was counted';
  EXCEPTION WHEN SQLSTATE 'RR400' THEN NULL;
  END;
  BEGIN
    PERFORM * FROM app.reporting_compute(gen_random_uuid(), '2026-09-30');
    RAISE EXCEPTION 'rapporteringsgrad 346: an unknown school was counted';
  EXCEPTION WHEN SQLSTATE 'RR404' THEN NULL;
  END;
END $$;

-- Summer time. The switch to summer time (Sunday 29 March 2026) and back (Sunday 25 October) are days of
-- 23 and 25 hours; a lesson is on the day it was written for whatever its instant says, a week is seven
-- calendar days, and an absence is compared by instants, so one that spans the night is neither longer nor
-- shorter than it says. All of this in the school's own times.
DO $$
DECLARE
  school uuid := app.current_school_id();
  t1 uuid := pg_temp.rg_id('rg-t1@example.invalid');
  t2 uuid := pg_temp.rg_id('rg-t2@example.invalid');
  t3 uuid := pg_temp.rg_id('rg-t3@example.invalid');
BEGIN
  -- Spring. Friday the 27th and Monday the 30th; Monday's first lesson (T3's) starts at midnight, which is
  -- Sunday 22:00 in UTC and still Monday's.
  PERFORM pg_temp.rg_lesson('2026-03-27', 8, ARRAY[t1], ARRAY['PRESENT']);
  PERFORM pg_temp.rg_lesson('2026-03-27', 23, ARRAY[t1]);
  PERFORM pg_temp.rg_lesson('2026-03-30', 0, ARRAY[t3]);
  PERFORM pg_temp.rg_lesson('2026-03-30', 8, ARRAY[t1], ARRAY['PRESENT']);
  -- Monday's 07:00 lesson falls inside T1's absence from Saturday evening to 07:30 on Monday, over the night
  -- that has 23 hours; the one at 08:00 does not.
  PERFORM pg_temp.rg_absent(t1, '2026-03-28 20:00', '2026-03-30 07:30');
  PERFORM pg_temp.rg_lesson('2026-03-30', 7, ARRAY[t1], ARRAY['PRESENT']);
  -- T2 is away from Saturday 20:00 to Sunday 12:00 local time, which is 15 hours of the clock but 14 of time.
  PERFORM pg_temp.rg_absent(t2, '2026-03-28 20:00', '2026-03-29 12:00');
  PERFORM pg_temp.rg_lesson('2026-03-28', 22, ARRAY[t2]);                  -- inside the absence
  PERFORM pg_temp.rg_lesson('2026-03-29', 11, ARRAY[t2]);                  -- inside it, the morning after the switch
  PERFORM pg_temp.rg_lesson('2026-03-29', 12, ARRAY[t2], ARRAY['PRESENT']); -- starts when it ends
  PERFORM pg_temp.rg_compute('2026-04-05');
  PERFORM pg_temp.rg_expect('346 spring week one', pg_temp.rg_sum('t1', '2026-03-23', '2026-03-29'), '1/2');
  PERFORM pg_temp.rg_expect('346 spring week two', pg_temp.rg_sum('t1', '2026-03-30', '2026-04-05'), '1/1');
  PERFORM pg_temp.rg_expect('346 midnight is Monday''s', pg_temp.rg_sum('t3', '2026-03-30', '2026-03-30') || ' ' || pg_temp.rg_sum('t3', '2026-03-29', '2026-03-29'), '0/1 0/0');
  PERFORM pg_temp.rg_expect('346 spring days', (SELECT string_agg(d.day::text || ' ' || d.reported || '/' || d.held, ', ' ORDER BY d.day)
      FROM "TeacherReportingDays" d WHERE d."teacherId" = t1 AND d.day BETWEEN '2026-03-01' AND '2026-04-30'),
    '2026-03-27 1/2, 2026-03-30 1/1');
  PERFORM pg_temp.rg_expect('346 spring across the night', pg_temp.rg_sum('t2', '2026-03-23', '2026-04-05'), '1/1');

  -- Autumn. Friday the 23rd and Monday the 26th; the Sunday in between has 25 hours.
  PERFORM pg_temp.rg_lesson('2026-10-23', 8, ARRAY[t1], ARRAY['PRESENT']);
  PERFORM pg_temp.rg_lesson('2026-10-26', 8, ARRAY[t1]);
  PERFORM pg_temp.rg_absent(t2, '2026-10-24 20:00', '2026-10-25 12:00');
  PERFORM pg_temp.rg_lesson('2026-10-25', 11, ARRAY[t2]);                  -- inside
  PERFORM pg_temp.rg_lesson('2026-10-25', 12, ARRAY[t2]);                  -- starts as it ends
  PERFORM pg_temp.rg_compute('2026-11-01');
  PERFORM pg_temp.rg_expect('346 autumn weeks', pg_temp.rg_sum('t1', '2026-10-19', '2026-10-25') || ' ' || pg_temp.rg_sum('t1', '2026-10-26', '2026-11-01'), '1/1 0/1');
  PERFORM pg_temp.rg_expect('346 autumn across the night', pg_temp.rg_sum('t2', '2026-10-19', '2026-11-01'), '0/1');
END $$;
ROLLBACK;
-- ---------------------------------------------------------------------------
-- Section 346, the roster: a lesson no pupil can be marked on is nobody's.
--
-- The roster is the register's own (calendar/lesson-roster.ts), the active pupils of the lesson's
-- class, of the groups joined to it, the members of those groups and the pupils the lesson names.
-- A lesson with none is neither held nor open nor reported, however long it stands, because the
-- teacher can do nothing about it; unless its register was saved before the roster emptied, which
-- stays a register. Every case below is a lesson on the Tuesday 2026-09-22.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT pg_temp.rg_as(pg_temp.rg_auth(1));
DO $$
DECLARE
  t1 uuid := pg_temp.rg_id('rg-t1@example.invalid');
  d date := '2026-09-22';
BEGIN
  -- Nobody on the roster: a class with no pupil, a class whose only pupil was deactivated before it held a day
  -- (no segment of the class history, and not active), a teaching group whose only member is a teacher, a
  -- lesson that names a teacher, and a lesson whose joined groups are two of those.
  PERFORM pg_temp.rg_lesson(d, 8, ARRAY[t1], '{}', 'SCHEDULED', NULL, NULL, 'RG7B');
  PERFORM pg_temp.rg_lesson(d, 9, ARRAY[t1], '{}', 'SCHEDULED', NULL, NULL, 'RG7C');
  PERFORM pg_temp.rg_lesson(d, 10, ARRAY[t1], '{}', 'SCHEDULED', NULL, NULL, 'RG7E');
  PERFORM pg_temp.rg_lesson(d, 12, ARRAY[t1], '{}', 'SCHEDULED', NULL, NULL, 'RG7B', '{}', ARRAY['rg-t2@example.invalid']);
  PERFORM pg_temp.rg_lesson(d, 7, ARRAY[t1], '{}', 'SCHEDULED', NULL, NULL, 'RG7B', ARRAY['RG7C', 'RG7E']);        -- groups joined to it that have nobody to list
  PERFORM pg_temp.rg_expect('346r nobody on the roster', pg_temp.rg_compute('2026-09-30'),
    'written 0, removed 0, teachers 0, held 0, reported 0');

  -- Each source is enough on its own, and each is a lesson the others do not reach.
  PERFORM pg_temp.rg_lesson(d, 13, ARRAY[t1]);                                                                      -- the class's pupils
  PERFORM pg_temp.rg_lesson(d, 14, ARRAY[t1], '{}', 'SCHEDULED', NULL, NULL, 'RG7D');                               -- a teaching group's members
  PERFORM pg_temp.rg_lesson(d, 15, ARRAY[t1], '{}', 'SCHEDULED', NULL, NULL, 'RG7B', ARRAY['RG7A']);                -- the pupils of a class joined to it
  PERFORM pg_temp.rg_lesson(d, 16, ARRAY[t1], '{}', 'SCHEDULED', NULL, NULL, 'RG7B', ARRAY['RG7D']);                -- the members of a group joined to it
  PERFORM pg_temp.rg_lesson(d, 17, ARRAY[t1], '{}', 'SCHEDULED', NULL, NULL, 'RG7B', '{}', ARRAY['rg-p4@example.invalid']); -- a pupil it names
  -- A pupil who has been deactivated since is still a pupil of a group or a lesson: the lesson was held with them
  -- on it, and a day that was counted does not change when they leave.
  PERFORM pg_temp.rg_lesson(d, 18, ARRAY[t1], '{}', 'SCHEDULED', NULL, NULL, 'RG7F');                              -- a member who has left
  PERFORM pg_temp.rg_lesson(d, 19, ARRAY[t1], '{}', 'SCHEDULED', NULL, NULL, 'RG7B', '{}', ARRAY['rg-p3@example.invalid']); -- a named pupil who has left
  PERFORM pg_temp.rg_lesson(d, 20, ARRAY[t1], '{}', 'SCHEDULED', NULL, NULL, 'RG7B', ARRAY['RG7F']);               -- the members of a joined group who have left
  PERFORM pg_temp.rg_expect('346r each source', pg_temp.rg_compute('2026-09-30'),
    'written 1, removed 0, teachers 1, held 8, reported 0');

  -- A register saved on a lesson stays a register, whatever the roster has become: reported, and held.
  PERFORM pg_temp.rg_lesson(d, 21, ARRAY[t1], ARRAY['PRESENT'], 'SCHEDULED', NULL, NULL, 'RG7B');
  PERFORM pg_temp.rg_expect('346r a saved register on an empty roster', pg_temp.rg_compute('2026-09-30'),
    'written 1, removed 0, teachers 1, held 9, reported 1');

  -- An administrator on a lesson is no teacher: no row, no count.
  PERFORM pg_temp.rg_lesson(d, 22, ARRAY[pg_temp.rg_id('rg-full@example.invalid')]);
  PERFORM pg_temp.rg_expect('346r an administrator on a lesson', pg_temp.rg_compute('2026-09-30'),
    'written 0, removed 0, teachers 1, held 9, reported 1');
  PERFORM pg_temp.rg_expect('346r the day', pg_temp.rg_days(), 't1 2026-09-22 1/9');
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 347: who reads and who writes.
--
-- Every administrator reads every teacher's days, the läsare too, and the
-- switch and the limit are Drift's to write; a teacher reads their own days
-- and the limit, a pupil and a guardian read nothing, and nobody writes a day,
-- the week's ledger or the reminders' ledger. The teacher's own list of open
-- lessons answers for the teacher it is asked by.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT pg_temp.rg_as(pg_temp.rg_auth(1));
DO $$
DECLARE
  school uuid := app.current_school_id();
  t1 uuid := pg_temp.rg_id('rg-t1@example.invalid');
  t2 uuid := pg_temp.rg_id('rg-t2@example.invalid');
  today date := (now() AT TIME ZONE 'Europe/Stockholm')::date;
BEGIN
  IF app.current_user_role() IS DISTINCT FROM 'SCHOOL_ADMIN' THEN RAISE EXCEPTION 'rapporteringsgrad 347: expected the full administrator'; END IF;
  PERFORM pg_temp.rg_lesson('2026-09-15', 8, ARRAY[t1], ARRAY['PRESENT']);
  PERFORM pg_temp.rg_lesson('2026-09-15', 9, ARRAY[t1]);
  PERFORM pg_temp.rg_lesson('2026-09-15', 14, ARRAY[t2], ARRAY['PRESENT'], 'SCHEDULED', ARRAY['SUBSTITUTE']);
  PERFORM pg_temp.rg_compute('2026-09-30');
  INSERT INTO "ReportingSettings" ("schoolId", "rektorDigest", "openAfterDays") VALUES (school, true, 3);
  IF (SELECT count(*) FROM app.reporting_digest(school, '2026-09-14', '2026-09-20')) <> 2 THEN
    RAISE EXCEPTION 'rapporteringsgrad 347: the week was not told to the two who decide';
  END IF;
  -- The lessons of the teacher's own list, measured from today: the limit is three days.
  PERFORM pg_temp.rg_lesson(today - 1, 8, ARRAY[t1]);                                       -- open, newer than the limit
  PERFORM pg_temp.rg_lesson(today - 3, 9, ARRAY[t1]);                                       -- open, on the limit
  PERFORM pg_temp.rg_lesson(today - 10, 10, ARRAY[t1]);                                     -- open, past it
  PERFORM pg_temp.rg_lesson(today - 40, 11, ARRAY[t1]);                                     -- further back than a month
  PERFORM pg_temp.rg_lesson(today - 95, 16, ARRAY[t1]);                                     -- further back than the list ever goes
  PERFORM pg_temp.rg_lesson(today - 2, 12, ARRAY[t1], ARRAY['PRESENT']);                    -- saved
  PERFORM pg_temp.rg_lesson(today - 2, 13, ARRAY[t1], ARRAY[]::text[], 'CANCELLED', NULL, 'MANUAL'); -- cancelled
  PERFORM pg_temp.rg_lesson(today - 4, 14, ARRAY[t2]);                                      -- the other teacher's
  PERFORM pg_temp.rg_lesson(today - 4, 15, ARRAY[t1, t2]);                                  -- both
  PERFORM pg_temp.rg_lesson(today - 2, 16, ARRAY[pg_temp.rg_id('rg-full@example.invalid')]); -- an administrator who also teaches
  PERFORM pg_temp.rg_lesson(today - 5, 17, ARRAY[t1], ARRAY[]::text[], 'SCHEDULED', NULL, NULL, 'RG7B'); -- nobody to mark: not open
  PERFORM set_config('app.test_rg_school', school::text, true);
END $$;

SELECT pg_temp.rg_as(pg_temp.rg_auth(31));
DO $$
BEGIN
  IF app.current_school_id() = current_setting('app.test_rg_school')::uuid THEN RAISE EXCEPTION 'rapporteringsgrad 347: the other administrator is at the first school'; END IF;
  INSERT INTO "ReportingSettings" ("schoolId") VALUES (app.current_school_id());
  PERFORM set_config('app.test_rg_other', app.current_school_id()::text, true);
END $$;

CREATE FUNCTION pg_temp.rg_count(p_auth text, p_table text) RETURNS integer LANGUAGE plpgsql AS $$
DECLARE
  n integer;
BEGIN
  PERFORM pg_temp.rg_as(p_auth);
  EXECUTE format('SELECT count(*) FROM %I', p_table) INTO n;
  RETURN n;
END $$;

-- The days the reader reads, as 'day reported/held', and how many of them are not theirs.
CREATE FUNCTION pg_temp.rg_sees(p_auth text) RETURNS text LANGUAGE plpgsql AS $$
DECLARE
  seen text;
BEGIN
  PERFORM pg_temp.rg_as(p_auth);
  SELECT coalesce(string_agg(d.day || ' ' || d.reported || '/' || d.held, ', ' ORDER BY d.day, d.held, d.reported), '')
    INTO seen FROM "TeacherReportingDays" d;
  RETURN seen;
END $$;

-- The reader's open lessons: how many days back, and a bang for one past the limit.
CREATE FUNCTION pg_temp.rg_open(p_auth text, p_days integer DEFAULT 30) RETURNS text LANGUAGE plpgsql AS $$
DECLARE
  seen text;
BEGIN
  PERFORM pg_temp.rg_as(p_auth);
  SELECT coalesce(string_agg((((now() AT TIME ZONE 'Europe/Stockholm')::date - o.day)::text || CASE WHEN o.overdue THEN '!' ELSE '' END),
                             ', ' ORDER BY o.starts_at DESC, o.lesson_id), '')
    INTO seen FROM app.reporting_open_lessons(p_days) o;
  RETURN seen;
END $$;

DO $$
DECLARE
  who record;
  t record;
BEGIN
  -- Every administrator reads the school's days, its switch and its ledger, and none of the other school's.
  FOR who IN SELECT * FROM (VALUES ('full', 1), ('rektor', 2), ('expedition', 3), ('schemaläggare', 4), ('läsare', 5)) v(name, n) LOOP
    IF pg_temp.rg_count(pg_temp.rg_auth(who.n), 'TeacherReportingDays') <> 2
       OR pg_temp.rg_count(pg_temp.rg_auth(who.n), 'ReportingSettings') <> 1
       OR pg_temp.rg_count(pg_temp.rg_auth(who.n), 'ReportingDigests') <> 1 THEN
      RAISE EXCEPTION 'rapporteringsgrad 347: the % does not read the 2 days, the switch and the 1 ledger row of the school', who.name;
    END IF;
  END LOOP;
  PERFORM pg_temp.rg_expect('347 admin', pg_temp.rg_sees(pg_temp.rg_auth(1)), '2026-09-15 1/1, 2026-09-15 1/2');
  -- The other school's administrator reads its own day, its own switch, and nothing of this school's.
  PERFORM pg_temp.rg_expect('347 the other school', pg_temp.rg_sees(pg_temp.rg_auth(31)), '2026-09-15 3/4');
  IF pg_temp.rg_count(pg_temp.rg_auth(31), 'ReportingSettings') <> 1 OR pg_temp.rg_count(pg_temp.rg_auth(31), 'ReportingDigests') <> 0 THEN
    RAISE EXCEPTION 'rapporteringsgrad 347: the other school''s administrator reads this school''s switch or ledger';
  END IF;

  -- A teacher reads their own days and no one else's, and the limit, which is no one's data.
  PERFORM pg_temp.rg_expect('347 T1', pg_temp.rg_sees(pg_temp.rg_auth(6)), '2026-09-15 1/2');
  PERFORM pg_temp.rg_expect('347 T2', pg_temp.rg_sees(pg_temp.rg_auth(7)), '2026-09-15 1/1');
  PERFORM pg_temp.rg_expect('347 T3', pg_temp.rg_sees(pg_temp.rg_auth(8)), '');
  PERFORM pg_temp.rg_expect('347 a teacher who has left', pg_temp.rg_sees(pg_temp.rg_auth(9)), '');
  PERFORM pg_temp.rg_expect('347 the other school''s teacher', pg_temp.rg_sees(pg_temp.rg_auth(32)), '2026-09-15 3/4');
  FOR who IN SELECT * FROM (VALUES (6), (7), (8)) v(n) LOOP
    PERFORM pg_temp.rg_as(pg_temp.rg_auth(who.n));
    IF (SELECT count(*) FROM "TeacherReportingDays" WHERE "teacherId" IS DISTINCT FROM app.current_user_id()) <> 0 THEN
      RAISE EXCEPTION 'rapporteringsgrad 347: a teacher reads a day that is not theirs';
    END IF;
    IF pg_temp.rg_count(pg_temp.rg_auth(who.n), 'ReportingSettings') <> 1 OR pg_temp.rg_count(pg_temp.rg_auth(who.n), 'ReportingDigests') <> 0 THEN
      RAISE EXCEPTION 'rapporteringsgrad 347: a teacher reads other than the limit';
    END IF;
  END LOOP;
  IF (SELECT "openAfterDays" FROM "ReportingSettings") <> 3 THEN RAISE EXCEPTION 'rapporteringsgrad 347: the teacher reads another limit than the school''s'; END IF;
  IF pg_temp.rg_count(pg_temp.rg_auth(9), 'ReportingSettings') <> 0 THEN RAISE EXCEPTION 'rapporteringsgrad 347: a teacher who has left reads the limit'; END IF;
  IF pg_temp.rg_count(pg_temp.rg_auth(32), 'ReportingSettings') <> 1 THEN RAISE EXCEPTION 'rapporteringsgrad 347: the other school''s teacher does not read their own limit'; END IF;

  -- A pupil, a guardian, an unknown login and no login read nothing, and nothing is theirs to see in the ledger.
  FOR who IN SELECT * FROM (VALUES (11), (21), (99)) v(n) LOOP
    IF pg_temp.rg_count(pg_temp.rg_auth(who.n), 'TeacherReportingDays') <> 0 OR pg_temp.rg_count(pg_temp.rg_auth(who.n), 'ReportingSettings') <> 0
       OR pg_temp.rg_count(pg_temp.rg_auth(who.n), 'ReportingDigests') <> 0 THEN
      RAISE EXCEPTION 'rapporteringsgrad 347: …% reads days, the switch or the ledger', who.n;
    END IF;
  END LOOP;
  PERFORM set_config('request.jwt.claims', '', true);
  IF (SELECT count(*) FROM "TeacherReportingDays") <> 0 OR (SELECT count(*) FROM "ReportingSettings") <> 0 OR (SELECT count(*) FROM "ReportingDigests") <> 0 THEN
    RAISE EXCEPTION 'rapporteringsgrad 347: no principal reads days, the switch or the ledger';
  END IF;

  -- The reminders' ledger is read by nobody: the table is closed to the API role itself.
  FOR who IN SELECT * FROM (VALUES (1), (2), (5), (6), (11), (21)) v(n) LOOP
    PERFORM pg_temp.rg_as(pg_temp.rg_auth(who.n));
    PERFORM pg_temp.rg_denied('SELECT count(*) FROM "ReportingReminders"');
    PERFORM pg_temp.rg_denied('INSERT INTO "ReportingReminders" ("schoolId", "teacherId", "calendarLessonId", "lessonDate") VALUES (app.current_school_id(), app.current_user_id(), gen_random_uuid(), current_date)');
    PERFORM pg_temp.rg_denied('UPDATE "ReportingReminders" SET "lessonDate" = current_date');
    PERFORM pg_temp.rg_denied('DELETE FROM "ReportingReminders"');
  END LOOP;
END $$;

-- The teacher's own list of open lessons.
DO $$
BEGIN
  PERFORM pg_temp.rg_expect('347 T1 open', pg_temp.rg_open(pg_temp.rg_auth(6)), '1, 3!, 4!, 10!');
  PERFORM pg_temp.rg_expect('347 T2 open', pg_temp.rg_open(pg_temp.rg_auth(7)), '4!, 4!');
  PERFORM pg_temp.rg_expect('347 T1 open, five days', pg_temp.rg_open(pg_temp.rg_auth(6), 5), '1, 3!, 4!');
  PERFORM pg_temp.rg_expect('347 T1 open, no days', pg_temp.rg_open(pg_temp.rg_auth(6), 0), '1');
  -- (The first day of the school's fixed-date lessons is 52 days or more back, so 45 days is stable.)
  PERFORM pg_temp.rg_expect('347 T1 open, forty-five days', pg_temp.rg_open(pg_temp.rg_auth(6), 45), '1, 3!, 4!, 10!, 40!');
  IF pg_temp.rg_open(pg_temp.rg_auth(6), 1000) ~ '(^|, )95!' THEN RAISE EXCEPTION 'rapporteringsgrad 347: the list went back further than 90 days'; END IF;
  IF pg_temp.rg_open(pg_temp.rg_auth(6), 1000) !~ '(^|, )40!' THEN RAISE EXCEPTION 'rapporteringsgrad 347: the list did not go back 90 days'; END IF;
  PERFORM pg_temp.rg_expect('347 T3 open', pg_temp.rg_open(pg_temp.rg_auth(8)), '');
  PERFORM pg_temp.rg_expect('347 an administrator''s open list', pg_temp.rg_open(pg_temp.rg_auth(1)), '');
  PERFORM pg_temp.rg_expect('347 the läsare''s open list', pg_temp.rg_open(pg_temp.rg_auth(5)), '');
  PERFORM pg_temp.rg_expect('347 a pupil''s open list', pg_temp.rg_open(pg_temp.rg_auth(11)), '');
  PERFORM pg_temp.rg_expect('347 a guardian''s open list', pg_temp.rg_open(pg_temp.rg_auth(21)), '');
  PERFORM pg_temp.rg_expect('347 a departed teacher''s open list', pg_temp.rg_open(pg_temp.rg_auth(9)), '');
  PERFORM pg_temp.rg_expect('347 the other school''s teacher', pg_temp.rg_open(pg_temp.rg_auth(32)), '');
  PERFORM set_config('request.jwt.claims', '', true);
  IF EXISTS (SELECT 1 FROM app.reporting_open_lessons(30)) THEN RAISE EXCEPTION 'rapporteringsgrad 347: no principal was handed an open list'; END IF;
  -- The names the list carries: the subject and the class, nothing of the lesson's pupils or marks.
  PERFORM pg_temp.rg_as(pg_temp.rg_auth(6));
  IF (SELECT count(*) FROM app.reporting_open_lessons(30) o WHERE o.subject_name = 'Rapportering' AND o.group_name = 'RG7A') <> 4 THEN
    RAISE EXCEPTION 'rapporteringsgrad 347: the list does not name the subject and the class';
  END IF;
  -- The limit is the school's: two days makes the lesson of three days ago past it still, and a lesson of the day before not.
  PERFORM pg_temp.rg_as(pg_temp.rg_auth(1));
  UPDATE "ReportingSettings" SET "openAfterDays" = 1;
  PERFORM pg_temp.rg_expect('347 T1 open, a day', pg_temp.rg_open(pg_temp.rg_auth(6)), '1!, 3!, 4!, 10!');
  PERFORM pg_temp.rg_as(pg_temp.rg_auth(1));
  UPDATE "ReportingSettings" SET "openAfterDays" = 30;
  PERFORM pg_temp.rg_expect('347 T1 open, thirty days', pg_temp.rg_open(pg_temp.rg_auth(6)), '1, 3, 4, 10');
END $$;

-- Nobody writes a day, the week's ledger or the reminders' ledger, not even the full administrator. The
-- switch and the limit are Drift's: every profile that writes Drift writes them and the läsare does not;
-- the row is never deleted; no teacher, guardian or pupil writes it.
DO $$
DECLARE
  who record;
  school uuid;
  mine uuid := current_setting('app.test_rg_school')::uuid;
  other uuid := current_setting('app.test_rg_other')::uuid;
  suffix integer;
BEGIN
  FOR who IN SELECT * FROM (VALUES ('full', 1, true), ('rektor', 2, true), ('expedition', 3, true),
                                   ('schemaläggare', 4, true), ('läsare', 5, false)) v(name, n, writes) LOOP
    PERFORM pg_temp.rg_as(pg_temp.rg_auth(who.n));
    school := app.current_school_id();
    PERFORM pg_temp.rg_denied(format('INSERT INTO "TeacherReportingDays" ("schoolId", "teacherId", day, held, reported) VALUES (%L, %L, current_date, 1, 1)', school, app.current_user_id()));
    PERFORM pg_temp.rg_denied('UPDATE "TeacherReportingDays" SET reported = 0');
    PERFORM pg_temp.rg_denied('DELETE FROM "TeacherReportingDays"');
    PERFORM pg_temp.rg_denied(format('INSERT INTO "ReportingDigests" ("schoolId", "periodStart", "periodEnd", recipients, teachers, held, reported) VALUES (%L, current_date, current_date, 0, 0, 0, 0)', school));
    PERFORM pg_temp.rg_denied('UPDATE "ReportingDigests" SET recipients = 9');
    PERFORM pg_temp.rg_denied('DELETE FROM "ReportingDigests"');
    PERFORM pg_temp.rg_denied('DELETE FROM "ReportingSettings"');
    BEGIN
      UPDATE "ReportingSettings" SET "openAfterDays" = 4 WHERE "schoolId" = school;
      IF NOT who.writes THEN RAISE EXCEPTION 'rapporteringsgrad 347: the % changed the limit', who.name; END IF;
      UPDATE "ReportingSettings" SET "openAfterDays" = 30 WHERE "schoolId" = school;
    EXCEPTION WHEN insufficient_privilege THEN
      IF who.writes THEN RAISE EXCEPTION 'rapporteringsgrad 347: the % was refused the limit', who.name; END IF;
    END;
    BEGIN
      UPDATE "ReportingSettings" SET "teacherReminders" = true, "rektorDigest" = true WHERE "schoolId" = school;
      IF NOT who.writes THEN RAISE EXCEPTION 'rapporteringsgrad 347: the % turned a switch on', who.name; END IF;
      UPDATE "ReportingSettings" SET "teacherReminders" = false WHERE "schoolId" = school;
    EXCEPTION WHEN insufficient_privilege THEN
      IF who.writes THEN RAISE EXCEPTION 'rapporteringsgrad 347: the % was refused a switch', who.name; END IF;
    END;
    -- And another school's row is not theirs to write.
    PERFORM pg_temp.rg_denied(format('UPDATE "ReportingSettings" SET "openAfterDays" = 9 WHERE "schoolId" = %L', other));
    PERFORM pg_temp.rg_denied(format('INSERT INTO "ReportingSettings" ("schoolId") VALUES (%L)', other));
  END LOOP;
  -- The other school's administrator: its own row, and this school's is not theirs.
  PERFORM pg_temp.rg_as(pg_temp.rg_auth(31));
  UPDATE "ReportingSettings" SET "openAfterDays" = 5;
  PERFORM pg_temp.rg_denied(format('UPDATE "ReportingSettings" SET "openAfterDays" = 9 WHERE "schoolId" = %L', mine));
  PERFORM pg_temp.rg_denied(format('DELETE FROM "ReportingSettings" WHERE "schoolId" = %L', mine));
  -- Teachers, a guardian and a pupil write none of the four.
  FOREACH suffix IN ARRAY ARRAY[6, 8, 21, 11] LOOP
    PERFORM pg_temp.rg_as(pg_temp.rg_auth(suffix));
    PERFORM pg_temp.rg_denied(format('INSERT INTO "ReportingSettings" ("schoolId") VALUES (%L)', other));
    PERFORM pg_temp.rg_denied(format('UPDATE "ReportingSettings" SET "openAfterDays" = 9 WHERE "schoolId" = %L', mine));
    PERFORM pg_temp.rg_denied('DELETE FROM "ReportingSettings"');
    PERFORM pg_temp.rg_denied(format('INSERT INTO "TeacherReportingDays" ("schoolId", "teacherId", day, held, reported) VALUES (%L, app.current_user_id(), current_date, 1, 1)', mine));
    PERFORM pg_temp.rg_denied('UPDATE "TeacherReportingDays" SET reported = 0');
    PERFORM pg_temp.rg_denied('DELETE FROM "TeacherReportingDays"');
    PERFORM pg_temp.rg_denied(format('INSERT INTO "ReportingDigests" ("schoolId", "periodStart", "periodEnd", recipients, teachers, held, reported) VALUES (%L, current_date, current_date, 0, 0, 0, 0)', mine));
    PERFORM pg_temp.rg_denied('DELETE FROM "ReportingDigests"');
  END LOOP;
END $$;

-- PostgREST's roles reach none of the four tables and none of the functions: authenticated is tried, and
-- the catalogue is asked for anon, service_role and PUBLIC (the API's role cannot become anon, so a
-- catalogue answer is the proof). The API's role holds what the migration gives it and no more.
DO $$
DECLARE
  stmt text;
  tbl text;
  fn text;
  r text;
  bad text;
BEGIN
  PERFORM pg_temp.rg_as(pg_temp.rg_auth(1));
  SET LOCAL ROLE authenticated;
  FOREACH stmt IN ARRAY ARRAY[
    'SELECT count(*) FROM "ReportingSettings"', 'SELECT count(*) FROM "TeacherReportingDays"',
    'SELECT count(*) FROM "ReportingReminders"', 'SELECT count(*) FROM "ReportingDigests"',
    'DELETE FROM "TeacherReportingDays"', 'DELETE FROM "ReportingSettings"',
    'SELECT * FROM app.reporting_lessons(gen_random_uuid(), current_date - 1, current_date, now())',
    'SELECT * FROM app.reporting_schools()',
    'SELECT * FROM app.reporting_compute(gen_random_uuid(), current_date - 1)',
    'SELECT * FROM app.reporting_open_lessons(30)',
    'SELECT * FROM app.reporting_remind(gen_random_uuid(), current_date)',
    'SELECT * FROM app.reporting_digest_due(gen_random_uuid(), current_date)',
    'SELECT * FROM app.reporting_digest(gen_random_uuid(), current_date, current_date)'
  ] LOOP
    BEGIN
      EXECUTE stmt;
      RAISE EXCEPTION 'rapporteringsgrad 347: authenticated was allowed to run %', stmt;
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
  END LOOP;
  SET LOCAL ROLE app_authenticated;
  -- The definition is read by the owner's functions alone: the API's role cannot ask it for anyone's rows.
  PERFORM pg_temp.rg_denied('SELECT * FROM app.reporting_lessons(app.current_school_id(), current_date - 1, current_date, now())');

  FOREACH tbl IN ARRAY ARRAY['ReportingSettings', 'TeacherReportingDays', 'ReportingReminders', 'ReportingDigests'] LOOP
    FOREACH r IN ARRAY ARRAY['anon', 'authenticated'] LOOP
      IF has_table_privilege(r, format('public.%I', tbl), 'SELECT, INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER') THEN
        RAISE EXCEPTION 'rapporteringsgrad 347: % holds a privilege on %', r, tbl;
      END IF;
    END LOOP;
    IF has_table_privilege('service_role', format('public.%I', tbl), 'INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER') THEN
      RAISE EXCEPTION 'rapporteringsgrad 347: service_role writes %', tbl;
    END IF;
    IF has_table_privilege('app_authenticated', format('public.%I', tbl), 'TRUNCATE, REFERENCES, TRIGGER') THEN
      RAISE EXCEPTION 'rapporteringsgrad 347: the API role truncates, references or triggers %', tbl;
    END IF;
  END LOOP;
  -- What the API's role holds: the switch is read and written but not deleted, the days and the week's ledger
  -- are read, and the reminders' ledger is not touched at all.
  IF NOT has_table_privilege('app_authenticated', 'public."ReportingSettings"', 'SELECT')
     OR NOT has_table_privilege('app_authenticated', 'public."ReportingSettings"', 'INSERT')
     OR NOT has_table_privilege('app_authenticated', 'public."ReportingSettings"', 'UPDATE')
     OR has_table_privilege('app_authenticated', 'public."ReportingSettings"', 'DELETE')
     OR NOT has_table_privilege('app_authenticated', 'public."TeacherReportingDays"', 'SELECT')
     OR has_table_privilege('app_authenticated', 'public."TeacherReportingDays"', 'INSERT, UPDATE, DELETE')
     OR NOT has_table_privilege('app_authenticated', 'public."ReportingDigests"', 'SELECT')
     OR has_table_privilege('app_authenticated', 'public."ReportingDigests"', 'INSERT, UPDATE, DELETE')
     OR has_table_privilege('app_authenticated', 'public."ReportingReminders"', 'SELECT, INSERT, UPDATE, DELETE') THEN
    RAISE EXCEPTION 'rapporteringsgrad 347: the API role holds other privileges than the migration gives it';
  END IF;

  -- The functions: PUBLIC and PostgREST's roles hold none; the API's role holds the six it calls and not the
  -- definition or the trigger's body.
  FOR fn, bad IN
    SELECT p.oid::regprocedure::text,
           concat_ws(',',
             CASE WHEN has_function_privilege('anon', p.oid, 'EXECUTE') THEN 'anon' END,
             CASE WHEN has_function_privilege('authenticated', p.oid, 'EXECUTE') THEN 'authenticated' END,
             CASE WHEN has_function_privilege('service_role', p.oid, 'EXECUTE') THEN 'service_role' END,
             CASE WHEN EXISTS (SELECT 1 FROM aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a WHERE a.grantee = 0) THEN 'PUBLIC' END)
      FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = 'app' AND p.proname LIKE 'reporting\_%'
  LOOP
    IF bad <> '' THEN RAISE EXCEPTION 'rapporteringsgrad 347: % may be run by %', fn, bad; END IF;
  END LOOP;
  FOREACH fn IN ARRAY ARRAY['app.reporting_schools()', 'app.reporting_compute(uuid, date)', 'app.reporting_open_lessons(integer)',
                            'app.reporting_remind(uuid, date)', 'app.reporting_digest_due(uuid, date)', 'app.reporting_digest(uuid, date, date)'] LOOP
    IF NOT has_function_privilege('app_authenticated', fn::regprocedure, 'EXECUTE') THEN
      RAISE EXCEPTION 'rapporteringsgrad 347: the API role cannot run %', fn;
    END IF;
  END LOOP;
  FOREACH fn IN ARRAY ARRAY['app.reporting_lessons(uuid, date, date, timestamptz)', 'app.reporting_settings_stamp()'] LOOP
    IF has_function_privilege('app_authenticated', fn::regprocedure, 'EXECUTE') THEN
      RAISE EXCEPTION 'rapporteringsgrad 347: the API role can run %, which is the owner''s', fn;
    END IF;
  END LOOP;

  -- Every policy on the four tables is the API role's alone, and these are the arms.
  SELECT string_agg(tablename || '.' || policyname, ', ') INTO bad
    FROM pg_policies WHERE schemaname = 'public' AND tablename IN ('ReportingSettings', 'TeacherReportingDays', 'ReportingReminders', 'ReportingDigests')
     AND roles <> ARRAY['app_authenticated']::name[];
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'rapporteringsgrad 347: policies not for app_authenticated alone: %', bad; END IF;
  SELECT string_agg(tablename || '.' || policyname, ', ' ORDER BY tablename, policyname) INTO bad
    FROM pg_policies WHERE schemaname = 'public' AND tablename IN ('ReportingSettings', 'TeacherReportingDays', 'ReportingReminders', 'ReportingDigests');
  IF bad <> 'ReportingDigests.reporting_digests_admin_select, ReportingSettings.reporting_settings_admin_insert, ReportingSettings.reporting_settings_admin_select, '
         || 'ReportingSettings.reporting_settings_admin_update, ReportingSettings.reporting_settings_teacher_select, '
         || 'TeacherReportingDays.reporting_days_admin_select, TeacherReportingDays.reporting_days_teacher_select' THEN
    RAISE EXCEPTION 'rapporteringsgrad 347: the arms are %, and the reminders'' ledger has none', bad;
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 348: the weekly notice, and the switches the reminders hang on.
--
-- The reminders themselves are asked on the owner's side (348o): they hang on
-- the date the switch went on, which a trigger stamps with today.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT pg_temp.rg_as(pg_temp.rg_auth(1));
DO $$
DECLARE
  school uuid := app.current_school_id();
  t1 uuid := pg_temp.rg_id('rg-t1@example.invalid');
  t2 uuid := pg_temp.rg_id('rg-t2@example.invalid');
  t3 uuid := pg_temp.rg_id('rg-t3@example.invalid');
  today date := (now() AT TIME ZONE 'Europe/Stockholm')::date;
  next_monday date := (now() AT TIME ZONE 'Europe/Stockholm')::date + (8 - extract(isodow FROM (now() AT TIME ZONE 'Europe/Stockholm')::date)::integer);
  who text;
  metas jsonb;
  led record;
BEGIN
  PERFORM pg_temp.rg_lesson('2026-09-15', 8, ARRAY[t1], ARRAY['PRESENT']);
  PERFORM pg_temp.rg_lesson('2026-09-15', 9, ARRAY[t1]);
  PERFORM pg_temp.rg_lesson('2026-09-15', 14, ARRAY[t2], ARRAY['PRESENT'], 'SCHEDULED', ARRAY['SUBSTITUTE']);
  PERFORM pg_temp.rg_lesson('2026-09-16', 10, ARRAY[t3]);
  PERFORM pg_temp.rg_compute('2026-09-30');

  -- No row at all: both off. Nothing is told and nothing written.
  IF EXISTS (SELECT 1 FROM app.reporting_digest(school, '2026-09-14', '2026-09-20')) OR EXISTS (SELECT 1 FROM "ReportingDigests") THEN
    RAISE EXCEPTION 'rapporteringsgrad 348: a school with no switch was told, or a ledger row written';
  END IF;
  IF EXISTS (SELECT 1 FROM app.reporting_remind(school, '2026-09-23')) THEN RAISE EXCEPTION 'rapporteringsgrad 348: a school with no switch was reminded'; END IF;
  IF EXISTS (SELECT 1 FROM app.reporting_digest_due(school, next_monday + 7)) THEN RAISE EXCEPTION 'rapporteringsgrad 348: a notice was due for a school with no switch'; END IF;

  -- A row with both off is no different.
  INSERT INTO "ReportingSettings" ("schoolId") VALUES (school);
  IF EXISTS (SELECT 1 FROM app.reporting_digest(school, '2026-09-14', '2026-09-20')) OR EXISTS (SELECT 1 FROM "ReportingDigests")
     OR EXISTS (SELECT 1 FROM app.reporting_remind(school, '2026-09-23')) OR EXISTS (SELECT 1 FROM app.reporting_digest_due(school, next_monday + 7)) THEN
    RAISE EXCEPTION 'rapporteringsgrad 348: a school with both off was told';
  END IF;

  -- On, today: the reminders skip every lesson dated before today, and the weekend.
  UPDATE "ReportingSettings" SET "teacherReminders" = true, "rektorDigest" = true;
  IF EXISTS (SELECT 1 FROM app.reporting_remind(school, '2026-09-23')) THEN RAISE EXCEPTION 'rapporteringsgrad 348: a lesson from before the switch was reminded of'; END IF;
  IF EXISTS (SELECT 1 FROM app.reporting_remind(school, '2026-09-26')) OR EXISTS (SELECT 1 FROM app.reporting_remind(school, '2026-09-27')) THEN
    RAISE EXCEPTION 'rapporteringsgrad 348: the weekend was reminded';
  END IF;

  -- Which week is due: the one that ended on or after the day the switch went on, and written once.
  IF (SELECT period_start || ' ' || period_end FROM app.reporting_digest_due(school, next_monday)) IS DISTINCT FROM ((next_monday - 7) || ' ' || (next_monday - 1)) THEN
    RAISE EXCEPTION 'rapporteringsgrad 348: the week due on % is %', next_monday, (SELECT period_start || ' ' || period_end FROM app.reporting_digest_due(school, next_monday));
  END IF;
  IF EXISTS (SELECT 1 FROM app.reporting_digest_due(school, next_monday - 1 - 7)) THEN
    RAISE EXCEPTION 'rapporteringsgrad 348: a week that ended before the switch was due';
  END IF;

  -- The notice: to rektor and full alone, with the school's totals and nothing that names anyone.
  SELECT string_agg(split_part(d.email, '@', 1), ', ' ORDER BY d.email), jsonb_agg(DISTINCT d.meta)
    INTO who, metas FROM app.reporting_digest(school, '2026-09-14', '2026-09-20') d;
  PERFORM pg_temp.rg_expect('348 recipients', who, 'rg-full, rg-rektor');
  IF metas <> '[{"held": 4, "reported": 2, "teachers": 3, "periodEnd": "2026-09-20", "periodStart": "2026-09-14"}]'::jsonb THEN
    RAISE EXCEPTION 'rapporteringsgrad 348: the notice says %', metas;
  END IF;
  IF metas::text ~* '(lärare|rg-|@|rapportering)' THEN RAISE EXCEPTION 'rapporteringsgrad 348: the notice names someone or something: %', metas; END IF;
  SELECT * INTO led FROM "ReportingDigests";
  IF led."periodStart" <> '2026-09-14' OR led."periodEnd" <> '2026-09-20' OR led.recipients <> 2 OR led.teachers <> 3 OR led.held <> 4 OR led.reported <> 2 THEN
    RAISE EXCEPTION 'rapporteringsgrad 348: the ledger says %', led;
  END IF;
  -- Written once: the same week again says nothing, and writes nothing.
  IF EXISTS (SELECT 1 FROM app.reporting_digest(school, '2026-09-14', '2026-09-20')) OR (SELECT count(*) FROM "ReportingDigests") <> 1 THEN
    RAISE EXCEPTION 'rapporteringsgrad 348: the same week was told twice';
  END IF;

  -- A week with no held lesson is entered and told to nobody; entered, it is not asked again.
  IF EXISTS (SELECT 1 FROM app.reporting_digest(school, '2026-09-21', '2026-09-27')) THEN RAISE EXCEPTION 'rapporteringsgrad 348: an empty week was told'; END IF;
  SELECT * INTO led FROM "ReportingDigests" WHERE "periodEnd" = '2026-09-27';
  IF led.recipients <> 0 OR led.held <> 0 OR led.reported <> 0 OR led.teachers <> 0 THEN RAISE EXCEPTION 'rapporteringsgrad 348: the empty week''s ledger row says %', led; END IF;

  -- A rektor who has left is not told; the full administrator still is.
  UPDATE "Users" SET "isActive" = false WHERE email = 'rg-rektor@example.invalid';
  PERFORM pg_temp.rg_lesson('2026-10-01', 8, ARRAY[t1], ARRAY['PRESENT']);
  PERFORM pg_temp.rg_compute('2026-10-04');
  SELECT string_agg(split_part(d.email, '@', 1), ', ' ORDER BY d.email) INTO who FROM app.reporting_digest(school, '2026-09-28', '2026-10-04') d;
  PERFORM pg_temp.rg_expect('348 recipients, one has left', who, 'rg-full');

  -- Off again: nothing is told, and no ledger row is written for the week.
  UPDATE "ReportingSettings" SET "rektorDigest" = false;
  PERFORM pg_temp.rg_lesson('2026-10-06', 8, ARRAY[t1], ARRAY['PRESENT']);
  PERFORM pg_temp.rg_compute('2026-10-11');
  IF EXISTS (SELECT 1 FROM app.reporting_digest(school, '2026-10-05', '2026-10-11')) OR EXISTS (SELECT 1 FROM "ReportingDigests" WHERE "periodEnd" = '2026-10-11') THEN
    RAISE EXCEPTION 'rapporteringsgrad 348: a switch that is off was told';
  END IF;
  IF EXISTS (SELECT 1 FROM app.reporting_digest_due(school, next_monday + 7)) THEN RAISE EXCEPTION 'rapporteringsgrad 348: a notice was due with the switch off'; END IF;
  -- The reminders' switch is its own: the notice off, the reminders still on.
  UPDATE "ReportingSettings" SET "teacherReminders" = false;
  IF EXISTS (SELECT 1 FROM app.reporting_remind(school, '2026-09-23')) THEN RAISE EXCEPTION 'rapporteringsgrad 348: a switch that is off reminded'; END IF;
END $$;
ROLLBACK;


-- ---------------------------------------------------------------------------
-- Section 350: krisläget står i katalogen som migreringen skrev det
-- (CrisisSettings, CrisisAlarms, CrisisCalls, CrisisCallTeachers, CrisisPupils,
-- CrisisReports, 20270113091000), och vem som får starta ett larm.
--
-- Sex tabeller, 24 armar, ingen DELETE för någon roll, UPDATE bara på
-- inställningarna och larmet, ingenting för PostgREST:s roller, och åtta
-- funktioner som bara API:ts roll får anropa. Migrationens egen vakt
-- (CRISIS_REACH) körs när migreringen läggs på; här står samma sak mot den
-- databas sviten kör mot, och med rättigheterna, triggrarna, det partiella
-- unika indexet och gallringsfunktionerna som måste bära varje grens gren.
-- Sedan frågan "får jag starta?" för varje profil i matrisskolan, med de
-- förval skolan har och med dem rektor kan välja.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', :'admin_auth_id')::text, true);
DO $$
DECLARE
  t text;
  r text;
  f text;
  n integer;
  tables text[] := ARRAY['CrisisSettings', 'CrisisAlarms', 'CrisisCalls', 'CrisisCallTeachers', 'CrisisPupils', 'CrisisReports'];
  functions text[] := ARRAY['app.crisis_may_start()', 'app.crisis_window_open(uuid)', 'app.crisis_call_window_open(uuid)',
                            'app.crisis_lists_are_open(uuid)', 'app.crisis_answers_for(uuid)', 'app.crisis_pupil_call(uuid, uuid)',
                            'app.crisis_has_no_call_in(uuid)', 'app.crisis_settle()'];
  src text;
BEGIN
  FOREACH t IN ARRAY tables LOOP
    IF NOT (SELECT relrowsecurity FROM pg_class WHERE oid = format('public.%I', t)::regclass) THEN
      RAISE EXCEPTION 'krisläge: % has no row-level security', t;
    END IF;
    IF NOT (has_table_privilege('app_authenticated', format('public.%I', t), 'SELECT')
            AND has_table_privilege('app_authenticated', format('public.%I', t), 'INSERT')) THEN
      RAISE EXCEPTION 'krisläge: the API role lacks a grant on %', t;
    END IF;
    -- The lists follow the marks by trigger and a mark is appended: only the
    -- settings and the alarm are changed by an arm.
    IF has_table_privilege('app_authenticated', format('public.%I', t), 'UPDATE') IS DISTINCT FROM (t IN ('CrisisSettings', 'CrisisAlarms')) THEN
      RAISE EXCEPTION 'krisläge: the API role''s UPDATE on % is not what the arms say', t;
    END IF;
    IF has_table_privilege('app_authenticated', format('public.%I', t), 'DELETE, TRUNCATE, REFERENCES, TRIGGER') THEN
      RAISE EXCEPTION 'krisläge: the API role may delete from, truncate, reference or trigger %', t;
    END IF;
    FOREACH r IN ARRAY ARRAY['authenticated', 'anon'] LOOP
      IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r)
         AND has_table_privilege(r, format('public.%I', t), 'SELECT, INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER') THEN
        RAISE EXCEPTION 'krisläge: % holds a privilege on %', r, t;
      END IF;
    END LOOP;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role')
       AND has_table_privilege('service_role', format('public.%I', t), 'INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER') THEN
      RAISE EXCEPTION 'krisläge: service_role writes %', t;
    END IF;
  END LOOP;

  SELECT count(*) INTO n FROM pg_policies WHERE schemaname = 'public' AND tablename = ANY (tables);
  IF n <> 24 THEN RAISE EXCEPTION 'krisläge: the six tables have % arms, not 24', n; END IF;
  SELECT count(*) INTO n FROM pg_policies
   WHERE schemaname = 'public' AND tablename = ANY (tables) AND (roles <> '{app_authenticated}'::name[] OR cmd = 'DELETE' OR cmd = 'ALL');
  IF n <> 0 THEN RAISE EXCEPTION 'krisläge: % arm(s) reach beyond the API role or delete', n; END IF;

  FOREACH f IN ARRAY functions LOOP
    IF NOT has_function_privilege('app_authenticated', f, 'EXECUTE') THEN
      RAISE EXCEPTION 'krisläge: the API role may not execute %', f;
    END IF;
    FOREACH r IN ARRAY ARRAY['anon', 'authenticated', 'service_role'] LOOP
      IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) AND has_function_privilege(r, f, 'EXECUTE') THEN
        RAISE EXCEPTION 'krisläge: % may execute %', r, f;
      END IF;
    END LOOP;
    IF EXISTS (SELECT 1 FROM pg_proc p, aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
                WHERE p.oid = f::regprocedure AND a.grantee = 0) THEN
      RAISE EXCEPTION 'krisläge: PUBLIC may execute %', f;
    END IF;
    IF NOT (SELECT p.prosecdef AND p.proconfig::text LIKE '%search_path=%' FROM pg_proc p WHERE p.oid = f::regprocedure) THEN
      RAISE EXCEPTION 'krisläge: % is not a SECURITY DEFINER with a fixed search_path', f;
    END IF;
  END LOOP;

  -- One open alarm of each mode: a partial unique index on the school and mode.
  IF NOT EXISTS (SELECT 1 FROM pg_indexes WHERE tablename = 'CrisisAlarms' AND indexname = 'CrisisAlarms_one_open_per_mode'
                  AND indexdef LIKE '%UNIQUE%' AND indexdef LIKE '%mode%' AND indexdef LIKE '%WHERE ("endedAt" IS NULL)%') THEN
    RAISE EXCEPTION 'krisläge: the partial unique index of open alarms is gone';
  END IF;
  -- The triggers that start an alarm in its writer's name, end it once, stamp a mark and apply it.
  FOREACH f IN ARRAY ARRAY['CrisisAlarms_a_born_open', 'CrisisAlarms_b_ends_once', 'CrisisReports_a_stamped', 'CrisisReports_b_applies'] LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = f AND NOT tgisinternal AND tgenabled = 'O') THEN
      RAISE EXCEPTION 'krisläge: the trigger % is missing or disabled', f;
    END IF;
  END LOOP;
  -- The enum values the notices and gallring use.
  FOREACH f IN ARRAY ARRAY['CRISIS_ALARM', 'CRISIS_ENDED', 'CRISIS_GUARDIAN_AFTER'] LOOP
    IF NOT EXISTS (SELECT 1 FROM unnest(enum_range(NULL::"NotificationType")) k WHERE k::text = f) THEN
      RAISE EXCEPTION 'krisläge: % is not a notification type', f;
    END IF;
  END LOOP;
  FOREACH f IN ARRAY ARRAY['CRISIS_DRILLS', 'CRISIS_ALARMS'] LOOP
    IF NOT EXISTS (SELECT 1 FROM unnest(enum_range(NULL::"RetentionDataType")) k WHERE k::text = f) THEN
      RAISE EXCEPTION 'krisläge: % is not a retention kind', f;
    END IF;
  END LOOP;
  -- app.gallring_due and app.gallring_purge are replaced whole by every release
  -- that adds a kind (20261026091000, 20261231090100, 20270102091000,
  -- 20270107090000, 20270112090100, 20270113091000), so the one that comes last must carry
  -- every branch before it. The branches' behaviour is the sections' (319,
  -- 343, 354); this is that none is missing from the bodies in force.
  SELECT p.prosrc INTO src FROM pg_proc p WHERE p.oid = 'app.gallring_due(uuid, "RetentionDataType", date, date)'::regprocedure;
  IF src NOT LIKE '%"AbsenceWatchFindings"%' THEN
    RAISE EXCEPTION 'gallring: app.gallring_due has lost the branch for the absence watch''s findings (Frånvarobevakning, 20261231090100)';
  END IF;
  IF src NOT LIKE '%"CoverRequests"%' OR src NOT LIKE '%"CoverConfirmations"%' THEN
    RAISE EXCEPTION 'gallring: app.gallring_due has lost the branch for the cover requests (Vikariefrågan, 20270102091000)';
  END IF;
  IF src NOT LIKE '%"PersonProtectionEvents"%' THEN
    RAISE EXCEPTION 'gallring: app.gallring_due has lost the branch for the marks'' history (Skyddad identitet, 20270107090000)';
  END IF;
  IF src NOT LIKE '%"TeacherReportingDays"%' OR src NOT LIKE '%"ReportingReminders"%' THEN
    RAISE EXCEPTION 'gallring: app.gallring_due has lost the branch for the reporting rate (Rapporteringsgrad, 20270112090100)';
  END IF;
  IF src NOT LIKE '%"CrisisAlarms"%' OR src NOT LIKE '%CRISIS_DRILLS%' OR src NOT LIKE '%CRISIS_ALARMS%' THEN
    RAISE EXCEPTION 'gallring: app.gallring_due has lost the branch for the alarms (Krisläge, 20270113091000)';
  END IF;
  SELECT p.prosrc INTO src FROM pg_proc p WHERE p.oid = 'app.gallring_purge(uuid, "RetentionDataType", integer)'::regprocedure;
  IF src NOT LIKE '%DELETE FROM "AbsenceWatchFindings"%' THEN
    RAISE EXCEPTION 'gallring: app.gallring_purge has lost the branch for the absence watch''s findings (Frånvarobevakning, 20261231090100)';
  END IF;
  IF src NOT LIKE '%WHEN ''COVER_REQUESTS'' THEN%' OR src NOT LIKE '%DELETE FROM "CoverRequests"%' THEN
    RAISE EXCEPTION 'gallring: app.gallring_purge has lost the branch for the cover requests (Vikariefrågan, 20270102091000)';
  END IF;
  IF src NOT LIKE '%DELETE FROM "PersonProtectionEvents"%' THEN
    RAISE EXCEPTION 'gallring: app.gallring_purge has lost the branch for the marks'' history (Skyddad identitet, 20270107090000)';
  END IF;
  IF src NOT LIKE '%DELETE FROM "TeacherReportingDays"%' OR src NOT LIKE '%DELETE FROM "ReportingReminders"%' THEN
    RAISE EXCEPTION 'gallring: app.gallring_purge has lost the branch for the reporting rate (Rapporteringsgrad, 20270112090100)';
  END IF;
  IF src NOT LIKE '%WHEN ''CRISIS_DRILLS'', ''CRISIS_ALARMS'' THEN%' OR src NOT LIKE '%DELETE FROM "CrisisAlarms"%' THEN
    RAISE EXCEPTION 'gallring: app.gallring_purge has lost the branch for the alarms (Krisläge, 20270113091000)';
  END IF;

  -- The same for what no section here names, read from the bodies as they stand (comments left out: a
  -- branch that is only in a comment, of either kind, is not one). Every kind of data a school sets a period for (but the
  -- people, who are pseudonymised) has a line in gallring_due and a branch in gallring_purge; every table
  -- the earlier releases purged is still deleted from in the purge and counted in the due; every table the
  -- purge deletes from is one the due counts; and no branch is dead by a predicate that cannot be true.
  -- A release that restates the two functions from an older body drops the branch of the release before
  -- it; this fails on that, for every kind and table there is after all migrations, whoever added it.
  DECLARE
    k text;
    tbl text;
    lost text[] := '{}';
    due text := regexp_replace(regexp_replace((SELECT p.prosrc FROM pg_proc p WHERE p.oid = 'app.gallring_due(uuid, "RetentionDataType", date, date)'::regprocedure),
                                              '/\*.*?\*/', '', 'g'), '--[^\n]*', '', 'g');
    purge text := regexp_replace(regexp_replace((SELECT p.prosrc FROM pg_proc p WHERE p.oid = 'app.gallring_purge(uuid, "RetentionDataType", integer)'::regprocedure),
                                                '/\*.*?\*/', '', 'g'), '--[^\n]*', '', 'g');
    -- What the bodies purged before Krisläge (D1, Frånvarobevakningen, Vikariefrågan, Skyddad identitet,
    -- Rapporteringsgrad) and what Krisläge purges. A release adds its tables here, and the check below fails
    -- until its bodies carry them.
    tables text[] := ARRAY['AttendanceRecords', 'AbsenceWatchFindings', 'TeacherReportingDays', 'ReportingReminders', 'AbsenceReports',
                           'LeaveRequests', 'Notifications', 'ScheduleChangeLogs', 'TeacherEmploymentLogs', 'GuardianStudentHistory',
                           'PersonProtectionEvents', 'PersonalDataAccess', 'CoverRequests', 'CoverConfirmations', 'CrisisAlarms'];
  BEGIN
    -- Tables a release after this one adds a branch for are found in the catalogue: any table that is purged
    -- under a RetentionDataType by the bodies of the previous release but not by these would be a lost branch,
    -- and the pair check below (purge deletes only what due counts) is what a new table meets first.
    FOR k IN SELECT e::text FROM unnest(enum_range(NULL::"RetentionDataType")) e WHERE e::text <> 'DEPARTED_PEOPLE' LOOP
      IF due NOT LIKE format('%%p_type = ''%s''%%', k) THEN lost := lost || format('gallring_due has no line for %s', k); END IF;
      IF purge !~ format('WHEN[^\n]*''%s''', k) THEN lost := lost || format('gallring_purge has no branch for %s', k); END IF;
    END LOOP;
    FOREACH tbl IN ARRAY tables LOOP
      IF purge NOT LIKE format('%%DELETE FROM "%s"%%', tbl) THEN lost := lost || format('gallring_purge no longer deletes from %s', tbl); END IF;
      IF due NOT LIKE format('%%"%s"%%', tbl) THEN lost := lost || format('gallring_due no longer counts %s', tbl); END IF;
    END LOOP;
    FOR tbl IN SELECT m[1] FROM regexp_matches(purge, 'DELETE FROM "([A-Za-z]+)"', 'g') m LOOP
      IF due NOT LIKE format('%%"%s"%%', tbl) THEN lost := lost || format('gallring_purge deletes from %s, which gallring_due does not count', tbl); END IF;
    END LOOP;
    IF due ~* '\m(and|where)\s+(false|null)\M|\m1\s*=\s*0\M' OR purge ~* '\m(and|where)\s+(false|null)\M|\m1\s*=\s*0\M' THEN
      lost := array_append(lost, 'a branch of gallring_due or gallring_purge is dead (AND false, WHERE false, 1 = 0)');
    END IF;
    IF cardinality(lost) > 0 THEN
      RAISE EXCEPTION 'gallring: a kind of data is no longer purged: %', array_to_string(lost, '; ');
    END IF;
  END;
END $$;
ROLLBACK;

-- 350b: vem som får starta ett larm. Matrisskolan har inga inställningar utöver
-- förvalet: varje profil som skriver Drift. Rektor och full får alltid; en
-- profil skolan tagit bort får inte; läsaren, läraren, eleven och
-- vårdnadshavaren får aldrig. Inställningarna skriver bara den som beslutar.
BEGIN;
CREATE FUNCTION pg_temp.refuses(stmt text, expected text, what text) RETURNS void LANGUAGE plpgsql AS $f$
DECLARE got text := 'none';
BEGIN
  BEGIN
    EXECUTE stmt;
  EXCEPTION WHEN OTHERS THEN
    got := SQLSTATE;
  END;
  IF got IS DISTINCT FROM expected THEN
    RAISE EXCEPTION 'krisläge: % should be refused with %, was %', what, expected, got USING ERRCODE = 'P0001';
  END IF;
END
$f$;
CREATE FUNCTION pg_temp.changes(stmt text) RETURNS bigint LANGUAGE plpgsql AS $f$
DECLARE n bigint;
BEGIN
  EXECUTE stmt;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END
$f$;
CREATE FUNCTION pg_temp.who_may_start() RETURNS text LANGUAGE plpgsql AS $f$
DECLARE
  rec record;
  seen text[] := '{}';
BEGIN
  FOR rec IN SELECT * FROM (VALUES
      ('00000000-0000-4000-8000-000000000105', 'FULL'),
      ('00000000-0000-4000-8000-000000000106', 'REKTOR'),
      ('00000000-0000-4000-8000-000000000107', 'SCHEMALAGGARE'),
      ('00000000-0000-4000-8000-000000000108', 'EXPEDITION'),
      ('00000000-0000-4000-8000-000000000115', 'LASARE'),
      ('00000000-0000-4000-8000-000000000111', 'TEACHER'),
      ('00000000-0000-4000-8000-000000000112', 'STUDENT'),
      ('00000000-0000-4000-8000-000000000113', 'GUARDIAN')) v(sub, who)
  LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', rec.sub)::text, true);
    IF app.crisis_may_start() THEN seen := seen || rec.who; END IF;
  END LOOP;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  RETURN array_to_string(seen, ',');
END
$f$;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
DO $$
DECLARE
  school uuid := app.current_school_id();
  seen text;
BEGIN
  IF (SELECT count(*) FROM "CrisisSettings" WHERE "schoolId" = school) <> 1 THEN
    RAISE EXCEPTION 'krisläge: the matrix school''s settings are not planted';
  END IF;
  seen := pg_temp.who_may_start();
  IF seen <> 'FULL,REKTOR,SCHEMALAGGARE,EXPEDITION' THEN
    RAISE EXCEPTION 'krisläge: by default the profiles that write Drift may start an alarm, got %', seen;
  END IF;

  -- Rektor narrows it to expeditionen: the deciders still may.
  IF pg_temp.changes(format($q$UPDATE "CrisisSettings" SET "startProfiles" = ARRAY['EXPEDITION']::"AdminProfile"[] WHERE "schoolId" = %L$q$, school)) <> 1 THEN
    RAISE EXCEPTION 'krisläge: the full administrator could not change who may start an alarm';
  END IF;
  seen := pg_temp.who_may_start();
  IF seen <> 'FULL,REKTOR,EXPEDITION' THEN
    RAISE EXCEPTION 'krisläge: with only expeditionen chosen the deciders and expeditionen may start, got %', seen;
  END IF;
  -- The arms say the same as the function: a schemaläggare is refused the start and the end of an
  -- alarm, expeditionen and the deciders are not. (An exercise is open in the school, so the row a
  -- start would add meets the one-open-alarm index: that is the arm having let it through.)
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000107')::text, true);
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisAlarms" ("schoolId", kind, mode) VALUES (%L, 'EVACUATION', 'DRILL')$q$, school),
                          '42501', 'a schemaläggare starting an exercise when the school has not let them');
  PERFORM pg_temp.refuses(format($q$UPDATE "CrisisAlarms" SET "endedAt" = now() WHERE "schoolId" = %L$q$, school),
                          '42501', 'a schemaläggare ending an alarm when the school has not let them');
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000108')::text, true);
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisAlarms" ("schoolId", kind, mode) VALUES (%L, 'EVACUATION', 'DRILL')$q$, school),
                          '23505', 'expeditionen starting an exercise they were let start');
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000106')::text, true);
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisAlarms" ("schoolId", kind, mode) VALUES (%L, 'EVACUATION', 'DRILL')$q$, school),
                          '23505', 'rektor starting an exercise, though not chosen');
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  -- Nobody chosen: only the deciders.
  PERFORM pg_temp.changes(format($q$UPDATE "CrisisSettings" SET "startProfiles" = '{}' WHERE "schoolId" = %L$q$, school));
  seen := pg_temp.who_may_start();
  IF seen <> 'FULL,REKTOR' THEN
    RAISE EXCEPTION 'krisläge: with nobody chosen only the deciders may start an alarm, got %', seen;
  END IF;
  -- The läsare writes no area and is no choice; a list may not be longer than the profiles that can start.
  PERFORM pg_temp.refuses(format($q$UPDATE "CrisisSettings" SET "startProfiles" = ARRAY['LASARE']::"AdminProfile"[] WHERE "schoolId" = %L$q$, school),
                          '23514', 'the läsare among those who may start');
  PERFORM pg_temp.refuses(format($q$UPDATE "CrisisSettings" SET "startProfiles" = ARRAY['FULL','REKTOR','SCHEMALAGGARE','EXPEDITION','FULL']::"AdminProfile"[] WHERE "schoolId" = %L$q$, school),
                          '23514', 'five profiles in a list of four');
  PERFORM pg_temp.refuses(format($q$DELETE FROM "CrisisSettings" WHERE "schoolId" = %L$q$, school), '42501', 'a delete of the settings');
  PERFORM set_config('app.test_rls350_school', school::text, true);
END $$;

-- Only the deciders write the settings; every administrator reads them; nobody else sees them.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000107')::text, true);
DO $$
BEGIN
  IF (SELECT count(*) FROM "CrisisSettings") <> 1 THEN RAISE EXCEPTION 'krisläge: a schemaläggare does not read the settings'; END IF;
  PERFORM pg_temp.refuses(format($q$UPDATE "CrisisSettings" SET "notifyGuardiansAfter" = true WHERE "schoolId" = %L$q$, current_setting('app.test_rls350_school')),
                          '42501', 'a schemaläggare changing the settings');
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisSettings" ("schoolId") VALUES (%L)$q$, current_setting('app.test_rls350_school')),
                          '42501', 'a schemaläggare writing settings');
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000115')::text, true);
DO $$
BEGIN
  IF (SELECT count(*) FROM "CrisisSettings") <> 1 THEN RAISE EXCEPTION 'krisläge: a läsare does not read the settings'; END IF;
  PERFORM pg_temp.refuses(format($q$UPDATE "CrisisSettings" SET "notifyGuardiansAfter" = true WHERE "schoolId" = %L$q$, current_setting('app.test_rls350_school')),
                          '42501', 'a läsare changing the settings');
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000106')::text, true);
DO $$
BEGIN
  IF pg_temp.changes(format($q$UPDATE "CrisisSettings" SET "notifyGuardiansAfter" = true WHERE "schoolId" = %L$q$, current_setting('app.test_rls350_school'))) <> 1 THEN
    RAISE EXCEPTION 'krisläge: rektor could not change the settings';
  END IF;
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000111')::text, true);
DO $$
BEGIN
  IF (SELECT count(*) FROM "CrisisSettings") <> 0 THEN RAISE EXCEPTION 'krisläge: a teacher reads the settings'; END IF;
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisSettings" ("schoolId") VALUES (%L)$q$, current_setting('app.test_rls350_school')),
                          '42501', 'a teacher writing settings');
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000112')::text, true);
DO $$
BEGIN
  IF (SELECT count(*) FROM "CrisisSettings") <> 0 THEN RAISE EXCEPTION 'krisläge: a pupil reads the settings'; END IF;
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000113')::text, true);
DO $$
BEGIN
  IF (SELECT count(*) FROM "CrisisSettings") <> 0 THEN RAISE EXCEPTION 'krisläge: a guardian reads the settings'; END IF;
END $$;
-- Another school's administrator reads and writes none of it.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000006')::text, true);
DO $$
BEGIN
  IF (SELECT count(*) FROM "CrisisSettings") <> 0 THEN RAISE EXCEPTION 'krisläge: another school''s administrator reads the settings'; END IF;
  IF pg_temp.changes(format($q$UPDATE "CrisisSettings" SET "notifyGuardiansAfter" = true WHERE "schoolId" = %L$q$, current_setting('app.test_rls350_school'))) <> 0 THEN
    RAISE EXCEPTION 'krisläge: another school''s administrator changed the settings';
  END IF;
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisSettings" ("schoolId") VALUES (%L)$q$, current_setting('app.test_rls350_school')),
                          '42501', 'another school''s administrator writing settings');
END $$;
-- Nobody with no login starts anything.
SELECT set_config('request.jwt.claims', '', true);
DO $$
BEGIN
  IF app.crisis_may_start() THEN RAISE EXCEPTION 'krisläge: a caller with no login may start an alarm'; END IF;
  PERFORM pg_temp.refuses($q$SELECT app.crisis_settle()$q$, 'none', 'the job''s pass with no login');
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
DO $$
BEGIN
  PERFORM pg_temp.refuses($q$SELECT app.crisis_settle()$q$, 'KL403', 'the job''s pass with a login');
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 351: ett larm börjar i sin skrivares namn, slutar en gång, och ses
-- av dem det angår (CrisisAlarms, 20270113091000).
--
-- Allt en skrivare inte ska välja väljs, och inget av det stannar: starttiden
-- är transaktionens, starter är den inloggade, och slutet, anteckningen, att
-- vårdnadshavarna sagts till och förseglingen börjar tomma. Ett skarpt larm
-- och en övning kan pågå samtidigt, aldrig två av samma slag. Art, läge och
-- start ändras inte; slutet läggs till en gång, förseglingen en gång;
-- anteckningen hör till slutet; vårdnadshavarna får veta bara efter ett skarpt
-- larm som tagit slut. En lärare ser ett larm som pågår och ett som tog slut
-- inom timmen, aldrig ett äldre; en elev, en vårdnadshavare och en annan
-- skolas administratör ser inget. Ingen roll tar bort ett larm.
-- ---------------------------------------------------------------------------

BEGIN;
CREATE FUNCTION pg_temp.refuses(stmt text, expected text, what text) RETURNS void LANGUAGE plpgsql AS $f$
DECLARE got text := 'none';
BEGIN
  BEGIN
    EXECUTE stmt;
  EXCEPTION WHEN OTHERS THEN
    got := SQLSTATE;
  END;
  IF got IS DISTINCT FROM expected THEN
    RAISE EXCEPTION 'krisläge: % should be refused with %, was %', what, expected, got USING ERRCODE = 'P0001';
  END IF;
END
$f$;
CREATE FUNCTION pg_temp.changes(stmt text) RETURNS bigint LANGUAGE plpgsql AS $f$
DECLARE n bigint;
BEGIN
  EXECUTE stmt;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END
$f$;
SELECT set_config('request.jwt.claims', json_build_object('sub', :'admin_auth_id')::text, true);
SELECT set_config('app.test_school_b', :'school_b', true), set_config('app.test_student_b', :'student_b', true);
DO $$
DECLARE
  school uuid := app.current_school_id();
  me uuid := app.current_user_id();
  t1 uuid; pupil uuid;
  al uuid; d uuid; al2 uuid; d2 uuid;
  r "CrisisAlarms";
BEGIN
  SELECT id INTO t1 FROM "Users" WHERE "schoolId" = school AND role = 'TEACHER' AND "isActive" ORDER BY "authId" LIMIT 1;

  -- The exercise comes first: a real alarm may begin beside one (the gateway cuts it short), but an
  -- exercise is not started beside a real alarm (351b).
  INSERT INTO "CrisisAlarms" ("schoolId", kind, mode) VALUES (school, 'LOCKDOWN', 'DRILL') RETURNING id INTO d;
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisAlarms" ("schoolId", kind, mode) VALUES (%L, 'EVACUATION', 'DRILL')$q$, school),
                          '23505', 'a second exercise');

  -- 351a: everything a writer should not choose is chosen; none of it is kept.
  INSERT INTO "CrisisAlarms" ("schoolId", kind, mode, "startedAt", "startedByUserId", "endedAt", "endedByUserId", "autoEnded", "endNote", "guardiansNotifiedAt", "listsSealedAt")
  VALUES (school, 'EVACUATION', 'LIVE', now() - interval '3 days', t1, now(), t1, true, 'x', now(), now()) RETURNING * INTO r;
  IF r."startedAt" <> now() OR r."startedByUserId" <> me THEN
    RAISE EXCEPTION 'krisläge: an alarm did not begin at the transaction''s time in its writer''s name (% by %)', r."startedAt", r."startedByUserId";
  END IF;
  IF r."endedAt" IS NOT NULL OR r."endedByUserId" IS NOT NULL OR r."autoEnded" OR r."endNote" IS NOT NULL
     OR r."guardiansNotifiedAt" IS NOT NULL OR r."listsSealedAt" IS NOT NULL THEN
    RAISE EXCEPTION 'krisläge: an alarm was born with an end, a note, a seal or the guardians told';
  END IF;
  al := r.id;

  -- 351b: one open alarm of each mode, and no exercise beside a real one (the real alarm cuts one short;
  -- KL412 is the database's answer to the other way round).
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisAlarms" ("schoolId", kind, mode) VALUES (%L, 'LOCKDOWN', 'LIVE')$q$, school),
                          '23505', 'a second real alarm');
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisAlarms" ("schoolId", kind, mode) VALUES (%L, 'EVACUATION', 'DRILL')$q$, school),
                          'KL412', 'an exercise beside a real alarm');

  -- 351c: what is fixed, and what an open alarm has no end to describe.
  PERFORM pg_temp.refuses(format($q$UPDATE "CrisisAlarms" SET kind = 'LOCKDOWN' WHERE id = %L$q$, al), 'KL422', 'a changed kind');
  PERFORM pg_temp.refuses(format($q$UPDATE "CrisisAlarms" SET mode = 'DRILL' WHERE id = %L$q$, al), 'KL422', 'a changed mode');
  PERFORM pg_temp.refuses(format($q$UPDATE "CrisisAlarms" SET "startedAt" = "startedAt" - interval '1 hour' WHERE id = %L$q$, al), 'KL422', 'a moved start');
  PERFORM pg_temp.refuses(format($q$UPDATE "CrisisAlarms" SET "endNote" = 'Hej' WHERE id = %L$q$, al), 'KL422', 'a note on an alarm that is going');
  PERFORM pg_temp.refuses(format($q$UPDATE "CrisisAlarms" SET "guardiansNotifiedAt" = now() WHERE id = %L$q$, al), 'KL422', 'guardians told of an alarm that is going');
  PERFORM pg_temp.refuses(format($q$UPDATE "CrisisAlarms" SET "autoEnded" = true WHERE id = %L$q$, al), 'KL422', 'an automatic end that is no end');
  PERFORM pg_temp.refuses(format($q$UPDATE "CrisisAlarms" SET "endedByUserId" = %L WHERE id = %L$q$, me, al), 'KL422', 'an ender with no end');
  PERFORM pg_temp.refuses(format($q$DELETE FROM "CrisisAlarms" WHERE id = %L$q$, al), '42501', 'a delete of an alarm');
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisAlarms" ("schoolId", kind, mode) VALUES (%L, 'EVACUATION', 'DRILL')$q$, current_setting('app.test_school_b')),
                          '42501', 'an alarm in another school');

  -- 351d: the lists are sealed once, by their writer, and stay.
  UPDATE "CrisisAlarms" SET "listsSealedAt" = now() - interval '1 day' WHERE id = al;
  SELECT * INTO r FROM "CrisisAlarms" WHERE id = al;
  IF r."listsSealedAt" IS NULL OR r."listsSealedAt" < r."startedAt" OR r."listsSealedAt" > clock_timestamp() THEN
    RAISE EXCEPTION 'krisläge: the seal is not the database''s own time (%)', r."listsSealedAt";
  END IF;
  PERFORM pg_temp.refuses(format($q$UPDATE "CrisisAlarms" SET "listsSealedAt" = NULL WHERE id = %L$q$, al), 'KL422', 'an unsealed list');
  PERFORM pg_temp.refuses(format($q$UPDATE "CrisisAlarms" SET "listsSealedAt" = "listsSealedAt" + interval '1 minute' WHERE id = %L$q$, al), 'KL422', 'a moved seal');

  -- 351e: the end is the database's time in the ender's name, once; the note belongs to it.
  UPDATE "CrisisAlarms" SET "endedAt" = now() - interval '5 days', "endNote" = 'Falsklarm', "autoEnded" = true WHERE id = d;
  SELECT * INTO r FROM "CrisisAlarms" WHERE id = d;
  IF r."endedAt" IS NULL OR r."endedAt" < r."startedAt" OR r."endedAt" > clock_timestamp() OR r."endedByUserId" <> me OR r."autoEnded" OR r."endNote" <> 'Falsklarm' THEN
    RAISE EXCEPTION 'krisläge: the end of an exercise is not the ender''s own, at the database''s time (%, %, %)', r."endedAt", r."endedByUserId", r."autoEnded";
  END IF;
  PERFORM pg_temp.refuses(format($q$UPDATE "CrisisAlarms" SET "endedAt" = now() WHERE id = %L$q$, d), 'KL409', 'a second end');
  PERFORM pg_temp.refuses(format($q$UPDATE "CrisisAlarms" SET "endNote" = 'Annat' WHERE id = %L$q$, d), 'KL409', 'a note changed after the end');
  PERFORM pg_temp.refuses(format($q$UPDATE "CrisisAlarms" SET "guardiansNotifiedAt" = now() WHERE id = %L$q$, d), '23514', 'the guardians told of an exercise');
  PERFORM pg_temp.refuses(format($q$UPDATE "CrisisAlarms" SET "endNote" = repeat('x', 301) WHERE id = %L$q$, al), 'KL422', 'a long note on an alarm that is going');
  PERFORM pg_temp.refuses(format($q$UPDATE "CrisisAlarms" SET "endedAt" = now(), "endNote" = repeat('x', 301) WHERE id = %L$q$, al), '23514', 'a note over 300 characters');
  PERFORM pg_temp.refuses(format($q$UPDATE "CrisisAlarms" SET "endedAt" = now(), "endNote" = ' tom ' WHERE id = %L$q$, al), '23514', 'a note with spaces round it');

  -- The real alarm ends, and the guardians' time is added to it once.
  UPDATE "CrisisAlarms" SET "endedAt" = now(), "guardiansNotifiedAt" = now() WHERE id = al;
  PERFORM pg_temp.refuses(format($q$UPDATE "CrisisAlarms" SET "guardiansNotifiedAt" = now() + interval '1 minute' WHERE id = %L$q$, al), 'KL409', 'the guardians told twice');

  -- Both are over, so a new alarm of each kind can begin; one is left open for the readers below.
  INSERT INTO "CrisisAlarms" ("schoolId", kind, mode) VALUES (school, 'EVACUATION', 'DRILL') RETURNING id INTO d2;
  INSERT INTO "CrisisAlarms" ("schoolId", kind, mode) VALUES (school, 'EVACUATION', 'LIVE') RETURNING id INTO al2;

  -- 351f: the hour's window as the function states it. The fixtures plant an
  -- exercise that ended three hours ago.
  IF NOT (app.crisis_window_open(al2) AND app.crisis_window_open(al) AND app.crisis_window_open(d)) THEN
    RAISE EXCEPTION 'krisläge: an alarm that is going or ended just now is outside the window';
  END IF;
  IF app.crisis_window_open('c0000000-0000-4000-8000-0000000f2201') THEN
    RAISE EXCEPTION 'krisläge: an alarm that ended three hours ago is inside the window';
  END IF;
  IF app.crisis_window_open(gen_random_uuid()) THEN RAISE EXCEPTION 'krisläge: an alarm that does not exist is inside the window'; END IF;

  SELECT id INTO pupil FROM "Users" WHERE "schoolId" = school AND role = 'STUDENT' AND "isActive" ORDER BY "authId" LIMIT 1;
  PERFORM set_config('app.test_rls351_al', al::text, true);
  PERFORM set_config('app.test_rls351_d', d::text, true);
  PERFORM set_config('app.test_rls351_al2', al2::text, true);
  PERFORM set_config('app.test_rls351_d2', d2::text, true);
  PERFORM set_config('app.test_rls351_school', school::text, true);
  PERFORM set_config('app.test_rls351_t1_auth', (SELECT "authId"::text FROM "Users" WHERE id = t1), true);
  PERFORM set_config('app.test_rls351_pupil_auth', (SELECT "authId"::text FROM "Users" WHERE id = pupil), true);
  PERFORM set_config('app.test_rls351_guardian_auth', (SELECT "authId"::text FROM "Users" WHERE "schoolId" = school AND role = 'GUARDIAN' AND "isActive" ORDER BY "authId" LIMIT 1), true);
  IF (SELECT count(*) FROM "CrisisAlarms" WHERE "schoolId" = school) <> 5 THEN
    RAISE EXCEPTION 'krisläge: the administrator reads % alarm(s), not the four of this section and the fixtures'' old one', (SELECT count(*) FROM "CrisisAlarms" WHERE "schoolId" = school);
  END IF;
END $$;

-- 351g: a teacher reads the alarms that are going or just over, never an older one, and writes none.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('app.test_rls351_t1_auth'))::text, true);
DO $$
DECLARE
  n bigint;
BEGIN
  SELECT count(*) INTO n FROM "CrisisAlarms";
  IF n <> 4 THEN RAISE EXCEPTION 'krisläge: a teacher reads % alarm(s), not the four that are going or ended within the hour', n; END IF;
  IF EXISTS (SELECT 1 FROM "CrisisAlarms" WHERE id = 'c0000000-0000-4000-8000-0000000f2201') THEN
    RAISE EXCEPTION 'krisläge: a teacher reads an alarm that ended three hours ago';
  END IF;
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisAlarms" ("schoolId", kind, mode) VALUES (%L, 'LOCKDOWN', 'LIVE')$q$, current_setting('app.test_rls351_school')),
                          '42501', 'a teacher starting an alarm');
  IF pg_temp.changes(format($q$UPDATE "CrisisAlarms" SET "endedAt" = now() WHERE id = %L$q$, current_setting('app.test_rls351_al2'))) <> 0 THEN
    RAISE EXCEPTION 'krisläge: a teacher ended an alarm';
  END IF;
  PERFORM pg_temp.refuses(format($q$DELETE FROM "CrisisAlarms" WHERE id = %L$q$, current_setting('app.test_rls351_al2')), '42501', 'a teacher deleting an alarm');
  IF app.crisis_may_start() THEN RAISE EXCEPTION 'krisläge: a teacher may start an alarm'; END IF;
END $$;

-- 351h: a pupil, a guardian and another school's administrator read no alarm and write none.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('app.test_rls351_pupil_auth'))::text, true);
DO $$
BEGIN
  IF (SELECT count(*) FROM "CrisisAlarms") <> 0 THEN RAISE EXCEPTION 'krisläge: a pupil reads an alarm'; END IF;
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisAlarms" ("schoolId", kind, mode) VALUES (%L, 'LOCKDOWN', 'LIVE')$q$, current_setting('app.test_rls351_school')),
                          '42501', 'a pupil starting an alarm');
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('app.test_rls351_guardian_auth'))::text, true);
DO $$
BEGIN
  IF (SELECT count(*) FROM "CrisisAlarms") <> 0 THEN RAISE EXCEPTION 'krisläge: a guardian reads an alarm'; END IF;
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000006')::text, true);
DO $$
BEGIN
  IF (SELECT count(*) FROM "CrisisAlarms") <> 0 THEN RAISE EXCEPTION 'krisläge: another school''s administrator reads an alarm'; END IF;
  IF pg_temp.changes(format($q$UPDATE "CrisisAlarms" SET "endedAt" = now() WHERE id = %L$q$, current_setting('app.test_rls351_al2'))) <> 0 THEN
    RAISE EXCEPTION 'krisläge: another school''s administrator ended an alarm';
  END IF;
  IF app.crisis_window_open(current_setting('app.test_rls351_al2')::uuid) THEN RAISE EXCEPTION 'krisläge: another school''s window is open to this one'; END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 352: grupperna och deras lärare (CrisisCalls, CrisisCallTeachers,
-- 20270113091000), and with it the alarm that 352-354 build and read from
-- every side.
--
-- The administrator writes an alarm for the primary school the way the
-- gateway does in the transaction that starts it: a real utrymning with three
-- groups. 7A (a lesson that is going on) has two teachers, t1 who leads and t3
-- who assists, and two pupils, the second of whom was absent before the alarm;
-- 8B (a group on its way to its next lesson, in a break) has t2 and one pupil;
-- 9C has nobody to answer for it and one pupil. Then it seals the lists. A
-- fourth teacher answers for nothing.
-- ---------------------------------------------------------------------------

BEGIN;
CREATE FUNCTION pg_temp.refuses(stmt text, expected text, what text) RETURNS void LANGUAGE plpgsql AS $f$
DECLARE got text := 'none';
BEGIN
  BEGIN
    EXECUTE stmt;
  EXCEPTION WHEN OTHERS THEN
    got := SQLSTATE;
  END;
  IF got IS DISTINCT FROM expected THEN
    RAISE EXCEPTION 'krisläge: % should be refused with %, was %', what, expected, got USING ERRCODE = 'P0001';
  END IF;
END
$f$;
CREATE FUNCTION pg_temp.changes(stmt text) RETURNS bigint LANGUAGE plpgsql AS $f$
DECLARE n bigint;
BEGIN
  EXECUTE stmt;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END
$f$;
SELECT set_config('request.jwt.claims', json_build_object('sub', :'admin_auth_id')::text, true);
DO $$
DECLARE
  school uuid := app.current_school_id();
  me uuid := app.current_user_id();
  t1 uuid; t2 uuid; t3 uuid; t4 uuid; p1 uuid; p2 uuid; p3 uuid; p4 uuid;
  lesson uuid; al uuid; d0 uuid; c1 uuid; c2 uuid; c3 uuid; n bigint;
BEGIN
  SELECT id INTO t1 FROM "Users" WHERE "schoolId" = school AND role = 'TEACHER' AND "isActive" ORDER BY "authId" LIMIT 1;
  SELECT id INTO t2 FROM "Users" WHERE "schoolId" = school AND role = 'TEACHER' AND "isActive" AND id NOT IN (t1) ORDER BY "authId" LIMIT 1;
  SELECT id INTO t3 FROM "Users" WHERE "schoolId" = school AND role = 'TEACHER' AND "isActive" AND id NOT IN (t1, t2) ORDER BY "authId" LIMIT 1;
  SELECT id INTO t4 FROM "Users" WHERE "schoolId" = school AND role = 'TEACHER' AND "isActive" AND id NOT IN (t1, t2, t3) ORDER BY "authId" LIMIT 1;
  SELECT id INTO p1 FROM "Users" WHERE "schoolId" = school AND role = 'STUDENT' AND "isActive" ORDER BY "authId" LIMIT 1;
  SELECT id INTO p2 FROM "Users" WHERE "schoolId" = school AND role = 'STUDENT' AND "isActive" AND id NOT IN (p1) ORDER BY "authId" LIMIT 1;
  SELECT id INTO p3 FROM "Users" WHERE "schoolId" = school AND role = 'STUDENT' AND "isActive" AND id NOT IN (p1, p2) ORDER BY "authId" LIMIT 1;
  SELECT id INTO p4 FROM "Users" WHERE "schoolId" = school AND role = 'STUDENT' AND "isActive" AND id NOT IN (p1, p2, p3) ORDER BY "authId" LIMIT 1;
  IF t4 IS NULL OR p4 IS NULL THEN
    RAISE EXCEPTION 'krisläge: the primary school lacks four teachers or four pupils';
  END IF;

  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", "updatedAt")
  SELECT school, (SELECT id FROM "Subjects" WHERE "schoolId" = school ORDER BY id LIMIT 1),
         (SELECT id FROM "StudentGroups" WHERE "schoolId" = school ORDER BY id LIMIT 1),
         DATE '2096-03-01', timestamptz '2096-03-01 08:00 UTC', timestamptz '2096-03-01 09:00 UTC', now()
  RETURNING id INTO lesson;

  -- An open exercise for 352c, planted first: an exercise is not started beside a real alarm.
  INSERT INTO "CrisisAlarms" ("schoolId", kind, mode) VALUES (school, 'LOCKDOWN', 'DRILL') RETURNING id INTO d0;
  PERFORM set_config('app.test_rls352_drill', d0::text, true);
  INSERT INTO "CrisisAlarms" ("schoolId", kind, mode) VALUES (school, 'EVACUATION', 'LIVE') RETURNING id INTO al;
  INSERT INTO "CrisisCalls" ("schoolId", "alarmId", "calendarLessonId", basis, "groupName", "subjectName", "roomName", "lessonStartsAt", "lessonEndsAt")
  VALUES (school, al, lesson, 'LESSON', '7A', 'Matematik', 'Sal 101', now() - interval '30 minutes', now() + interval '30 minutes') RETURNING id INTO c1;
  INSERT INTO "CrisisCalls" ("schoolId", "alarmId", basis, "groupName", "subjectName", "lessonStartsAt", "lessonEndsAt")
  VALUES (school, al, 'NEXT_LESSON', '8B', 'Svenska', now() + interval '10 minutes', now() + interval '60 minutes') RETURNING id INTO c2;
  INSERT INTO "CrisisCalls" ("schoolId", "alarmId", basis, "groupName", "subjectName", "lessonStartsAt", "lessonEndsAt")
  VALUES (school, al, 'LESSON', '9C', 'Idrott', now() - interval '30 minutes', now() + interval '30 minutes') RETURNING id INTO c3;
  INSERT INTO "CrisisCallTeachers" ("schoolId", "callId", "teacherId", role)
  VALUES (school, c1, t1, 'LEAD'), (school, c1, t3, 'ASSISTANT'), (school, c2, t2, 'SUBSTITUTE');
  INSERT INTO "CrisisPupils" ("schoolId", "alarmId", "callId", "studentId", "priorAbsentSource")
  VALUES (school, al, c1, p1, NULL), (school, al, c1, p2, 'ATTENDANCE'), (school, al, c2, p3, NULL), (school, al, c3, p4, NULL);
  UPDATE "CrisisAlarms" SET "listsSealedAt" = now() WHERE id = al;

  -- 352a: the administrator reads all of it.
  SELECT count(*) INTO n FROM "CrisisCalls" WHERE "alarmId" = al;
  IF n <> 3 THEN RAISE EXCEPTION 'krisläge: the administrator reads % call(s), not 3', n; END IF;
  SELECT count(*) INTO n FROM "CrisisCallTeachers" WHERE "callId" IN (c1, c2, c3);
  IF n <> 3 THEN RAISE EXCEPTION 'krisläge: the administrator reads % call teacher(s), not 3', n; END IF;
  SELECT count(*) INTO n FROM "CrisisPupils" WHERE "alarmId" = al;
  IF n <> 4 THEN RAISE EXCEPTION 'krisläge: the administrator reads % pupil(s), not 4', n; END IF;

  -- 352b: once sealed, nothing is added to the lists, not a group, not a teacher, not a pupil.
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisCalls" ("schoolId", "alarmId", basis, "groupName", "subjectName", "lessonStartsAt", "lessonEndsAt") VALUES (%L, %L, 'LESSON', '7B', 'Bild', now(), now() + interval '1 hour')$q$, school, al),
                          '42501', 'a group added to a sealed alarm');
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisCallTeachers" ("schoolId", "callId", "teacherId") VALUES (%L, %L, %L)$q$, school, c3, t4),
                          '42501', 'a teacher added to a sealed alarm');
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisPupils" ("schoolId", "alarmId", "callId", "studentId") SELECT %L, %L, %L, id FROM "Users" WHERE "schoolId" = %L AND role = 'STUDENT' AND id NOT IN (%L, %L, %L, %L) LIMIT 1$q$, school, al, c3, school, p1, p2, p3, p4),
                          '42501', 'a pupil added to a sealed alarm');

  PERFORM set_config('app.test_rls352_school', school::text, true);
  PERFORM set_config('app.test_rls352_al', al::text, true);
  PERFORM set_config('app.test_rls352_c1', c1::text, true);
  PERFORM set_config('app.test_rls352_c2', c2::text, true);
  PERFORM set_config('app.test_rls352_c3', c3::text, true);
  PERFORM set_config('app.test_rls352_t1', t1::text, true);
  PERFORM set_config('app.test_rls352_t2', t2::text, true);
  PERFORM set_config('app.test_rls352_t3', t3::text, true);
  PERFORM set_config('app.test_rls352_p1', p1::text, true);
  PERFORM set_config('app.test_rls352_p2', p2::text, true);
  PERFORM set_config('app.test_rls352_p3', p3::text, true);
  PERFORM set_config('app.test_rls352_p4', p4::text, true);
  PERFORM set_config('app.test_rls352_me', me::text, true);
  PERFORM set_config('app.test_rls352_lesson', lesson::text, true);
  PERFORM set_config('app.test_rls352_me_auth', (SELECT "authId"::text FROM "Users" WHERE id = me), true);
  PERFORM set_config('app.test_rls352_t1_auth', (SELECT "authId"::text FROM "Users" WHERE id = t1), true);
  PERFORM set_config('app.test_rls352_t2_auth', (SELECT "authId"::text FROM "Users" WHERE id = t2), true);
  PERFORM set_config('app.test_rls352_t3_auth', (SELECT "authId"::text FROM "Users" WHERE id = t3), true);
  PERFORM set_config('app.test_rls352_t4_auth', (SELECT "authId"::text FROM "Users" WHERE id = t4), true);
  PERFORM set_config('app.test_rls352_p1_auth', (SELECT "authId"::text FROM "Users" WHERE id = p1), true);
  PERFORM set_config('app.test_rls352_guardian_auth', (SELECT "authId"::text FROM "Users" WHERE "schoolId" = school AND role = 'GUARDIAN' AND "isActive" ORDER BY "authId" LIMIT 1), true);
  PERFORM set_config('app.test_rls352_old_call', (SELECT id::text FROM "CrisisCalls" WHERE "alarmId" = 'c0000000-0000-4000-8000-0000000f2201'), true);
END $$;

-- 352c: the lists while they are open: a foreign key to a lesson, a teacher or a pupil of another
-- school is refused, so are a pupil on two lists of one alarm and a call of one alarm under another.
SELECT set_config('app.test_school_b', :'school_b', true), set_config('app.test_student_b', :'student_b', true);
DO $$
DECLARE
  school uuid := current_setting('app.test_rls352_school')::uuid;
  -- A fifth teacher, who answers for no group of the alarm the readers below look at.
  t5 uuid := (SELECT id FROM "Users" WHERE "schoolId" = school AND role = 'TEACHER' AND "isActive"
                 AND id NOT IN (current_setting('app.test_rls352_t1')::uuid, current_setting('app.test_rls352_t2')::uuid,
                                current_setting('app.test_rls352_t3')::uuid,
                                (SELECT id FROM "Users" WHERE "authId" = current_setting('app.test_rls352_t4_auth')::uuid))
                 ORDER BY "authId" LIMIT 1);
  p1 uuid := current_setting('app.test_rls352_p1')::uuid;
  d uuid; call uuid; call2 uuid;
BEGIN
  d := current_setting('app.test_rls352_drill')::uuid;
  INSERT INTO "CrisisCalls" ("schoolId", "alarmId", basis, "groupName", "subjectName", "lessonStartsAt", "lessonEndsAt")
  VALUES (school, d, 'LESSON', 'Gruppen', 'Matematik', now(), now() + interval '1 hour') RETURNING id INTO call;
  INSERT INTO "CrisisCalls" ("schoolId", "alarmId", basis, "groupName", "subjectName", "lessonStartsAt", "lessonEndsAt")
  VALUES (school, d, 'LESSON', 'Andra', 'Bild', now(), now() + interval '1 hour') RETURNING id INTO call2;
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisCalls" ("schoolId", "alarmId", "calendarLessonId", basis, "groupName", "subjectName", "lessonStartsAt", "lessonEndsAt") VALUES (%L, %L, %L, 'LESSON', 'G', 'M', now(), now() + interval '1 hour')$q$, school, d, gen_random_uuid()),
                          '23503', 'a call on a lesson that is not the school''s');
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisCalls" ("schoolId", "alarmId", "calendarLessonId", basis, "groupName", "subjectName", "lessonStartsAt", "lessonEndsAt") VALUES (%L, %L, %L, 'LESSON', 'G3', 'M', now(), now() + interval '1 hour')$q$, school, d, current_setting('app.test_rls352_lesson')),
                          'none', 'a call on a lesson of the school');
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisCalls" ("schoolId", "alarmId", basis, "groupName", "subjectName", "lessonStartsAt", "lessonEndsAt") VALUES (%L, %L, 'LESSON', '', 'M', now(), now() + interval '1 hour')$q$, school, d),
                          '23514', 'a call with no name');
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisCalls" ("schoolId", "alarmId", basis, "groupName", "subjectName", "lessonStartsAt", "lessonEndsAt") VALUES (%L, %L, 'LESSON', 'G', 'M', now(), now())$q$, school, d),
                          '23514', 'a lesson with no span');
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisCallTeachers" ("schoolId", "callId", "teacherId") VALUES (%L, %L, %L)$q$, school, call, current_setting('app.test_student_b')),
                          '23503', 'a teacher of another school on a call');
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisPupils" ("schoolId", "alarmId", "callId", "studentId") VALUES (%L, %L, %L, %L)$q$, school, d, call, current_setting('app.test_student_b')),
                          '23503', 'a pupil of another school on a list');
  INSERT INTO "CrisisCallTeachers" ("schoolId", "callId", "teacherId") VALUES (school, call, t5);
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisCallTeachers" ("schoolId", "callId", "teacherId") VALUES (%L, %L, %L)$q$, school, call, t5),
                          '23505', 'a teacher twice on one call');
  INSERT INTO "CrisisPupils" ("schoolId", "alarmId", "callId", "studentId") VALUES (school, d, call, p1);
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisPupils" ("schoolId", "alarmId", "callId", "studentId") VALUES (%L, %L, %L, %L)$q$, school, d, call2, p1),
                          '23505', 'a pupil on two lists of one alarm');
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisPupils" ("schoolId", "alarmId", "callId", "studentId") VALUES (%L, %L, %L, %L)$q$, school, d, current_setting('app.test_rls352_c1'), current_setting('app.test_rls352_p3')),
                          '23503', 'a pupil on the call of another alarm');
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisPupils" ("schoolId", "alarmId", "callId", "studentId", "priorAbsentSource") VALUES (%L, %L, %L, %L, 'FOO')$q$, school, d, call2, current_setting('app.test_rls352_p2')),
                          '23514', 'an unknown reason for being absent before');
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisPupils" ("schoolId", "alarmId", "callId", "studentId", state) VALUES (%L, %L, %L, %L, 'FOUND')$q$, school, d, call2, current_setting('app.test_rls352_p2')),
                          '23514', 'a mark with no time');
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisPupils" ("schoolId", "alarmId", "callId", "studentId", state, "stateAt") VALUES (%L, %L, %L, %L, 'RETRACTED', now())$q$, school, d, call2, current_setting('app.test_rls352_p2')),
                          '23514', 'a withdrawn mark kept as a pupil''s state');
  PERFORM pg_temp.refuses(format($q$UPDATE "CrisisCalls" SET "groupName" = 'X' WHERE id = %L$q$, call), '42501', 'a changed call');
  PERFORM pg_temp.refuses(format($q$DELETE FROM "CrisisCalls" WHERE id = %L$q$, call), '42501', 'a deleted call');
  PERFORM pg_temp.refuses(format($q$UPDATE "CrisisCallTeachers" SET role = 'ASSISTANT' WHERE "callId" = %L$q$, call), '42501', 'a changed call teacher');
  PERFORM pg_temp.refuses(format($q$UPDATE "CrisisPupils" SET state = 'FOUND', "stateAt" = now() WHERE "callId" = %L$q$, call), '42501', 'a pupil''s mark written by hand');
  PERFORM pg_temp.refuses(format($q$DELETE FROM "CrisisPupils" WHERE "callId" = %L$q$, call), '42501', 'a deleted pupil');
END $$;

-- 352d: a teacher reads the calls they answer for, the teachers who answer for them with them, and
-- nothing of anyone else's group; the lead and the assistant answer for the same call.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('app.test_rls352_t1_auth'))::text, true);
DO $$
DECLARE n bigint;
BEGIN
  SELECT count(*) INTO n FROM "CrisisCalls";
  IF n <> 1 OR NOT EXISTS (SELECT 1 FROM "CrisisCalls" WHERE id = current_setting('app.test_rls352_c1')::uuid) THEN
    RAISE EXCEPTION 'krisläge: the leading teacher reads % call(s), not their own', n;
  END IF;
  -- The teachers of a call they answer for, themselves and the one who assists, and no others.
  SELECT count(*) INTO n FROM "CrisisCallTeachers";
  IF n <> 2 OR (SELECT array_agg("teacherId" ORDER BY "teacherId") FROM "CrisisCallTeachers")
               IS DISTINCT FROM (SELECT array_agg(x ORDER BY x) FROM unnest(ARRAY[current_setting('app.test_rls352_t1')::uuid, current_setting('app.test_rls352_t3')::uuid]) x) THEN
    RAISE EXCEPTION 'krisläge: a teacher reads % call teacher row(s), not the two of the call they answer for', n;
  END IF;
  IF EXISTS (SELECT 1 FROM "CrisisCalls" WHERE id = current_setting('app.test_rls352_old_call')::uuid) THEN
    RAISE EXCEPTION 'krisläge: a teacher reads a call of an alarm that ended three hours ago';
  END IF;
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisCalls" ("schoolId", "alarmId", basis, "groupName", "subjectName", "lessonStartsAt", "lessonEndsAt") VALUES (%L, %L, 'LESSON', 'G', 'M', now(), now() + interval '1 hour')$q$, current_setting('app.test_rls352_school'), current_setting('app.test_rls352_al')),
                          '42501', 'a teacher writing a group');
  PERFORM pg_temp.refuses(format($q$INSERT INTO "CrisisCallTeachers" ("schoolId", "callId", "teacherId") VALUES (%L, %L, %L)$q$, current_setting('app.test_rls352_school'), current_setting('app.test_rls352_c2'), current_setting('app.test_rls352_t1')),
                          '42501', 'a teacher putting themselves on another call');
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('app.test_rls352_t3_auth'))::text, true);
DO $$
BEGIN
  IF (SELECT array_agg(id) FROM "CrisisCalls") IS DISTINCT FROM ARRAY[current_setting('app.test_rls352_c1')::uuid] THEN
    RAISE EXCEPTION 'krisläge: the assistant does not read the call they assist, or reads another';
  END IF;
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('app.test_rls352_t2_auth'))::text, true);
DO $$
BEGIN
  IF (SELECT array_agg(id) FROM "CrisisCalls") IS DISTINCT FROM ARRAY[current_setting('app.test_rls352_c2')::uuid] THEN
    RAISE EXCEPTION 'krisläge: the vikarie does not read the call they answer for, or reads another';
  END IF;
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('app.test_rls352_t4_auth'))::text, true);
DO $$
BEGIN
  IF (SELECT count(*) FROM "CrisisCalls") + (SELECT count(*) FROM "CrisisCallTeachers") <> 0 THEN
    RAISE EXCEPTION 'krisläge: a teacher who answers for nothing reads a call';
  END IF;
  -- The alarm itself they do read: they must learn that one is going.
  IF NOT EXISTS (SELECT 1 FROM "CrisisAlarms" WHERE id = current_setting('app.test_rls352_al')::uuid) THEN
    RAISE EXCEPTION 'krisläge: a teacher who answers for nothing cannot learn that an alarm is going';
  END IF;
END $$;

